\section{A general error estimate}\label{sec:abstract}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Let $U, V$ denote Hilbert spaces, and $B\colon U \to V'$ be a linear and bounded operator.
We say that $B$ is bounded below if there exists $c_B>0$, such that
\begin{align}\label{eq:Biso}
  c_B \|u\|_U \leq \|Bu\|_{V'}  \quad\forall u\in U.
\end{align}
Note that if $B$ is bounded below, then $B$ has closed range and is injective.

Let $V_h\subseteq V$ denote a finite-dimensional subspace equipped with a norm $\|\cdot\|_{V_h}$, induced by the inner product $\ip{\cdot}\cdot_{V_h}$, uniformly equivalent to $\|\cdot\|_V$. This is, there exists $C_\mathrm{equiv}>0$, independent of $V_h$, such that
\begin{align}\label{eq:normequivV}
  C_\mathrm{equiv}^{-1} \|v\|_V \leq \|v\|_{V_h} \leq C_\mathrm{equiv}\|v\|_V \quad\forall v\in V_h.
\end{align}
Clearly, $C_\mathrm{equiv}=1$ if $\|\cdot\|_{V_h}=\|\cdot\|_V$.
For a given $u\in U$, define for any $w\in U$
\begin{align}\label{eq:defeta}
  \eta(w) = \sup_{0\neq v\in V_h} \frac{b(u-w,v)}{\|v\|_{V_h}} = \|B(u-w)\|_{V_h'},
\end{align}
where $b\colon U\times V\to\R$ denotes the bilinear form induced by the operator $B$.
Finally, let $\Pi_h\colon V\to V_h$ denote a linear operator with $\|\Pi_h\|<\infty$, and set for any $w\in U$
\begin{align}\label{eq:defmu}
  \mu(w) = \sup_{0\neq v\in V} \frac{b(w-u,v-\Pi_hv)}{\|v\|_{V}}.
\end{align}
In our analysis, we also use the kernel space
\begin{align}\label{eq:defkernel}
  U_0(\Pi_h) = \set{w\in U}{b(w,v-\Pi_h v) = 0 \quad\forall v\in V}.
\end{align}
Note that $0\in U_0(\Pi_h)$ and $U_0(\Pi_h)$ is closed since it is the kernel of the linear and bounded operator $U\to V'$, $w\mapsto (v\mapsto b(w,v-\Pi_hv))$.
The following result will serve as the basis of our further investigations and discussions. 

\begin{theorem}\label{thm:equivest}
  Let $u\in U$ be given and $\eta$, $\mu$, $U_0(\Pi_h)$ be defined as in~\eqref{eq:defeta}--\eqref{eq:defkernel}.
  Then, for all $w\in  U$
  \begin{subequations}\label{eq:equivest}
  \begin{align}\label{eq:equivest:a}
    C_\mathrm{equiv}^{-1} \eta(w) \leq \|B(u-w)\|_{V'} \leq
    C_\mathrm{equiv} \|\Pi_h\| \eta(w) + \mu(w)
  \end{align}
  and
  \begin{align}\label{eq:equivest:b}
    \mu(w) \leq \|1-\Pi_h\|\inf_{w_0\in U_0(\Pi_h)}\|B(u-w-w_0)\|_{V'}
    \leq \|1-\Pi_h\|\|B(u-w)\|_{V'}.
  \end{align}
  \end{subequations}
\end{theorem}
\begin{proof}
  Let $w\in U$ be given. The lower bound in~\eqref{eq:equivest:a} follows directly from the norm equivalence~\eqref{eq:normequivV} and $V_h\subseteq V$.
  To obtain the upper bound, write $b(u-w,v) = b(u-w,\Pi_h v) + b(u-w,v-\Pi_h v)$. Then, the triangle inequality, boundedness of $\Pi_h$ and the estimates~\eqref{eq:normequivV} and~\eqref{eq:Biso}, show that
  \begin{align*}
    \|B(u-w)\|_{V'} & \leq \sup_{0\neq v\in V} \frac{b(u-w,\Pi_hv)}{\|v\|_V} 
    + \sup_{0\neq v\in V} \frac{b(u-w,v-\Pi_hv)}{\|v\|_V} \\
    &\leq \|\Pi_h\|\sup_{0\neq v\in V} \frac{b(u-w,\Pi_hv)}{\|\Pi_h v\|_V} + \mu(w)
    \\
    &\leq \|\Pi_h\| \sup_{0\neq v_h\in V_h} \frac{b(u-w,v_h)}{\|v_h\|_V} + \mu(w)
    \\
    &\leq C_\mathrm{equiv} \|\Pi_h\|\eta(w) + \mu(w).
  \end{align*}
  To prove the first inequality in~\eqref{eq:equivest:b}, let $w_0\in U_0(\Pi_h)$ be arbitrary. Observe that
  \begin{align*}
    |b(u-w,v-\Pi_h v)| = |b(u-w-w_0,v-\Pi_h v)| &\leq  \|B(u-w-w_0)\|_{V'}\|1-\Pi_h\|\|v\|_V.
  \end{align*}
  Dividing by $\|v\|_V$, taking the supremum over $V\setminus\{0\}$, and noting that $w_0\in U_0(\Pi_h)$ is arbitrary, proves the first inequality in~\eqref{eq:equivest:b}. The second inequality follows from recalling that $0\in U_0(\Pi_h)$, concluding the proof.
\end{proof}

\begin{remark}
  Since $B$ is bounded, it follows from~\eqref{eq:equivest:a} that 
  \begin{align*}
    C_\mathrm{equiv}^{-1} \eta(w)\leq \|B\| \|u-w\|_U
  \end{align*}
  and from~\eqref{eq:equivest:b} that
  \begin{align*}
    \mu(w) \leq \|B\|\,\|1-\Pi_h\|\inf_{w_0\in U_0(\Pi_h)} \|u-w-w_0\|_U \leq \|B\|\,\|1-\Pi_h\|\,\|u-w\|_U.
  \end{align*}
  Suppose that $B$ is bounded below~\eqref{eq:Biso}. Then,~\eqref{eq:equivest:a} implies that
  \begin{align*}
    c_B \|u-w\|_U \leq C_\mathrm{equiv} \|\Pi_h\| \eta(w) + \mu(w).
  \end{align*}
  In particular, 
  \begin{align*}
    \|u-w\|_U \eqsim \|B(u-w)\|_{V'} \eqsim \eta(w) + \mu(w) \quad\forall w\in U, 
  \end{align*} where the involved constants only depend on $c_B$, $\|B\|$, $C_\mathrm{equiv}$, $\|\Pi_h\|$.  
\end{remark}


\begin{remark}
  Let $U_h\subset U$ denote a finite-dimensional subspace. If ``$w\in U$'' is replaced by ``$w\in U_h$'' in Theorem~\ref{thm:equivest} and assuming that $\Pi_h\colon V\to V_h$ satisfies the Fortin condition $b(w,v-\Pi_hv)=0$ for $w\in U_h$, $v\in V$, then Theorem~\ref{thm:equivest} reduces to a version of~\cite[Theorem 2.1]{DPGaposteriori} for bounded below operators $B$.
  In particular, Theorem~\ref{thm:equivest} can be seen as a generalization of~\cite[Theorem~2.1]{DPGaposteriori}. In Section~\ref{sec:observations} below, we give further details on relations to (discontinuous) Petrov--Galerkin methods.
\end{remark}


For our applications in mind, we have that $V = \prod_{j=1}^n V_j$ where $V_j$, $j=1,\dots,n$ are Hilbert spaces and $B\colon U\to V'$ can be written as $B  = \sum_{j=1}^n B_j$, with $B_j\colon U\to V_j'$ (and the canonical embedding $V_j'\to V'$), $j=1,\dots,n$. Then,
\begin{align*}
  \|B(u-w)\|_{V'}^2 = \sum_{j=1}^n \|B_j(u-w)\|_{V_j'}^2.
\end{align*}
For all $j=1,\dots,n$ let $V_{h,j}\subset V_j$ denote a finite-dimensional subspace, $\Pi_{h,j}\colon V_j\to V_{h,j}$ a linear and bounded operator and define $\eta_j$, $\mu_j$ as in~\eqref{eq:defeta}--\eqref{eq:defmu} replacing $B$, $V$, $V_h$, $\Pi_h$ by $B_j$, $V_j$, $V_{h,j}$, $\Pi_{h,j}$. Similarly, let $\|\cdot\|_{V_{h,j}}$ denote an equivalent norm on $V_{h,j}$ with equivalence constant $C_\mathrm{equiv,j}$, $j=1,\dots,n$.
The next result follows from applying Theorem~\ref{thm:equivest} for all $j=1,\dots,n$.
\begin{corollary}\label{cor:equivest}
  Under the aforegoing assumptions, define
  \begin{align*}
    \eta(w)^2 = \sum_{j=1}^n \eta_j(w)^2, \qquad \mu(w)^2 = \sum_{j=1}^n \mu_j(w)^2.
  \end{align*}
  Then, 
  \begin{align*}
    C_1 \eta(w) \leq \|B(u-w)\|_{V'} \leq C_2\eta(w) + \sqrt{2}\mu(w) \quad\forall w\in U.
  \end{align*}
  Here, $C_1 = \min\{C_{\mathrm{equiv},j}^{-1}\,:\,j=1,\dots,n\}$, $C_2 = \sqrt{2}\min\{C_{\mathrm{equiv,j}}\|\Pi_{h,j}\|\,:\,j=1,\dots,n\}$.
  Furthermore, with $C_3 = \max\{\|1-\Pi_{h,j}\|\,:\,j=1,\dots,n\}$,
  \begin{align*}
    \mu(w) \leq C_3\|B(u-w)\|_{V'} \quad\forall w\in U.
  \end{align*}
  If $B$ is additionally bounded below, then
  \begin{align*}
    \|u-w\|_U \eqsim \eta(w) + \mu(w) \quad\forall w\in U
  \end{align*}
  where the involved constants only depend on $C_1$, $C_2$ and $C_3$.
\end{corollary}

\subsection{Observations and some notes on relations to finite element methods}\label{sec:observations}
In what follows we discuss some observations implied by Theorem~\ref{thm:equivest}.
First, estimates~\eqref{eq:equivest} show the equivalence
\begin{align*}
  \|u-w\|_U \eqsim \eta(w) + \mu(w),
\end{align*}
provided that $B$ is bounded below, which we assume for the remainder of this section.
While $\eta(w)$ is computable, $\mu(w)$ is, in general, not, as it involves taking the supremum over the whole (infinite-dimensional) space $V$.

In this work, we propose using techniques from the a posteriori analysis of finite element methods to localize $\mu$ and obtain a computable upper bound $\rho$. This is, we aim to provide an estimate of the form
\begin{align}\label{eq:locest}%localization of estimator
  \mu(w) = \sup_{0\neq v\in V} \frac{b(u-w,v-\Pi_h v)}{\|v\|_V} \leq C \rho(w) \quad\forall w\in U
\end{align}
with some generic constant $C>0$. In section~\ref{sec:modelpoisson}, we provide several examples of how to obtain such an estimate for a general second-order problem with uniformly bounded physical parameters. %and a singularly perturbed problem.
Note, however, that in general $\rho(w)$ is not a lower bound for the error $\|u-w\|_U$, i.e., the estimate
\begin{align*}
  \rho(w) \lesssim \|u-w\|_U \text{ does not hold in general.}
\end{align*}


Let us discuss the estimator contributions $\eta$, $\mu$, $\rho$ in the context of two popular numerical methods; the Galerkin method and the (discontinuous) Petrov--Galerkin method with optimal test functions or, more generally, the Minimum Residual method (MINRES).

\noindent\emph{Galerkin method.} 
Suppose that $V=U$ and that $b\colon U\times U\to \R$ is a bounded and coercive bilinear form. 
%Then, as a consequence of the Lax--Milgram lemma the operator $B$ is an isomorphism so that all assumptions are satisfied.
Let $U_h\subseteq U$ denote a closed subspace. Set $F=Bu$. The Galerkin method reads: Find $u_h\in U_h$, such that
\begin{align*}
  b(u_h,v_h) = F(v_h) \quad\forall v_h \in V_h:=U_h.
\end{align*}
By Galerkin orthogonality, $b(u-u_h,v_h) = 0$ for all $v_h\in U_h$, it follows that $\eta(u_h) = 0$, hence, 
\begin{align*}
  \|u-u_h\|_U \eqsim \mu(w) = \sup_{0\neq v\in U} \frac{F(v-\Pi_h v)-b(u_h,v-\Pi_h v)}{\|v\|_U}.
\end{align*}
Depending on the problem under consideration, the latter term can be localized assuming certain regularity of the involved data and choosing $\Pi_h$ to be some quasi-interpolator. 
As an example, we mention mesh-size weighted
residual-based error estimation for second-order elliptic problems see, e.g.,~\cite{Verfuerth94}. 
\smallskip\\
\noindent\emph{Petrov--Galerkin method with optimal test functions.}
Suppose that $U_h\subset U$, $V_h\subset V$ are finite dimensional subspaces, set $F:=Bu$ and define
\begin{align*}
  u_h = \argmin_{w\in U_h} \|Bw-F\|_{V_h'} = \argmin_{w\in U_h} \eta(w).
\end{align*}
It is well known that the latter minimization problem admits a unique solution if there exists a Fortin operator $\Pi_h\colon V\to V_h$ satisfying $b(w,v-\Pi_h v) = 0$, for all $v\in V$ and $w\in U_h$, see~\cite{DPG_ActaNumerica}. Note that the existence of a Fortin operator also implies that
\begin{align*}
  \mu(w) &= \sup_{0\neq v\in V} \frac{F(v-\Pi_h v)-b(w,v-\Pi_h v)}{\|v\|_V} = \sup_{0\neq v\in V} \frac{F(v-\Pi_h v)}{\|v\|_V}
  \\
  &= \|F\circ(1-\Pi_h)\|_{V'} =: \osc(F).
\end{align*}
Therefore, $\mu(w)\neq 0$ in general, but it is independent of $w$. 
Finally, observe that
\begin{align*}
  \argmin_{w\in U_h} \eta(w)+\mu(w) = \argmin_{w\in U_h} \|Bw-F\|_{V_h'} + \mu(w) = \argmin_{w\in U_h} \|Bw-F\|_{V_h'} = u_h
\end{align*}
Summarizing these observations, we always have
\begin{align*}
  \|u - u_h\|_U \eqsim \eta(u_h) + \mu(u_h).
\end{align*}
In the FEM context, for Galerkin methods we have $\eta(u_h) = 0$, so the error depends solely on $\mu(u_h)$, while for MINRES (Petrov--Galerkin) methods, $\mu(u_h)$ is independent of $u_h$, and the error is typically governed by $\eta(u_h)$. However, in the general case where $U_h$ is not a finite element space, both contributions must be considered to ensure robust error estimations.
%
\subsection{Efficient computation of the lower bound}\label{sec:computelowerbound}
In this short section, we review a general approach for computing $\eta(w)$. To that end, let $\ip\cdot\cdot_{V_h}$ denote the inner product on $V_h$ that induces the norm $\|\cdot\|_{V_h}$, and define, for each $w\in U$, $\phi_h(w) \in V_h$ as the discrete Riesz representative of the residual; that is, the discrete function satisfying
\begin{align}\label{eq:rieszrep:discrete}
  \ip{\phi_h(w)}{v}_{V_h} = F(v)-b(w,v) \quad\forall v\in V_h.
\end{align}
Then, 
\begin{align*}
  \eta(w) = \sup_{0\neq v\in V_h} \frac{F(v)-b(w,v)}{\|v\|_{V_h}} 
  = \sup_{0\neq v\in V_h} \frac{F(v)-b(w,v)}{\|v\|_{V_h}}
  = \sup_{0\neq v\in V_h}  \frac{\ip{\phi_h(w)}{v}_{V_h}}{\|v\|_{V_h}}
  = \|\phi_h(w)\|_{V_h}.
\end{align*}
%
Let $v_1,\cdots,v_N$, with $N=\dim(V_h)$ denote a basis of $V_h$, and define the Riesz matrix $\bR\in\R^{N\times N}$ by
\begin{align*}
  \bR_{jk} = \ip{v_k}{v_j}_{V} \quad j,k=1,\ldots,N.
\end{align*}
Let $\bP\in\R^{N\times N}$ denote the Riesz matrix with respect to the $\ip\cdot\cdot_{V_h}$ inner product, i.e., 
\begin{align*}
  \bP_{jk} = \ip{v_k}{v_j}_{V_h} \quad j,k=1,\ldots,N.
\end{align*}
By the norm equivalence assumption~\eqref{eq:normequivV} we have that
\begin{align*}
  C_\mathrm{equiv}^{-2} \bx\cdot \bR\bx \leq \bx\cdot\bP\bx \leq C_\mathrm{equiv}^2 \bx\cdot \bR\bx
  \quad\forall \bx\in\R^N.
\end{align*}
This means that $\bR$ and $\bP$ are spectrally equivalent. In particular, their inverses $\bR^{-1}$ and $\bP^{-1}$ are symmetric positive definite matrices that are also spectrally equivalent.

To compute $\|\phi_h(w)\|_{V_h}$, it suffices to evaluate $\bP^{-1}$ on a single vector, 
\begin{align*}
  \|\phi_h(w)\|_{V_h}^2 = \br(w)\cdot\bP^{-1}\br(w), 
\end{align*}
where $\br(w)\in\R^N$ is the residual vector with entries $(\br(w))_j = F(v_j)-b(w,v_j)$, $j=1,\ldots,N$.
The computation of $\|\phi_h(w)\|_{V_h}$ is efficient if the action of $\bP^{-1}$ can be computed efficiently. Two relevant situations will be considered in this work:
First, when $\bR$ has a block-diagonal structure and each block can be efficiently inverted. In that case it suffices to set $\ip\cdot\cdot_{V_h} = \ip{\cdot}{\cdot}_V$, so that $\bP=\bR$. 
Second, the direct computation of $\bR^{-1}$ is impractical, but it can be efficiently approximated by a preconditioner matrix $\bP^{-1}$. 

\section{Notation and auxiliary results}\label{sec:notation}
In this section, we introduce notations for Lebesgue and Sobolev spaces, meshes and other relevant definitions together with some auxiliary results.
Let $\Omega\subset \R^d$, $d\geq 2$ denote a bounded Lipschitz domain with polytopal boundary $\Gamma:= \partial\Omega$.

\subsection{Volume and trace spaces}
For a fixed Banach space $X$, we denote by $L^p(\Omega;X)$, for $p\in[1,\infty]$, the Lebesgue space of functions with values in $X$. If $X=\R$, we simply write $L^p(\Omega)=L^p(\Omega;\R)$. 
The (standard) inner product on $L^2(\Omega)$ is denoted by $\ip{\cdot}\cdot_\Omega$, and the induced norm by $\|\cdot\|_\Omega$.
We also use the notation $\ip{\cdot}\cdot_\Omega$ and $\|\cdot\|_\Omega$ for the inner product and induced norm, respectively, in $L^2(\Omega;\R^d)$ and $L^2(\Omega;\R_\mathrm{sym}^{d\times d})$ where $\R_\mathrm{sym}^{d\times d}$ is the space of $\R$-valued symmetric matrices.
We use analogous notations for spaces defined over subdomains $\omega\subseteq\Omega$ or  $\omega\subseteq \Gamma$.

We denote by $H^1(\Omega)$ the Sobolev space of all $L^2(\Omega)$ functions whose first-order weak derivatives also belong to $L^2(\Omega)$. 
We equip this space with the norm
\begin{align*}
  \|u\|_{H^1(\Omega)} = \sqrt{\|\nabla u\|_\Omega^2 +\|u\|_\Omega^2} \quad\forall u\in H^1(\Omega).
\end{align*}
The space of all $L^2(\Omega;\R^d)$ functions whose weak divergence belongs to $L^2(\Omega)$ is denoted by $\Hdivset\Omega$ and we endow it with the norm
\begin{align*}
  \|\bsigma\|_{\Hdivset\Omega} = \sqrt{\|\div\bsigma\|_\Omega^2 + \|\bsigma\|_\Omega^2} \quad\forall \bsigma\in\Hdivset\Omega.
\end{align*}

Let us introduce the trace operators $\trgrad\Omega\colon H^1(\Omega) \to (\Hdivset\Omega)'$ and $\trdiv\Omega\colon \Hdivset\Omega\to (H^1(\Omega))'$, defined by
\begin{align*}
  \dual{\trgrad\Omega u}{\btau}_\Gamma &:= \ip{\div\btau}{u}_\Omega + \ip{\btau}{\nabla u}_\Omega, \\
  \dual{\trdiv\Omega \bsigma}{v}_\Gamma &:= \ip{\div\bsigma}v_\Omega + \ip{\bsigma}{\nabla v}_\Omega,
\end{align*}
for all $u,v\in H^1(\Omega)$, $\bsigma,\btau\in\Hdivset\Omega$. The corresponding trace spaces are defined as $H^{1/2}(\Gamma) := \ran(\trgrad\Omega)$, $H^{-1/2}(\Gamma) := \ran(\trdiv\Omega)$, and are endowed with the respective quotient norms
\begin{align*}
\|\widehat u\|_{1/2,\Gamma} &= \inf\set{\|u\|_{H^1(\Omega)}}{\trgrad\Omega u = \widehat u}, \\
\|\widehat \sigma\|_{-1/2,\Gamma} &= \inf\set{\|\bsigma\|_{\Hdivset\Omega}}{\trdiv\Omega \bsigma = \widehat \sigma}.
\end{align*}
Let us note that the trace spaces are in duality with each other. 
The following basic result provides a more explicit formulation of this fact. Its proof follows from the more general statement of~\cite[Lemma~2.2]{BreakingSpaces16}.
\begin{lemma}\label{lem:tracedualities}
  The following identities hold true for all $u\in H^1(\Omega)$, $\bsigma\in\Hdivset\Omega$:
  \begin{align*}
    \|\trgrad\Omega u\|_{1/2,\Gamma} &= \sup_{0\neq\widehat\tau\in H^{-1/2}(\Gamma)} \frac{\dual{\trgrad\Omega u}{\widehat\tau}_\Gamma}{\|\widehat\tau\|_{-1/2,\Gamma}} = \sup_{0\neq\btau \in \Hdivset\Omega} \frac{\dual{\trgrad\Omega u}{\btau}_\Gamma}{\|\btau\|_{\Hdivset\Omega}}, \\
    \|\trdiv\Omega \bsigma\|_{-1/2,\Gamma} &= \sup_{0\neq \widehat v \in H^{1/2}(\Gamma)} \frac{\dual{\trdiv\Omega\bsigma}{\widehat v}_\Gamma}{\|\widehat v\|_{1/2,\Gamma}} = \sup_{0\neq v \in H^1(\Omega)} \frac{\dual{\trdiv\Omega \bsigma}{v}_\Gamma}{\|v\|_{H^1(\Omega)}}.
  \end{align*}
\end{lemma}
Note that, by definition $\dual{\trgrad\Omega u}{\bsigma}_\Gamma = \dual{\trdiv\Omega\bsigma}u_\Gamma$. Therefore, for simplicity of notation, either term may be written as  $\dual{u}{\bsigma\cdot\normal}_\Gamma$ or $\dual{\bsigma\cdot\normal}u_\Gamma$ if the meaning is clear from the context. Here, $\normal$ denotes the exterior normal vector on $\Gamma$ pointing from $\Omega$ outwards.

We stress that $\trgrad\Omega$ can be identified with the classical trace operator $\gamma_0\colon H^1(\Omega) \to H^{1/2}(\Gamma)$ where $\gamma_0 u = u|_\Gamma$ for all $u$ in the dense subspace $C^\infty(\overline\Omega)$.
Furthermore, let $H^1(\Gamma)$ denote the space of $L^2(\Gamma)$ functions $u$ whose surface gradient $\nabla_\Gamma u$ is in $L^2(\Gamma;\R^d)$.

Finally, let $H_0^1(\Omega)$ denote the subspace of $H^1(\Omega)$ consisting of functions with vanishing trace. We endow this space with norm $\|\nabla\cdot\|_\Omega$, and note that, by Poincar\'e's inequality, 
\begin{align*}
  \|\nabla u\|_\Omega\eqsim \|u\|_{H^1(\Omega)} \quad\forall u\in H_0^1(\Omega). 
\end{align*}
The dual space $H^{-1}(\Omega) = (H_0^1(\Omega))'$ is equipped with the norm
\begin{align*}
  \|\phi\|_{H^{-1}(\Omega)} = \sup_{0\neq v\in H_0^1(\Omega)} \frac{\dual{\phi}{v}_\Omega}{\|\nabla v\|_\Omega} \quad\forall\phi\in H^{-1}(\Omega).
\end{align*}
We note that all duality brackets introduced are understood as continuously extended $L^2$ inner products.

\subsection{Meshes and mesh-dependent spaces}

\subsubsection{Volume mesh}
Let $\mesh$ denote a regular simplicial mesh of $\Omega$, and let $h_\mesh\in  L^\infty(\Omega)$ be the local mesh-size function defined by $h_\mesh|_T:=\diam(T)$ for each $T\in\mesh$.
The set of facets is denoted by $\faces_\mesh$. 
Let $P^k(T)$ denote the space of polynomials of degree $\leq k\in\N_0$ with domain $T\in\mesh$. The space of $\mesh$-piecewise polynomials is denoted by $P^k(\mesh)$. 
The $L^2(\Omega)$ projection onto $P^k(\mesh)$ is denoted by $\pi_\mesh^k$.
Let $J_{\mesh,0}^{k+1}\colon L^2(\Omega)\to P^{k+1}(\mesh)\cap H_0^1(\Omega)$ denote a Scott--Zhang-type projection operator with
\begin{align*}
  \|J_{\mesh,0}^{k+1}v\|_T &\lesssim \|v\|_{\Omega(T)}, \quad \|\nabla J_{\mesh,0}^{k+1} v\|_T \lesssim \|\nabla v\|_{\Omega(T)}, \\
  \|(1-J_{\mesh,0}^{k+1})v\|_T &\lesssim h_T \|\nabla v\|_{\Omega(T)},
\end{align*}
where, for each $T\in\mesh$, the patch $\Omega(T):=\set{T'\in\mesh}{\overline{T}\cap\overline{T'}\neq\emptyset}\subseteq \Omega$ denotes the domain associated with the vicinity of $T$.
Combining these estimates together with the inverse inequality $\|w\|_F^2\lesssim \|w\|_T(h_T^{-1}\|w\|_T+\|\nabla w\|_T)$ shows that 
\begin{align}\label{eq:sztraceest}
  \|v-J_{\mesh,0}^{k+1}v\|^2_F \lesssim \|v-J_{\mesh,0}^{k+1}v\|_{T}\|\nabla v\|_{\Omega(T)}
  \lesssim h_T\|\nabla v\|_{\Omega(T)}^2
\end{align}
for $F\in \faces_T$, with $\faces_T$ being the $d+1$ boundary faces of $T\in\mesh$.

We also work with the space of element bubble functions $P_b^k(\mesh) = \set{v}{v|_T = q\eta_{b,T} \text{ with }q\in P^k(T), T\in\mesh}$, where $\eta_{T,b}\in P^{d+1}(T)$ denotes the product of the $d+1$ barycentric coordinate function with non-vanishing support on $T\in\mesh$. 
\begin{lemma}\label{lem:szbubble}
  There exists $J_{\mesh,0,b}^{k+1,m}\colon L^2(\Omega) \to P^{k+1}(\mesh)\cap H_0^1(\Omega)+P_b^m(\mesh)$, such that
  \begin{align*}
    \|J_{\mesh,0,b}w\|_{T} &\lesssim \|w\|_{\Omega(T)}, \quad \|\nabla J_{\mesh,0,b}w\|_{T} \,\lesssim \|\nabla w\|_{\Omega(T)}, \\
    \|w-J_{\mesh,0,b}w\|_{T} + h_T\|\nabla (w-J_{\mesh,0,b}w)\|_{T}&\lesssim h_T^{k+n}\|D^{k+n} w\|_{\Patch(T)}, \quad k+n\geq 1,\forall T\in\mesh \\
    \ip{q_m}{w-J_{\mesh,0,b}w}_\Omega &= 0, \quad\forall q_m \in P^m(\mesh).
  \end{align*}
\end{lemma}
\begin{proof}
  For a proof of a similar result, we refer to, e.g.,~\cite[Proposition~4.1]{MSS24}.
\end{proof}
Furthermore, let $\RT{p}(\mesh)$ denote the Raviart--Thomas space of order $p\in\N_0$. We use the operator constructed in~\cite[Theorem~3.1]{MR4410735} which we denote by $\PiDivRT{p}$. It satisfies the boundedness estimate
  \begin{align*}
    \|\PiDivRT{p}\btau\|_{\Hdivset\Omega} \lesssim \|\btau\|_{\Hdivset\Omega} \quad\forall \btau\in\Hdivset\Omega.
  \end{align*}
%
\subsubsection{Boundary mesh}
Let $\faces$ denote a simplicial partition of $\Gamma$ with
(local) mesh-size function $h_\faces\in L^\infty(\Gamma)$. We assume that there exists a partition $\widetilde\mesh$ of $\Omega$, such that the restrictions of its elements to the boundary generate $\faces$. Note that, in particular, we might use the restrictions of the bulk mesh $\mesh$ to the boundary to define a partition $\faces$ of $\Gamma$. 

Let $J_\faces^{p+1}\colon L^2(\Gamma)\to P^{p+1}(\faces)\cap H^1(\Gamma)$ denote the Scott--Zhang-type operator constructed and analyzed in~\cite{AFKPP13}.
We stress that, for each $s\in[0,1]$, the operator $J_\faces^{p+1}$ is a bounded mapping from $H^s(\Gamma)$ to $H^s(\Gamma)$.
Further, it enjoys the following approximation property
\begin{align*}
  \|h_\faces^{-1/2}(w-J_\faces^{p+1}w)\|_{\Gamma} + \|w-J_\faces^{p+1}w\|_{H^{1/2}(\Gamma)} \lesssim 
  \|h_\faces^{1/2}\nabla_\Gamma w\|_\Gamma, \quad\forall w\in H^1(\Gamma)
\end{align*}
as well as (\cite[Proposition~3.1]{AFKPP13})
\begin{align}\label{eq:propszbou}
  \|h_\faces^{1/2}\nabla_\Gamma(1-J_\faces^{p+1})w\|_\Gamma \eqsim \|h_\faces^{1/2}(1-\pi_\faces^p)\nabla_\Gamma w\|_\Gamma,
  \quad\forall w\in H^1(\Gamma).
\end{align}
%
\subsubsection{Mesh-dependent spaces}
Consider the broken space
\begin{align*}
  H^1(\mesh) &= \set{v\in L^2(\Omega)}{v|_T\in H^1(T), T\in\mesh},
  \end{align*}
equipped with the (squared) norm
\begin{align*}
  \|v\|_{H^1(\mesh)}^2 &= \|\nabla_\mesh v\|_\Omega^2 + \|v\|_\Omega^2 := \sum_{T\in\mesh} \|\nabla v\|_T^2 + \|v\|_T^2, \quad v\in H^1(\mesh).
\end{align*}
Define the trace operator $\trdiv{\mesh}\colon \Hdivset\Omega\to H^1(\mesh)'$ by
\begin{align*}
  \dual{\trdiv\mesh\btau}{v}_{\partial\mesh}:=\dual{v}{\btau\cdot\normal}_{\partial\mesh}:= \sum_{T\in\mesh} \ip{\div\btau}{v}_T + \ip{\btau}{\nabla_\mesh v}_\Omega, \quad\btau\in\Hdivset\Omega, v\in H^1(\mesh).
\end{align*}
Set $H^{-1/2}(\partial\mesh):= \ran(\trdiv\mesh)$, and equip this space with the canonical quotient norm, denoted by $\|\cdot\|_{-1/2,\partial\mesh}$. 
Similar to Lemma~\ref{lem:tracedualities}, the following trace duality result holds, see also~\cite[Lemma~2.2]{BreakingSpaces16} in the context of discontinuous Petrov--Galerkin methods.
\begin{lemma}\label{lem:traceduality:broken}
\begin{align*}
  \|\lambda\|_{-1/2,\partial\mesh} = \sup_{0\neq v\in H^1(\mesh)} \frac{\dual{\lambda}{v}_{\partial\mesh}}{\|v\|_{H^1(\mesh)}}, \quad\forall \lambda\in H^{-1/2}(\partial\mesh).
\end{align*}
\end{lemma}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{A second-order elliptic problem}\label{sec:modelpoisson}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
As a model problem, we consider the second-order elliptic problem
\begin{subequations}\label{eq:modelPDE}
\begin{alignat}{2}
  -\div\bA\nabla u + \bbeta\cdot\nabla u + c u &= f &\quad&\text{in }\Omega, \\
  u &= g &\quad&\text{on } \Gamma := \partial\Omega.
\end{alignat}
\end{subequations}
Here, $\bA \in L^\infty(\Omega;\R^{d\times d}_\mathrm{sym})$ with uniformly bounded below eigenvalues, $\bbeta\in L^\infty(\Omega;\R^d)$, $\div\bbeta\in L^\infty(\Omega)$, and $c\in L^\infty(\Omega)$ with $-\tfrac12\div\bbeta + c \geq 0$.
We stress that, under the above assumptions, the weak formulation
\begin{align}\label{eq:weakform}
\begin{split}
  \ip{\bA\nabla u}{\nabla v}_\Omega + \ip{\bbeta\cdot\nabla u}{v}_\Omega + \ip{cu}v_\Omega &= \ip{f}v_\Omega
  \quad\forall v\in H_0^1(\Omega), 
  \\
  u|_\Gamma &= g,
\end{split}
\end{align}
admits a unique solution $u\in H^1(\Omega)$, given $f\in H^{-1}(\Omega)$ and $g\in H^{1/2}(\Gamma)$. 
In order to be able to localize residual contributions, we further assume throughout this article that
\begin{align*}
  \nabla(\bA)_{jk}\in L^\infty(\Omega,\R^d), \, j,k=1,\ldots,d, 
  \quad
  f\in L^2(\Omega), g\in H^1(\Gamma).
\end{align*}
In what follows, we discuss three formulations of the latter PDE, the weak formulation~\eqref{eq:weakform} (Section~\ref{sec:weakform}), another one based on broken test spaces (Section~\ref{sec:brokenform}), and a strong formulation (Section~\ref{sec:strongform}).
For all cases, we can write $V = V_\Omega\times V_\Gamma$ so that the operator $B\colon U\to V'\equiv V_\Omega'\times V_\Gamma'$ can be written as the sum of two operators, say, $B = B_\Omega+B_\Gamma$ with $B_\Omega\colon U\to V_\Omega'$ and $B_\Gamma\colon U\to V_\Gamma'$. In a similar fashion, we decompose $F = F_\Omega + F_\Gamma$.
In particular, $V_\Gamma = H^{-1/2}(\Gamma)$ or $V_\Gamma = \Hdivset\Omega$ (both choices are equivalent by Lemma~\ref{lem:tracedualities}) and $B_\Gamma = \trgrad\Omega$ (see Section~\ref{sec:notation}).
In any case, we have the abstract form
\begin{align*}
  \|u-w\|_U \eqsim \|F_\Omega -B_\Omega w\|_{V_\Omega'} + \|F_\Gamma - B_\Gamma w\|_{V_\Gamma'}.
\end{align*}
Note that, by our abstract framework from section~\ref{sec:abstract} (Corollary~\ref{cor:equivest}), we can treat both terms on the right-hand side independently.
We start by discussing the boundary trace term in Section~\ref{sec:boucond}.
The volume residual will be handled in sections~\ref{sec:weakform}--\ref{sec:strongform}.

\subsection{Boundary estimators}\label{sec:boucond}
Let $B_\Gamma = \trgrad\Omega$. In view of the observations from Section~\ref{sec:abstract}, the goal is to define estimators $\eta_\Gamma$ and $\rho_\Gamma$ such that
\begin{align}\label{eq:bouequiv}
  \eta_\Gamma(w) \lesssim \|B_\Gamma w-g\|_{V_\Gamma'} \lesssim \eta_\Gamma(w) + \rho_\Gamma(w).
\end{align}
In what follows, we discuss various alternatives for deriving such estimates. The first option is based on using $\Hdivset\Omega$ to define the trace norm, and this representation was proposed and utilized in~\cite{MSS_QOLS24}.
The second one uses $H^{-1/2}(\Gamma)$ and its use in MINRES methods was analyzed in~\cite{MSS24}.
To simplify notation, we write $w$ or $w|_\Gamma$ instead of $B_\Gamma w$.

\subsubsection{First option}\label{sec:boucond:opt1}
For the first alternative we set $V_\Gamma = \Hdivset\Omega$ and recall from Lemma~\ref{lem:tracedualities} that
\begin{align*}
  \|\cdot\|_{1/2,\Gamma} = \sup_{0\neq \btau\in\Hdivset\Omega} \frac{\dual{\cdot}\btau_\Gamma}{\|\btau\|_{\Hdivset\Omega}}.
\end{align*}
We choose $V_{\Gamma,\widetilde\mesh} = \RT{p}(\widetilde\mesh)$ and recall that the boundary mesh $\faces$ is defined as the restriction of the volume mesh $\widetilde\mesh$ to the boundary. For all $w\in H^1(\Omega)$ with $w|_\Gamma\in H^1(\Gamma)$ set
\begin{subequations}\label{eq:defetarhobou1}
\begin{align}
  \eta_\Gamma(w) &= \sup_{0\neq \btau\in V_{\Gamma,\widetilde\mesh}} \frac{\dual{w-g}\btau_\Gamma}{\|\btau\|_{\Hdivset\Omega}}, \\
  \rho_\Gamma(w) &= \begin{cases}
    \|h_{\faces}^{1/2}\nabla_\Gamma(w-g)\|_\Gamma & p=0, \\
    \|h_{\faces}^{1/2}(1-\pi_\faces^{p-1})\nabla_\Gamma(w-g)\|_\Gamma & p>0.
  \end{cases}
\end{align}
\end{subequations}


\begin{lemma}\label{lem:bouest1}
  Suppose that $\eta_\Gamma$ and $\rho_\Gamma$ are defined as in~\eqref{eq:defetarhobou1}. Then, inequalities~\eqref{eq:bouequiv} are satisfied for all $g\in H^1(\Gamma)$ and $w\in H^1(\Omega)$ with $w|_\Gamma\in H^1(\Gamma)$.
\end{lemma}
\begin{proof}
  In view of the previously established abstract results, we define a bounded linear operator $\Pi_\mesh\colon V_\Gamma \to V_{\Gamma,\mesh}$.
  First, we consider $p>0$. 
  Let $\btau\in\Hdivset\Omega$ be given. Note that $J_{\faces}^p$ is bounded in $H^{1/2}(\Gamma)$ and its dual $(J_{\faces}^p)'$ is therefore bounded in $H^{-1/2}(\Gamma)$. One also verifies that the range of the dual operator is in $P^p(\faces)$.
  Let $\btau\in \Hdivset\Omega$ be given and define $\widetilde\btau\in\Hdivset\Omega$ as the unique solution to
  \begin{align*}
    -\nabla\div\widetilde\btau + \widetilde\btau &= 0, \quad \trdiv\Omega\widetilde\btau = (J_{\faces}^p)'\trdiv\Omega\btau.
  \end{align*}
  Set $\Pi_{\widetilde\mesh} \btau:= \PiDivRTtilde{p}\widetilde\btau$. Then,
  \begin{align*}
    \|\Pi_{\widetilde\mesh} \btau\|_{\Hdivset\Omega} &\lesssim \|\widetilde\btau\|_{\Hdivset\Omega} \lesssim \|(J_{\faces}^p)'\trdiv\Omega\btau\|_{H^{-1/2}(\Gamma)} \lesssim \|\trdiv\Omega\btau\|_{H^{-1/2}(\Gamma)} \lesssim \|\btau\|_{\Hdivset\Omega} 
  \end{align*}
  which means that $\Pi_{\widetilde\mesh}$ is a bounded operator. 
  Further, 
  \begin{align*}
    |\dual{w-g}{\trdiv\Omega(\btau-\Pi_{\widetilde\mesh}\btau)}_\Gamma| &= |\dual{w-g}{(1-(J_{\faces}^p)')\trdiv\Omega\btau}_\Gamma|
    = |\dual{(1-J_{\faces}^p)(w-g)}{\trdiv\Omega\btau}_\Gamma|\\
    &\lesssim \|(1-J_{\faces}^p)(w-g)\|_{1/2,\Gamma}\|\trdiv\Omega\btau\|_{-1/2,\Gamma} \\
    &\lesssim \|h_{\faces}^{1/2}\nabla_\Gamma(1-J_{\faces}^p)(w-g)\|_\Gamma \|\btau\|_{\Hdivset\Omega}.
  \end{align*}
  The last estimates and~\eqref{eq:propszbou} show that
  \begin{align*}
  \sup_{0\neq \btau\in\Hdivset\Omega} \frac{\dual{w-g}{\trdiv\Omega(\btau-\Pi_{\widetilde\mesh}\btau)}_\Gamma}{\|\btau\|_{\Hdivset\Omega}}
  &\lesssim \|h_{\faces}^{1/2}\nabla_\Gamma(1-J_{\faces}^p)(w-g)\|_\Gamma
    \\
    &\eqsim \|h_\faces^{1/2}(1-\pi_\faces^{p-1})\nabla_\Gamma(w-g)\|_\Gamma
    = \rho_\Gamma(w),
  \end{align*}
  which completes the proof for $p>0$. The case $p=0$ is slightly more technical, but follows similar arguments.
  Instead of the operator $J_{\faces}^p$, we consider $J_{\faces}^1\pi_{\faces}^0$. We stress that one can show that this operator is bounded in $H^{1/2}(\Gamma)$, and its dual has range in $P^0(\faces)$. Moreover,
  \begin{align*}
    \|(1-J_{\faces}^1\pi_{\faces}^0)(w-g)\|_{H^{1/2}(\Gamma)} \lesssim \|h_{\faces}^{1/2}\nabla_\Gamma(w-g)\|_\Gamma.
  \end{align*}
  Following the same arguments as in the case $p>0$ concludes the proof.
\end{proof}

\begin{remark}
  The efficient computation of $\eta_\Gamma(w)$ requires a spectrally equivalent preconditioner (Section~\ref{sec:computelowerbound}). 
  Efficient preconditioners for $\Hdivset\Omega$ are known in the literature (see, e.g.,~\cite{Hiptmair97}).
\end{remark}

\subsubsection{Second option}\label{sec:boucond:opt2}
For the second alternative we set $V_\Gamma = H^{-1/2}(\Gamma)$ and recall from Lemma~\ref{lem:tracedualities} that
\begin{align*}
  \|\cdot\|_{1/2,\Gamma} = \sup_{0\neq \mu\in  H^{-1/2}(\Gamma)} \frac{\dual{\cdot}\mu_\Gamma}{\|\mu\|_{-1/2,\Gamma}}.
\end{align*}
We choose $V_{\Gamma,\faces} = P^p(\faces)$ and set for all $w\in H^1(\Omega)$ with $w|_\Gamma\in H^1(\Gamma)$
\begin{subequations}\label{eq:defetarhobou2}
\begin{align}
  \eta_\Gamma(w) &= \sup_{0\neq \btau\in V_{\Gamma,\faces}} \frac{\dual{w-g}\mu_\Gamma}{\|\mu\|_{-1/2,\Gamma}}, \\
  \rho_\Gamma(w) &= \begin{cases}
    \|h_{\faces}^{1/2}\nabla_\Gamma(w-g)\|_\Gamma & p=0, \\
    \|h_{\faces}^{1/2}(1-\pi_\faces^{p-1})\nabla_\Gamma(w-g)\|_\Gamma & p>0.
  \end{cases}
\end{align}
\end{subequations}
Note that the definitions~\eqref{eq:defetarhobou2} are similar to~\eqref{eq:defetarhobou1}. The difference is that since we only need to consider discretizations of spaces defined over the manifold $\Gamma$ instead of $\Omega$, though at the price of dealing with a fractional norm.

\begin{lemma}\label{lem:bouest2}
  Suppose that $\eta_\Gamma$ and $\rho_\Gamma$ are defined as in~\eqref{eq:defetarhobou2}. Then, inequalities~\eqref{eq:bouequiv} are satisfied for all $g\in H^1(\Gamma)$ and $w\in H^1(\Omega)$ with $w|_\Gamma\in H^1(\Gamma)$.
\end{lemma}
\begin{proof}
  In the proof of Lemma~\ref{lem:bouest1} the operator $\Pi_{\widetilde\mesh}$ is constructed. By taking the normal trace of this operator to define $\Pi_{\Gamma,\faces}\colon V_\Gamma\to V_{\Gamma,\faces}$, we can follow the same lines of arguments.
  We omit further details. 
\end{proof}

The evaluation of $\eta_\Gamma(w)$ requires the evaluation of the $H^{-1/2}(\Gamma)$ inner product on $V_{\Gamma,\faces} = P^p(\faces)$. 
We note the following equivalence (see, e.g.,~\cite[p.215]{MultilevelNorms}). 
\begin{lemma}
  \begin{align*}
  \|\phi\|_{-1/2,\Gamma} \eqsim \|\pi_\faces^0\phi\|_{-1/2,\Gamma} + \|h_\faces^{1/2}(1-\pi_\faces^0)\phi\|_\Gamma 
  \quad\forall \phi \in P^p(\faces).
\end{align*}
\end{lemma}
%
Based on the aforementioned equivalence, it suffices to focus on the fast evaluation of $ \|\pi_\faces^0 \phi\|_{-1/2, \Gamma}$ to compute $\eta_\Gamma$ efficiently.  
Optimal preconditioners for piecewise constant functions in negative Sobolev spaces include multilevel preconditioners (see, e.g.,~\cite{MultilevelNorms,STBook21}), as well as operator preconditioners (see, e.g.,~\cite{MR4044445}).
%
\subsubsection{Third option}\label{sec:boucond:opt3} 
%
As a third alternative, instead of working with definitions given by dual norms, we may directly work with the interpolation norm on trace space $H^{1/2}(\Gamma)$. 
Define for $p\in\N_0$
\begin{subequations}\label{eq:defetarhobou3}
\begin{align}
  \eta_\Gamma(w) &= \|J_\faces^{p+1}(w-g)\|_{1/2,\Gamma} \\
  \rho_\Gamma(w) &= \|h_\faces^{1/2}(1-\pi_\faces^p)\nabla_\Gamma(w-g)\|_\Gamma
\end{align}
\end{subequations}
for all $w\in H^1(\Omega)$ with $w|_\Gamma\in H^1(\Gamma)$.

\begin{lemma}\label{lem:bouest3}
  Suppose that $\eta_\Gamma$ and $\rho_\Gamma$ are defined as in~\eqref{eq:defetarhobou3}. Then,
  inequalities~\eqref{eq:bouequiv} are satisfied
  for all $g\in H^1(\Gamma)$ and $w\in H^1(\Omega)$, with $w|_\Gamma\in H^1(\Gamma)$.
\end{lemma}
\begin{proof}
  This simply follows from the triangle inequality and properties of the operator $J_\faces^{p+1}$.
\end{proof}

For the fast evaluation of $\eta_\Gamma$, we note that efficient preconditioners in $H^{1/2}(\Gamma)$ are well established (see, e.g.,~\cite{STBook21,MR4094780}).
\begin{remark}\label{rem:investbou}
  Using an inverse estimate and boundedness of $J_\faces^{p+1}$ one gets that
  \begin{align*}
    \eta_\Gamma(w) &= \|J_\faces^{p+1}(w-g)\|_{1/2,\Gamma} \lesssim \|h_\faces^{-1/2}J_\faces^{p+1}(w-g)\|_\Gamma
    \lesssim \|h_\faces^{-1/2}(w-g)\|_\Gamma.
  \end{align*}
  Replacing $\eta_\Gamma$ by the weighted $L^2(\Gamma)$ norm $\|h_\faces^{-1/2}(w-g)\|_\Gamma$ is a common technique in least-squares (based) finite element methods~\cite{BG09} to avoid dealing with non-local fractional norms.
  We emphasize that the weighted norm is not equivalent to $\eta_\Gamma(w)$. 
  However, it can be used as an upper bound in combination with $\rho_\Gamma(w)$ since
  \begin{align*}
    \|w-g\|_{1/2,\Gamma} \lesssim \eta_\Gamma(w) + \rho_\Gamma(w) \lesssim \|h_\faces^{-1/2}(w-g)\|_\Gamma +\|h_\faces^{1/2}(1-\pi_\faces^p)\nabla_\Gamma(w-g)\|_\Gamma.
  \end{align*}
\end{remark}

\subsection{Weak formulation}\label{sec:weakform}
We consider the weak formulation~\eqref{eq:weakform} of the model problem~\eqref{eq:modelPDE}. Define $U = H^1(\Omega)$, $V_\Omega = H_0^1(\Omega)$. Define the operator $B_\Omega \colon U \to V_\Omega'$ to represent the left-hand side of~\eqref{eq:weakform} and let $F_\Omega\in V_\Omega'$ be the right-hand side, i.e., 
\begin{align*}
  (B_\Omega w)(v) &:= b_\Omega(w,v) := \ip{\bA\nabla u}{\nabla v}_\Omega + \ip{\bbeta\cdot\nabla u+c u}{v}_\Omega, \\
  F_\Omega(v) &:= \ip{f}v_\Omega
\end{align*}
for all $w\in U$, $v\in V_\Omega$.
From well-posedness of the weak formulation~\eqref{eq:weakform} it follows that
\begin{align*}
  \|u-w\|_U \eqsim \|F_\Omega-B_\Omega w\|_{V_\Omega'} + \|F_\Gamma-B_\Gamma w\|_{V_\Gamma'}, 
\end{align*}
with $F_\Gamma$, $B_\Gamma$ and $V_\Gamma$ as discussed in Section~\ref{sec:boucond} above.
%
We consider two choices of discrete test spaces.
%
\subsubsection{Lagrange FEM test space}\label{sec:lagrangefem}
We choose $V_{\Omega,\mesh} = P^{k+1}(\mesh)\cap H_0^1(\Omega)$ and set, for all $w\in H^1(\Omega)$ such that $\div\bA\nabla w|_T\in L^2(T)$ for all $T\in\mesh$, 
\begin{subequations}\label{eq:defWeakFormEstimators}
\begin{align}
  \eta_{\Omega}(w) &= \sup_{0\neq v\in V_{\Omega,\mesh}} \frac{\ip{f}{v}_\Omega-b_\Omega(w,v)}{\|\nabla v\|_{\Omega}},
  \\
  \rho_{\Omega}(w)^2 &= \sum_{T\in\mesh}h_T^2\|f+\div\bA\nabla w-\bbeta\cdot\nabla w-cw\|_T^2
  + h_T\|\jump{\bA\nabla w\normal}\|_{\partial T\setminus\Gamma}^2, \\
  \eta(w)^2 &= \eta_\Omega(w)^2 + \eta_\Gamma(w)^2, \\
  \rho(w)^2 &= \rho_\Omega(w)^2 + \rho_\Gamma(w)^2.
\end{align}
\end{subequations}
Here, $(\eta_\Gamma$, $\rho_\Gamma)$ denote any of the options described in Section~\ref{sec:boucond}.

\begin{theorem}\label{thm:lagrangeFEM}
  Under the aforegoing definitions~\eqref{eq:defWeakFormEstimators} and assumptions, the estimates
  \begin{align*}
    \eta(w) \lesssim \|u-w\|_{H^1(\Omega)} \lesssim \eta(w) + \rho(w).
  \end{align*}
  hold for all $w\in H^1(\Omega)$, with $\div\bA\nabla w|_T\in L^2(T)$, $T\in\mesh$.
\end{theorem}
\begin{proof}
  We only need to show that
  \begin{align}
    \eta_\Omega(w) \lesssim \|F_\Omega - B_\Omega w\|_{V_\Omega'} \lesssim \eta_\Omega(w) + \rho_\Omega(w).
  \end{align}
  First observe that $\Pi_\mesh:= J_{\mesh,0}^{k+1}$ is bounded in $V_\Omega = H_0^1(\Omega)$. Therefore, by the considerations from Section~\ref{sec:abstract}, the lower bound follows. 
  For the upper bound, we set $\widetilde v = v-J_{\mesh,0}^{k+1}v$ and use integration by parts to obtain
  \begin{align*}
    |F_\Omega(\widetilde v)-b_\Omega(w,\widetilde v)| &= \left\lvert\sum_{T\in\mesh}\ip{f+\div\bA\nabla w-\bbeta\cdot\nabla w -cw}{\widetilde v}_T
    -\dual{\bA\nabla w\normal}{\widetilde v}_{\partial T}\right\rvert.
  \end{align*}
  Then, using the (local) approximation properties of the quasi-interpolator and the Cauchy--Schwarz estimate we find that
  \begin{align*}
    &\sum_{T\in\mesh}|\ip{f+\div\bA\nabla w-\bbeta\cdot\nabla w -cw}{\widetilde v}_T| \\&\qquad\lesssim 
    \left(\sum_{T\in\mesh}h_T^2\|f+\div\bA\nabla w-\bbeta\cdot\nabla w -cw\|_T^2\right)^{1/2}\|v\|_{H^1(\Omega)}.
  \end{align*}
  Finally, similar arguments prove that
  \begin{align*}
    \left\vert\sum_{T\in\mesh}\dual{\bA\nabla w\normal}{\widetilde v}_{\partial T}\right\rvert &= \left\lvert\sum_{F\in\faces_\mesh^0} \dual{\jump{\bA\nabla w\normal}}{\widetilde v}_{F}\right\rvert 
    \lesssim \left(\sum_{T\in\mesh} h_T\|\jump{\bA\nabla w\normal}\|_{\partial T\setminus\Gamma}^2\right)^{1/2}\|v\|_{H^1(\Omega)}.
  \end{align*}
  Overall, we have shown that
  \begin{align*}
    \sup_{0\neq v\in V_\Omega} \frac{F_\Omega(v-\Pi_\mesh v)-b_\Omega(w,v-\Pi_\mesh v)}{\|v\|_{V_\Omega}}\lesssim \rho_\Omega(w),
  \end{align*}
  which concludes the proof.
\end{proof}

\begin{remark}\label{rem:weakformsmooth}
  Note that if $w$ is sufficiently smooth, e.g., if $w\in H^2(\Omega)$, then $\div\bA\nabla w\in L^2(\Omega)$ by our assumptions on $\bA$, so that the jump terms in the estimator contribution $\rho_\Omega(w)$ vanish.
  This regularity is ensured, for instance, when $w$ is the output of a neural network with smooth activation functions.
\end{remark}

\begin{remark}\label{rem:etaOmegaPrecond}
  In view of efficient computation of $\eta_\Omega$ as discussed in Section~\ref{sec:computelowerbound}, we note that many optimal preconditioners exist for this problem, e.g., the BPX preconditioner or other multilevel techniques, see~\cite{Oswald94}.
\end{remark}

\subsubsection{Bubble enriched test space}\label{sec:weakform:bubbleEnriched}
We choose $V_{\Omega,\mesh} = P^{k+1}(\mesh)\cap H_0^1(\Omega)+P_b^m(\mesh)$ and set for all $w\in H^1(\Omega)$ with $\div\bA\nabla w|_T\in L^2(T)$ for all $T\in\mesh$, 
\begin{subequations}\label{eq:defWeakFormBubbleEstimators}
\begin{align}
  \eta_{\Omega}(w) &= \sup_{0\neq v\in V_{\Omega,\mesh}} \frac{\ip{f}{v}_\Omega-b_\Omega(w,v)}{\|\nabla v\|_{\Omega}}
  \\
  \rho_{\Omega}(w)^2 &= \sum_{T\in\mesh}h_T^2\|(1-\pi_\mesh^m)(f+\div\bA\nabla w-\bbeta\cdot\nabla w-cw)\|_T^2
  + h_T\|\jump{\bA\nabla w\normal}\|_{\partial T\setminus\Gamma}^2, \\
  \eta(w)^2 &= \eta_\Omega(w)^2 + \eta_\Gamma(w)^2, \\
  \rho(w)^2 &= \rho_\Omega(w)^2 + \rho_\Gamma(w)^2.
\end{align}
\end{subequations}
Here, $(\eta_\Gamma$, $\rho_\Gamma)$ denote any of the options described in Section~\ref{sec:boucond}.

\begin{theorem}
  Under the aforegoing definitions~\eqref{eq:defWeakFormBubbleEstimators} and assumptions, the estimates
  \begin{align*}
    \eta(w) \lesssim \|u-w\|_{H^1(\Omega)} \lesssim \eta(w) + \rho(w)
  \end{align*}
  hold for all $w\in H^1(\Omega)$, with $\div\bA\nabla w|_T\in L^2(T)$, $T\in\mesh$.
\end{theorem}
\begin{proof}
  The proof follows the same argumentation as the proof of Theorem~\ref{thm:lagrangeFEM}. 
  The only difference is that we use the operator $\Pi_\mesh = J_{\mesh,0,b}^{k+1,m}$, which allows us to write, for each $T\in\mesh$, the volume residual term as (see Lemma~\ref{lem:szbubble})
  \begin{align*}
    \ip{f+\div\bA\nabla w-\bbeta\cdot\nabla w -cw}{v-\Pi_\mesh v}_T = \ip{(1-\pi_\mesh^m)(f+\div\bA\nabla w-\bbeta\cdot\nabla w -cw)}{v-\Pi_\mesh v}_T.
  \end{align*}
The remaining estimates follow verbatim as in the proof of Theorem~\ref{thm:lagrangeFEM}.
\end{proof}
Remarks~\ref{rem:weakformsmooth} and~\ref{rem:etaOmegaPrecond} apply here as well.
Note that the main difference compared to Section~\ref{sec:lagrangefem} is the presence of the operator $(1-\pi_\mesh^m)$ in the definition of $\rho_\Omega$. This modification reduces the magnitude of the term $\rho_\Omega$, and thus yields a tighter upper bound. 

\subsection{Weak formulation with broken test space}\label{sec:brokenform}
The evaluation of $\eta_\Omega(w)$ for the formulations based on the weak formulation, as described in Section~\ref{sec:weakform} requires inverting the Riesz matrix associated with (discrete) subspaces of $H_0^1(\Omega)$, or alternatively, evaluating appropriate preconditioners (see Remark~\ref{rem:etaOmegaPrecond}). 
This motivates the study of formulations with broken test spaces, which enable a more efficient realization of the Riesz matrix inversion.
%
For the broken formulation that we study here, we use 
\begin{align*}
  U = H^1(\Omega)\times H^{-1/2}(\partial\mesh), \quad V_\Omega = H^1(\mesh).
\end{align*}
We define the bilinear form $B_\Omega\colon U\to V_\Omega'$ and functional $F_\Omega\in V_\Omega'$ for all $(u,\lambda)\in U$, $v\in V_\Omega$ by
\begin{align*}
  B_\Omega(u,\lambda;v) &:= \ip{\bA\nabla u}{\nabla_\mesh v}_\Omega + \ip{\bbeta\cdot\nabla u+cu}v_\Omega
  - \dual{\lambda}{v}_{\partial\mesh}, \\
  F_\Omega(v) &:= \ip{f}{v}_\Omega.
\end{align*}
%
For the proof of the following result, we use techniques from~\cite{PrimalDPG13,BreakingSpaces16}.
\begin{lemma}\label{lem:broken}
  The equivalence 
  \begin{align*}
    \|(w,\lambda)\|_U \eqsim \|B_\Omega(w,\lambda)\|_{V_\Omega'} + \|w\|_{1/2,\Gamma}
  \end{align*}
  holds for all $w\in H^1(\Omega)$, and $\lambda\in H^{-1/2}(\partial\mesh)$. In particular, if additionally $\div\bA\nabla w\in L^2(\Omega)$ and $u\in H^1(\Omega)$ is the (unique) solution of~\eqref{eq:weakform}, then
  \begin{align*}
    \|(u,\trdiv\mesh\bA\nabla u)-(w,\trdiv\mesh\bA\nabla w)\|_U \eqsim \|F_\Omega - B_\Omega(w,\lambda)\|_{V_\Omega'} + \|F_\Gamma-B_\Gamma w\|_{V_\Gamma'},
  \end{align*}
  where $B_\Gamma$, $F_\Gamma$ and $V_\Gamma$ are as in Section~\ref{sec:boucond}.
\end{lemma}
\begin{proof}
  The second asserted equivalence follows directly from the first. To establish the first one, let $(w,\lambda)\in U$ be given. Define $\widetilde w\in H^1(\Omega)$ as the solution of~\eqref{eq:weakform} with $f=0$ and $g=w|_\Gamma$. One verifies that $\widetilde\lambda:= \trdiv\mesh\bA\nabla \widetilde w \in H^{-1/2}(\partial\mesh)$.
  In particular, $(\widetilde w,\widetilde\lambda)\in U$ and, by construction, $B_\Omega(\widetilde w,\widetilde\lambda)=0$. Observe further that $w-\widetilde w\in H_0^1(\Omega)$. Thus, by~\cite{PrimalDPG13}, it follows that
  \begin{align*}
    \|(w-\widetilde w,\lambda-\widetilde\lambda)\|_U \eqsim \|B_\Omega(w-\widetilde w,\lambda-\widetilde\lambda)\|_{V_\Omega'} = \|B_\Omega(w,\lambda)\|_{V_\Omega'}.
  \end{align*}
  Noting that $\|(\widetilde w,\widetilde\lambda)\|_U \lesssim \|\widetilde w\|_{H^1(\Omega)} \lesssim \|w\|_{1/2,\Gamma}$, and applying the triangle inequality, proves that
  \begin{align*}
    \|(w,\lambda)\|_U \leq \|(w-\widetilde w,\lambda-\widetilde\lambda)\|_U + \|(\widetilde w,\widetilde\lambda)\|_U 
    \lesssim \|B_\Omega(w,\lambda)\|_{V_\Omega'} + \|w\|_{1/2,\Gamma}.
  \end{align*}
  The right-hand side is bounded by $\|(w,\lambda)\|_U$ since $B_\Omega$ is bounded and the trace operator $H^1(\Omega)\to H^{1/2}(\Gamma)$ is bounded. This finishes the proof.
\end{proof}
We choose $V_{\Omega,\mesh} = P^k(\mesh)$ for some $k\in\N_0$ and set, for all $w\in H^1(\Omega)$ with $\bA\nabla w\in \Hdivset\Omega$, 
\begin{subequations}\label{eq:defBrokenWeakFormEstimators}
  \begin{align}
    \eta_\Omega(w) &= \sup_{0\neq v\in V_{\Omega,\mesh}} \frac{\ip{f}v_\Omega-b_\Omega(w,v)}{\|v\|_V}, \\
    \rho_\Omega(w)^2 &= \sum_{T\in\mesh} h_T^2\|(1-\pi_\mesh^k)(f+\div\bA\nabla w-\bbeta\cdot\nabla w-cw)\|_T^2, \\
    \eta^2 &= \eta_\Omega^2 + \eta_\Gamma^2, \\
    \rho^2 &= \rho_\Omega^2 + \rho_\Gamma^2.
\end{align}
\end{subequations}
Here, $(\eta_\Gamma$, $\rho_\Gamma)$ denote any of the options described in Section~\ref{sec:boucond}.

\begin{theorem}\label{thm:equivest:brokenweak}
  Under the aforegoing definitions~\eqref{eq:defBrokenWeakFormEstimators} and assumptions, the estimates
  \begin{align*}
\eta(w) \lesssim \|u-w\|_{H^1(\Omega)} + \|\trdiv\mesh\bA\nabla u - \trdiv\mesh\bA\nabla w\|_{-1/2,\partial\mesh} \lesssim \eta(w) + \rho(w)
  \end{align*}
  hold for all $w\in H^1(\Omega)$, with $\bA\nabla w\in \Hdivset\Omega$.
\end{theorem}
\begin{proof}
  Based on Corollary~\ref{cor:equivest} and our previous considerations from Section~\ref{sec:boucond}, it only remains to show that
  \begin{align*}
    \|(F_\Omega-B_\Omega (w,\trdiv\mesh\bA\nabla w))\circ(1-\Pi_{\mesh})\|_{V_{\Omega}'} \lesssim \rho(w)
  \end{align*}
  for some bounded operator $\Pi_{\mesh}\colon V\to V_{\Omega,\mesh}$. Choosing $\Pi_{\mesh} = \pi_\mesh^k$ (which can be easily seen to be bounded), and employing integration by parts along with the definition of the trace operator, we see that
  \begin{align*}
    &F_\Omega(v-\pi_\mesh^k v) -b_\Omega( (w,\trdiv\mesh\bA\nabla w),v-\pi_\mesh^kv) \\
    &\qquad = \ip{f}{v-\pi_\mesh^k v} 
    \\
    &\qquad\qquad-\Big( \ip{\bA\nabla w}{\nabla_\mesh (v-\pi_\mesh^k v)}_\Omega + \ip{\bbeta\cdot\nabla w+cw}{v-\pi_\mesh^k v}_\Omega 
    -\dual{\trdiv\mesh\bA\nabla w}{v-\pi_\mesh^k v}_{\partial\mesh}\Big)
    \\
    &\qquad = \ip{f+\div\bA\nabla w-\bbeta\cdot\nabla w-cw}{v-\pi_\mesh^k v}_\Omega \\
    &\qquad = \ip{(1-\pi_\mesh^k)(f+\div\bA\nabla w-\bbeta\cdot\nabla w-cw)}{v-\pi_\mesh^k v}_\Omega.
  \end{align*}
  Using the local approximation property $\|v-\pi_\mesh^k v\|_T\leq h_T \|\nabla v\|_T$ ($T\in\mesh$) and the Cauchy--Schwarz inequality, we conclude the proof.
\end{proof}
%
We stress that the computation of all volume terms (i.e., $\eta_\Omega$ and $\rho_\Omega$) is completely local, since the inverse of the Riesz matrix required for $\eta_\Omega$ can be computed element-wise.  
In fact, as the following observation shows, one may even replace $\eta_\Omega$ with simple $L^2$ volume terms.
%
\begin{theorem}\label{thm:brokenweak:eta}
  Under the assumptions of Theorem~\ref{thm:equivest:brokenweak}, set
  $r_\mesh(w)|_T:= f+\div\bA\nabla w - \bbeta\cdot\nabla w-cw|_T \in L^2(T)$ for all $T\in\mesh$. 
  Then,
  \begin{align*}
    \|\pi_\mesh^0 r_\mesh(w)\|_\Omega \leq \eta_\Omega(w)
    \leq \|\pi_\mesh^0 r_\mesh(w)\|_\Omega + \|h_\mesh(1-\pi_\mesh^0)\pi_\mesh^k r_\mesh(w)\|_\Omega
  \end{align*}
  Furthermore, $\|h_\mesh(1-\pi_\mesh^0)\pi_\mesh^k r_\mesh(w)\|_\Omega \lesssim \eta_\Omega(w)$ so that, in particular, 
  \begin{align*}
    \eta_\Omega(w) \eqsim \|\pi_\mesh^0 r_\mesh(w)\|_\Omega + \|h_\mesh(1-\pi_\mesh^0)\pi_\mesh^k r_\mesh(w)\|_\Omega.
  \end{align*}
\end{theorem}
\begin{proof}
  First, for all $v\in V_{\Omega,\mesh} = P^k(\mesh)$, integration by parts gives
  \begin{align*}
    F_\Omega(v) -b_\Omega( (w,\trdiv\mesh\bA\nabla w),v) = \ip{f+\div\bA\nabla w-\bbeta\cdot\nabla w-cw}{v}_\Omega
= \ip{r_\mesh(w)}v_\Omega.
  \end{align*}
  The lower bound follows by observing that $P^0(\mesh)\subseteq P^k(\mesh)$ and $\|z\|_{V_\Omega} = \|z\|_\Omega$ for $z\in P^0(\mesh)$, yielding
  \begin{align*}
    \eta_\Omega(w) &= \sup_{0\neq v\in P^k(\mesh)} \frac{\ip{r_\mesh(w)}{v}_\Omega}{\|v\|_{V_\Omega}}
    \geq \sup_{0\neq v\in P^0(\mesh)} \frac{\ip{r_\mesh(w)}{v}_\Omega}{\|v\|_\Omega}
    \\
    &= \sup_{0\neq v\in P^0(\mesh)} \frac{\ip{\pi_\mesh^0r_\mesh(w)}{v}_\Omega}{\|v\|_\Omega}
    = \|\pi_\mesh^0r_\mesh(w)\|_\Omega.
  \end{align*}
  For the upper bound decompose $P^k(\mesh)\ni v = \pi_\mesh^0v + (1-\pi_\mesh^0)v$ and note that
  \begin{align*}
    |\ip{r_\mesh(w)}{v}_\Omega| &= |\ip{\pi_\mesh^kr_\mesh(w)}{v}_\Omega| \leq 
    |\ip{\pi_\mesh^kr_\mesh(w)}{\pi_\mesh^0 v}_\Omega| + |\ip{\pi_\mesh^kr_\mesh(w)}{(1-\pi_\mesh^0) v}_\Omega|
    \\
    &= |\ip{\pi_\mesh^0r_\mesh(w)}{\pi_\mesh^0 v}_\Omega| + |\ip{(1-\pi_\mesh^0)\pi_\mesh^kr_\mesh(w)}{(1-\pi_\mesh^0) v}_\Omega|
  \end{align*}
  The first term is bounded by $\|\pi_\mesh^0 r_\mesh(w)\|_\Omega\|v\|_{V_\Omega}$ and the second by using the local approximation property, i.e.,
  \begin{align*}
    |\ip{(1-\pi_\mesh^0)\pi_\mesh^kr_\mesh(w)}{(1-\pi_\mesh^0) v}_\Omega| \leq \|h_\mesh(1-\pi_\mesh^0)\pi_\mesh^kr_\mesh(w)\|_\Omega\|\nabla_\mesh v\|_\Omega.
  \end{align*}
  This implies the second inequality. 
%
  In addition, note that
  \begin{align*}
    \|h_T\pi_\mesh^k r_\mesh(w)\|_T^2 &= \ip{r_\mesh(w)}{h_T^2\pi_\mesh^kr_\mesh(w)}_T
    \\
    &\lesssim \sup_{0\neq v\in P^k(T)} \frac{\ip{r_\mesh(w)}{v}_T}{\|v\|_{H^1(T)}} h_T^2\|\pi_\mesh^kr_\mesh(w)\|_{H^1(T)}
    \\
    &\lesssim \|\pi_\mesh^k r_\mesh(w)\|_{(H^1(T))'} h_T\|\pi_\mesh^kr_\mesh(w)\|_T
  \end{align*}
  where, in the last estimate, we used the inverse estimate $h_T\|\nabla q\|_T\lesssim \|q\|_T$ for $q\in P^k(T)$.
  Dividing by the last term, this shows that
  \begin{align*}
    \|h_T(1-\pi_\mesh^0)\pi_\mesh^k r_\mesh(w)\|_T \leq \|h_T\pi_\mesh^k r_\mesh(w)\|_T \lesssim \sup_{0\neq v\in P^k(T)} \frac{\ip{r_\mesh(w)}{v}_T}{\|v\|_{H^1(T)}}.
  \end{align*}
  Squaring, summing over all $T\in\mesh$ and noting that $\|\cdot\|_{V_{\Omega,\mesh}'}^2 = \sum_{T\in\mesh} \|\cdot\|_{P^k(T)'}^2$ (where, in this notation, $P^k(T)$ is equipped with the $H^1(T)$ norm) proves the last assertion.
\end{proof}

\begin{remark}
  By the definition of $\eta_\Omega$, $\rho_\Omega$, the equivalence from Theorem~\ref{thm:equivest:brokenweak} and properties of the orthogonal projection, it is straightforward to see that
  \begin{align*}
    \eta_\Omega(w)^2 + \rho_\Omega(w)^2 \eqsim \|\pi_\mesh^0 r_\mesh(w)\|_\Omega^2 + \|h_\mesh(1-\pi_\mesh^0) r_\mesh(w)\|_\Omega^2.
  \end{align*}
%  Noteably, the right-hand side is independent of the choice of $k\in\N_0$.
\end{remark}

\subsection{Strong formulation}\label{sec:strongform}
In this section, we discuss a strong formulation of our model problem~\eqref{eq:modelPDE} which can be used to interpret classical PINNs; see the comments below. 
To that end, define the space and norm
\begin{align*}
  U&= \set{w\in H^1(\Omega)}{\div\bA\nabla u\in L^2(\Omega)}, \\
  \|w\|_U^2 &= \|w\|_{H^1(\Omega)}^2 + \|\div\bA\nabla w\|_\Omega^2, \quad w\in U
\end{align*}
as well as $V_\Omega := L^2(\Omega)$ with norm $\|\cdot\|_{V_\Omega} := \|\cdot\|_\Omega$.
Define the operator $B_\Omega\colon U \to V_\Omega'$ by
\begin{align*}
  B_\Omega(u)(v) := \ip{-\div\bA\nabla u+\bbeta\cdot\nabla u + cu}v_\Omega
\end{align*}
and $B_\Gamma$, $V_\Gamma$ as discussed in Section~\ref{sec:boucond} above. 
\begin{lemma}\label{lem:strongform}
  The equivalence
  \begin{align*}
    \|w\|_U \eqsim \|B_\Omega w\|_{V_\Omega'} + \|B_\Gamma w\|_{V_\Gamma'}
  \end{align*}
  holds for all $w\in U$. 
\end{lemma}
\begin{proof}
  Let $w\in U$ be given and consider the splitting $w = w_0 + \widetilde w$ where $\widetilde w\in H^1(\Omega)$ solves~\eqref{eq:modelPDE} with $f=0$ and $g=w|_\Gamma$. 
  It follows that $\widetilde w\in U$, thus, $w_0\in U$ and $w_0|_\Gamma = 0$.
  We prove that $\|w_0\|_{U}\lesssim \|B_\Omega w\|_{V_\Omega'}$ and $\|\widetilde w\|_U\lesssim \|B_\Gamma w\|_{V_\Gamma'}$. 
  The latter follows as in the proof of Lemma~\ref{lem:broken}.
  Note that the properties of $\bA$ and the Poincar\'e--Friedrich's inequality imply that $\|w_0\|_{H^1(\Omega)}^2 \eqsim \ip{\bA\nabla w_0}{w_0}_\Omega$.
  Using integration by parts, $\ip{\bbeta\cdot\nabla w_0+cw_0}{w_0}_\Omega\geq 0$, Cauchy--Schwarz and Young's inequality with parameter $\delta>0$, we infer that
  \begin{align*}
    \|w_0\|_{H^1(\Omega)}^2 &\eqsim \ip{\bA\nabla w_0}{\nabla w_0}_\Omega 
    = \ip{-\div\bA\nabla w_0+\bbeta\cdot\nabla w_0 + cw_0}{w_0}_\Omega -\ip{\bbeta\cdot\nabla w_0+cw_0}{w_0}_\Omega
    \\
    &\leq \ip{-\div\bA\nabla w_0+\bbeta\cdot\nabla w_0 + cw_0}{w_0}_\Omega
    \\
    &\leq \frac{\delta^{-1}}2 \|B_\Omega w_0\|_\Omega^2 + \frac\delta2 \|w_0\|_\Omega^2.
  \end{align*}
  Subtracting the last term for sufficiently small $\delta>0$ and $B_\Omega w_0 = B_\Omega w$ proves that
  \begin{align*}
    \|w_0\|_{H^1(\Omega)} \lesssim \|B_\Omega w\|_{V_\Omega'}.
  \end{align*}
  With the last estimate it also follows that $\|w_0\|_U \lesssim \|B_\Omega w\|_{V_\Omega'}$. 
  This concludes the direction ``$\lesssim$'' of the statement. The other direction follows from the boundedness of the involved operators.
\end{proof}

Set $V_{\Omega,\mesh} = P^k(\mesh)$ and define for $w\in U$
\begin{subequations}\label{eq:defStrongFormEstimators}
  \begin{align}
    \eta_\Omega(w) &= \|\pi_\mesh^k(f+\div\bA\nabla w-\bbeta\cdot\nabla w-cw)\|_\Omega, \\
    \rho_\Omega(w) &= \|(1-\pi_\mesh^k)(f+\div\bA\nabla w-\bbeta\cdot\nabla w-cw)\|_\Omega, \\
    \eta^2 &= \eta_\Omega^2 + \eta_\Gamma^2, \\
    \rho^2 &= \rho_\Omega^2 + \rho_\Gamma^2.
\end{align}
\end{subequations}
Here, $(\eta_\Gamma$, $\rho_\Gamma)$ denote any of the options described in Section~\ref{sec:boucond}.
\begin{theorem}\label{thm:equivest:strongform}
  Under the aforegoing definitions~\eqref{eq:defStrongFormEstimators} and assumptions the estimates
  \begin{align*}
    \eta(w) \lesssim \|u-w\|_{H^1(\Omega)} + \|\div\bA\nabla (u-w)\|_{\Omega} \lesssim \eta(w) + \rho(w).
  \end{align*}
  hold for all $w\in U$.
\end{theorem}
\begin{proof}
  Based on Corollary~\ref{cor:equivest} and our previous considerations from Section~\ref{sec:boucond} as well as Lemma~\ref{lem:strongform} we only need to show that there exists $\Pi_\mesh\colon V\to V_{\Omega,\mesh}$ with $\|\Pi_\mesh\|<\infty$. Clearly, $\Pi_\mesh = \pi_\mesh^k$ does the job in this case and the proof is concluded. 
\end{proof}

\begin{remark}\label{rem:PINN}
  Note that $\eta_{\Omega}^2(w) + \rho_\Omega^2(w) = \|f+\div\bA\nabla w-\bbeta\cdot\nabla w - cw\|_\Omega^2$. 
  Thus, when using $\eta_{\Omega}^2+\rho_{\Omega}^2$ as part of the loss functional in training, this resembles PINNs. 
  However, note that in classical PINNs, a boundary term of the form
  \begin{align*}
    \alpha \|w-g\|_\Gamma^2
  \end{align*}
  is used with a parameter $\alpha>0$ to be chosen by the user. 
  From our considerations from Section~\ref{sec:boucond} we stress that this term does, in general, not provide a lower nor an upper bound of the boundary error. 
  We propose to replace this term by
    \begin{align*}
      \|h_\faces^{-1/2}(w-g)\|_\Gamma^2 + \|h_\faces^{1/2}(1-\pi_\faces^p)\nabla_\Gamma(w-g)\|_\Gamma^2
    \end{align*}
  which is a guaranteed upper bound for $\|w-g\|_{1/2,\Gamma}^2$, see Remark~\ref{rem:investbou}.
\end{remark}
