\subsection{Forward Filtering Backward Sampling}

 Following \cite{Sylvia1994} and \cite{Carter1994}: \\

{\textit{Forward filtering equations:} 
\begin{itemize}
\item[a.] Posterior distribution at age $x_0$: $
\boldsymbol{\theta}_{x_0}| {\bf D}_{x_0} \sim \mathcal{N}({\bf m}_{x_0},{\bf C}_{x_0}); 
$

\item[b.] Prior distribution at age $x$: $\boldsymbol{\theta}_{x} | {\bf D}_{x-1} \sim \mathcal{N}({\bf a}_{x},{\bf R}_{x}),$
\noindent
with ${\bf a}_{t} = {\bf G}_{x}\textbf{m}_{x-1}$ and ${\bf R}_{x}={\bf G}_{x}{\bf C}_{x-1}{\bf G}'_{x}+{\bf W}_{x} ;$

\item[c.] One step ahead prediction:
$ {\bf Y}_{x}| {\bf D}_{x-1} \sim \mathcal{N}({\bf f}_{x},{\bf Q}_{x}), $
\noindent
with ${\bf f}_{x} = {\bf F}'_{x}{\bf a}_{x}$ and ${\bf Q}_{t}={\bf F}'_{x}{\bf R}_{x}{\bf F}_{t}+{\bf V}$, 

\item[d.] Posterior distribution at age $x$: $\boldsymbol{\theta}_{x}|\textbf{D}_{x} \sim \mathcal{N}({\bf m}_{x},{\bf C}_{x}),$
\noindent
with ${\bf m}_{x} = {\bf a}_{x}+ {\bf A}_{x}{\bf e}_{x}$ and ${\bf C}_{x}={\bf R}_{x}- {\bf A}_{x}{\bf Q}_{x}{\bf A}'_{x}$ and ${\bf A}_{t}={\bf R}_{t}{\bf F}_{x}{\bf Q}_{x}^{-1}$, ${\bf e}_{x}={\bf y}_{x}-{\bf f}_{x}$ the forecast error.
\end{itemize}

\textit{Backward Sampling equations:}\\

 This step is computed retrospectively, using the following decomposition:
 $$p(\boldsymbol{\theta}_{x_0},...,\boldsymbol{\theta}_\vartheta|{\bf D}_\vartheta)=p(\boldsymbol{\theta}_{\vartheta} | {\bf D}_\vartheta)\prod_{x=x_0}^{\vartheta}p(\boldsymbol{\theta}_x|\boldsymbol{\theta}_{x+1},{\bf D}_x).$$

 From Bayes Theorem, for $x=\vartheta-1,...,x_0$:
 $$ p(\boldsymbol{\theta}_x|\boldsymbol{\theta}_{x+1},\textbf{D}_\vartheta) \propto p(\boldsymbol{\theta}_{x+1}|\boldsymbol{\theta}_{x},\textbf{D}_\vartheta)p(\boldsymbol{\theta}_x|\textbf{D}_\vartheta),  $$
 with $\boldsymbol{\theta}_x|\boldsymbol{\theta}_{x+1},\textbf{D}_\vartheta \sim \mathcal{N}({\bf h}_x,{\bf H}_x)$. Then,
 $${\bf h}_x = {\bf m}_x+{\bf C}_x {\bf G}'_{x+1}{\bf R}_{x+1}^{-1}(\boldsymbol{\theta}_{x+1}-{\bf a}_{x+1}),$$ 
 $${\bf H}_x = {\bf C}_x - {\bf C}_x {\bf G}'_{x+1}{\bf R}_{x+1}^{-1}{\bf G}_{x+1}{\bf C}_x,$$ with ${\bf h}_{\vartheta} = {\bf m}_{\vartheta}$, ${\bf H}_{\vartheta} = {\bf C}_{\vartheta}$ being the initial values. \\

