\author{Jinghui Chen\thanks{Corresponding author: Jinghui Chen, Department of Mathematics and Statistics at York University, and RISC Foundation.  (email: \texttt{jh8chen@yorku.ca}).}, Edward Furman\thanks{Edward Furman, Department of Mathematics and Statistics at York University, and RISC Foundation.  (email: \texttt{efurman@yorku.ca}).}, and X.\ Sheldon Lin\thanks{X.\ Sheldon Lin, Department of Statistical Sciences at University of Toronto, and RISC Foundation. (email: \texttt{sheldon.lin@utoronto.ca}).}}
