Figure~\ref{risk bounds figure} presents the lower and upper bounds of  $\mathrm{MES}_p(X_j,S)$ as a function of the prudence level $p$ for the case $X_i\sim \text{Lognorm}(0,1)$, $i\in\mathcal{N}$. The vertical solid line illustrates the full range of possible MES values, from the minimum (LES) to the maximum (ES). As shown, $$\lim_{p\rightarrow 0}\mathrm{MES}_p(X_j,S)=\lim_{p\rightarrow 0}\mathrm{LES}_{1-p}(X_j)=\lim_{p\rightarrow 0}\mathrm{ES}_p(X_j)=\mu_j.$$ Furthermore, the curves of the risk bounds are determined solely by the marginal distribution $F_i$. For instance, if $F_i$ is symmetric, the lower and upper bounds at any $p$ are symmetric around the mean $\mu_j$, that is, $\mathrm{ES}_p(X_j)-\mu_j=\mu_j-\mathrm{LES}_{1-p}(X_j)$.

In contrast to the upper bound of $\mathrm{MES}_p(X_j, S)$ obtained by the comonotonicity, the lower bound in Inequality~\eqref{lower bounds for d risks} is not necessarily sharp.  In the following discussion, we explore the conditions under which the lower bound is sharp, emphasizing the properties of the marginal distributions.

\subsection{On the sharpness of the lower bound}
The lower bound for $\mathrm{MES}_p(X_j, S)$ in Theorem~\ref{lower bound}, in general, not sharp. Its sharpness depends critically on the properties of the joint distribution function of the random vector $(X_1,X_2,\dots,X_d)$. In this subsection, we first identify the conditions under which the lower bound is attained and subsequently demonstrate sharpness through examples and counterexamples.

\begin{theorem}[Sharpness of the lower bound]\label{sharpness condition}
	Let $X_i\sim F_i$, $i\in\mathcal{N},$ be $d$ risks, and $S=\sum_{i=1}^{d}X_i$ be the aggregate risk. The lower bound, $m(p)=\mathrm{LES}_{1-p}(X_j)$ in Theorem~\ref{lower bound}, is obtained if and only if the two conditions are satisfied:
	\begin{enumerate}[(1)]
		\item $\mathbb{P}(X_j> \text{VaR}_{1-p}(X_j), S> \text{VaR}_{p}(S))=0$.
		\item $\mathbb{P}(X_j\leq \text{VaR}_{1-p}(X_j), S\leq \text{VaR}_{p}(S))=0$.
	\end{enumerate}
\end{theorem}
\begin{proof}
	The lower bound is sharp if and only if both inequalities in \eqref{lower bound inequalities} hold with equality. For the first one, we have to prove that $$\mathbb{P}\left(X_j> x_{j,1-p}, S> s_p\right)=0\iff \mathbb{E}[X_j-x_{j,1-p}\vert X_j>x_{j,1-p}, S>s_p]\mathbb{P}\left(S> s_p\vert X_j>x_{j,1-p}\right)=0.$$ $``\Rightarrow"$ is evident since $$\mathbb{P}\left(X_j> x_{j,1-p}, S> s_p\right)=0\Rightarrow\mathbb{P}\left(S> s_p\vert X_j>x_{j,1-p}\right)=\frac{\mathbb{P}\left(X_j> x_{j,1-p}, S> s_p\right)}{p}=0.$$ Furthermore, $``\Leftarrow"$ is true because
	\begin{equation*}
		\begin{aligned}
		&\mathbb{E}[X_j-x_{j,1-p}\vert X_j>x_{j,1-p}, S>s_p]\mathbb{P}\left(S> s_p\vert X_j>x_{j,1-p}\right)=0\\
		&\Rightarrow \mathbb{P}\left(S> s_p\vert X_j>x_{j,1-p}\right)=0 \\
		&\Rightarrow \mathbb{P}\left(X_j> x_{j,1-p}, S> s_p\right)=0.
	\end{aligned}
	\end{equation*} The first ``$\Rightarrow $'' holds because $\mathbb{E}[X_j-x_{j,1-p}\vert X_j>x_{j,1-p}, S>s_p]>0$. We omit the proof for (2) because the argument for the second equality is similar.
\end{proof}

\begin{remark}\label{discrete point}
	Conditions (1) and (2) of Theorem~\ref{sharpness condition} are satisfied if and only if $X_j$ and $S$ are antimonotonic, under the assumption that the components 
	$X_i$, $i\in\mathcal{N}$, are continuous. In this case, 
	\begin{equation*}
		\begin{aligned}
			\mathbb{P}(X_j> \text{VaR}_{1-p}(X_j), S> \text{VaR}_{p}(S))&=\mathbb{P}(U<p, U>p)\\
			&=0\\
			&=\mathbb{P}(U\geq p, U\leq p)\\
			&=\mathbb{P}(X_j\leq \text{VaR}_{1-p}(X_j), S\leq \text{VaR}_{p}(S)),
		\end{aligned}
	\end{equation*} where $U\sim U[0,1]$. However, if $X_i$ are discrete RVs, the third equation in the previous formula does not always hold.
\end{remark}
The following example illustrates the point of Remark~\ref{discrete point}.
\begin{example}
	Let $X_1\sim F_1$ and $X_2\sim F_2$ denote two discrete RVs having, respectively, five mass points $\{-2,-1,0,1,2\}$ and $\{-1,1,3,5,7\}$ with equal probability. When $X_1=\{-2,-1,0,1,2\}$ and $X_2=\{7,5,3,1,-1\}$, we obtain that $$\mathbb{P}(X_2> \text{VaR}_{1-p}(X_2), S> \text{VaR}_{p}(S))=p$$
	and
	$$\mathbb{P}(X_2\leq \text{VaR}_{1-p}(X_2), S\leq \text{VaR}_{p}(S))=1-p.$$
\end{example}
We next provide propositions and examples illustrating when the lower bound of $m(p)$ is sharp.
\begin{proposition}[Symmetric marginal]\label{symmetric margin}
	Let $X_i\sim F$, $i\in\mathcal{N},$ be $d\ge 3$ continuous risks such that $F$ is symmetric, and $S=\sum_{i=1}^{d}X_i$ be the aggregate risk. There exists a random vector $(X_1,X_2,\dots, X_d)$ such that (1) and (2) of Theorem~\ref{sharpness condition} hold. Hence, $m(p)=\mathrm{LES}_{1-p}(X_j)$ is obtained by such a random vector. Furthermore, $X_j=F^{-1}(1-U)$ and $X_i=F^{-1}(U)$ for $i\in\mathcal{N}/j$, in which $U\sim U[0,1]$.
\end{proposition}
\begin{proof}
	When $X_j=F^{-1}(1-U)$ and $X_i=F^{-1}(U)$ for $i\in\mathcal{N}/j$, we have $$S=(d-2)F^{-1}(U)+2\mu,$$ where $\mu$ is the mean of $F$. This result follows from the property $F^{-1}(U)+F^{-1}(1-U)=2\mu$, as discussed in the concept of complete mixability; see \citet{wang2011complete}. Then,
	\begin{equation*}
		\begin{aligned}
			&\mathbb{P}(X_j> \text{VaR}_{1-p}(X_j), S> \text{VaR}_{p}(S)) \\
			=&\mathbb{P}\left(F^{-1}(1-U)> \text{VaR}_{1-p}\left(F^{-1}(1-U)\right),\right.\\
			&\left. (d-2)F^{-1}(U)+2\mu> \text{VaR}_{p}\left((d-2)F^{-1}(U)+2\mu\right)\right)\\
			=&\mathbb{P}\left(F^{-1}(1-U)> \text{VaR}_{1-p}\left(F^{-1}(1-U)\right), F^{-1}(U)> \text{VaR}_{p}\left(F^{-1}(U)\right)\right)\\
			=&\mathbb{P}\left(1-U> 1-p, U> p\right)=\mathbb{P}\left(U<p, U> p\right)=0.
		\end{aligned}
	\end{equation*} The second equation holds because VaR is translative and positively homogeneous, that is, $\text{VaR}_p(X_j+a)=\text{VaR}_p(X_j)+a$ and $\text{VaR}_p(cX_j)=c\text{VaR}_p(X_j)$ for any constant $a$ and any positive constant $c$. The equality $\mathbb{P}(X_j\leq \text{VaR}_{1-p}(X_j), S\leq \text{VaR}_{p}(S))=0$ can be proved similarly, and thus, the proof is omitted.
\end{proof}
\begin{example}
	Let $U_i\sim U(0,1)$, $i\in\mathcal{N},$ be $d\ge 3$ risks, and $S=\sum_{i=1}^{d}U_i$ be the aggregate risk. Hence, $$m(p)=\mathrm{LES}_{1-p}(U_j)=\frac{\int_{0}^{1-p}udu}{1-p}=\frac{1-p}{2}$$ is obtained when $U_i=U$ and $U_j=1-U$ for $j\in\mathcal{N}/i$.
\end{example}
The assumption of symmetric and homogeneous risks in Proposition~\ref{symmetric margin} may, however, be overly restrictive. We now propose a weaker set of assumptions.

%\begin{proposition}\label{max margin}
%	Let $X_i$, $i\in\mathcal{N},$ be $d$ risks, and $S=\sum_{i=1}^{j}X_i$ such that $X_j$, $j\in\mathcal{N},$ and $S$ are antimonotonic. Hence, $m(p)=\mathrm{LES}_{1-p}(X_j)$.
%\end{proposition}
\begin{proposition}\label{max margin}
	Let $X_i\sim F_i$, $i\in\mathcal{N},$ be $d$ risks and $S=\sum_{i=1}^{d}X_i\sim F_S$ such that $X_j=F_j^{-1}(1-U)$ and $S= F_S^{-1}(U)$ are attainable simultaneously. Hence, $m(p)=\mathrm{LES}_{1-p}(X_j)$ is obtained when $X_j=F^{-1}_j(1-U)$ and $X_i=F^{-1}_i(U)$ for $i\in\mathcal{N}/j$.
\end{proposition}
The proof is straightforward and therefore omitted. A corollary to Proposition~\ref{max margin} is stated as follows.
\begin{corollary}\label{jointly mixable margin}
	Let $X_i\sim F_i$ for $i\in\mathcal{N},$ be $d$ risks such that the tuple of distributions $(F_i, F_j)$ is jointly mixable for some $j\in\mathcal{N}/i$. Let $S=\sum_{i=1}^{d}X_i$ denote the aggregate risk. Then, there exists a random vector $(X_1,X_2,\dots, X_d)$ such that (1) and (2) of Theorem~\ref{sharpness condition} are satisfied. In this case, $m(p)=\mathrm{LES}_{1-p}(X_j)$ is obtained. Furthermore, it holds that $X_j=F^{-1}_j(1-U)$ and $X_i=F^{-1}_i(U)$ for all $i\in\mathcal{N}/j$.
\end{corollary}
The proof follows directly, as under this construction, we have $$S=K+\sum_{k=1, k\neq i,j}^{d}F_k^{-1}(U)=F_S^{-1}(U),$$ where $K\in\mathbb{R}$ is the joint center of $(F_i, F_j)$. An example with normal marginal distributions is provided to support Proposition~\ref{max margin}.
\begin{example}
	Let $X_i\sim N(\mu_i, \sigma_i^2)$, $i\in\mathcal{N},$ such that $\sum_{i=1\&i\neq j}^{d}\sigma_i>\sigma_j$, and $S=\sum_{i=1}^{d}X_i$. Then, the lower bound of $\mathrm{MES}_p(X_j, S)$ is $$m(p)=\mathrm{LES}_{1-p}(X_j)=\frac{\mu_j-\sigma_j\phi\left(\Phi^{-1}(1-p)\right)}{1-p}.$$ Moreover, $m(p)$ is obtained when $X_j=\mu_j+\sigma_j\Phi^{-1}(1-U)$ and $X_i=\mu_i+\sigma_i\Phi^{-1}(U)$. In this case, $S=\sum_{i=1}^{d}\mu_i+\left(\sum_{i=1\&i\neq j}^{d}\sigma_i-\sigma_j\right)\Phi^{-1}(U)$ is antimonotonic to $X_j$.
\end{example}
In the case $d=2$, an explicit expression for $m(p)$ can be derived for arbitrary marginal distributions, as shown in the following proposition.  
\begin{proposition}[Two dimensions]\label{lower bound for 2 dimension}
	Let $X_1\sim F_1$ and $X_2\sim F_2$ and $S=X_1+X_2$. The lower bound of $\mathrm{MES}_p(X_j, S)$ is 
	\begin{equation}\label{lower bounds for 2 risks}
		m(p)=\mathrm{MES}_{p}(F_j^{-1}(U_j),F_1^{-1}(U_1)+F_2^{-1}(U_2)),
	\end{equation} in which $j=1,2$, $U_1=U\sim U[0,1]$ and $U_2=1-U$.
\end{proposition}
\begin{proof}
	Let $C(u_1,u_2)$ be the copula of $(X_1,X_2)$, in which $u_i=F_i(x_i)$. We have \begin{equation}
		\begin{aligned}
			\mathrm{MES}_{p}(X_j,X_1+X_2)=&\frac{\mathbb{E}(X_j\mathds{1}_{X_1+X_2>\text{VaR}_p(X_1+X_2)})}{1-p}\\
			=&\frac{1}{1-p}\underset{F_1^{-1}(u_1)+F_2^{-1}(u_2)>\text{VaR}_p(X_1+X_2)}{\int\int}\text{VaR}_{u_j}(X_j)dC(u_1,u_2)\\
			\geq & \frac{1}{1-p}\underset{F_1^{-1}(u)+F_2^{-1}(1-u)>\text{VaR}_p(X_1+X_2)}{\int\int}\text{VaR}_{u_j}(X_j)dC(u,1-u)
		\end{aligned}
	\end{equation} because $C(u_1,u_2)\geq C(u,1-u)$ (see Fr\'{e}chet-Hoeffding lower bound in \cite{nelsen2006introduction}).
\end{proof}
To demonstrate that $m(p)$ in \eqref{lower bound for 2 dimension} satisfies $m(p)\geq\mathrm{LES}_{1-p}(X_j)$, we provide several illustrative examples.
\begin{example}
	Let $X_1\sim F_1$ and $X_2\sim F_2$ denote two discrete RVs having respective five mass points with equal probability, and $p=0.6$.
	\begin{enumerate}[(1)]
		\item Let $F_1$ and $F_2$ have mass points $\{-2,0,4,6,8\}$ and $\{6,7,8,9,10\}$, respectively. Under a antimonotonic dependence among $X_1$ and $X_2$, $m(p)=\mathrm{MES}_{p}(X_2, X_1+X_2)=6.5=\mathrm{LES}_{1-p}(X_2)$.
		\item Let $F_1$ and $F_2$ have mass points $\{-2,-1,0,1,2\}$ and $\{6,7,8,9,10\}$, respectively. Under a antimonotonic dependence among $X_1$ and $X_2$, $m(p)=\mathrm{MES}_{p}(X_2, X_1+X_2)=8>\mathrm{LES}_{1-p}(X_2)=6.5$.
	\end{enumerate}
\end{example}
While the constructions above achieve sharpness under specific dependence structures, it is important to recognize that risk bounds under the assumption of completely uncertain dependence are often of limited practical use. Typically, the gap between the lower and upper bounds is substantial; see \citet{bernard2017risk}. Consequently, incorporating additional dependence information is essential to obtain tighter and more informative bounds for risk measures.

\section{Risk bounds for factor models}\label{factor models sec}
Factor models play a pivotal role across multiple disciplines, including statistics, economics, and insurance \citep{bernard2017risk}. Applications include asset pricing \citep{fama1993common}, portfolio optimization \citep{santos2013comparing}, and risk management \citep{gordy2000comparative}. 

In this section, we focus on deriving improved risk bounds for $\mathrm{MES}_p(X_j,S)$ by incorporating additional dependence information through a structural assumption based on a factor model. In such models, the risks $X_i$, $i\in\mathcal{N}$, are  represented in the functional form $$X_i=f_i(Y, Z_i),$$ where $Y$ denotes a background (systemic) risk, and $Z_i$ represent idiosyncratic risks. A prominent example is the arbitrage pricing theory (APT) in economics \citep{ross1976arbitrage}, where the structure takes the form $f_i(Y, Z_i)=a_i+b_iY+Z_i$, where $a_i$ denoting the mean of $X_i$ and $b_i$ capturing the sensitivity of $X_i$ to the common factor $Y$. 

Mathematically, we derive lower and upper bounds for $\mathrm{MES}_p(X_j,S)$ under the assumption that the marginal distributions $F_i$ are known and that partial dependence information is available via the factor model structure. These bounds are denoted by
\begin{align}
	m^f(p)&=\inf \left\{\mathrm{MES}_p(X_j,S): \bm{X}\in \mathcal{B}(\bm{X}), S=\sum_{i=1}^{d}X_i \right\}, \label{m for factor} \\
	M^f(p)&=\sup \left\{\mathrm{MES}_p(X_j,S): \bm{X}\in \mathcal{B}(\bm{X}), S=\sum_{i=1}^{d}X_i\right\},\label{M for factor}
\end{align} respectively, where
\begin{equation*}
	\mathcal{B}(\bm{X})=\left\{\bm{X}\in \mathcal{X}^d:(X_i, Y)\sim H_i, 1\leq i\leq d\right\}
\end{equation*} is the model with fully marginal and partially dependent information. Related analyses for $\text{VaR}_p(S)$ and convex risk measures under structural dependence assumptions have been previously studied by \cite{bernard2017risk}.

To assess the degree of improvement gained from incorporating the factor model, we introduce a measure of improvement, denoted by $\delta_p$, defined as
\begin{equation*}
	\delta_p = 1-\frac{M^f(p)-m^f(p)}{M(p)-m(p)},
\end{equation*} where we conventionally set $\delta_p=1$ whenever $M(p)=m(p)$; see a similar definition for general risk measures in \citet{bernard2017risk}. Here, $M(p)-m(p)$ and $M^f(p)-m^f(p)$ are referred to as the dependence uncertainty spreads of $\mathrm{MES}_p(X_j,S)$ in the unconstrained and constrained setting, respectively.

\subsection{Factor models}
The following theorems establish upper and lower bounds for $\mathrm{MES}_p(X_j, S)$ when the risks $X_i$ are specified through arbitrary factor models.
\begin{theorem}[Upper bound for factor models]\label{upper bound for factor}
	Let $X_i=f_i(Y, Z_i)$, $i\in\mathcal{N},$ be $d$ risks where $Y\sim H$, $Z_i$ are independent of $Y$ and $X_{i\vert Y}\sim F_{i\vert Y}$. Let $S=\sum_{i=1}^{d}f_i(Y, Z_i)$ denote the aggregate risk. The upper bound of $\mathrm{MES}_p(X_j, S)$, $j\in\mathcal{N}$, is 
	\begin{equation}\label{factor upper bounds for d risk}
		M^f(p)\leq\frac{1}{1-p}\int \mathbb{E}\left[f_j(y, Z_j)\left\vert f_j(y, Z_j)> x_{j,p}\right.\right]\mathbb{P}\left(f_j(y, Z_j)> x_{j,p}\right)dH(y),
	\end{equation} where $x_{j,p}=\text{VaR}_p(f_j(Y, Z_j))$.
\end{theorem}
\begin{proof}
	Let $X_{j\vert y}=f_j(y, Z_j)$, $x_{j,p}=\text{VaR}_p(X_j)$, $S_y=\sum_{i=1}^{d}f_i(y, Z_i)$, $s_p=\text{VaR}_p(S)$ and $f_Y(y)$ be the probability density function of $Y$. We have \begin{equation*}
		\begin{aligned}
			\mathrm{MES}_{p}\left(X_{j},S\right)=&\mathbb{E}[X_{j}\vert S>s_p]=\int\mathbb{E}\left[X_{j}\vert S>s_p, Y=y\right]\mathbb{P}(Y=y|S>s_p)dy
			\\
			=&\int\mathbb{E}\left[X_{j}\vert S>s_p, Y=y\right]\frac{\mathbb{P}(S>s_p|Y=y)f_Y(y)}{\mathbb{P}(S>s_p)}dy\\
			=&\frac{1}{1-p}\int\mathbb{E}\left[X_{j}\vert S>s_p, Y=y\right]\mathbb{P}(S>s_p|Y=y)dH(y)\\
			=&\frac{1}{1-p}\int\mathbb{E}\left[X_{j\vert y}\left\vert S_y>s_p\right.\right]\mathbb{P}\left(S_y>s_p\right)dH(y)\\
			=&\frac{1}{1-p}\int x_{j,p}\mathbb{P}\left(S_y>s_p\right)+\mathbb{E}\left[X_{j\vert y}-x_{j,p}\left\vert S_y>s_p\right.\right]\mathbb{P}\left(S_y>s_p\right)dH(y).
		\end{aligned}
	\end{equation*} Then,
	\begin{equation*}
		\begin{aligned}
			\mathbb{E}\left[X_{j\vert y}-x_{j,p}\left\vert S_y>s_p\right.\right]=
			&\mathbb{E}\left[X_{j\vert y}-x_{j,p}\left\vert S_y>s_p, X_{j\vert y}> x_{j,p}\right.\right]\mathbb{P}\left(X_{j\vert y}> x_{j,p}\vert S_y>s_p\right)+\\
			&\mathbb{E}\left[X_{j\vert y}-x_{j,p}\left\vert S_y>s_p, X_{j\vert y}\leq x_{j,p}\right.\right]\mathbb{P}\left(X_{j\vert y}\leq x_{j,p}\vert S_y>s_p\right)\\
			\leq
			&\mathbb{E}\left[X_{j\vert y}-x_{j,p}\left\vert S_y>s_p, X_{j\vert y}> x_{j,p}\right.\right]\mathbb{P}\left(X_{j\vert y}> x_{j,p}\vert S_y>s_p\right)\\
			=
			&\mathbb{E}\left[X_{j\vert y}-x_{j,p}\left\vert S_y>s_p, X_{j\vert y}> x_{j,p}\right.\right]\mathbb{P}\left(S_y>s_p\vert X_{j\vert y}> x_{j,p}\right)\frac{\mathbb{P}\left(X_{j\vert y}> x_{j,p}\right)}{\mathbb{P}\left(S_{y}> s_p\right)}\\
			\leq
			&\frac{\mathbb{P}\left(X_{j\vert y}> x_{j,p}\right)}{\mathbb{P}\left(S_{y}> s_p\right)}\left\{\mathbb{E}\left[X_{j\vert y}-x_{j,p}\left\vert S_y>s_p, X_{j\vert y}> x_{j,p}\right.\right]\mathbb{P}\left(S_y>s_p\vert X_{j\vert y}> x_{j,p}\right)\right. \\
			&\left.+\mathbb{E}\left[X_{j\vert y}-x_{j,p}\left\vert S_y\leq s_p, X_{j\vert y}> x_{j,p}\right.\right]\mathbb{P}\left(S_y\leq s_p\vert X_{j\vert y}> x_{j,p}\right)\right\}\\
			=&\frac{\mathbb{P}\left(X_{j\vert y}> x_{j,p}\right)}{\mathbb{P}\left(S_{y}> s_p\right)}\mathbb{E}\left[X_{j\vert y}-x_{j,p}\left\vert X_{j\vert y}> x_{j,p}\right.\right].
		\end{aligned}
	\end{equation*}
	Therefore, we have
	\begin{equation*}
		\begin{aligned}
			\mathrm{MES}_{p}\left(X_{j},S\right)\leq&\frac{1}{1-p}\int x_{j,p}\mathbb{P}\left(S_y>s_p\right)-x_{j,p}\mathbb{P}\left(X_{j\vert y}> x_{j,p}\right)\\
			&+\mathbb{P}\left(X_{j\vert y}> x_{j,p}\right)\mathbb{E}\left[X_{j\vert y}\left\vert X_{j\vert y}> x_{j,p}\right.\right]dH(y)\\
			=&\frac{1}{1-p}\int x_{j,p}\mathbb{P}\left(S>s_p\vert Y=y\right)-x_{j,p}\mathbb{P}\left(X_{j}> x_{j,p}\vert Y=y\right)\\
			&+\mathbb{P}\left(X_{j\vert y}> x_{j,p}\right)\mathbb{E}\left[X_{j\vert y}\left\vert X_{j\vert y}> x_{j,p}\right.\right]dH(y)\\
			=&\frac{1}{1-p}\int \mathbb{P}\left(X_{j|y}> x_{j,p}\right)\mathbb{E}\left[X_{j|y}\left\vert X_{j|y}> x_{j,p}\right.\right]dH(y).
		\end{aligned}
	\end{equation*}The inequality in \eqref{factor upper bounds for d risk} becomes an equality if, for every $y$ in the domain of $Y$, $$\mathbb{P}\left(X_{j\vert y}\leq x_{j,p}, S_y>s_p\right)=\mathbb{P}\left(S_y\leq s_p, X_{j\vert y}> x_{j,p}\right)=0.$$
\end{proof}
It is important to note that the upper bound \( M^f(p) \) is not necessarily attained even when \( X_{i\vert Y} = F_{i\vert Y}^{-1}(U) \). Moreover, \( M^f(p) \) can be strictly smaller than the right-hand side of \eqref{factor upper bounds for d risk}; see Example~\ref{two normal example}. The sharpness of the upper bound \( M^f(p) \) depends on the specific form of the factor models $f_i$ and the joint distributions of $(Y,Z_i)$. These features differentiate the factor model setting from the classical setting where only marginal distributions are specified.

To illustrate these differences, we consider the following example. Let $X\sim \text{Pois}(\lambda)$ denote a Poisson-distributed RV with rate parameter 
$\lambda$.
\begin{example}\label{cond com not upper}
	\begin{enumerate}[(1)]
		\item[]
		\item Let $X_i=Y+Z_i$, $i=1,2,3$ be three risks such $Y\sim \text{Pois}(\lambda_1)$ and $Z_i\sim \text{Pois}(\lambda_2)$ are independent of $Y$. In this case, $X_i\sim\text{Pois}(\lambda_1+\lambda_2)$. The upper bound
		\begin{equation*}
			M^f(p)=\frac{\lambda_1+\lambda_2}{1-p}\left(1-\frac{\Gamma\left(\text{VaR}_p(Y+Z_j),\lambda_1+\lambda_2\right)}{\left(\text{VaR}_p(Y+Z_j)-1\right)!}\right)
		\end{equation*} in which $\Gamma(x, y)$ is the upper incomplete gamma function. The upper bound is obtained when $Z_i$ are comonotonic. Under the comonotonicity, \begin{equation*}
			\begin{aligned}
				\mathbb{P}\left(X_{j\vert y}\leq x_{j,p}, S_y>s_p\right)&=\mathbb{P}\left(y+Z_j\leq \text{VaR}_p(Y+Z_j), 3y+3Z_j>\text{VaR}_p(3Y+3Z_j)\right)\\
				&=\mathbb{P}\left(y+Z_j\leq \text{VaR}_p(Y+Z_j), y+Z_j>\text{VaR}_p(Y+Z_j)\right)\\
				&=\mathbb{P}\left(y+Z_j> \text{VaR}_p(Y+Z_j), y+Z_j\leq\text{VaR}_p(Y+Z_j)\right)\\
				&=\mathbb{P}\left(S_y\leq s_p, X_{j\vert y}> x_{j,p}\right)=0,
			\end{aligned}
		\end{equation*} for any $y\geq 0$.
		\item Let $\bm{X}=(X_1,X_2,X_3)=Y(-1,1,1)+(Z_1,Z_2,Z_3)$ be a three-dimensional random vector such that $Y\sim \text{N}(0, 1)$ and $Z_i\sim \text{N}(0, 1)$ are independent of $Y$. Hence, $X_i\sim\text{N}(0, 2)$. The upper bound of $\mathrm{MES}_{p}(X_2, S)$ is
		\begin{equation*}
			M^f(p)=\sqrt{2}\frac{\phi(\Phi^{-1}(p))}{1-p}.
		\end{equation*} The upper bound is obtained when $Z_1=Z_2=\Phi^{-1}(U)$ and $Z_3=\Phi^{-1}(1-U)$. Under such dependence structure, \begin{equation*}
			\begin{aligned}
				&\mathbb{P}\left(X_{2\vert y}\leq x_{j,p}, S_y>s_p\right)\\&=\mathbb{P}\left(y+Z_2\leq \text{VaR}_p(Y+Z_2), y+\sum_{i=1}^{3}Z_i>\text{VaR}_p\left(Y+\sum_{i=1}^{3}Z_i\right)\right)\\
				&=\mathbb{P}\left(y+\Phi^{-1}(U)\leq \text{VaR}_p(Y+\Phi^{-1}(U)), y+\Phi^{-1}(U)>\text{VaR}_p(Y+\Phi^{-1}(U))\right)\\
				&=\mathbb{P}\left(y+\Phi^{-1}(U)> \text{VaR}_p(Y+\Phi^{-1}(U)), y+\Phi^{-1}(U)\leq\text{VaR}_p(Y+\Phi^{-1}(U))\right)\\
				&=\mathbb{P}\left(S_y\leq s_p, X_{j\vert y}> x_{j,p}\right)=0,
			\end{aligned}
		\end{equation*} for any $y\in \mathbb{R}$. Under the conditional comonotonicity,\begin{equation*}
		\begin{aligned}
			\mathbb{P}\left(X_{2\vert y}\leq x_{j,p}, S_y>s_p\right)&=\mathbb{P}\left(y+Z_2\leq \text{VaR}_p(Y+Z_2), y+3Z_2>\text{VaR}_p(Y+3Z_2)\right)\\
			&=\mathbb{P}\left(y+Z_2\leq \sqrt{2}\Phi^{-1}(p), y+3Z_2>\sqrt{10}\Phi^{-1}(p)\right)\\
			&=\mathbb{P}\left(\frac{\sqrt{10}}{3}\Phi^{-1}(p)-\frac{y}{3}<Z_2\leq \sqrt{2}\Phi^{-1}(p)-y\right)\\
			&\neq\mathbb{P}\left(\sqrt{2}\Phi^{-1}(p)-y<Z_2\leq \frac{\sqrt{10}}{3}\Phi^{-1}(p)-\frac{y}{3}\right)\\
			&=\mathbb{P}\left(S_y\leq s_p, X_{j\vert y}> x_{j,p}\right)=0,
		\end{aligned}
		\end{equation*}if $y<\frac{3\sqrt{2}-\sqrt{10}}{2}\Phi^{-1}(p)$.
	\end{enumerate}
\end{example}
Part (2) of Example~\ref{cond com not upper} demonstrates that MES is not a law-invariant convex risk measure, since conditional comonotonicity maximizes all law-invariant convex risk measures; see Proposition~3.2 of \citet{bernard2017risk}.

We next present the corresponding lower bound.

\begin{theorem}[Lower bound for factor models]\label{lower bound for factor}
	Let $X_i=f_i(Y, Z_i)$, $i\in\mathcal{N},$ be $d$ risks such that $Y\sim H$, $Z_i$ are independent of $Y$, $X_{i\vert Y}\sim F_{i\vert Y}$. Let $S=\sum_{i=1}^{d}f_i(Y, Z_i)$ denote the aggregate risk. The lower bound of $\mathrm{MES}_p(X_j, S)$, $j\in\mathcal{N}$, is 
	\begin{equation}\label{factor lower bounds for d risks}
		m^f(p)\geq\frac{1}{1-p}\int \mathbb{E}\left[f_j(y, Z_j)\left\vert f_j(y, Z_j)\leq x_{j,1-p}\right.\right]\mathbb{P}\left(f_j(y, Z_j)\leq x_{j,1-p}\right)dH(y),
	\end{equation} where $x_{j,1-p}=\text{VaR}_{1-p}(f_j(Y, Z_j))$.
\end{theorem}
The proof of Theorem~\ref{lower bound for factor} is omitted, as it closely follows the arguments used in Theorems~\ref{lower bound} and~\ref{upper bound for factor}. The lower bound $m^f(p)$ is sharp if and only if
	$$\mathbb{P}(X_{j\vert Y}> \text{VaR}_{1-p}(X_{j}), S_{Y}> \text{VaR}_{p}(S))=\mathbb{P}(X_{j\vert Y}\leq \text{VaR}_{1-p}(X_{j}), S_{Y}\leq \text{VaR}_{p}(S))=0.$$
In the following subsections, we analyze the properties of these constrained bounds through three specific types of factor models: the additive background risk model (Section~\ref{ABRM}), the multiplicative background risk model (Section~\ref{MBRM}), and the minimum-based background risk model (Section~\ref{MBBRM}).

\subsection{Additive background risk model}\label{ABRM}
In this subsection, we derive improved risk bounds under the setting of the additive background risk (ABR) model. Specifically, we consider a risk vector of the form
\begin{equation*}
	\bold{X}=\left(\mu_1+b_1Y+\sigma_1Z_1,\mu_2+b_2Y+\sigma_2Z_2,\dots,\mu_d+b_dY+\sigma_dZ_d\right),
\end{equation*}where $\bm{\mu}=(\mu_1,\mu_2,\dots,\mu_d)$, $\bm{b}=(b_1,b_2,\dots,b_d)$ and $\bm{\sigma}=(\sigma_1,\sigma_2,\dots,\sigma_d)$ are parameter vectors.

The ABR model framework has been widely applied across economics, finance, and insurance; see, for instance, \citet{fama1993common} and \citet{fama2004capital} for the Capital Asset Pricing Model, and \citet{gollier1996risk}, \citet{furman2018weighted}, and \citet{zhou2018approximation} for applications in insurance risk management.

Without loss of generality, we assume $\bm{\mu}=(0,0,\dots,0)$ because \begin{equation*}
	\begin{aligned}
		\mathrm{MES}_p(X_j, S)&=\mathbb{E}\left[\mu_j+b_jY+\sigma_jZ_j\left\vert \sum_{i=1}^{d}\mu_i+b_iY+\sigma_iZ_i>\text{VaR}_{p}\left(\sum_{i=1}^{d}\mu_i+b_iY+\sigma_iZ_i\right)\right.\right]\\
		&=\mu_j+\mathbb{E}\left[b_jY+\sigma_jZ_j\left\vert \sum_{i=1}^{d}b_iY+\sigma_iZ_i>\text{VaR}_{p}\left(\sum_{i=1}^{d}b_iY+\sigma_iZ_i\right)\right.\right].
	\end{aligned}
\end{equation*} The general case can be recovered by incorporating the parameter $\mu_j$ as needed. The following proposition directly follows from Theorems~\ref{upper bound for factor} and~\ref{lower bound for factor}.

\begin{proposition}[Risk bounds for ABR model]\label{risk bounds for ABRM}
	Let $X_i=b_iY+\sigma_iZ_i$, $i\in\mathcal{N},$ be $d$ risks such that $Y\sim H$, $Z_i\sim G_i$ are independent of $Y$, $X_{i\vert Y}\sim F_{i\vert Y}$. Let $S=Y\sum_{i=1}^{d}b_i+\sum_{i=1}^{d}\sigma_i Z_i$ denote the aggregate risk. The upper bound of $\mathrm{MES}_p(X_j, S)$, $j\in\mathcal{N}$, is 
	\begin{equation}\label{ABRM upper bounds for d risk}
		M^f(p)\leq\frac{1}{1-p}\int \mathbb{E}\left[b_iy+\sigma_iZ_i\left\vert b_iy+\sigma_iZ_i> x_{j,p}\right.\right]\mathbb{P}\left(b_iy+\sigma_iZ_i> x_{j,p}\right)dH(y),
	\end{equation} where $x_{j,p}=\text{VaR}_p(b_jY+\sigma_jZ_j)$. The upper bound $M^f(p)$ is obtained when $X^c_{i\vert Y}=F_{i\vert Y}^{-1}(U)$, where $U\sim U[0,1]$. Moreover, the lower bound of $\mathrm{MES}_p(X_j, S)$ is 
	\begin{equation}\label{ABRM lower bounds for d risks}
		m^f(p)\geq \frac{1}{1-p}\int \mathbb{E}\left[b_iy+\sigma_iZ_i\left\vert b_iy+\sigma_iZ_i\leq x_{j,1-p}\right.\right]\mathbb{P}\left(b_iy+\sigma_iZ_i\leq x_{j,1-p}\right)dH(y),
	\end{equation}where $x_{j,1-p}=\text{VaR}_{1-p}(b_jY+\sigma_jZ_j)$. 
\end{proposition}
We now consider a specific example in which each variable $X_i$ follows a standard normal distribution.
\begin{example}\label{two normal example}
	Let $X_i=b_iY+\sqrt{1-b_i^2}Z_i$, $i=1,2,$ be two standard normally distributed risks such that $b_i\in(-1,1)$, $(X_i,Y)\sim N_2(\boldsymbol{\mu}, \bf{\Sigma})$ where the mean vector $\boldsymbol{\mu}=(0, 0)^T$ and the covariance matrix $\bf{\Sigma}=\begin{bmatrix}
		1 & b_i\\
		b_i & 1
	\end{bmatrix}$, and $Z_i\sim N(0,1)$ are independent of $Y$. Moreover, we denote the aggregate risk $S=\sum_{i=1}^{2}b_iY+\sqrt{1-b_i^2} Z_i$. As for the unconstrained bounds of $\mathrm{MES}_p(X_j, S)$, we obtain that
	$$M(p)=\frac{\phi\left(\Phi^{-1}(p)\right)}{1-p}, \text{ and } m(p)=0.$$ Under the setting of the ABR model, the constrained bounds of $\mathrm{MES}_p(X_j, S)$ are
	$$M^f(p)=\frac{b_j(b_1+b_2)+\sqrt{1-b_j^2}\sum_{i=1}^{2}\sqrt{1-b_i^2}}{\sqrt{2\left(1+b_1b_2+\sqrt{(1-b_1^2)(1-b_2^2)}\right)}}\frac{\phi\left(\Phi^{-1}(p)\right)}{1-p},$$ and $$m^f(p)=\frac{b_j(b_1+b_2)+\sqrt{1-b_j^2}\left(\sqrt{1-b_j^2}-\sqrt{1-b_i^2}\right)}{\sqrt{2\left(1+b_1b_2-\sqrt{(1-b_1^2)(1-b_2^2)}\right)}}\frac{\phi\left(\Phi^{-1}(p)\right)}{1-p},$$ where $i,j=1,2,$ and $i\neq j$. 
	Hence, the degree of improvement we obtain through the ABR model information is
	\begin{equation*}
		\delta_p=1-\frac{b_j(b_1+b_2)+\sqrt{1-b_j^2}\sum_{i=1}^{2}\sqrt{1-b_i^2}}{\sqrt{2\left(1+b_1b_2+\sqrt{(1-b_1^2)(1-b_2^2)}\right)}}+\frac{b_j(b_1+b_2)+\sqrt{1-b_j^2}\left(\sqrt{1-b_j^2}-\sqrt{1-b_i^2}\right)}{\sqrt{2\left(1+b_1b_2-\sqrt{(1-b_1^2)(1-b_2^2)}\right)}}.
	\end{equation*}

	Interestingly, under the ABR model setting with standard normal marginals, the measure of improvement \(\delta_p\) is independent of the prudence level \(p\). This property is clearly illustrated in Panels A, B, C, and D of Table~\ref{normal distributed risks}, where the percentages of \(\delta_p\) remain unchanged for \(p=0.90\) and \(p=0.95\) when other parameters are held constant.

	In Panels A and B, where \(b_1 = b_2\), the upper bounds remain unchanged whether or not factor model information is incorporated, whereas the lower bounds show substantial improvement, with the extent of improvement increasing with \(b_1\). In contrast, when 
	\(b_1 = -b_2\), as considered in Panels C and D, the constrained lower bound coincides with the unconstrained bound, i.e., \(m^f(p) = m(p)\), while the constrained upper bound \(M^f(p)\) decreases as \(b_1\) increases. Across all cases, the improvement in the dependence uncertainty spread becomes more pronounced as the magnitude of \(b_1\) increases. 

	Moreover, for two standard normally distributed risks, it can be analytically shown---and is further confirmed by Table~\ref{normal distributed risks}---that \(M^f(p) \leq M(p) = \mathrm{ES}_{p}(X_j)\) and \(m^f(p) \geq m(p) \geq \mathrm{LES}_{1-p}(X_j)\). Thus, while the dependence information provided by the ABR model improves the bounds on $\mathrm{MES}_p(X_j, S)$, the improvement is invariant with respect to \(p\). However, the extent of improvement crucially depends on the correlation coefficients between each \(X_i\) and the systemic risk \(Y\), represented by the parameters \(b_i\).   

	To further explore the impact of \(b_i\), Figure~\ref{normal distributed risks for b} plots the unconstrained and constrained risk bounds for \(\mathrm{MES}_{0.95}(X_j, S)\) as a function of \(b_2 \in (-1,1)\), given \(b_1=0.3\). As \(b_2\) increases, the improvement in both the lower and upper bounds initially declines and subsequently increases. In particular, the minimum degree of improvement occurs at \(b_2=-0.3\). Notably, these findings for \(\mathrm{MES}_p(X_j, S)\) are consistent with those reported for \(\mathrm{ES}_{p}(S)\) in Example~3.7 of \cite{bernard2017risk}. 

