Through Example~\ref{two normal example}, we demonstrate that incorporating partial dependence information via the ABR model can significantly affect the dependence uncertainty spread when evaluating \(\mathrm{MES}_p(X_j, S)\). In other words, the ABR model can improve the precision of risk assessment, although the degree of this improvement is influenced by both the dependence parameters and the marginal distributions of the underlying risks.  

\subsection{Multiplicative background risk model}\label{MBRM}
In this subsection, we derive risk bounds under the setting of the multiplicative background risk (MBR) model. Specifically, the risk vector is given by
\begin{equation*}
	\bold{X}=\left(\mu_1+\sigma_1\frac{Z_1}{Y},\mu_2+\sigma_2\frac{Z_2}{Y},\dots,\mu_d+\sigma_d\frac{Z_d}{Y}\right),
\end{equation*}where $\bm{\mu}=(\mu_1,\mu_2,\dots,\mu_d)$ and $\bm{\sigma}=(\sigma_1,\sigma_2,\dots,\sigma_d)$ are parameter vectors. In this model, the functional form is $f_i(Y,Z_i)=\mu_i+\sigma_i\frac{Z_i}{Y}$ for each $i\in\mathcal{N}$. 

The MBR model has received considerable attention in the literature; see, for example, \citet{franke2011risk}, \citet{asimit2016background}, \citet{furman2021multiplicative}, and \citet{marri2022risk}.

As in the previous subsection, we set $\bm{\mu}=(0,0,\dots,0)$ for simplicity. Consequently, the risk vector reduces to
\begin{equation*}
	\bold{Z}=\left(\frac{\sigma_1Z_1}{Y},\frac{\sigma_2Z_2}{Y},\dots,\frac{\sigma_dZ_d}{Y}\right).
\end{equation*}
\begin{proposition}[Risk bounds for MBR model]\label{risk bound for MBRM}
	Let $X_i=\frac{\sigma_i Z_i}{Y}$, $i\in\mathcal{N},$ be $d$ risks such that $Y\sim H$, $Z_i$ are independent of $Y$ and $X_{i\vert Y}\sim F_{i\vert Y}$. Let $S=\frac{\sum_{i=1}^{d}\sigma_i Z_i}{Y}$ denote the aggregate risk. The upper bound of $\mathrm{MES}_p(X_j, S)$, $j\in\mathcal{N}$, is 
	\begin{equation}\label{MBRM upper bounds for d risk}
		M^f(p)\leq\frac{1}{1-p}\int \mathbb{E}\left[\frac{\sigma_j Z_j}{y}\left\vert \frac{\sigma_j Z_j}{y}> x_{j,p}\right.\right]\mathbb{P}\left(\frac{\sigma_j Z_j}{y}> x_{j,p}\right)dH(y),
	\end{equation}where $x_{j,p}=\text{VaR}_p(\frac{\sigma_j Z_j}{Y})$. The lower bound of $\mathrm{MES}_p(X_j, S)$ is 
	\begin{equation}\label{MBRM lower bounds for d risks}
			m^f(p)\geq\frac{1}{1-p}\int \mathbb{E}\left[\frac{\sigma_j Z_j}{y}\left\vert \frac{\sigma_j Z_j}{y}\leq x_{j,1-p}\right.\right]\mathbb{P}\left(\frac{\sigma_j Z_j}{y}\leq x_{j,1-p}\right)dH(y),
	\end{equation}where $x_{j,1-p}=\text{VaR}_{1-p}(\frac{\sigma_j Z_j}{Y})$.
\end{proposition}
The proof of Proposition~\ref{risk bound for MBRM} is omitted, as it follows directly from Theorems~\ref{upper bound for factor} and~\ref{lower bound for factor}. The following example illustrates the bounds for $\mathrm{MES}_p(X_j, S)$ when the individual risks are Lomax distributed.

\begin{example}\label{pareto example}
	Let $X_i=\frac{\sigma_i Z_i}{Y}$, $i\in\mathcal{N},$ be $d$ risks such that $Z_i$ follow the exponential distribution with mean 1, and $Y$, which is independent of $Z_i$, is the gamma RV with shape parameter $\alpha>0$ and rate parameter $\beta=1$. In this setting, each $X_i$ follows a Lomax distribution with shape parameter $\alpha$ and scale parameter $\sigma_i>0$. 

	Under the condition $\sum_{i=1\& i\neq j}^{d}\sigma_i\geq \sigma_j(\frac{1}{p}-1)^{\frac{1}{\alpha}+1}$, the unconstrained bounds for $\mathrm{MES}_p(X_j, S)$ are given by
	$$M(p)=\frac{\sigma_j\alpha(1-p)^{-\frac{1}{\alpha}}}{(\alpha-1)}-\sigma_j \text{ and } m(p)=\sigma_j\frac{\alpha p^{1-\frac{1}{\alpha}}+(1-\alpha)p-1}{(1-\alpha)(1-p)}.$$ The parameters constraint ensures that $m(p)$ is sharp in \eqref{lower bounds for d risks} of Theorem~\ref{lower bound}.
%	Let $\lambda_i>0$, $i\in\mathcal{N}$, $\alpha>0$ and $U\in(0,1)$. What is the condition for parameters $\lambda_i$ and $\alpha$ to make
%	$$f(U)=(\lambda_1+\lambda_2+\cdots+\lambda_{j-1}+\lambda_{j+1}+\cdots+\lambda_d)(1-U)^{-\frac{1}{\alpha}}+\lambda_jU^{-\frac{1}{\alpha}}$$
%	an non-decreasing function of $U$?
%	
%	$$\frac{df(U)}{dU}=\frac{1}{\alpha}(\sum_{i\neq j}\lambda_i)(1-U)^{-\frac{1}{\alpha}-1}-\frac{1}{\alpha}\lambda_jU^{-\frac{1}{\alpha}-1}$$

	Under the MBR model, assuming $\alpha>1$ and $\sum_{i=1\& i\neq j}^{d}\sigma_i\geq \sigma_j(\frac{1}{p}-1)$, the constrained bounds of $\mathrm{MES}_p(X_j, S)$ are
	$$M^f(p)=\frac{\sigma_j\alpha(1-p)^{-\frac{1}{\alpha}}}{(\alpha-1)}-\sigma_j \text{ and } m^f(p)=\sigma_j\frac{\alpha p^{1-\frac{1}{\alpha}}+(1-\alpha)p-1}{(1-\alpha)(1-p)}.$$
	Here, $M^f(p)$ is obtained when $Z_i$ are comonotonic. In this case, \begin{equation*}\begin{aligned}
	\mathbb{P}\left(X_{j\vert y}\leq x_{j,p}, S_y> s_p\right)&=\mathbb{P}\left(\frac{\sigma_j Z_j}{y}\leq \text{VaR}_p\left(\frac{\sigma_j Z_j}{Y}\right), \frac{\sum_{i=1}^{d}\sigma_i Z_i}{y}>\text{VaR}_p\left[\frac{\sum_{i=1}^{d}\sigma_i Z_i}{Y}\right]\right)\\
	&=\mathbb{P}\left(\frac{\sigma_j Z_j}{y}\leq \text{VaR}_p\left(\frac{\sigma_j Z_j}{Y}\right), \frac{ Z_j\sum_{i=1}^{d}\sigma_i}{y}>\text{VaR}_p\left(\frac{ Z_j\sum_{i=1}^{d}\sigma_i}{Y}\right)\right)\\
	&=\mathbb{P}\left(\frac{Z_j}{y}\leq \text{VaR}_p\left(\frac{Z_j}{Y}\right), \frac{ Z_j}{y}>\text{VaR}_p\left(\frac{Z_j}{Y}\right)\right)\\
	&=\mathbb{P}\left(S_y\leq s_p, X_{j\vert y}> x_{j,p}\right)=0,\end{aligned}\end{equation*} for any $y>0$. In particular, under the parameter constraints, the inequality in \eqref{MBRM upper bounds for d risk} of Theorem~\ref{risk bound for MBRM} becomes an equality, and $m^f(p)$ is also sharp. 
\end{example} 
From Example~\ref{pareto example}, we observe that incorporating partial dependence information through the MBR model may not necessarily reduce the dependence uncertainty spread. Thus, in contrast to the ABR model, the MBR model does not inherently improve the assessment of risk exposure.

\subsection{Minimum-based background risk model}\label{MBBRM}
This subsection is dedicated to study improved risk bounds within the framework of the minimum-based background risk (MBBR) model, a structure studied in, e.g., \citet{asimit2010multivariate} and \citet{pai2020livestock}. The risk vector in this model is defined as
\begin{equation*}
	\bold{X}=\left(\min(Y, Z_1),\min(Y, Z_2),\dots,\min(Y, Z_d)\right),
\end{equation*}where the functional form is $f_i(Y,Z_i)=\min(Y, Z_i)$ for each $i\in\mathcal{N}$.

The improved risk bounds for MBBR model is derived in the proposition below.
\begin{proposition}[Risk bounds for MBBR model]\label{risk bound for MBBRM}
	Let $X_i=\min(Y, Z_i)$, $i\in\mathcal{N},$ be $d$ risks such that $Y\sim H$ and $Z_i\sim G_i$ are independent of $Y$. Let $S=\sum_{i=1}^{d}\min(Y, Z_i)$ denote the aggregate risk. The upper bound of $\mathrm{MES}_p(X_j, S)$, $j\in\mathcal{N}$, is 
	\begin{equation}\label{MBBRM upper bounds for d risk}
		M^f(p)\leq\frac{\int_{x_{j,p}}^{+\infty}\int_{x_{j,p}}^{y} zdG_j(z)dH(y)+\int_{x_{j,p}}^{+\infty}\int_{x_{j,p}}^{z} ydH(y)dG_j(z)}{1-p},
	\end{equation}where $x_{j,p}=\text{VaR}_p(\min(Y, Z_j))$. The lower bound of $\mathrm{MES}_p(X_j, S)$ is 
	\begin{equation}\label{MBBRM lower bounds for d risks}
		m^f(p)\geq\frac{\mu_j-\int_{x_{j,1-p}}^{+\infty}\int_{x_{j,1-p}}^{y} zdG_j(z)dH(y)-\int_{x_{j,1-p}}^{+\infty}\int_{x_{j,1-p}}^{z} ydH(y)dG_j(z)}{1-p},
	\end{equation}where $\mu_j=\mathbb{E}[\min(Y, Z_j)]$ and $x_{j,1-p}=\text{VaR}_{1-p}(\min(Y, Z_j))$.
\end{proposition}
The subsequent example illustrates the bounds when the individual risks $X_i$ for $i=1,2$ are exponentially distributed.
\begin{example}\label{exponential example}
	Let $X_i=\min(Y, Z_i)$, $i=1,2,$ be two risks such that $Z_i\sim \text{Expo}(\lambda)$ follow the exponential distribution with rate parameter $\lambda$, and $Y\sim  \text{Expo}(\lambda_0)$ is independent of $Z_i$. Under this setting, it follows that $X_i\sim\text{Expo}(\lambda_0+\lambda)$. For the unconstrained bounds of $\mathrm{MES}_{p}(X_1, S)$, we obtain
	$$M(p)=\frac{1-\ln(1-p)}{\lambda_0+\lambda}\text{ and } m(p)=-\frac{1}{\lambda_0+\lambda}\mathbb{E}\left[\ln(1-U)\vert -\ln(U-U^2)>u^p\right],$$
	where $p\in (0, 1)$, $U\sim U[0,1]$ and $u^p=\text{VaR}_p(-\ln(U-U^2))$. Under the MBBR model, the constrained bounds for $\mathrm{MES}_{p}(X_1, S)$ are given by
	$$M^f(p)=\frac{1-\ln(1-p)}{\lambda_0+\lambda},$$ and $$ m^f(p)=\mathbb{E}\left[\min\left(\frac{f(U_1)}{\lambda_0}, \frac{f(U)}{\lambda}\right)\left\vert \min\left(\frac{f(U_1)}{\lambda_0}, \frac{f(U)}{\lambda}\right)+\min\left(\frac{f(U_1)}{\lambda_0}, -\frac{\ln(U)}{\lambda}\right)>v^p\right.\right],$$ where $U\perp U_1\sim U[0,1]$, $f(x)=-\ln(1-x),$ and $$v^p=\text{VaR}_p\left(\min\left(\frac{f(U_1)}{\lambda_0}, \frac{f(U)}{\lambda}\right)+\min\left(\frac{f(U_1)}{\lambda_0}, -\frac{\ln(U)}{\lambda}\right)\right).$$
	The upper bound \( M^f(p) \) is attained when the \( Z_i \) are comonotonic, whereas the lower bound \( m^f(p) \) corresponds to the antimonotonic case. Notably, under the MBBR model framework, the unconstrained and constrained upper bounds coincide. While explicit closed-form solutions for \( m(p) \) and \( m^f(p) \) are unavailable, they can be approximated via simple numerical methods by simulating \( U \) and \( U_1 \). 

	In Figure~\ref{exponential distributed risks}, we depict the (improved) risk bounds for \( \mathrm{MES}_{0.95}(X_1, S) \) when \( X_i \), $i=1,2,$ (along with \( Y \) and \( Z_i \)) follow an exponential distribution with rate parameter \( \lambda_0+\lambda \) (parameters \( \lambda_0\) and \( \lambda \), respectively). The left panel presents the results for \( \lambda_0=1 \) and \( \lambda \in (0.1, 2.1) \), while the right panel shows the degree of improvement \( \delta_{0.95} \). The (improved) lower bound is computed numerically using a discretized version of \( U = \left[\frac{1}{n+1}, \frac{2}{n+1}, \dots, \frac{n}{n+1} \right] \) with \( n=10^5 \), while \( U_1 \) is obtained by randomly shuffling the elements of \( U \). The results indicate that as \( \lambda \) increases, the degree of improvement decreases.

