\section{Alternative improved risk bounds}\label{linear condition}
In this section, we derive a different form of improved risk bounds compared to those for factor models discussed previously. Specifically, we assume that the conditional expectation of each individual RV has a common linear relationship with the aggregate sum of all risks. For $\alpha, \beta\in \mathbb{R},$ we formulate the corresponding problems as 
\begin{align}
	m^l(p)&=\inf \left\{\mathrm{MES}_p(X_j,S): \bm{X}\in \mathcal{C}(\bm{X}), S=\sum_{i=1}^{d}X_i \right\}, \label{m for linear} \\
	M^l(p)&=\sup \left\{\mathrm{MES}_p(X_j,S): \bm{X}\in \mathcal{C}(\bm{X}), S=\sum_{i=1}^{d}X_i\right\},\label{M for linear}
\end{align} where
\begin{equation*}
	\mathcal{C}(\bm{X})=\left\{\bm{X}\in \mathcal{X}^d:X_i\sim F_i, \mathbb{E}[X_i|S]=\alpha+\beta S, 1\leq i\leq d\right\}
\end{equation*} denotes the model with fully specified marginal distributions and partially known dependence information.

We first recall the following theorem regarding the Weighted Insurance Pricing Model (WIPM) from \citet{furman2008weighted, furman2017adaptation} and references therein.

\begin{theorem}[WIPM]\label{WIPM}
	Let $X_i\sim F_i$, $i\in\mathcal{N},$ be $d$ risks and $S=\sum_{i=1}^{d}X_i$. Let $\Pi_{w}(X_j, S)=\frac{\mathbb{E}[X_jw(S)]}{\mathbb{E}[w(S)]}$ and $\pi_{w}(S)=\Pi_{w}(S, S)$, where $w(\cdot)$ is a weight function. If there exist constants $\alpha, \beta\in \mathbb{R}$ such that $\mathbb{E}[X_i|S]=\alpha+\beta S$ for all $i$, then
	\begin{equation}\label{wipm}
		\Pi_{w}(X_j, S)=\mathbb{E}[X_j]+\beta\left(\pi_{w}(S)-\mathbb{E}[S]\right)
	\end{equation} holds for every non-decreasing weight function $w(\cdot)$ for which all quantities under consideration are well-defined and finite.
\end{theorem}

\begin{remark}The weighted risk capital allocation rule $\Pi_{w}(X_j, S)$ is a versatile risk measure enables the study of different risk problems through appropriate choices of $w$. For example, by choosing $w(s)=\mathds{1}_{s>t},$ where $t\in\mathbb{R}$, $\Pi_{w}(X_j, S)$ reduces to the systemic risk allocation measure $\mathrm{MES}_p(X_j,S)$. We refer to \cite{furman2008weighted} further details on different weighted allocation rules corresponding to various choices of $w(s)$.
\end{remark}
\begin{proposition}\label{bivariate normal}
		Let $(X,S)\sim N_2(\boldsymbol{\mu}, \bf{\Sigma})$, where the mean vector $\boldsymbol{\mu}=(\mu_X, \mu_S)$ and covariance matrix $\bf{\Sigma}=\begin{bmatrix}
			\sigma_X^2 & \rho\sigma_X\sigma_S \\
			\rho\sigma_X\sigma_S & \sigma_S^2
		\end{bmatrix}.$  The improved lower and upper bounds of $\mathrm{MES}_{p}(X, S)$ are 
	\begin{equation}\label{risk bounds for normal risk}
		\mu_X-\frac{\sigma_X}{\sigma_S}\left(\mathrm{ES}_{p}(S)-\mu_S\right)\leq\mathrm{MES}_{p}(X, S)\leq \mu_X+\frac{\sigma_X}{\sigma_S}\left(\mathrm{ES}_{p}\left(S\right)-\mu_S\right).
	\end{equation}
\end{proposition}
\begin{proof}Under the bivariate normal setting, it is well-known that $\mathbb{E}[X|S]=\alpha+\beta S$, where $\alpha=\mu_X-\beta\mu_S$ and $\beta=\rho\frac{\sigma_X}{\sigma_S}$; see, e.g., \cite{furman2017beyond}. An application of Theorem~\ref{WIPM} then yields
	\begin{equation*}
		\mathrm{MES}_{p}(X, S)=\mu_X+\rho \frac{\sigma_X}{\sigma_S}\left(\mathrm{ES}_{p}(S)-\mu_S\right),
	\end{equation*} Since $\rho\in [-1,1]$ and all other terms are constants, the corresponding risk bounds follow as shown in Equation~\eqref{risk bounds for normal risk}. 
\end{proof}
\begin{remark}
	Proposition~\ref{bivariate normal} can be further extended to the case where $(X,S)$ follows a bivariate elliptical distribution. In this generalization, the intercept $\alpha$ and slope $\beta$ retain the same forms as in the normal case \citep{fang2018symmetric}, although $\sigma_S^2$, $\sigma_X^2$ and $\rho\sigma_{X}\sigma_{S}$ may not represent the actual variances and covariance.
\end{remark}

\begin{definition}[Joint mixability \citep{wang2016joint}]
	A $d$-tuple of probability distributions $(F_1,F_2,\dots, F_d)$ on $\mathbb{R}$ is said to be jointly mixable if there exist RVs $X_1\sim F_1$, $X_2\sim F_2,\dots,X_d\sim F_d$ such that $X_1+X_2+\cdots+X_d=K$ a.s., for some constant $K\in \mathbb{R}$, termed the joint center of $(F_1,F_2,\dots, F_d)$. The random vector $(X_1,X_2,\dots, X_d)$ is called jointly mixable.
\end{definition}

\begin{theorem}
	Let $X_i\sim F_i$, $i\in\mathcal{N},$ be $d$ non-negative (or non-positive) risks with $\mu_i=\mathbb{E}[X_i]$, and denote $S=\sum_{i=1}^{d}X_i$ as the aggregate risk. Suppose there exist constants $\alpha, \beta\in \mathbb{R}$ such that $\mathbb{E}[X_i|S]=\alpha+\beta S$. Then, the improved lower and upper bounds for $\mathrm{MES}_p(X_j, S)$ are given by
	\begin{equation}\label{risk bounds for nonnegative risk}
		m^l(p)=\mu_j\leq\mathrm{MES}_p(X_j, S)\leq r_j\sum_{i=1}^{d}\mathrm{ES}_{p}\left(X_i\right)=M^l(p),
	\end{equation} where $r_j=\frac{\mu_j}{\sum_{i=1}^{d}\mu_i}$. Furthermore, the lower bound $\mu_j$ is sharp if there exists $Y_i\overset{d}{=}X_i$ such that $(Y_1,Y_2,\dots,Y_d)$ is jointly mixable. The upper bound $r_j\sum_{i=1}^{d}\mathrm{ES}_{p}\left(X_i\right)$ is obtained when $X_i=F_i^{-1}(U)$, in which $U\sim U[0,1]$.
\end{theorem}
\begin{proof}
	We first prove the case of $d$ non-negative risks. Since $\sum_{i=1}^{d}\mathbb{E}[X_i|S=0]=\mathbb{E}[S|S=0]=0$ and $\mathbb{E}[X_i|S=0]\geq 0$ for all $i$, it follows that $\alpha=0$ if $\mathbb{E}[X_j|S]=\alpha+\beta S$. In addition,\begin{equation*}
		\beta=\frac{\mu_j}{\sum_{i=1}^{d}\mu_i},
	\end{equation*}because $\mathbb{E}[\mathbb{E}[X_j|S]]=\mathbb{E}[X_j]=\beta \mathbb{E}[S]$. Since $\Pi_{w}(X_j, S)=\mathrm{MES}_p(X_j, S)$ for $w(s)=\mathds{1}_{s>t}$, Theorem~\ref{WIPM} applies. Then,
	\begin{equation}\label{connection between x and s}
		\mathrm{MES}_p(X_j, S)=\mu_j+\frac{\mu_j}{\sum_{i=1}^{d}\mu_i}\left(\mathrm{ES}_{p}(S)-\sum_{i=1}^{d}\mu_i\right)=\frac{\mu_j}{\sum_{i=1}^{d}\mu_i}\mathrm{ES}_{p}(S).
	\end{equation}In this case, solving for risk bounds on $\mathrm{MES}_p(X_j, S)$ reduces to solving for bounds on $\mathrm{ES}_{p}(S)$. By Propositions~3.2 and 3.5 of \cite{bernard2017risk},
	\begin{equation*}
		\sum_{i=1}^{d}\mu_i=\mathrm{ES}_{p}\left(\sum_{i=1}^{d}\mu_i\right)	\leq \mathrm{ES}_{p}(S)\leq \mathrm{ES}_{p}\left(\sum_{i=1}^{d}F_i^{-1}(U)\right)=\sum_{i=1}^{d}\mathrm{ES}_{p}\left(X_i\right).
	\end{equation*} The last equation holds because ES is comonotonic additive and objective. The risk bounds on $\mathrm{MES}_p(X_j, S)$ are thus obtained by Equation~\eqref{connection between x and s} and $\beta\geq 0$. 

	The proof for non-positive risks is similar, with the crucial observation that $\beta\geq 0$ in both cases.
\end{proof}
\begin{remark}
	To achieve the sharp lower bound in \eqref{risk bounds for nonnegative risk}, joint mixability of $(F_1, F_2, \dots, F_d)$ must be established, which in general is a nontrivial problem. Necessary and sufficient conditions for joint mixability for various classes of distributions are provided in \cite{wang2016joint}; see also the initial concept introduced by \cite{wang2011complete}. Therefore, the sharpness of the lower bound is affected by the nature of the distribution functions. The upper bound, however, is always sharp and corresponds to the comonotonic case. This comonotonicity yields sharp upper bounds for all law-invariant convex risk measures; see, e.g., \citet{meilijson1979convex} and \citet{puccetti2012bounds}.
\end{remark}
The following example illustrates a case where the linear conditional expectation assumption is satisfied.
\begin{example}\label{unif example}
	Let $X_i\sim U[0,1]$, $i=1,2,3,$ where $\mu_i=\frac{1}{2}$, and define $S=X_1+X_2+X_3$ as the aggregate risk. The unconstrained bounds for $\mathrm{MES}_p(X_j, S)$ are
	$$M(p)=\frac{1}{2}(1+p) \text{ and } m(p)=\frac{1}{2}(1-p).$$
	Assuming $\mathbb{E}[X_i|S]=\frac{1}{3}S$, the constrained bounds for $\mathrm{MES}_p(X_j, S)$ are
	$$M^l(p)=\frac{1}{2}(1+p), \qquad m^l(p)=\frac{1}{2}.$$
    Furthermore, the lower bound $\frac{1}{2}$ is obtained when 
	\begin{equation*}
		\begin{aligned}
			Y_1&=U\sim U[0,1]; \\
			Y_2&=\left\{
			\begin{aligned}
				&-2U+1,  &\text{if } 0\le U \le \frac{1}{2}; \\
				&-2U+2,    &\text{if } \frac{1}{2}\le U \le 1;
			\end{aligned}
			\right. \\
			Y_3&=\left\{
			\begin{aligned}
				&U+\frac{1}{2},  &\text{if } 0\le U \le \frac{1}{2}; \\
				&U-\frac{1}{2},    &\text{if } \frac{1}{2}\le U \le 1.
			\end{aligned}
			\right. \\
		\end{aligned}
	\end{equation*} Note that $(Y_1,Y_2,Y_3)$ is jointly mixable with joint center $K=\frac{3}{2}$, i.e., $\sum_{i=1}^{3}Y_i=\frac{3}{2}$ almost surely; see \citet{ruschendorf2002variance} for the concept of the mixing copula. The upper bound $\frac{1}{2}(1+p)$ is obtained when $H_i=U$ for each $i$.

	The degree of improvement is $\delta_p=\frac{1}{2},$ which is independent of $p$. Importantly, while there is an improvement in the lower bound: $$m(p)=\frac{1}{2}(1-p)\leq \frac{1}{2}=m^l(p),$$ there is no difference between the constrained and unconstrained upper bounds. These findings are illustrated in Table~\ref{unif distributed risks}, where the gap between improved bounds constitutes exactly 50\% of the original spread between unconstrained bounds. 

