\title{\normalsize Phase transitions and spontaneous symmetry breaking in the renormalized Ginzburg-Landau theory}

\author{O. C. Feulefack$^{a}$, C. Tsague Fotio$^{b}$, R. M. Keumo Tsiaze$^{a,c}$}

