\subsection{Continuous Compounding}
\label{Subsec: continuous}
It is interesting to examine the limit case of continuous compounding where $\tau_{i,k}\rightarrow 0$ and the \euro STR spot overnight rate in eq. \eqref{eq: totalcomp} becomes
\begin{equation}\begin{split}
R_\textit{\euro ST}(T_{i-1},T_i)
&\rightarrow\dfrac{1}{\tau_{i}}
	\Brack{e^{\int_{T_{i-1}}^{T_i}r_{\textit{\euro ST}}(u)\,du}-1}\\
&=\dfrac{1}{\tau_{i}}
	\Brack{e^{\Delta\tau_{i}}e^{\int_{T_{i-1}}^{T_i}r_\textit{EON}(u)\,du}-1}.
\end{split}
\end{equation}
We show in App. \ref{App: OIS continuous} that in this case the \euro STR OIS price and par rate are given by 
\begin{align}
\OIS_\textit{\euro ST}(t;\bm{T},\bm{S},K,\omega,\alpha)
&\approx \OIS_\textit{EON}(t;\bm{T},\bm{S},K,\omega,\alpha)
+ \omega N \sum_{i=\eta_R(t)}^n P^\alpha(t;T_i) \Sigma_{c,i}(\Delta) \tau_{R,i},
\label{eq: OIS price difference continuous}\\
R_\textit{\euro ST}(t;\textbf{T},\textbf{S},\alpha)
&\approx R_\textit{EON}(t;\textbf{T},\textbf{S},\alpha) + \delta_c(t;\Delta,\bm{T},\bm{S},\alpha),
\label{eq: OIS rate impact continuous}\\
\delta_c(t;\Delta,\bm{T},\bm{S},\alpha) 
&= \dfrac{\sum_{i=\eta_R(t)}^n P^\alpha(t;T_i)\Sigma_{c,i}(\Delta)\tau_{R,i}}{A(t;\bm{S},\alpha)},
\label{eq: OIS rate spread continuous}\\
\Sigma_{c,i}(\Delta)
&= F_\textit{\euro ST,i}(t) - F_\textit{EON,i}(t)\nonumber\\
&=\dfrac{1}{\tau_{i}}\Brack{e^{\Delta\tau_{i}}-1}\dfrac{P^\textit{EON}(t;T_{i-1})}{P^\textit{EON}(t;T_{i})}.
\label{eq: OIS Sigma continuous}
\end{align}
