\subsection{Discrete Compounding}
\label{App: OIS discrete}
We compute the \euro STR forward overnight compounded rate $F_\textit{\euro ST,i}(t)$ expected at time at time $t<T_i$ for the future OIS floating coupon period $\Brack{T_{i-1},T_i}$ as the expectation of the corresponding spot rate in eq. \eqref{eq: totalcomp} under the $T_i-$forward measure, using the forward measure equivalence $\mathbb{Q}^\textit{\euro ST}_{T_i} \sim \mathbb{Q}^\textit{EON}_{T_i}$ discussed in sec. \ref{Subsec: measure equiv},
\begin{equation}
\begin{split}
F_\textit{\euro ST,i}(t) 
&=\mathbb{E}_t^{\mathbb{Q}^\textit{\euro ST}_{T_i}}\Brack{R_\textit{\euro ST}(T_{i-1},T_i)}  
=\mathbb{E}_t^{\mathbb{Q}^\textit{EON}_{T_i}}\Brack{R_\textit{\euro ST}(T_{i-1},T_i)} \\
&=\frac{1}{\tau_{i}} \mathbb{E}_t^{\mathbb{Q}^\textit{EON}_{T_i}}
	\Brace{\prod_{k=1}^{n_i}
	\Brack{1+\Brack{R_\textit{EON}(T_{i,k-1},T_{i,k}) + \Delta} \tau_{i,k} } -1 }\\
&=\frac{1}{\tau_{i}} 
\Brace{\prod_{k=1}^{n_i}
	\Brack{1+ \Brack{\mathbb{E}_t^{\mathbb{Q}^\textit{EON}_{T_{i,k}}}
	\Brack{R_\textit{EON}(T_{i,k-1},T_{i,k})}+ \Delta} \tau_{i,k} } -1 }\\
&=\frac{1}{\tau_{i}} 
	\Brace{\prod_{k=1}^{n_i}
	\Brack{1+\Brack{F_\textit{EON,i,k}(t)+\Delta } \tau_{i,k}} -1 }\\
&=\frac{1}{\tau_{i}}
	\Brace{\prod_{k=1}^{n_i}
	\Brack{\frac{P^\textit{EON}(t;T_{i,k-1})}{P^\textit{EON}(t;T_{i,k})}+\Delta\,
	\tau_{i,k} }-1 },
\label{eq: RESTon}
\end{split}
\end{equation}
(see e.g. \cite{AmeBia13,Hen14} for detailed math), where $F_\textit{EON,i,k}(t)$ is the forward overnight rate observed at time $t$ for the future overnight period $\Brack{T_{i,k-1},T_{i,k}}$, a martingale under the $T_{i,k}-$ forward measure $\mathbb{Q}_{T_{i,k}}$ given in eq. \eqref{eq: IBOR forward rate vs risky ZCBs}.
%\begin{align}
%F_\textit{on,ij}^\textit{EON}(t) = F_\textit{on}^\textit{EON}(T_{i,k-1},T_{i,k})
%&=\mathbb{E}_{t}^{\mathbb{Q}_{T_{i,k}}} 	
%	\Brack{R_\textit{EON}(T_{i,k-1},T_{i,k})}\nonumber\\
%&=\frac{1}{\tau_F(T_{i,k-1},T_{i,k})}
%	\Brack{\frac{P^\textit{EON}(t;T_{i,k-1})}{P^\textit{EON}(t;T_{i,k})}-1 }.
%\label{eq: on fwd rate}
%\end{align}
In eq. \ref{eq: RESTon} we assumed $\tau_{F,i,k}=\tau_{i,k}\;\forall\; i,k$.
The product in the last row of eq. \eqref{eq: RESTon} may be manipulated as follows,
\begin{multline}
\prod_{k=1}^{n_i}
\Brace{\frac{P^\textit{EON}(t;T_{i,k-1})}{P^\textit{EON}(t;T_{i,k})}
	+\Delta\,\tau_{i,k} }\\
= \Brack{\frac{P^\textit{EON}(t;T_{i,0})}{P^\textit{EON}(t;T_{i,1})}
	+\Delta\,\tau_{i,1}}\cdot 
	\Brack{\frac{P^\textit{EON}(t;T_{i,1})}{P^\textit{EON}(t;T_{i,2})}
	+\Delta\,\tau_{i,2}}\cdots
	\Brack{\frac{P^\textit{EON}(t;T_{i,n_{i-1}})}{P^\textit{EON}(t;T_{i,n_i})}
	+\Delta\,\tau_{i,n_i}}\\
=\prod_{k=1}^{n_i} \frac{P^\textit{EON}(t;T_{i,k-1})}{P^\textit{EON}(t;T_{i,k})}
	+ \Delta \sum_{l=1}^{n_i} \tau_{i,l} \prod_{\substack{k=1\\k\neq l}}^{n_i}
	\frac{P^\textit{EON}(t;T_{i,k-1})}{P^\textit{EON}(t;T_{i,k})}
	+ f\Brack{\textit{O}(\Delta^m, m\geq2)},
\label{eq: product 2}
\end{multline}
where $f$ gathers the remaining terms of order $m\geq 2$ in the spread $\Delta$, which can be neglected. 
The second term in eq. \eqref{eq: product 2} can be written as follows,
\begin{align}
&\Delta \sum_{l=1}^{n_i} \tau_{i,l} \prod_{\substack{k=1\\k\neq l}}^{n_i}
\frac{P^\textit{EON}(t;T_{i,k-1})}{P^\textit{EON}(t;T_{i,k})}
= \Delta \sum_{l=1}^{n_i} \tau_{i,l}
	\frac{P^\textit{EON}(t;T_{i,l})}{P^\textit{EON}(t;T_{i,l-1})}
	\prod_{k=1}^{n_i}
	\frac{P^\textit{EON}(t;T_{i,k-1})}{P^\textit{EON}(t;T_{i,k})}.
\end{align}
Hence, considering the telescopic product
\begin{equation}
\prod_{k=1}^{n_i}
\frac{P^\textit{EON}(t;T_{i,k-1})}{P^\textit{EON}(t;T_{i,k})}
= \frac{P^\textit{EON}(t;T_{i,0})}{P^\textit{EON}(t;T_{i,n_i})}
= \frac{P^\textit{EON}(t;T_{i-1})}{P^\textit{EON}(t;T_i)},
\end{equation}
eq. \eqref{eq: RESTon} becomes
\begin{align}
F_\textit{\euro ST,i}(t) 
&\approx \frac{1}{\tau_{i}}
	\Brack{\frac{P^\textit{EON}(t;T_{i-1})}{P^\textit{EON}(t;T_i)}
	+ \Delta \frac{P^\textit{EON}(t;T_{i-1})}{P^\textit{EON}(t;T_i)}
	\sum_{l=1}^{n_i} \tau_{i,l} 
	\frac{P^\textit{EON}(t;T_{i,l})}{P^\textit{EON}(t;T_{i,l-1})}-1 }\nonumber \\
&= F_\textit{EON,i}(t)  + \Sigma_{d,i}(\Delta),
\label{eq: fwd ESTR vs EONIA}\\
\Sigma_{d,i}(\Delta)
&:=\frac{\Delta}{\tau_{i}}
	\Brack{\frac{P^\textit{EON}(t;T_{i-1})}{P^\textit{EON}(t;T_i)}
	\sum_{l=1}^{n_i} \tau_{i,l} \frac{P^\textit{EON}(t;T_{i,l})}{P^\textit{EON}(t;T_{i,l-1})}}.
\label{eq: sigma_i}
\end{align}
Eq. \eqref{eq: fwd ESTR vs EONIA} allows to express the \euro STR forward overnight compounded rate as the EONIA forward overnight compounded rate plus the spread in eq. \eqref{eq: sigma_i}. 
Hence, the price a \euro STR OIS is given, using eq. \eqref{eq: IRS price}, by
\begin{multline}
\OIS_\textit{\euro ST}(t;\bm{T},\bm{S},K,\omega,\alpha)
= \omega N \Brack{\sum_{i=\eta_R(t)}^{n} 
	P^\alpha(t;T_i) F_\textit{\euro ST,i}(t) \tau_{R,i} 
	- K A(t;\bm{S},\alpha)},\\
= \omega N \Brace{\sum_{i=\eta_R(t)}^{n} \Brack{P^\alpha(t;T_i) F_\textit{EON,i}(t) \tau_{R,i} 
	+ P^\alpha(t;T_i) \Sigma_{d,i}(\Delta) \tau_{R,i}} 
	- K A(t;\bm{S},\alpha)},\\
= \OIS_\textit{EON}(t;\bm{T},\bm{S},K,\omega,\alpha)
	+ \omega N \sum_{i=\eta_R(t)}^{n} P^\alpha(t;T_i) \Sigma_{d,i}(\Delta) \tau_{R,i}.
\end{multline}
The \euro ST OIS par rate is obtained by setting $\OIS_\textit{\euro ST}(t;\bm{T},\bm{S},K,\omega,\alpha)=0$ and solving for $K$. The result is given in eq. \eqref{eq: OIS rate difference discrete}.


