&\approx\dfrac{1}{\tau_{i}}\left[e^{\int_{T_{i-1}}^{T_{i}}r_{\textit{\euro ST}}(u)d u}-1\right]\\
&=\dfrac{1}{\tau_{i}}\left[e^{\int_{T_{i-1}}^{T_{i}}[r_\textit{EON}(u) + \Delta]d u}-1\right]\\
&=\dfrac{1}{\tau_{i}}\left[e^{\Delta\tau_{i}}e^{\int_{T_{i-1}}^{T_{i}}r_\textit{EON}(u)d u}-1\right].
\end{split}
