\section{Risky ZCB details}

\subsection{Hazard rate}
\label{App: hazard rate}
The hazard rate $ \gamma=\gamma(t) $ referred to the default time process $ \tau $ is defined as
\begin{equation}
\gamma(t)dt=\mathbb{Q}(t<\tau\leq t+dt|\tau>t)
\label{eq: hazard rate}
\end{equation}
that is the probability that  default occurs within the interval $ \mathopen{(}t,t+dt\mathclose{]} $, conditioned to the fact that the default has not already occurred at $ t $; using conditioned probability definition, we may write
\begin{equation}
\mathbb{Q}(t<\tau\leq t+dt)=\gamma(t)\mathbb{Q}(\tau>t)dt
\end{equation}
and then
\begin{equation}\begin{split}
\mathbb{Q}(t<\tau\leq t+dt|\tau>t)&=\mathbb{Q}(\textcolor{black}{\{\tau\leq t+dt\}}\cap\textcolor{black}{\{\tau>t\}})\\
&=\mathbb{Q}(\{\tau>t\}\setminus\{\tau>t+dt\})\\
&=\mathbb{Q}(\tau>t)-\mathbb{Q}(\tau>t+dt).
\end{split}\end{equation}
Setting $ \Gamma(t):=\mathbb{Q}(\tau>t) $ we get
\begin{gather}
\Gamma(t)-\Gamma(t+dt)=\gamma(t)\Gamma(t)dt\\
\Gamma'(t)=-\gamma(t)\Gamma(t).
\label{eq: gamma}
\end{gather}
Hence we obtain the following expression for the survival probability
\begin{gather}
\mathbb{Q}(\tau>t) = \Gamma(t) = e^{-\int_0^t\gamma(s)ds}.
\end{gather}
The derivation above assumes $\gamma$ deterministic. According to \cite{BriMer06} for $\gamma$ stochastic we have
\begin{gather}
\mathbb{Q}(\tau>t) 
:= \mathbb{E}^{\mathbb{Q}}\Brack{\mathds{1}_{\{\tau>T\}}\Big|\mathcal{H}_t}
= \mathbb{E}^\mathbb{Q}\Brack{e^{-\int_0^t\gamma(s)ds}\Big|\mathcal{H}_t}
:=S(0;t).
\label{eq: survival probability}
\end{gather}



\subsection{Risky Zero Coupon Bond}
\label{App: riskyZCB}
We define the risky zero coupon bond with no recovery rate as the bond issued by a defaultable issuer $I$ paying one unit of currency at maturity $T$ if the issuer $I$ has not defaulted before. The price at time $t<T$ is given by a generalization of eq. \eqref{eq: ZCBrf},
\begin{equation}
\begin{split}
P_I(t;T)=\mathbb{E}^\mathbb{Q}\Brack{D(t;T)\bm{1}_{\Brace{\tau_I>T}}|\mathcal{G}_t},
\end{split}
\end{equation}
where $\tau_{I}>t$ is the (stochastic) default time of the issuer. 
If interest rates and default time are independent of each other we obtain, using eq. \ref{eq: survival probability},
\begin{multline}
P_{I}(t;T) = 
\mathbb{E}^\mathbb{Q}\Brack{D(t;T)|\mathcal{F}_t}
\mathbb{E}^\mathbb{Q}\Brack{\bm{1}_{\Brace{\tau_I>T}}|\mathcal{H}_t}\\
= P(t;T)S_I(t;T)
=\mathbb{E}^{\mathbb{Q}}\left[e^{-\int_{t}^{T}\Brack{r(s)+\gamma_I(s)}ds}\Big|\mathcal{F}_t\right],
\label{eq: ZCBrr}
\end{multline}
where $S_{I}(t,T)$ is the survival probabiliy for $I$ until time $T$, evaluated in $t$, and $\gamma$ is the hazard rate defined in sec. \ref{App: hazard rate}. 
\par 
Let’s now consider the more realistic case where recovery rate is represented by a non-null process $\mathcal{R}_I$. 
It can be shown (see \cite{Bie13,Gra05}) that the price of a risky zero coupon bond becomes 
\begin{equation}\begin{split}
P_I(t;T)
&=\mathbb{E}_{t}^{\mathbb{Q}}\left[D(t;\tau_I)\mathcal{R}(\tau_{I})\mathds{1}_{\{\tau_{I}\leq T\}} 
+ D(t;T)\mathds{1}_{\{\tau_{I}>T\}} \right]\\
&=\mathbb{E}_t^{\mathbb{Q}}\left[\int_{t}^{T}\mathcal{R}_I(u)\gamma_I(u)e^{-\int_{t}^{u}\Brack{r(s)+\gamma_I(s)}ds}du\right] 
+ P_I(t;T).
\label{eq: risky zero coupon bond}
\end{split}\end{equation}
We adopt the recovery of treasury model (\cite{Bie13,Gra05}), such that 
\begin{equation}
\mathcal{R}_I(t) = \textit{Rec}_I\,P(t;T),
\label{eq: rt}
\end{equation}
where $ \textit{Rec}_I $ is a constant. Under such model the price of the risky zero coupon bond in eq. \eqref{eq: risky zero coupon bond} simplifies as
\begin{equation}\begin{split}
P_I(t;T)&= \textit{Rec}_I \mathbb{E}_{t}^{\mathbb{Q}}\left[\int_{t}^{T}P(u,T)\gamma_I(u)e^{-\int_{t}^{u}\Brack{r(s)+\gamma_I(s)}ds}du\right] + P_{I}(t;T)\\
&=\textit{Rec}_I \mathbb{E}_{t}^{\mathbb{Q}}\left[D(t;T)\int_{t}^{T}\gamma_I(u)e^{-\int_{t}^{u}\gamma_I(s)ds}du\right] + P_{I}(t;T)\\
&=\textit{Rec}_I \mathbb{E}_{t}^{\mathbb{Q}}\left[D(t;T)\left(1-e^{-\int_{t}^{T}\gamma_I(s)ds}\right)\right] + P_{I}(t;T)\\
&=\textit{Rec}_I \left[P(t;T)-P_{I}(t;T)\right]+P_{I}(t;T)\\
%&=\textit{Rec}_I P(t;T)+(1-\textit{Rec}_I)P_{I}(t;T)\\
%&=\textit{Rec}_I P(t;T)+(1-\textit{Rec}_I)P(t;T)S_{I}(t,T)\\
&=P(t;T)\Brack{\textit{Rec}_I+(1-\textit{Rec}_I)S_{I}(t,T)}.
\label{eq: ZCB rr}
\end{split}\end{equation}


\subsection{Funding Spread}
\label{App: funding spread}
The zero funding spread rate defined in eq. \eqref{eq: zero rate} can be written as
\begin{equation}
\mathcal{S}_I(t,T)=\dfrac{1}{T-t}\log\dfrac{P(t;T)}{P_I(t,T)}.
\label{eq: zero funding spread}
\end{equation}
Using eq. \eqref{eq: ZCB rr} above we obtain
%\begin{equation}
%\begin{split}
%P_I(t;T)
%%&=P(t;T)\left[\textit{Rec}_I+S_{I}(t,T)-\textit{Rec}_IS_{I}(t,T)+1-1\right]\\
%%&=P(t;T)\left[1-(1-\textit{Rec}_I)+S_{I}(t,T)(1-\textit{Rec}_I)\right]\\
%&=P(t;T)\Brace{1-(1-\textit{Rec}_I)\Brack{1-S_{I}(t,T)}}.
%\end{split}
%\end{equation}
%then
\begin{equation}
\begin{split}
\mathcal{S}_I(t,T)
&=\dfrac{1}{T-t}\log\dfrac{1}{1-(1-\textit{Rec}_I)\Brack{1-S_I(t,T)}}\\
&= -\dfrac{1}{T-t}\log\Brace{1-(1-\textit{Rec}_I)\Brack{1-S_I(t,T)}}\\
&= -\dfrac{1}{T-t}\log\Brack{1-1+S_I(t,T)+\textit{Rec}_I - \textit{Rec}_I S_I(t,T)}\\
&= -\dfrac{1}{T-t}\log\Brace{S_I(t,T)\Brack{1+\textit{Rec}_I\Parenthesis{-1+\dfrac{1}{S_{I}(t,T)}}}}.
\label{eq: spread zero}
\end{split}
\end{equation}
We now recall that the survival probability may be defined through the hazard rate (define in sec \ref{App: hazard rate})
\begin{equation}
S_I(t,T)=e^{-\int_t^T\gamma(s)ds}.
\label{eq: survival pbt}
\end{equation}
Inserting the survivial probability \eqref{eq: survival pbt} inside the spread rate formula \eqref{eq: spread zero}, we arrive to (see \cite{Jar97}, \cite{Bie13})
\begin{equation}\begin{split}
\mathcal{S}(t,T)&=\dfrac{\int_{t}^{T}\gamma(s)ds}{T-t} -\dfrac{1}{T-t}\log\Brack{1+\textit{Rec}_I\left(e^{\int_t^T\gamma(s)ds}-1\right)}.
\end{split}\end{equation}
In order to obtain the short spread rate, we apply the limit
\begin{equation}
\begin{split}
s_I(t) := \lim_{T\rightarrow t^{+}}\mathcal{S}(t,T)=\gamma(t)(1-\textit{Rec}_I).
\label{eq: inst spread}
\end{split}
\end{equation}
Using eq. \eqref{eq: gamma} we finally obtain
\begin{equation}
s_I(u)=-\dfrac{\partial_{u}S_I(t,u)}{S_I(t,u)}(1-\textit{Rec}_I).
\end{equation}



