\begin{example}(Laplace mechanism, \cite{dwork2014algorithmic})
Under Condition \ref{Con1}, and by applying the Cauchy–Schwarz inequality, we know that
 \begin{align*}
     \|\nabla f(\theta, x) - \nabla f(\theta, x^\prime)\|_1 \leq \sqrt{d}\|\nabla f(\theta, x) - \nabla f(\theta, x^\prime)\|_2
 \end{align*}
 for two different values $x$ and $x^\prime.$ Correspondingly, the $\ell_1$-sensitivity of $\nabla f(\theta,x)$ is bounded by $2\sqrt{d}C_0.$ Therefore, $\theta_i$ achieves $\varepsilon_i$-LDP if {each component of the $d$-dimensional noise vector} $\omega_i(\varepsilon_i,\delta_i)$ is sampled from ${\rm Laplace}(0,2\sqrt{d}/\varepsilon_i)$.
\end{example}

\begin{example}(Gaussian mechanism, \cite{dwork2014algorithmic})
If instead we consider $\ell_2$-sensitivity of $\nabla f(\theta,x)$, for $d$-dimensional noise vectors $\omega_i(\varepsilon_i,\delta_i)$ sampled from normal distribution ${N}(\boldsymbol{0}_d, (8\log(1.25/\delta_i)/\varepsilon_i)\boldsymbol{I}_d)$, then $\theta_i$ achieves $(\varepsilon_i, \delta_i)$-LDP.
\end{example}

\begin{example}(Gaussian differential privacy mechanism, \cite{dong2022gaussian}) \label{eg3}
To overcome the weak interpretability of $(\varepsilon,\delta)$-DP, GDP provides an intuitively appealing interpretation: determining whether an individual is part of a given dataset is at least as challenging as distinguishing between two normal distributions--specifically ${N}(0,1)$ and ${N}(\mu,1)$ based on one draw, where $\mu \geq 0$. For $\omega_i(\varepsilon_i,\delta_i)$ sampled from ${N}(\boldsymbol{0}_d, (4/\mu_i)\boldsymbol{I}_d)$, then $\theta_i$ achieves local $\mu_i$-GDP. Actually, using Corollary 1 in \citet{dong2022gaussian}, $\theta_i$ is also $(\varepsilon_i,\delta_{\mu_i}(\varepsilon_i))$-LDP for all $\varepsilon_i>0$, where
 \begin{align*}
     \delta_{\mu_i}(\varepsilon_i) = \Phi(-\frac{\varepsilon_i}{\mu_i} + \frac{\mu_i}{2}) - e^{\varepsilon_i}\Phi(-\frac{\varepsilon_i}{\mu_i} - \frac{\mu_i}{2})
 \end{align*}
and $\Phi(\cdot)$ is the cumulative distribution function of the standard normal
distribution.
\end{example}


 From (\ref{psgd}), each individual has different privacy budgets $(\varepsilon_i,\delta_i)$, $i=1,\ldots, n$, which protect the privacy of individual data owners without the need for a trusted third party.
 %Unlike traditional central DP, LDP empowers each participant to apply a DP mechanism to their own raw data locally. The perturbed data is then securely transmitted to an untrusted server.
 In practice, stochastic approximation schemes are sequentially interactive cases, which is a typical example of LDP \citep{duchi2018minimax}. The estimator $\theta_i$ defined in (\ref{psgd}) is referred to LDP-SGD estimator. Without loss of generality, we assume each iteration of (\ref{psgd}) satisfies $(\varepsilon_i,\delta_i)$-LDP and establish the following results.


\begin{theorem}{\label{sgd11}}
  The LDP-SGD estimator  ${\theta}_i$
 obtained from (\ref{psgd}) is $(\max_{1\leq j\leq i}\varepsilon_j,\max_{1\leq j \leq i}\delta_j)$-LDP, where $i\geq 1$.
    \end{theorem}

A special case is that the proposed LDP-SGD estimator $\theta_n$ is central $(\varepsilon,\delta)$-DP when $\varepsilon_1=\cdots=\varepsilon_n = \varepsilon$ and $\delta_1 = \cdots = \delta_n = \delta$ without considering different privacy budget for each individual.

Meanwhile, we also consider the Polyak-Ruppert averaging private estimator $\bar{\theta}_n = \sum_{i=1}^n{\theta}_i/n$ after $n$ iterations, which is referred to LDP-ASGD estimator. Note that this estimator
can also be recursively updated: $\bar{\theta}_n = (n-1)\bar{\theta}_{n-1}/n + {\theta}_n/n$. The post-processing property in Proposition \ref{lemma3} along with Theorem \ref{sgd11} easily imply the following results:
\begin{theorem}{\label{asgd}}
 The LDP-ASGD estimator    $\bar{\theta}_i$ is $(\max_{1\leq j\leq i}\varepsilon_i,\max_{1\leq j \leq i}\delta_i)$-LDP.
    \end{theorem}

