\section{Theoretical properties}
\label{sec:thm}
\renewcommand{\theequation}{4.\arabic{equation}}
\setcounter{equation}{0}

\subsection{Strongly convex objectives}
In this subsection, we focus on conducting a direct non-asymptotic analysis of the LDP-SGD and LDP-ASGD estimators. To better illustrate the theoretical properties of the proposed estimators, we impose the following regularity conditions on the objective functions.


\begin{condition}{\label{Con2}}
Assume that $F(\theta)$ is differentiable, $M$-smooth, and $m$-strongle convex, i.e.
\begin{itemize}
 \item[(i).]  $F(\theta_1) - F(\theta_2) \leq \langle \nabla F(\theta_2), \theta_1-\theta_2 \rangle + \frac{M}{2}\|\theta_1-\theta_2\|^2,\quad \forall\theta_1, \theta_2\in{\Theta}\subseteq\mathbb{R}^d,$
  \item[(ii).]    $F(\theta_1) - F(\theta_2) \geq \langle \nabla F(\theta_2), \theta_1-\theta_2 \rangle + \frac{m}{2}\|\theta_1-\theta_2\|^2,\quad \forall\theta_1, \theta_2\in{\Theta}\subseteq\mathbb{R}^d,$
\end{itemize}
for some constants $M$ and $m$.
 \end{condition}
Strong convexity and smoothness are both standard conditions for the convergence analysis of stochastic gradient optimization methods; similar conditions can be found in \cite{gower2019sgd, vaswani2022towards}. To establish our results, we also require the local linearity condition on the gradient of the objective function $f(\theta,\cdot)$, which is commonly assumed for SGD’s method with the Polyak-Ruppert averaging, see \cite{polyak1992acceleration,fang2018online,wang2021convergence}.
\begin{condition}{\label{Con3}}
Assume that the gradient $E\{\nabla f(\theta,\cdot)\}$ can be approximated using the Hessian matrix $E\{\nabla^2 f(\theta^\ast,\cdot)\}$  around the minimizer $\theta^\ast$ as
    \begin{align*}
    \|E\{\nabla f(\theta,x_i)\} - E\{\nabla^2 f(\theta^\ast,x_i)\}(\theta -\theta^\ast)\| \leq C_1\|\theta - \theta^\ast\|^2.
\end{align*}
 \end{condition}


Before presenting the non-asymptotic bounds, we first introduce the following family of functions: $\psi_\beta: (0,+\infty)\rightarrow \mathbb{R}$ given by:
$$
\psi_\beta(t)= (t^\beta-1)/\beta,\quad  \text { if } \beta \neq 0,~{t>0.}
$$
Notice that the function $\beta \mapsto \psi_\beta(t)$ is continuous for all $t>0$. In addition, for $\beta>0, \psi_\beta(t)<t^\beta/\beta$, while for $\beta<0$, we have $\psi_\beta(t)< -1/\beta$.

Denote $\Omega$ as the maximum expectation of the  $\ell_2$-norm of the noise vector $\omega_i(\varepsilon_i,\delta_i)$, i.e., $\Omega = \max_i\{E(\|\omega_i(\varepsilon_i,\delta_i)\|_2^2)\}$. We then have the following non-asymptotic bounds for the LDP-SGD and LDP-ASGD estimators. For notation simplicity, let $\delta_n = E(\|{\theta}_n - \theta^\ast\|^2)$, $\bar{\delta}_n = E(\|{\bar{\theta}}_n - \theta^\ast\|^2)$, $\Delta_n=E\{\hat{F}(\theta_n) - \hat{F}({\theta}^\ast)\}$ and $\bar{\Delta}_n=E\{\hat{F}(\bar{\theta}_n) - \hat{F}({\theta}^\ast)\}$, where $\hat{F}(\theta) = \sum_{i=1}^n f(x_i,\theta)/n$.

Also, for two sequences $\{a_n\}$ and $\{b_n\}$, we denote $a_n = o(b_n)$ if $a_n$ is of smaller order than $b_n$, i.e., $a_n / b_n \to 0$ as $n \to \infty$. Similarly, we denote $a_n = \mathcal{O}(b_n)$ if $a_n$ is of the same order as $b_n$, meaning that $|a_n / b_n|$ is bounded for sufficiently large $n$. For stochastic sequences, we use $\mathcal{O}_p$ and $o_p$ to denote orders in probability. Specifically, $a_n = o_p(b_n)$ if $a_n / b_n \xrightarrow{p} 0$, and $a_n = \mathcal{O}_p(b_n)$ if $a_n / b_n$ is stochastically bounded, i.e., $\sup_n P(|a_n / b_n| > M) \to 0$ as $M \to \infty$.


\begin{theorem}{\label{the1}}
Assume Conditions \ref{Con1}, \ref{Con2}, \ref{Con3} hold, if $\eta_i=\eta i^{-\alpha}$, we then have, for $\alpha\in[0,1)$
\begin{align*}
\delta_n \leq C_0^2(1+\Omega)\frac{\eta}{m n^{\alpha}} + r_n,
%\leq \mathcal{O}\left(\frac{C_0^2\eta\Omega}{mn^{\alpha}}\right).\\
% E(\|{\theta}_n - \theta^\ast\|^2) & \leq  C_0^2\left\{\frac{\eta}{m n^{\alpha}} +  \eta^2\psi_{1-2\alpha}(n)\operatorname{exp}(-{m\eta}n^{1-\alpha}/2) \right\}(1+{64d}/{\min\limits_k\{\mu_k^2\}})\\
% & \quad + \operatorname{exp}\{-2m\eta\psi_{1-\alpha}(n)\}E(\|{\theta}_0 - \theta^\ast\|^2).
\end{align*}
where $r_n=o(n^{-\alpha})$ is the reminder term. The exact upper bound can be found in the proofs of the Appendix.
\end{theorem}

The quantity \( \Omega \) is a constant with respect to the sample size \( n \), but it depends on the dimension \( d \) and the privacy budget. In this theorem and those that follow, \( \Omega \) varies depending on the choice of noise distribution. Specifically, for the three mechanisms discussed earlier (Laplace, Gaussian, and GDP mechanisms), the corresponding forms of \( \Omega \) are \( \mathcal{O}(d^3 (\ln d)^2 / \min_i\{\varepsilon_i^2\}) \), \( \mathcal{O}(d / \min_i\{\varepsilon_i^2\}) \), and \( \mathcal{O}(d / \min_i\{\mu_i^2\}) \), respectively, where \( \mathcal{O}(\cdot) \) hides a positive constant independent of \( d \).

\begin{remark}\label{rmk1}
From Theorem \ref{the1}, we know that the non-asymptotic upper bound of the LDP-SGD estimator ${\theta}_n$ is influenced by several factors: the initial condition \(\|{\theta}_0 - \theta^\ast\|^2\), which is included in the reminder term $r_n$, the initial step size \(\eta\), the decay rate \(\alpha\), and the dimensionality \(d\) of the parameters. Specifically, \\[-1.5em]
\begin{itemize}
    \item \textbf{Initial condition:} The term involving the initial condition diminishes at a sub-exponential rate as \( n \) increases for \( \alpha \in [0, 1) \), which follows directly from the exact upper bound provided in the Appendix.\\[-1.5em]
    \item \textbf{Convergence rate:} The predominant convergence rate is \(\mathcal{O}(n^{-\alpha})\) for \(\alpha \in [0,1)\). For a scenario where \(\alpha=1\), the convergence of the LDP-SGD estimator \(\theta_n\) is not assured.\\[-1.5em]
    \item \textbf{Parameter dimension:} The influence of the dimensionality $d$ is implicitly captured through the maximum expectation $\Omega$. As outlined in Theorem \ref{the1}, under Condition \ref{Con1}, the Laplace noise exhibits a higher order dependence on $d$ compared to the Gaussian noise, consequently, it is more significantly affected by the curse of dimensionality. \\[-1.5em]

\end{itemize}
\end{remark}




The following theorem presents the non-asymptotic upper bounds for the LDP-ASGD estimator.


\begin{theorem}{\label{the2}}
Assume Conditions \ref{Con1}, \ref{Con2}, \ref{Con3} hold, if $\eta_i=\eta i^{-\alpha}$, we then have, for $\alpha\in[0,1)$
\begin{align*}
\bar{\delta}_n & \leq \frac{1}{n}\operatorname{tr}\left[E\{\nabla^2 f\left(\theta^*, x_1\right)\}^{-1}S E\{\nabla^2 f\left(\theta^*, x_1\right)\}^{-1}\right] \\
& \quad+ \frac{C_0^2(1+\Omega)}{mn}+ \frac{C_1 C_{3,0}\eta^2}{nm^2}\psi_{1-2\alpha}(n) +r_n, %\mathcal{O}\left(\frac{C_0^2\eta\Omega}{mn}\right)+ \mathcal{O}\left(\frac{C_0^2\eta^2\Omega\psi_{1-2\alpha}(n)}{m^2n}\right).\\
%         E(\|\bar{\theta}_n - \theta^\ast\|^2)\leq& \frac{1}{n}\operatorname{tr}\left[E\{\nabla^2 f\left(\theta^*, x_k\right)\}^{-1}S E\{\nabla^2 f\left(\theta^*, x_k\right)\}^{-1}\right] + \frac{4\alpha^2\tilde{\sigma}_\mu^2}{m^2n^2\eta}\psi_{\alpha-1}(n) + \frac{\tilde{\sigma}_\mu^2}{m^2n^{2-\alpha}\eta}\\
%     &  + \left(\frac{1}{mn^2\eta^2_1}+\frac{1}{mn^{2(1-\alpha)}\eta^2}+\frac{4M^2}{mn^2}\right)E(\|\theta_0 - \theta^\ast\|^2) +\frac{\tilde{\sigma}_\mu^2}{mn^{2(1-\alpha)}}\psi_{1-2\alpha}(n)\\
%     & + \frac{C_1 C_{3,0}\eta^2}{n^2m^2}\psi_{1-2\alpha}(n) + \frac{2C_1 C_{4,0}\eta^3}{n^2m^2}\psi_{1-3\alpha}(n) + \frac{4M^2\eta\tilde{\sigma}_\mu^2}{m^2n^2}\psi_{1-\alpha}(n) + \frac{\tilde{\sigma}_\mu^2}{mn} \\
%     &+\frac{C_1}{4mn^2}E(\|\theta_0 - \theta^\ast\|^4) + \left(\frac{4\alpha^2}{mn^2\eta^2} + \frac{4M^2}{mn^2}\right)\{E(\|\theta_0 - \theta^\ast\|^2)+\eta^2\tilde{\sigma}_\mu^2\}B \\
%     &+
% \frac{4M^2\eta\tilde{\sigma}_\mu^2}{m^2n^2} \left\{ E(\|\theta_0 - \theta^\ast\|^4)+ C_{3,0}\eta^3\psi_{1-3\alpha}(n) + C_{4,0}\eta^4\psi_{1-4\alpha}(n)\right\} B,
\end{align*}
where $x_1$ is the first sample, $S$ is a constant matrix defined latter in \eqref{eq:clt}, $C_1$, $C_{3,0}$ are the constants defined in the supplementary, and $r_n=o((1+\psi_{1-\alpha}(n))/n)$ is the reminder term. The exact upper bound can be found in the proofs of the Appendix.
\end{theorem}

\begin{remark}
   From Theorem \ref{the2}, notice that the non-asymptotic upper bound of the LDP-ASGD estimator $\bar{\theta}_n$ is influenced by the same factors in a similar way to the bound in Theorem \ref{the1}. \\[-1.5em]
    \begin{itemize}
        \item \textbf{Initial Condition:} For all $\alpha\in[0,1)$, the term involving the initial condition diminishes at rate $O(n^{-2})$, which can be obtained from the exact upper bound.\\[-1.5em]
        \item \textbf{Convergence rate:} For $\alpha\in[0,1/2]$, we have $\psi_{1-2\alpha}(n)=\mathcal{O}(n^{1-2\alpha})$, then the third term on the error bound in Theorem \ref{the2} is the asymptotic leading term with order $\mathcal{O}(n^{-2\alpha})$. For $\alpha\in[1/2,1)$, we have $\psi_{1-2\alpha}(n)=\mathcal{O}(1)$ and the third term has the same convergence rate $\mathcal{O}(n^{-1})$ as the first two terms.
    \end{itemize}
\end{remark}

\begin{corollary}(Asymptotic properties) \label{coro1}
Based on the decomposition shown in the Appendix, $\bar{\theta}_n-\theta^*$ can be represented as follows:
$$
\sqrt{n}(\bar{\theta}_n-\theta^*) = -\frac{1}{\sqrt{n}}\sum_{j=1}^n A^{-1}\left(\nabla f\left(\theta^*, x_j\right)+C_0\omega_j(\varepsilon_j,\delta_j)\right)+\mathcal{O}_p\left(\frac{\psi_{1-\alpha}(n)}{\sqrt{n}}\right)+o_p(1),
$$
where $A=E\{\nabla^2f\left(\theta^*, x_n\right)\}$. For $1/2<\alpha<1$, we have $\mathcal{O}_p(\psi_{1-\alpha}(n)/\sqrt{n})=\mathcal{O}_p(n^{1/2-\alpha})=o_p(1)$. Then by the central limit theorem, we have
\begin{align}
    \begin{aligned}
    \label{eq:clt}
        \sqrt{n}(\bar\theta_n - \theta^*)\rightarrow \mathcal{N}(0, A^{-1}SA^{-1}),
    \end{aligned}
\end{align}
where $S=\mathbb{E}\{\nabla f(\theta^*,x_n)\nabla f(\theta^*,x_n)^\top\}+S_{noise}$, and $S_{noise} = C_0^2\mathbb{E}\{\omega_n(\varepsilon_n,\delta_n)\omega_n(\varepsilon_n,\delta_n)^\top\}$. The first term in $S$ is what we can obtain from a non-private SGD algorithm, while $S_{noise}$ is the price we pay to achieve the desired level of privacy.

\end{corollary}

\subsection{Non-strongly convex obejectives}
In this subsection, we do not assume that the function $F(\theta)$ is strongly convex, but impose the following condition.
\begin{condition}{\label{Con4}}
 Assume the objective function $F(\theta)$ attains its global minimum at $\theta^\ast\in\Theta.$
\end{condition}
Notice that $\theta^\ast$ is not necessarily unique when the objective function $F(\theta)$ is not strongly convex, but we may bound the loss function as follows:


\begin{theorem}{\label{the3}}
Assume Conditions \ref{Con1}, \ref{Con2}, \ref{Con3}, \ref{Con4} hold, then if $\eta_i = \eta i^{-\alpha}$, for $\alpha\in[1/3,1)$,
\begin{align*}
\Delta_n\leq \left\{\begin{array}{lr}
{2G^{1/2}H}/{\psi_{1-\alpha}(n)},& \alpha\in(2/3,1),\\
{2G^{1/2}H}/{\psi_{\alpha/2}(n)},&\alpha\in(1/2,2/3],\\
{2JH}/\{(1-2\alpha)^{1/2}\psi_{3\alpha/2-1/2}(n)\},& \alpha\in[1/3,1/2],
\end{array}
\right.
\end{align*}
where $G = \delta_0 + C_0^2(1+\Omega)\eta^2\psi_{1-2\alpha}(n)$, $H = (1+4M^{1/2}C_0(1+\Omega)^{1/2}\eta^{3/2})/\eta$, and $J = \delta_0 +C_0^2(1+\Omega)\eta^2$.
\end{theorem}


\begin{remark}
   From Theorem \ref{the3}, we note that the upper bound of $\Delta_n$ shares the same constant $\Omega$ as in the strongly convex scenario, suggesting a similar relationship with dimension and privacy budget as discussed before. Moreover, we have \\[-1.5em]
    \begin{itemize}
        \item \textbf{Initial Condition:} For \( \alpha \in (1/3, 1) \), the initial condition \( \delta_0 \) appears in the expressions for \( G \) and \( J \). The terms involving \( \delta_0 \) decay to zero as \( n \) increases, and they dominate the convergence behavior and constitute the leading term in this regime.\\[-1.5em]
        \item \textbf{Convergence rate:} For $\alpha\in(1/3,1/2]$, the convergence rate of $\Delta_n$ is $O(n^{-(3\alpha-1)/2})$;  for $\alpha\in(1/2,2/3]$, the convergence rate is $O(n^{-\alpha/2})$, while for $\alpha\in(2/3,1)$ the convergence rate becomes $O(n^{-(1-\alpha)})$.
    \end{itemize}
\end{remark}

The following theorem is shown in a similar way to Theorem \ref{the2}, which provides the bound of the difference between the expected loss of LDP-ASGD estimators and optimal.

\begin{theorem}{\label{the4}}
Assume Conditions \ref{Con1}, \ref{Con2}, \ref{Con3}, \ref{Con4} hold, then if $\eta_n = \eta n^{-\alpha}$, for $\alpha\in[0,1)$, we have
\begin{align*}
\bar{\Delta}_n \leq \frac{1}{2\eta n^{1-\alpha}}\{\delta_0 + C_0^2(1+\Omega)\eta^2\psi_{1-2\alpha}(n)\} + \frac{C_0^2(1+\Omega)\eta\psi_{1-\alpha}(n)}{2n}.%\mathcal{O}\left(\frac{C_0^2\eta\Omega\psi_{1-2\alpha}(n)}{n^{1-\alpha}}\right)+\mathcal{O}\left(\frac{C_0^2\eta\Omega\psi_{1-\alpha}(n)}{n}\right).
% E\{F(\bar{\theta}_n) - F({\theta}^\ast)\}\leq  \frac{1}{2\eta n^{1-\alpha}}\{E(\|{\theta}_0 - \theta^\ast\|^2) + \tilde{\sigma}_\mu^2\eta^2\psi_{1-2\alpha}(n)\} + \frac{\tilde{\sigma}_\mu^2\eta\psi_{1-\alpha}(n)}{2n},
\end{align*}
%The exact upper bound can be found in equation \eqref{result:4-4} in the proofs in the Appendix.
\end{theorem}
\begin{remark}
    The convergence rate of $\bar{\Delta}_n$ follows \(O(n^{-\alpha})\) when \(\alpha \in [0, 1/2)\). However, in the range \(1/2 < \alpha < 1\), it adheres to \(O(n^{\alpha-1})\). Consequently, the optimal asymptotic rate stands at \(O(n^{-1/2})\) when taking $\alpha=1/2$. It is worth noting that through averaging, the algorithm extends the \(\alpha\) range to ensure convergence, shifting it from \([1/3, 1)\) to \([0,1)\), and also achieves faster convergence rate than $\Delta_n$. %Nonetheless, in real-world scenarios when \(\alpha > 1/2\), the constant terms in equation \eqref{result:4-4} could vastly exceed its square root, leading to a bigger loss in the averaged estimators.
\end{remark}


