\begin{algorithm}[t]
\SetKw{logicalNot}{not}
\SetKw{logicalAnd}{and}
\SetKw{logicalOr}{or}
\SetNlSty{}{}{:}
\small{
    \nl Input $\mathbf{x}_0, \mathbf{x}_g$ and conduct passages and cell preprocessing\;
    \nl $V \leftarrow \{ \mathbf{x}_0 \}$; $E \leftarrow \emptyset$; $f_c \leftarrow \infty$\;
     \nl Locate $\mathbf{x}_0$ in Gabriel cells and $\mathbf{x}_0.\texttt{cost} \leftarrow \texttt{Cost}(\mathbf{x}_0)$\;
    \nl \For {$i \leftarrow 1$ \KwTo $n$} {
        \nl $\mathbf{x}_{rand} \leftarrow \texttt{SampleFree}()$\;
        \nl $\mathbf{x}_{nearest} \leftarrow \texttt{Nearest}(G = (V, E), \mathbf{x}_{rand})$\;
        \nl $\mathbf{x}_{new} \leftarrow \texttt{Steer}(\mathbf{x}_{nearest}, \mathbf{x}_{rand})$\;
        \nl \If{\textnormal{\texttt{ObstacleFree}$(\mathbf{x}_{nearest}, \mathbf{x}_{new})$}} {
            \nl $X_{near} \leftarrow \texttt{Near}(G = (V, E), \mathbf{x}_{new}, r_{RRT^*})$\;
            \nl \ForEach{$\mathbf{x}_{near} \in X_{near}$} {
                    \nl \If {\logicalNot \textnormal{\texttt{ObstacleFree}$(\mathbf{x}_{near}, \mathbf{x}_{new})$}} {
                        \nl $X_{near}.\text{remove}(\mathbf{x}_{near})$\;
                    }
                }
            \nl $\mathbf{x}_{min} \leftarrow \mathbf{x}_{nearest}$\; 
            \nl $c_{min} \leftarrow \texttt{NewCost}(\mathbf{x}_{min}, \mathbf{x}_{new})$\;
            \nl \ForEach{$\mathbf{x}_{near} \in X_{near}$} {
                \nl \If{\textnormal{ \texttt{NewCost}$(\mathbf{x}_{near}, \mathbf{x}_{new}) < c_{min}$}} {
                    \nl $\mathbf{x}_{min} \leftarrow \mathbf{x}_{near}$\; 
                    \nl $c_{min} \leftarrow \texttt{NewCost}(\mathbf{x}_{near}, \mathbf{x}_{new})$\;
                    }
                }
            \nl \texttt{SubtreeUpdate}$(\mathbf{x}_{min}, \mathbf{x}_{new})$\;
            \nl $V \leftarrow V \cup \{ \mathbf{x}_{new} \}; \, E \leftarrow E \cup \{ (\mathbf{x}_{min}, \mathbf{x}_{new}) \}$\;
            \nl \ForEach{$\mathbf{x}_{near} \in X_{near}$} {
                \nl \label{AlgLine: Rewire Condition}\If{\textnormal{\texttt{NewCost}$(\mathbf{x}_{new}, \mathbf{x}_{near}) < \mathbf{x}_{near}.\texttt{cost}$ 
                    \logicalOr (\texttt{NewCost}$(\mathbf{x}_{new}, \mathbf{x}_{near}) == \mathbf{x}_{near}.\texttt{cost}$ \logicalAnd $\mathbf{x}_{new}.\texttt{len} + \text{Len}(l(\mathbf{x}_{new}, \mathbf{x}_{near})) < \mathbf{x}_{near}.\texttt{len}$)}} {
                    \nl $E \leftarrow E \backslash \{ (\mathbf{x}_{near}.\texttt{parent}, \mathbf{x}_{near}) \} \cup \{ (\mathbf{x}_{new}, \mathbf{x}_{near}) \}$\; 
                    \nl \texttt{SubtreeUpdate}$(\mathbf{x}_{new}, \mathbf{x}_{near})$\;
                    }
                }
            \nl \If{\textnormal{Len$(l(\mathbf{x}_{new}, \mathbf{x}_g)) < r_{RRT^*}$
            \logicalAnd \texttt{ObstacleFree}$(\mathbf{x}_{new}, \mathbf{x}_{g})$ 
            \logicalAnd $\texttt{NewCost}(\mathbf{x}_{new}, \mathbf{x}_g) < f_c$}}{
                \nl $\mathbf{x}_g.\texttt{parent} \leftarrow \mathbf{x}_{new}$\;
                \nl $f_c \leftarrow \texttt{NewCost}(\mathbf{x}_{new}, \mathbf{x}_g)$\;
                }
        }
        }
        \nl \Return \texttt{GetPath}$(\mathbf{x}_0, \mathbf{x}_g)$\;
    }
    \caption{\small RRT$^*$ for PTOPP}
    \label{Alg: RRT* for PTOPP}
\end{algorithm}
