\section{Problem Setting and Preliminaries}
\label{sec:prelim}
\paragraph{Notation.} We use $\twonorm{\cdot}$ for the Euclidean $L_2$ norm. We denote $\bb{P}[E]$ as the probability of any event $E$. $\bb{E}[{X}]$ denotes the expectation of any random variable ${X}$. For any distribution $\calD$, $supp(\calD)$ represents the support of the distribution, $\calN(0, \sigma^2I_d)$ is the isotropic normal distribution with mean 0 and covariance $\sigma^2 I_d$. For any set S, $Unif(S)$ is the uniform distribution over the set $S$. $D\bb{B}^d = \{x \in \Real^d: \twonorm{x} \leq D\}$. $\mathbf{0}_d$, $\mathbf{1}_d$, and $\mathbf{e}_i$ represent $d$ dimensional all zero, all one, and the $i^{th}$ standard basis vectors, respectively. For a vector $v \in \Real^d$, $\{v\}_i$ represents the $i^{th}$ coordinate of the vector; $[n]$ denotes the set of natural numbers less than or equal to $n$. $\Pi_D(x) = \argmin_{u \in D}\twonorm{x-u}$ is used to denote the projection of $x \in \Real^d$ onto the set $D$. For any function $f$, $dom(f)$ represents the domain of the function $f$.

\paragraph{Problem Setting.} We consider the problem of minimizing the empirical loss function with respect to the dataset $\calD = \{d_1, d_2, ..., d_n\}$ given a closed convex set $\calC \subseteq \Real^d$
\begin{align*}
    \min_{w \in \calC}~\calL(w; \calD)
\end{align*}
where $\calL(w;\cdot): \calC \rightarrow \Real$ is convex and $L$-Lipschitz. There can be additional assumptions on $\calL(w;\cdot)$ such as $\Delta$ strong convexity. Recall that a function $g$ is called $L$-Lipschitz if $\twonorm{g(x) - g(y)} \leq L\twonorm{x-y}$ for all $x,y \in \calC$ and it is called $\mu$-Strongly Convex when for all $x, y \in \calC$, $f(x) \geq f(y) + \inner{z}{y - x} + \frac{\mu}{2}\twonorm{y-x}^2$ where $z$ is any subgradient of $f$. Next, we define the notion of Differential Privacy.

\begin{definition}[Differential Privacy \citep{originalDP}]
    \label{def:dp}
    Two datasets of the same size are neighbouring if $|\calD \Delta \calD'| = 2$ where $\Delta$ represents the symmetric set difference. Let $\varepsilon \geq 0, ~\delta \in [0, 1).$ A randomized algorithm $\calA$ is $(\varepsilon, \delta)$-differentially private (DP) if for all pairs of neighbouring data sets $\calD, \calD'$, we have
    \begin{equation}
    \label{eq: DP}
    \bb{P}(\calA(\calD) \in O) \leq e^\varepsilon \bb{P}(\calA(\calD') \in O) + \delta, 
    \end{equation}
for any measurable set~$O$. 
\end{definition}

\paragraph{ZO Stochastic Gradient Descent.} The algorithmic framework that we will be operating under is the \textit{projected stochastic ZO descent} as given in Algorithm \ref{alg:proj_zo_sgd}. Algorithm \ref{alg:proj_zo_sgd} requires access to \textit{zeroth order oracles} to query the update direction at each step. We define such oracles below. 
\begin{definition}
    \label{def:zeroorderoracle}
    A zeroth order oracle $\calO$ is an oracle which takes a function $f: \Real^d \rightarrow \Real$, a single point $w \in \Real^d$ and returns a probability measure over a subset of $\Real^d$ using only function evaluations on different points depending on $w$.
\end{definition}

Notably, ZO oracle may require multiple function evaluations, which may not necessarily depend on the point $w$. In the design of ZO algorithms, these oracles are typically implemented using well-established ZO estimators. Below, we provide examples of such estimators.

\begin{example}
    \label{ex:elemestimators}
    Here we list three popular ZO estimators: Simultaneous Perturbation Stochastic Approximation (SPSA) introduced by \citet{spsa}, Finite Difference (FD) introduced by \citet{Nesterov2015RandomGM}, and Single Point (SP) estimator introduced by \citet{singlepoint}.
    \begin{enumerate}
        \item $SPSA_{\xi}(f, w)$: Sample ${Z} \sim \calN(0, I_d)$ and return 
        $\widehat{\nabla}_1 f_\xi(w) \define \frac{f(w + \xi {Z}) - f(w - \xi {Z})}{2\xi}{Z}$.
        \item $FD_{\xi}(f, w)$: Sample ${Z} \sim \calN(0, I_d)$ and return $\widehat{\nabla}_2 f_\xi(w) \define \frac{f(w + \xi {Z}) - f(w)}{\xi}{Z}$.
        \item $SP_\xi(f, w)$: Sample ${Z} \sim \calN(0, I_d)$ and return $\widehat{\nabla}_3 f_\xi(w) \define \frac{d}{\xi}f\left(w + \xi {Z}\right){Z}$
    \end{enumerate}
\end{example}

 The above mentioned estimators are widely used in various zeroth order optimization and control algorithms. They are unbiased estimators of the gradient of a smoothed version of the function $f$, defined as $f_\xi(x) = \bb{E}_{{Z} \sim \calN(0, I_d)}\left[f(x + \xi{Z})\right]$. In other words, $\bb{E}\left[\widehat{\nabla} f_\xi(w)\right] = \nabla f_\xi(x)$ \citep{Nesterov2015RandomGM, nemrosyud}. 

Since the aforementioned estimators are randomized, several works, such as \citet{zhang2024private}, \citet{malladi2023mezo}, and \citet{duchioptzero}, have focused on strategies to reduce the variance of the updates obtained through these estimators, by taking the mean of different samples. Building on these randomized estimators, multi-point estimators can be defined aggregate information across multiple points. We provide an example of such aggregation below.

\begin{example}
    \label{ex:mean}
    For any randomized estimator $\calE$, the mean extension of the estimator $M^\calE_m(f, w)$ works as follows: Sample i.i.d. $U_1, U_2, ..., U_m \sim \calE(f, w)$ and return $\frac{1}{m} \sum_{i=1}^m U_i$.
\end{example}

\begin{algorithm}[t]
\caption{Projected Stochastic ZO Descent}
\label{alg:proj_zo_sgd}
    Given number of steps $T$, initialization distribution $\calR_{init}$, ZO oracle $\calO$, and constraint set $\calD$ \\
    Sample $w_0 \sim \calR_{init}$ \\
    \For{$t \gets 1, ..., T$}{
        Draw $\gradest \calL(w_{t-1}; \calX)$ from the distribution $\calO(\calL(\cdot; \calX), w_{t-1})$\\
        $w_{t} \gets \Pi_\calD\paren{w_{t-1} - \eta \gradest \calL(w_{t-1}; \calX)}$\\
    }
\end{algorithm}

\begin{example}
    Using the construction mentioned in Example~\ref{ex:mean}, one can further define $M_m^{SPSA}$ \citep{malladi2023mezo, zhang2024private}, $M_m^{FD}$ \citep{duchioptzero}, and $M_m^{SP}$.
    \begin{enumerate}
        \item $M_m^{SPSA_\xi}(f, w)$: Sample i.i.d. $Z_1, ..., Z_m \sim \calN(0, I_d)$ and return 
        $\widehat{\nabla}^m_1 f_\xi(w) \define \frac{1}{m}\sum_{i=1}^m \frac{f(w + \xi {Z_i}) - f(w - \xi {Z_i})}{2\xi}{Z_i}$.
        \item $M_m^{FD_\xi}(f, w)$: Sample i.i.d. $Z_1, ..., Z_m \sim \calN(0, I_d)$ and return 
        $\widehat{\nabla}^m_2 f_\xi(w) \define \frac{1}{m}\sum_{i=1}^m \frac{f(w + \xi {Z_i}) - f(w)}{\xi}{Z_i}$.
        \item $M_m^{SP_\xi}(f, w)$: Sample i.i.d. ${Z_1, Z_2, ..., Z_m} \sim \calN(0, I_d)$ and return $\widehat{\nabla}^m_3 f_\xi(w) \define \frac{1}{m} \sum_{i=1}^m\frac{d}{\xi}f\left(w + \xi {Z_i}\right){Z_i}$
    \end{enumerate}
\end{example}

It is important to note that most work in ZO convex optimization relies on these estimators. Consequently, it becomes essential to define a subclass of randomized zeroth order oracles that generalizes this family of estimators and also \textit{provides a clearer understanding of their privacy implications}. Understanding the properties of such oracles is crucial for analyzing the privacy aspects of ZO methods that reveal their intermediate states.

\section{Privacy of Randomized Zeroth-Order Oracles}
\label{sec:privacyzosgd}

In this section, we define and discuss a subclass of randomized zeroth-order oracles as defined in Definition~\ref{def:zeroorderoracle}, and discuss privacy properties of this subclass. Let us start by defining \zpn oracles:

\begin{definition}
\label{def:multnoiseoracle}
    An oracle $\calO$ is a \zpn oracle if for any $f: \bb{R}^d \rightarrow \bb{R}$, it satisfies the following properties,
    \begin{enumerate}
        \item $\calO(f, w)$ returns $\mathbf{0}_d$ when $f(w) = 0$ for all $w \in \Real^d$ i.e. if $U \sim \calO(0, w)$ then $\bb{P}[U = \mathbf{0}_d] = 1$. 
        \item For $a > 0$, if $f(u) = \frac{a}{2}\twonorm{u}^2$, then $\calO(f, w)$ is a continuous probability measure for $w \neq \mathbf{0}_d$ i.e. if $U \sim \calO(f, w)$ and $w \neq \mathbf{0}_d$ then for all $c \in \bb{R}^d, \bb{P}[U = c] = 0$.
        %
    \end{enumerate}
\end{definition}

It is important to note that, a \zpn oracle does not necessarily imply a zeroth order oracle. For instance, consider the estimator: Sample $Z \sim \calN(0, I_d)$ and return $\widehat{\nabla} f(u) = (Z^T\nabla f(u))Z$. We see that this estimator satisfies the property of being a \zpn oracle, even though it still uses first order information.

Nonetheless, \zpn oracles capture many popular ZO estimators used in the literature. In the following lemma, we show that several of the estimators discussed in Example~\ref{ex:elemestimators} satisfy Definition~\ref{def:multnoiseoracle}.

\vspace{0.1cm}

\begin{lemma}\label{estimator:multiplicative}
    $SPSA$, $FD$, $SP$, $M_m^{SPSA}$, $M_m^{FD}$ and $M_m^{SP}$ are \zpn oracles.
\end{lemma}

\vspace{0.1cm}

We defer the proof to \cref{app:estimatormultiplicative}. We also give example of another estimator proposed in \citet{zhang2024dpzero} and show that it is also a \zpn oracle. 

 The following lemma shows that any \zpn oracle is not differentially private.
\begin{theorem}
    \label{lemma:non-privacyofZOestimators}
    If $\calO$ is a \zpn oracle (as defined in Definition~\ref{def:multnoiseoracle}), then there exists an L-Lipschitz strongly convex loss function over the set $L\bb{B}^d$ and a pair of datasets such that $\calO$ is not $(\varepsilon, \delta)$-differentially private for any $\varepsilon < \infty$ and any $\delta < 1$.
\end{theorem}
\begin{proof}
Let $\calX = \{x_1, x_2, ..., x_n\}$ be the database with $x_i \in \Real^k$ and $\twonorm{x_i} \leq 1, \;\forall i$. Given this database, consider the  function 
    \begin{align*}
        \calL(w; \calX) = \frac{1}{n} \sum_{i = 1}^n \twonorm{x_i} \twonorm{w}^2,
    \end{align*}
    with parameter $w \in L\bb{B}^d$.
    Consider the neighboring databases $\calX = \{x_1, x_2, ..., x_{n-1}, x_n\}$ and $\calX' = \{x_1, x_2, ..., x_{n-1}, x_n'\}$ differing at the last entry (WLOG). Assigning $x_1, ..., x_{n-1}$ to be ${0}_k$. 
    For the last points take, $x_n = 0$ and $x_n' = \frac{1}{\sqrt{k}}{1}_k$. 
    With this construction, we have  $\calL(w; \calX) = 0$ and $\calL(w; \calX') = \frac{L}{n}\twonorm{w}^2$.
    Let $R_\calX \sim \calO(\calL(\cdot; \calX), w)$
    and $ R_{\calX'} \sim \calO(\calL(.; \calX'), w)$.
    By the property of a \zpn oracle, we have $\bb{P}\left[R_\calX = \mathbf{0}_d\right] = 1$, while $R_{\calX'}$ would be a continuous random variable. 
    Hence,  for  the singleton set $S = \{\mathbf{0}_s\}$, we have  $Pr[R_\calX \in S] = 1$ and $Pr[R_{\calX'} \in S] = 0$ because $R_{\calX'}$ is a continuous random variable with unbounded support. Clearly, $\bb{P}[R_\calX \in S] > e^\varepsilon \bb{P}[R_{\calX'} \in S] + \delta$  for any $\varepsilon < \infty$ and $\delta < 1$,  contradicting $(\varepsilon,\delta)$-differential privacy  definition.
\end{proof}

A few key observations about this result are
\begin{enumerate}
    \item \citet{abadipaper, charles2024finetuninglargelanguagemodels} showed that for GD and SGD algorithms to be differentially private, each parameter update must be differentially private if the attacker has access to the all the intermediate states. Thus, understanding the privacy preserving properties of distribution of updates (e.g. ZO oracles) helps us in understanding the privacy of the algorithm itself.
    \item Theorem~\ref{lemma:non-privacyofZOestimators} demonstrates that algorithms involving the sharing of gradient estimates or parameter updates sampled from \zpn oracles between parties are not private. For instance, in many federated learning mechanisms \citep{lowy2023privatefederatedlearningtrusted, pmlr-v206-lowy23a, fedother, gao2024privateheterogeneousfederatedlearning}, gradients (estimates) are shared from silos to a central server. In the absence of a trusted server, the lack of privacy of the updates, from a particular silo, poses a significant risk to the confidentiality of the data within the silo.
\end{enumerate}

It is also important to note that Theorem~\ref{lemma:non-privacyofZOestimators} does not dismiss the privacy guarantee of zeroth order estimators with \textit{independent} additive noise as discussed in \citet{zhang2024dpzero} and \citet{zhang2024private}. This is because gradient estimators with \textit{independent} additive noise do not satisfy the first property of Definition~\ref{def:multnoiseoracle}. Consider the gradient estimator with an additive noise to be $\widehat{\nabla} f(w) = \widehat{\nabla}' f(w) + \gamma$ where $\widehat{\nabla}' f(w): \Real^d \rightarrow \Real^d$ represents an arbitrary estimator and $\gamma \sim \calN(0, \sigma^2 I_d)$ is an independent noise for a $\sigma$ which satisfies $(\epsilon, \delta)$ DP (assuming that $\widehat{\nabla}' f(w)$ has bounded sensitivity). We see that (in the worst case) when $\widehat{\nabla}' f(w)$ is a constant $\widehat{\nabla} f(w)$ is still a continuous distribution since $\gamma$ is an independent noise added.

\section{Privacy of ZO SGD}
\label{sec:privacyzosgdunk}

At this point, we have given a partial answer to the question asked in \citet{zhang2024dpzero, tang2024privatefinetuninglargelanguage} with respect to privacy of \textit{their zeroth order oracles}. However, this result does not account for the fact when we have no knowledge about the intermediate states of the algorithm. \citet{ NEURIPS2021_7c6c1a7b, altschuler2022privacy} have proven that when one considers the case that the attacker has no access to hidden states, then after a small burn-in period, Projected Noisy SGD on strongly convex and convex functions incurs no additional loss in privacy as T increases. Thus, it is possible for some iterates to not be private individually, but the noise due to the zeroth order oracle ``accumulates" over time and gives certain privacy guarantees for the final iterate. Therefore, a natural question is as follows:

\fbox{
    \begin{minipage}{\columnwidth - 14pt}
    \textit{Is {the inherent noise of ZO Stochastic Gradient Descent (SGD) with a constant initialization sufficient to preserve privacy given access to the final iterate only?}  }
    \end{minipage}
}

The following theorem answers this question.

\begin{theorem}
    \label{multidim:fixedinit} Consider running T steps of Algorithm \ref{alg:proj_zo_sgd} using a \zpn oracle $\calO$, as defined in Definition~\ref{def:multnoiseoracle}, with $D > 0$ and $\calR_{init}$ as a fixed constant $w_0 \in \Real^d$ such that $\twonorm{w_0} < D$. Assume that the algorithm only returns the final iterate. Then, there exists an L-Lipschitz linear loss function over the set $[-D, D]^d \subset \Real^d$ such that for any $T \geq 1$ the output of Algorithm \ref{alg:proj_zo_sgd} is not $(\varepsilon, \delta)$-differentially private for any $\varepsilon < \infty$, $\delta < 1$
\end{theorem}
\begin{proof}
    Consider the following function for a database $\calX = \{x_1, x_2, ..., x_n\}$ where for all $i \in [n]$ $x_i \in \Real^k$ such that $\twonorm{x_i} \leq 1$ with parameter $w \in L\bb{B}^d$
    \begin{align*}
        \calL(w; \calX) = \frac{1}{n} \sum_{i = 1}^n \twonorm{x_i} \twonorm{w}^2.
    \end{align*}

    Consider the neighboring databases differing at the last entry (WLOG) $\calX = \{x_1, x_2, ..., x_{n-1}, x_n\}$ and $\calX' = \{x_1, x_2, ..., x_{n-1}, x_n'\}$. Assign $x_1, ..., x_{n-1}$ to be ${0}_k$. For the last points take, $x_n = 0$ and $x_n' = \frac{1}{\sqrt{k}}{1}_k$. With the above construction, we have the following two functions under $\calX$ and $\calX'$, $\calL(w; \calX) = 0$ and $\calL(w; \calX') = \frac{L}{n}\twonorm{w}^2$.

    Take the random variables for iterates corresponding to running Algorithm \ref{alg:proj_zo_sgd} on $\chi$ and $\chi'$ to be $W^\chi_t$ and $W^{\chi'}_t$ respectively.  Since $\calL(w;\chi) = 0$, then by the first property of $\calO$ along with the fact that $\calO(f, w) = \mathbf{0}_d$ for a constant $f$, we have that $\bb{P}\left[\calO(\calL(\cdot, \chi), w) = \mathbf{0}_d\right] = 1$. This implies that the iterate would not change on each step and since $w_0 \in D\Ball^d$, projection would be identity at each step, which implies $W^\chi_t = w_0$.

    On the other hand, $W_t^{\chi'} = \Pi_{D\Ball^d}\paren{W_{t-1}^{\chi'} - \eta \widehat{\nabla}\calL(W_{t-1}; \calX')}$. Since the minima of $\calL(w; \calX')$ lies strictly at $w = {0}$, it implies that $\calL(w_0; \calX') \neq 0$ and since $\calL(w; \calX')$ is not a constant, then by the second property in Definition~\ref{def:multnoiseoracle} it implies that $\widehat{\nabla}\calL(W^{\chi'}_{t-1}, \chi')$ is a continuous distribution, which implies that $W_{t-1}^{\chi'} - \eta \widehat{\nabla}\calL(W_{t-1}; \calX')$ is a continuous distribution. However, since we are projecting into a ball at every iteration, then it implies that for $w \in D\bb{B}^d$ such that $\twonorm{w} < D$, $\bb{P}[W_t^{\chi'} = w] = \bb{P}[W_{t-1}^{\chi'} - \eta \widehat{\nabla}\calL(W_{t-1}; \calX') = w]= 0$ while for $\twonorm{w} = D$, $\bb{P}[W_t^{\chi'} = D] = \bb{P}[W_{t-1}^{\chi'} - \eta \widehat{\nabla}\calL(W_{t-1}; \calX') \geq D]$.      
    Thus, if we consider the singleton set $S = \{w_0\}$, then we would get that $Pr[W^\chi_T \in S] = 1$ and $Pr[W^{\chi'}_T \in S] = 0$ because $\twonorm{w_0}$ is strictly less than $D$. Hence, $\bb{P}[W^\chi_T \in S] > e^\varepsilon \bb{P}[W^\chi_T \in S] + \delta$ for any $\varepsilon < \infty$ and $\delta < 1$.
\end{proof}

 This result answers the open question proposed by \citet{tang2024privatefinetuninglargelanguage} and \citet{zhang2024dpzero} on the privacy of zeroth order (S)GD with a fixed initialization. Thus, it dismisses the promise of privacy of (S)GD under such oracles. It is important to note that our framework does not capture certain algorithms like Stochastic Zeroth Order Conditional Gradient Descent \citep{Balasubramanian2022-zu} or Mirror Descent \citep{duchioptzero}. It would be interesting to see if such a result can be generalized for other classes of optimization algorithms discussed in \citet{duchioptzero} or \citet{Balasubramanian2022-zu}.

Notably, in modern machine learning tasks, model parameters are initialized randomly \citep{7410480}. Thus, if we consider the optimization of the functions corresponding to two neighbouring datasets as defined in Definition~\ref{def:dp}, then we cannot comment about the distribution of the final iterate. Therefore, a natural extension to our previous question emerges as follows:

\fbox{
    \begin{minipage}{\columnwidth - 14pt}
    \textit{Is {the inherent noise of ZO Stochastic Gradient Descent (SGD) \textbf{with random initialization} sufficient to preserve privacy given access to the final iterate only?}  }
    \end{minipage}
}

 It is important to note that the distribution of the initial iterate is continuous. Thus, by proof of Theorem~\ref{multidim:fixedinit}, the continuity of the \zpn oracle is no longer sufficient to ensure privacy. We define a new class of oracles below for which we analyse privacy.

\begin{definition}
    \label{def:badoracle}
    An update oracle $\calO$ is $C_s$-\ac (AC) if there exists an index $i^* \in [d]$ such that if we consider the function class $\c{F} = \left\{\inner{g\mathbf{e}_{i^*}}{w}: - L \leq g \leq 0\right\}$, then for any $h \in \c{F}$ and $\overline{w} \in \Real^d$, if $U \sim \calO(h, \overline{w})$ then,
    \begin{enumerate}
        \item $\{\nabla h(\overline{w})\}_{i^*} = 0$ implies $U = \mathbf{0}_d$ w.p. 1 i.e. $\bb{P}\left[U = \mathbf{0}_d\right] = 1$
        \item $\{\nabla h(\overline{w})\}_{i^*} \neq 0$ implies $\bb{P}\left[\{U\}_{i^*} < 0\right] = 1$ 
        \item $\bb{E}\left[\{U\}_{i^*}\right] \leq \{\nabla h(\overline{w})\}_{i^*}$
        \item For any set of $\{w_1, w_2, ..., w_N\} \subset \Real^d$, let $U_j \sim \calO(h, w_j)$ independently for all $j \in [N]$. Then $\Ex{\paren{\sum_{j=1}^N \{U_j\}_{i^*}}^2}\leq C_s\Ex{\sum_{j=1}^N \{U_j\}_{i^*}}^2$
    \end{enumerate}
\end{definition}

This oracle roughly gives us a stronger guarantee (than \zpn oracles) that updates for a certain class of functions (with non-zero gradients) would be strictly increasing while ensuring a zero-preserving property (like \zpn oracles) on functions which are zero over $\Real^d$. Further its distributional properties, like the condition on expectation and variance, are necessary for ensuring an ``anti-concenteration'' phenomena over the updates (hence the name). This suggests that the updates from AC oracles would shift the iterates away from the initial point with a good probability, even when it is randomized.

Similar to the definition of \zpn oracles, this seemingly specific oracle class is able to capture the two point oracles we have discussed so far. Specifically, we show that the $SPSA$ and $FD$ estimators are 3-\acs~oracles.

\begin{lemma}
    SPSA and FD are 3-\acs.
\end{lemma}

\begin{proof} We defer the complete proof to Appendix~\ref{app:baddiscussion}. (Sketch) The proof comes from fixing $i^* = 1$ and analyzing the output of the estimator for any function in the function class ($\calF$) corresponding to $i^*$  as specified in Definition~\ref{def:badoracle}. Due to the difference form of the estimators, the distribution of the first index of the outputs of these estimators turns out to be a chi-squared random variable with the degree of freedom 1 scaled by the parameter $g$ defined in Definition~\ref{def:badoracle}. Hence, this distribution satisfies all the properties mentioned in Definition~~\ref{def:badoracle}, thus completing the proof. 
\end{proof}

 We further prove that the two-point oracle proposed by \citet{duchioptzero} is also 3-\acs. Moreover, the property of being an AC oracle is preserved under the mean extension, as shown by the following lemma.

\begin{lemma}
    If an oracle $\c{E}$ is $C_s$-\acs~ then $M_m^{\c{E}}$ is $C_s$-\acs.
\end{lemma}
\begin{proof}
    We defer the complete proof to Appendix~\ref{app:baddiscussion}. (Sketch) The argument here is, we are taking mean of i.i.d. random variables $U^{(f,w_j)}_i \sim \c{E}(f, w_j)$ for all $i \in [m]$ for $\c{E}$ which are $C_s$ anti-concentrated. Hence, the ``strict'' properties (namely zero-preserving property and the strict negativity under non-zero gradient of AC oracles) of samples of $\c{E}(f, w_j)$ also comply to the mean of i.i.d. samples from distribution satisfying property 1 and property 2. Due to linearity of expectation, the same upper bound on the expectation holds for the mean satisfying property 3. Due to reordering of RV and Young's inequality, property 4 also complies to the mean.
\end{proof}

This lemma directly implies that $M_m^{FD}$ and $M_m^{SPSA}$ are 3-\acs. 

If we restrict ourselves to the class of zeroth order oracles, then we make an interesting observation: All the estimators discussed above that use at least \textit{two function evaluations} satisfy the properties mentioned in Definition~\ref{def:badoracle}. On the other hand, for the $SP$ estimator defined in Example~\ref{ex:elemestimators}, we observe that it does not satisfy the third property of Definition~\ref{def:badoracle}. Thus, restricted to zeroth order oracles, the idea of an \acs~oracle roughly captures an important distinction between popular single-point and two-point estimator(s).

Using the definition of an \acs~oracle, we show that even with unknown (but random) initialization, the model loses privacy for a large enough diameter of the constraint set.

\begin{theorem}
    \label{multidim:varinit}
     Consider running T steps of Algorithm \ref{alg:proj_zo_sgd} using a $C_s$-\acs~oracle $\calO$, as defined in Definition~\ref{def:badoracle}, with $D > \frac{\eta L}{2n}$ and $\calR_{init}$ is $\calN(0, \sigma^2I)$. Assume that the algorithm only returns the final iterate. Then, there exists an L-Lipschitz linear loss function over the set $[-D, D]^d \subset \Real^d$ such that for any $T \geq 1$ the output of Algorithm \ref{alg:proj_zo_sgd} is not $(\varepsilon, \delta)$-differentially private for any $\varepsilon, \delta$ satisfying $\delta \leq \frac{1}{16C_s}\max\left\{\frac{1}{T^{2/3}}, \frac{\eta L}{2nD}\right\}$ and
    \begin{align*}
        \varepsilon \leq \min\left\{\frac{\eta^2L^2T^{4/3}}{8n^2\sigma^2}, \frac{D^2}{2\sigma^2}\right\} + \ln\paren{\frac{\sqrt{2\pi}L\eta}{64C_sn\sigma}}.
    \end{align*}
\end{theorem}

We defer the proof to Appendix~\ref{app:multidim:varinit}. %
If we take the values of $n \in [100, 1000]$, $\eta \in [0.001, 0.01]$, $C_s = 3$, $L = 100$, and $\sigma = \frac{1}{1020}$, we see that for a large enough $D\left(\geq \frac{T^{2/3}}{200}\right)$ this result gives us that privacy is not possible (roughly) for $\epsilon \leq 896 \cdot T^{4/3}$ and $\delta \leq \frac{1}{96T^{2/3}}$. Notably, we get the same flavor of result as obtained in the lower bound construction of \citet{altschuler2022privacy}. Hence, it would be interesting to see if a matching upper bound is attainable for Projected ZO-GD.

\section{Conclusion and Open Problems}

In this work, we demonstrated that projected (stochastic) ZO-gradient descent cannot ensure differential privacy without incorporating additional (additive) noise. While our findings apply to a broad class of zeroth-order oracles, the algorithmic framework we used is limited to the class of projected SGD. Potential future directions for this problem include:






\begin{enumerate}
    \item Can we prove Theorem~\ref{multidim:varinit} for other function classes (e.g., strongly convex loss functions)?
    \item Can we extend our (lower-bound) analysis beyond projected (stochastic) ZO-GD?
    \item Although zeroth-order estimators do not offer inherent privacy on their own, can they amplify the privacy of other (additive) noisy methods?
    %
\end{enumerate}
The answer to any of these questions will help understand the limitations and potential of zeroth-order optimization for private optimization.

