\section{Useful Inequalities}

\begin{lemma}[Gaussian Concentration \citep{daganshamir}]
    \label{lem:gauconc}
    Let W be a random variable (RV) distributed normally with mean 0 and variance $\sigma^2$. Then, for any $w > 0$, 
    \begin{align*}
        \bb{P}\left[W \geq w\right] \leq \frac{\sigma e^{-w^2/2\sigma^2}}{w\sqrt{2\pi}}.
    \end{align*}
\end{lemma}

\begin{lemma}[\citep{paley1932some}]
    \label{lem:pz}
    Let Z be a non-negative random variable (RV) and let $\alpha \in [0, 1]$, then
    \begin{align*}
        \bb{P}\left[Z \geq \alpha\Ex{Z}\right] \geq (1 - \alpha)^2\frac{(\Ex{Z})^2}{\Ex{Z^2}}.
    \end{align*}
\end{lemma}

\section{Proofs and Discussions of Section~\ref{sec:privacyzosgd}}
\subsection{Proof of Lemma~\ref{estimator:multiplicative}}
\label{app:estimatormultiplicative}
\begin{proof}
    By the definition of SPSA estimator for $f(w)$, $\mu > 0$ and ${Z} \sim \calN(0, I_d)$, we have
    \begin{align*}
        SPSA(f, w) &= \frac{f(w + \mu {Z}) - f(w - \mu {Z})}{2\mu} {Z}.
    \end{align*}
    If $f(w) = 0$ for all $w \in \Real^d$, then $SPSA(f, w) = \mathbf{0}_d$ satisfying property 1. Moreover, for the function $f(w) = \frac{a}{2}\twonorm{w}^2$ for $a > 0$, we have:
    \begin{align*}
        SPSA(f, w) &= \frac{a}{2}\frac{\twonorm{w + \mu {Z}}^2 - \twonorm{w - \mu {Z}}^2}{2\mu} {Z} \\
        &= \frac{a}{2} \frac{\paren{\twonorm{w}^2 + \twonorm{\mu {Z}}^2 + 2\mu w^T{Z}} - \paren{\twonorm{w}^2 + \twonorm{\mu {Z}}^2 - 2\mu w^T{Z}}}{2\mu} {Z} \\
        &= a{Z}{Z}^Tw.
    \end{align*}
    Then for any $c \in \bb{R}^d$, consider its first index $\{c\}_1$, then the event $a{Z}{Z}^Tw = c$ implies that $\{a{Z}{Z}^Tw\}_1 = \{c\}_1$ i.e. $\bb{P}\left[a{Z}{Z}^Tw = c\right] \leq \bb{P}\left[\{a{Z}{Z}^Tw\}_1 = \{c\}_1\right]$. Now, we can write $\{a{Z}{Z}^Tw\}_1 = aw_1\{Z\}_1^2 + a\sum_{i=2}^d w_i\{Z\}_i\{Z\}_1$. Since $Z \sim \calN(0, I_d)$, it implies that $\{a{Z}{Z}^Tw\}_1$ is a non-constant polynomial in $\{Z\}_1, ..., \{Z\}_d$ which means that $\{a{Z}{Z}^Tw\}_1$ is continuous, implying that $\bb{P}\left[\{a{Z}{Z}^Tw\}_1 = \{c\}_1\right] = 0$ for any $\{c\}_1 \in \Real$, implying that $\bb{P}\left[a{Z}{Z}^Tw = c\right] = 0$. Hence, $SPSA(f, w)$ is a continuous RV satisfying property 2.

    Similarly, by definition of the FD estimator for $f(w)$, $\mu > 0$ and ${Z} \sim \calN(0, I_d)$, we get that
    \begin{align*}
        FD(f, w) &= \frac{f(w + \mu {Z}) - f(w)}{2\mu} {Z}
    \end{align*}
    If $f(w) = 0$ for all $w \in \Real^d$, then $FD(f, w) = \mathbf{0}_d$ satisfying property 1. If $f(w) = \frac{a}{2}\twonorm{w}^2$ for $a > 0$, we have that:
    \begin{align*}
        FD(f, w) &= \frac{a}{2}\frac{\twonorm{w + \mu {Z}}^2 - \twonorm{w}^2}{\mu} {Z} \\
        &= \frac{a}{2} \frac{\paren{\twonorm{w}^2 + \twonorm{\mu {Z}}^2 + 2\mu w^T{Z}} - \twonorm{w}^2}{\mu} {Z} \\
        &= \frac{a}{2}\paren{\mu\twonorm{{Z}}^2 + 2w^T{Z}} {Z}.
    \end{align*}
    Considering a similar argument as the SPSA estimator, we evaluate $\{FD(f,w)\}_1$, which is equal to $\frac{a\mu}{2}\{Z\}_1^3 + \frac{a\mu}{2} \sum_{i=2}^d \{Z\}_i^2\{Z\}_1 + aw_1\{Z\}_1^2 + a\sum_{i=2}^dw_i\{Z\}_i\{Z\}_1$. Since $\{FD(f,w)\}_1$ is a non-constant polynomial in $\{Z\}_1, ..., \{Z\}_d$, $\{FD(f,w)\}_1$ is continuous.
    Hence, $FD(f, w)$ is a continuous RV satisfying property 2.

    Similarly, by definition of the SP estimator for $f(w)$, $\mu > 0$ and ${Z} \sim \calN(0, I_d)$, we get that
    \begin{align*}
        SP(f, w) &= \frac{d}{\mu}f(w + \mu {Z})Z
    \end{align*}
    If $f(w) = 0$ for all $w \in \Real^d$, then $FD(f, w) = \mathbf{0}_d$ satisfying property 1. If $f(w) = \frac{a}{2}\twonorm{w}^2$ for $a > 0$, we have that:
    \begin{align*}
        SP(f, w) &= \frac{d}{\mu}f(w + \mu {Z})Z \\
        &= \frac{ad}{2\mu}\twonorm{w + \mu Z}^2{Z} \\
        &= \frac{a}{2}\paren{\twonorm{w}^2 + \mu^2\twonorm{{Z}}^2 + 2w^TZ} {Z}.
    \end{align*}
    Considering similar arguments as the SPSA and FD estimator, we see that $\{SP(f,w)\}_1$ is a non-constant polynomial in $\{Z\}_1, ..., \{Z\}_d$ which implies that $\{SP(f,w)\}_1$ is continuous. Hence, $SP(f, w)$ is a continuous RV satisfying property 2.

    For the mean extensions of the given oracles, we use the definition of the mean oracle
    \begin{align*}
        M^\calE(f, w, m) = \frac{1}{m} \sum_{i=1}^m U_i,
    \end{align*}
    where $U_i$ drawn i.i.d. from $\calE(f, w)$.
    Each $U_i$ is $\mathbf{0}_d$ when $f(w) = 0$ for all $w \in \Real^d$. Then, we get that for $f(w) = 0$ for all $w \in \Real^d$, $M^\calE(f, w, m) = \mathbf{0}_d$, satisfying property 1. In the other case, since $\calE_i(f, w)$ is continuous for all $i \in [m]$. We
    utilize the fact that if multiple continuous and independent random variables are added then their resultant addition is also a continuous random variable. Thus, the results extend for $M^{SPSA}$, $M^{FD}$, and $M^{SP}$.
\end{proof}

\subsection{Further Discussion on Zeroth Order Estimators}
Consider the estimator given by \citet{duchioptzero} for minimization of non-smooth functions.
\begin{definition}[\citet{duchioptzero}]
    \label{duchi:oracle}
    If ${Z_1}, {Z_1} \sim \calN(0, I_d)$, then the estimator is given by
    \begin{align*}
        G_{\mu_1, \mu_2}(f, w) = \frac{f(w + \mu_1{Z_1} + \mu_2{Z_2}) - f(w + \mu_1{Z_1})}{\mu_2}{Z_2}.
    \end{align*}
\end{definition}

\begin{lemma}
    The oracle defined in Definition~\ref{duchi:oracle} is a \zpn oracle.
\end{lemma}

\begin{proof}
    Using identical arguments from the proof of Theorem~\ref{estimator:multiplicative}, we see that with $f(w) = 0$ for all $w \in \Real^d$, $G_{\mu_1, \mu_2}(f, w) = \mathbf{0}_d$. Calculating for $f(w) = \frac{A}{2}\twonorm{w}^2$, we get that
    \begin{align*}
        G_{\mu_1, \mu_2}(f, w) = &= \frac{A}{2}\frac{\twonorm{w + \mu_1 {Z_1} + \mu_2 {Z_2}}^2 - \twonorm{w + \mu_1 {Z_1}}^2}{\mu_2} {Z_2} \\
        &= \frac{A}{2} \frac{\paren{\twonorm{w}^2 + \twonorm{\mu_1 {Z_1} + \mu_2 {Z_2}}^2 + 2 w^T\paren{\mu_1 {Z_1} + \mu_2 {Z_2}}} - \twonorm{w}^2}{\mu_2} {Z_2} \\
        &= \frac{A}{2\mu_2}\paren{\twonorm{\mu_1 {Z_1} + \mu_2 {Z_2}}^2 + 2w^T\paren{\mu_1 {Z_1} + \mu_2 {Z_2}}} {Z_2}.
    \end{align*}
    Thus, using arguments similar to the proof of Lemma~\ref{estimator:multiplicative} $G_{\mu_1, \mu_2}(f, w)$ would have a continuous distribution, proving our claim.
\end{proof}

The above lemma also implies that $\c{M}^{G_{\mu_1, \mu_2}}$ would also be a continuous distribution. It is evident that almost every zeroth order estimator used in the literature (yet) satisfies the properties of \zpn oracles.

\section{Proofs of Section~\ref{sec:privacyzosgdunk}}

\subsection{Proof of Theorem~\ref{multidim:varinit}}
\label{app:multidim:varinit}

\begin{definition}{(Restated Definition~\ref{def:badoracle})}
    An update oracle $\calO$ is $C_s$-\ac if there exists an index $i^* \in [d]$ such that if we consider the function class $\c{F} = \left\{\inner{g\mathbf{e}_{i^*}}{w}: - L \leq g \leq 0\right\}$, then for any $h \in \c{F}$ and $\overline{w} \in \Real^d$, if $U \sim \calO(h, \overline{w})$ then,
    \begin{enumerate}
        \item $\{\nabla h(\overline{w})\}_{i^*} = 0$ implies $U = \mathbf{0}_d$ w.p. 1 i.e. $\bb{P}\left[U = \mathbf{0}_d\right] = 1$
        \item $\{\nabla h(\overline{w})\}_{i^*} \neq 0$ implies $\bb{P}\left[\{U\}_{i^*} < 0\right] = 1$ 
        \item $\bb{E}\left[\{U\}_{i^*}\right] \leq \{\nabla h(\overline{w})\}_{i^*}$
        \item For any set of $\{w_1, w_2, ..., w_N\} \subset \Real^d$, let $U_j \sim \calO(h, w_j)$ independently for all $j \in [N]$. Then $\Ex{\paren{\sum_{j=1}^N \{U_j\}_{i^*}}^2}\leq C_s\Ex{\sum_{j=1}^N \{U_j\}_{i^*}}^2$
    \end{enumerate}
\end{definition}

\begin{theorem}{(Restated Theorem~\ref{multidim:varinit})}
     Consider running T steps of Algorithm \ref{alg:proj_zo_sgd} using a $C_s$-\acs~oracle $\calO$, as defined in Definition~\ref{def:badoracle}, with $D > \frac{\eta L}{2n}$ and $\calR_{init}$ is $\calN(0, \sigma^2I)$. Assume that the algorithm only returns the final iterate. Then, there exists an L-Lipschitz linear loss function over the set $[-D, D]^d \subset \Real^d$ such that for any $T \geq 1$ the output of Algorithm \ref{alg:proj_zo_sgd} is not $(\varepsilon, \delta)$-differentially private for any $\varepsilon, \delta$ satisfying $\delta \leq \frac{1}{16C_s}\max\left\{\frac{1}{T^{2/3}}, \frac{\eta L}{2nD}\right\}$ and
    \begin{align*}
        \varepsilon \leq \min\left\{\frac{\eta^2L^2T^{4/3}}{8n^2\sigma^2}, \frac{D^2}{2\sigma^2}\right\} + \ln\paren{\frac{\sqrt{2\pi}L\eta}{64C_sn\sigma}}.
    \end{align*}
\end{theorem}

\begin{proof}
    Consider the following loss function for a database $\calX = \{x_1, x_2, ..., x_n\}$
    \begin{align*}
        \mathcal{L}(w; \calX) = \frac{-1}{n} \inner{w}{\sum_{i = 1}^n x_i},
    \end{align*}
    where $\twonorm{x_i} \leq L$ for all $i \in [n]$ and $x_i \in \Real^d$ with $w \in [-D, D]^d$.
    Consider the neighbouring databases $\chi = \{x_1, x_2, ..., x_{n-1}, x_n\}$ and $\chi' = \{x_1, x_2, ..., x_{n-1}, x_n'\}$ differing only at the last entry. Let $x_1, ..., x_{n-1}, x_n$ to be $\mathbf{0}_d$. Given the index $i^{*}$ defined in Defintion~\ref{def:badoracle} for $C_s$-\acs~oracles, let $x_n' = L{\mathbf{e}_{i^*}}$. With this construction, we have $\calL(w; \calX) = 0$ and $\calL(w; \calX') = \frac{-L}{n}\inner{w}{{\mathbf{e}_{i^*}}}$. Let $W^{\calX}_t$ and $W^{\calX'}_t$ be the $t^{th}$ iterate of Algorithm~\ref{alg:proj_zo_sgd} is run on $\calL(\cdot, \calX)$ and $\calL(\cdot, \calX')$, respectively. 

    To show that the algorithm is differentially private, we need to define a measurable set $S$ so that Definition~\ref{def:dp} fails. Let
    \begin{align*}
        S = \left\{w \in \Real^d: \{w\}_{i^*} \geq \min\left\{\frac{\eta L}{2n}T^{2/3}, D\right\}  \right\}.
    \end{align*}

     We will show that for this set S, $\bb{P}\left[W^{\calX'}_T \in S\right] \geq e^{\varepsilon_0}\bb{P}\left[W^{\calX}_T \in S\right] + \delta_0$ for some $\varepsilon_0$ and $\delta_0$.

    \textbf{Note:} The two adjacent functions have been designed in a manner such that in one case, the iterate stays near origin with high probability. In the other case, it shifts away from its original point with a good probability, enough to ensure separation between the high probability regions of the two iterates.

    Based on our definition of S, we divide our analysis into two cases:
\begin{itemize}
    \item \textbf{Case 1:} $T \leq \paren{\frac{2nD}{\eta L}}^{3/2}$ or equivalently $\frac{\eta L}{2n}T^{2/3} \leq D$\\
        \textbf{Computing $\bb{P}\left[W^{\calX'}_T \in S\right]$} Since we have assumed the constraint space to be a hypercube, projection corresponds to coordinate wise clipping. Hence, it would suffice to analyze the setting for one coordinate without affecting the other coordinates and vice versa. Due to the second property in Definition~\ref{def:badoracle}, we have that $\{W^{\calX'}_t\}_{i^*}$ is monotonic, i.e. $\{W^{\calX'}_{t-1}\}_{i^*} \leq \{W^{\calX'}_{t}\}_{i^*}$ for $t \geq 2$. Notice that if $W^{\calX'}_T \notin S$ then $\{W^{\calX'}_T\}_{i^*} < D$ which implies that no projection occurred in the ${i^*}^{th}$ coordinate on the right side of the interval $[-D, D]$ in $T$ iterations. Hence, $\{W^{\calX'}_T\}_{i^*} =\max\left\{-D, \{W^{\calX'}_0\}_{i^*} - \eta \{U^{\calX'}_1\}_{i^*}\right\} - \eta \sum_{j=2}^{T}\{U^{\calX'}_j\}_{i^*}$ where $U^{\calX'}_j \sim \calO\left(\mathcal{L}(\cdot;\calX'), W^{\calX'}_{j-1}\right)$. Hence, 
        \begin{align*}
                \bb{P}\left[W^{\calX'}_T \in S\right] &= 1 -\bb{P}\left[\max\left\{-D, \{W^{\calX'}_0\}_{i^*} - \eta \{U^{\calX'}_1\}_{i^*}\right\} - \eta \sum_{j=2}^{T}\{U^{\calX'}_j\}_{i^*} < \frac{\eta L}{2n}T^{2/3}\right] \\
                &\geq 1 - \bb{P}\left[\{W^{\calX'}_0\}_{i^*} - \eta \sum_{j=1}^{T}\{U^{\calX'}_j\}_{i^*} < \frac{\eta L}{2n}T^{2/3}\right]\\
                &= \bb{P}\left[\{W^{\calX'}_0\}_{i^*} - \eta \sum_{j=1}^{T}\{U^{\calX'}_j\}_{i^*} \geq \frac{\eta L}{2n}T^{2/3}\right], \tag{a}
        \end{align*}
        where the inequality is due to the fact $\{W^{\calX'}_T\}_{i^*} \geq \{W^{\calX'}_0\}_{i^*} - \eta \sum_{j=1}^{T}\{U^{\calX'}_j\}_{i^*}$. Next, we obtain a lower bound on $\bb{P}\left[\{W^{\calX'}_0\}_{i^*} - \eta \sum_{j=1}^{T}\{U^{\calX'}_j\}_{i^*} \geq \frac{\eta L}{2n}T^{2/3} \right]$. Take $Z = -\sum_{j=1}^{T}\{U^{\calX'}_j\}_{i^*}$. We have
        \begin{align*}
            \bb{P}\left[\{W^{\calX'}_0\}_{i^*} + \eta Z \geq \frac{\eta L}{2n}T^{2/3} \right] &\geq \bb{P}\left[\eta Z \geq \frac{\eta L}{2n}T^{2/3} - \{W^{\calX'}_0\}_{i^*} \bigg\vert \{W^{\calX'}_0\}_{i^*} \geq 0\right]\bb{P}\left[\{W^{\calX'}_0\}_{i^*} \geq 0\right]\\
            &\geq \frac{1}{2}\bb{P}\left[Z \geq \frac{L}{2n}T^{2/3} \right] \\
            &\geq \frac{1}{2}\bb{P}\left[Z \geq \frac{1}{2T^{1/3}}\frac{LT}{n} \right]\\
            &\geq \frac{1}{2}\bb{P}\left[Z \geq \frac{1}{2T^{1/3}}\Ex{Z} \right]. \tag{1}
        \end{align*}
        In the first inequality, we used the fact that $\{W^{\calX'}_0\}_{i^*} \sim \calN(0, \sigma^2)$ and therefore $\bb{P}\left[\{W^{\calX'}_0\}_{i^*} \geq 0\right] = \frac{1}{2}$. In the fourth inequality, we used the third property of the $C_s$-AC oracle in Definition~\ref{def:badoracle} which (with linearity of expectation) implies that $\Ex{Z} = \Ex{-\sum_{j=1}^T \{U_j\}_{i^*}} \leq -\sum_{j=1}^T\{\nabla \mathcal{L}(W_j^{\chi'};\chi')\}_{i^*} $ and the fact that $\{\nabla \mathcal{L}(w; \chi')\}_{i^*} = -\frac{L}{n}$ for all $w \in \Real^d$, by our construction. 

        Using, the second property of $C_s$-AC oracle, we have  $Z = -\sum_{j=1}^T \{U_j\}_{i^*} \geq 0$. Thus, applying Paley-Zygmund (Lemma~\ref{lem:pz}) on random variable Z for $\alpha = \frac{1}{2T^{1/3}}$, we get
        \begin{align*}
            \bb{P}\left[Z \geq \frac{1}{2T^{1/3}}\Ex{Z} \right] & \geq \paren{1 - \frac{1}{2T^{1/3}}}^2\frac{(\Ex{Z})^2}{\Ex{Z^2}} \\
            &\geq \frac{1}{4C_sT^{2/3}}. \tag{2}
        \end{align*}
      In the second inequality, we use the fourth property of $C_s$-AC oracles as defined in Definition~\ref{def:badoracle} to get $\Ex{\paren{\sum_{j=1}^N \{U_j\}_{i^*}}^2} \leq C_s \Ex{\sum_{j=1}^N \{U_j\}_{i^*}}^2$ which implies that $\Ex{Z^2} \leq C_s (\Ex{Z})^2$ and $T \geq 1$. Combining inequalities 1 and 2, we get that,
      \begin{align*}
          \bb{P}\left[\{W^{\calX'}_0\}_{i^*} - \eta \sum_{j=1}^{T}\{U^{\calX'}_j\}_{i^*} \geq \frac{\eta L}{2n}T^{2/3} \right] \geq \frac{1}{8C_sT^{2/3}}. \tag{b}
      \end{align*}
      Combining inequalities (a) and (b), we get
      \begin{align*}
          \bb{P}\left[W^{\calX'}_T \in S\right] \geq \frac{1}{8C_sT^{2/3}}. \tag{C1}
      \end{align*}
      So far, we computed a lower bound on $\bb{P}\left[W^{\calX'}_T \in S\right]$. Next, we compute an upper bound on $\bb{P}\left[W^{\calX}_T \in S\right]$.
        \paragraph{Computing $\bb{P}\left[W^{\calX}_T \in S\right]$} Using the first property of the $C_s$-AC oracle in Definition~\ref{def:badoracle}, we have that $W^{\calX}_T = W_0 \sim \calN(0, I_d)$. Since the projection operator simply projects any value outside the interval to the edge, it does not change the inverse CDF on points which are within the interval. Then, we get that 
        \begin{align*}
            \bb{P}\left[W^{\calX}_T \in S\right] &= \bb{P}\left[\{w_0\}_{i^*} \geq \frac{\eta L}{2n}T^{2/3} \right] \\
            &\leq \frac{2n\sigma}{\sqrt{2\pi} \eta L T^{2/3}}e^{-\frac{\eta^2L^2T^{4/3}}{8n^2\sigma^2}}, \tag{C2}
        \end{align*}

        where the inequality is due to Gaussian Concenteration (Lemma~\ref{lem:gauconc}) . Using inequalities (C1) and (C2), we get that 
        \begin{align*}
            \frac{\bb{P}\left[W^{\calX'}_t \in S\right] - \frac{1}{16C_sT^{2/3}}}{\bb{P}\left[W^{\calX}_T \in S\right]} \geq \frac{\sqrt{2\pi}\eta L}{32n\sigma C_s}e^{\frac{\eta^2L^2T^{4/3}}{8n^2\sigma^2}}.
        \end{align*}
        Therefore,
        \begin{align*}
            \bb{P}\left[W^{\calX'}_t \in S\right] \geq e^{\frac{\eta^2L^2T^{4/3}}{8n^2\sigma^2} + \ln\paren{\frac{\sqrt{2\pi}L\eta}{32C_sn\sigma}}}\bb{P}\left[W^{\calX}_T \in S\right] + \frac{1}{16C_sT^{2/3}}.
        \end{align*}

    \item \textbf{Case 2:} $T \geq \paren{\frac{2nD}{\eta L}}^{3/2}$ or equivalently $\frac{\eta L}{2n}T^{2/3} \geq D$

    The approach to this case is the same Case 1. It only differs in the computation of the constants and dependence on the respective variables.

    \textbf{Computing $\bb{P}\left[W^{\calX'}_T \in S\right]$} Using the same argument as that in case 1, we get that
        \begin{align*}
            \bb{P}\left[W^{\calX'}_T \in S\right] &\geq \bb{P}\left[\{W^{\calX'}_0\}_{i^*} - \eta \sum_{j=1}^{T}\{U^{\calX'}_j\}_{i^*} \geq D\right]  \tag{d}
        \end{align*}
        Now, to obtain the lower bound on $\bb{P}\left[\{W^{\calX'}_0\}_{i^*} - \eta \sum_{j=1}^{T}\{U^{\calX'}_j\}_{i^*} \geq D \right]$, we use the same series of steps as those in Case 1.
        \begin{align*}
            \bb{P}\left[\{W^{\calX'}_0\}_{i^*} - \eta \sum_{j=1}^{T}\{U^{\calX'}_j\}_{i^*} \geq D \right] &\geq \frac{1}{2}\bb{P}\left[-\sum_{j=1}^{T}\{U^{\calX'}_j\}_{i^*} \geq \frac{D}{\eta} \right] \\
            &\geq \frac{1}{2}\bb{P}\left[-\sum_{j=1}^{T}\{U^{\calX'}_j\}_{i^*} \geq \frac{Dn}{\eta LT}\frac{LT}{n} \right] \\
            & \geq \frac{1}{2}\bb{P}\left[-\sum_{j=1}^{T}\{U^{\calX'}_j\}_{i^*} \geq \frac{Dn}{\eta LT}\Ex{-\sum_{j=1}^{T}\{U^{\calX'}_j\}_{i^*}} \right] \\
            & \geq \frac{1}{2}\paren{1 - \frac{Dn}{\eta LT}}^2\frac{1}{C_s} \\
            &\geq \frac{1}{2}\paren{1 - \frac{1}{2}\sqrt{\frac{\eta L}{2Dn}}}^2\frac{1}{C_s} \\
            &\geq \frac{1}{16}\frac{\eta L}{Dn}\frac{1}{C_s}. \tag{e}
        \end{align*}

        In the first equality, we simply used the fact that $\{W^{\calX'}_0\}_{i^*} \sim \calN(0, \sigma^2)$ and therefore $\bb{P}\left[\{W^{\calX'}_0\}_{i^*} \geq 0\right] = \frac{1}{2}$. In the third inequality, we used the third property of the $C_s$-AC oracle where $\{\nabla \mathcal{L}(\cdot; \chi')\}_{i^*} T \geq \Ex{\sum_{j=1}^T \{U_j\}_{i^*}}$ and $\{\nabla \mathcal{L}(\cdot; \chi')\}_{i^*} = -\frac{L}{n}$, by our construction. In the fourth inequality, using the second property of the $C_s$-AC oracle, we get $-\sum_{j=1}^T \{U_j\}_{i^*} \geq 0$, $T \geq 1$. Hence, we apply Paley-Zygmund on $-\sum_{j=1}^N \{U_j\}_{i^*}$ and then use the fourth property of the $C_s$-AC oracle implying that $\Ex{\paren{\sum_{j=1}^N \{U_j\}_{i^*}}^2} \leq C_s \Ex{\sum_{j=1}^N \{U_j\}_{i^*}}^2$. In the fifth inequality, we use the fact that $T \geq \paren{\frac{2nD}{\eta L}}^{3/2}$ and in the sixth inequality, we use the fact that $\frac{1}{2}\sqrt{\frac{\eta L}{2Dn}} \leq \frac{1}{2}$. Thus, combining inequalities (d) and (e), we get that
        \begin{align*}
            \bb{P}\left[W^{\calX'}_t \notin S\right] \geq \frac{1}{16}\frac{\eta L}{Dn}\frac{1}{C_s}  \tag{F1}
        \end{align*}

        \paragraph{Computing $\bb{P}\left[W^{\calX}_T \in S\right]$} This argument follows exactly from the first case. We get that 
        \begin{align*}
            \bb{P}\left[W^{\calX}_T \in S\right] = \bb{P}\left[\{w_0\}_{i^*} \geq D \right] \leq \frac{\sigma}{\sqrt{2\pi} D}e^{-\frac{D^2}{2\sigma^2}} \tag{F1}
        \end{align*}
        Hence, using inequalities F1 and F2, we get
        \begin{align*}\frac{\bb{P}\left[W^{\calX'}_t \in S\right] - \frac{\eta L}{32C_sDn}}{\bb{P}\left[W^{\calX}_T \in S\right]} \geq \frac{\sqrt{2\pi}\eta L}{32C_sn\sigma}e^{\frac{D^2}{2\sigma^2}} 
        \end{align*}

        Therefore,
        \begin{align*}
        \bb{P}\left[W^{\calX'}_t \in S\right] \geq e^{{\frac{D^2}{2\sigma^2}} + \ln\paren{\frac{\sqrt{2\pi}\eta L}{32C_sn\sigma}}}\bb{P}\left[W^{\calX}_T \in S\right] + \frac{Dn}{32C_s\eta L}
        \end{align*}
\end{itemize}

Combining the above two cases proves our claim.
\end{proof}

\section{Discussion of Oracles}
\label{app:baddiscussion}
\begin{lemma}
    SPSA, FD, and estimator defined in Definition~\ref{duchi:oracle} are 3 \acs.
\end{lemma}
\begin{proof}
    Take $i^* = 1$. Consider any $f \in \calF$. Then, the expression of $f = \inner{ge_1}{w}$, which means that $\abs{\{\nabla f\}_{i^*}} = g$. Then, for ${Z_{SPSA}}, {Z_{FD}}, {Z_{G_1}} {Z_{G_2}} \sim \calN(0, I_d)$,
    \begin{align*}
        SPSA(f, w) &= \frac{\inner{ge_1}{w + \mu {Z_{SPSA}}} - \inner{ge_1}{w - \mu {Z_{SPSA}}}}{2\mu}{Z_{SPSA}} \\
        &= g\{{Z_{SPSA}}\}_1{Z_{SPSA}} \\
        FD(f, w) &= \frac{\inner{ge_1}{w + \mu {Z_{FD}}} - \inner{ge_1}{w}}{\mu}{Z_{FD}} \\
        &= g\{{Z_{FD}}\}_1{Z_{FD}}\\
        G_{\mu_1, \mu_2}(f, w) &= \frac{\inner{ge_1}{w + \mu_1 {Z_{G_1}} + \mu_2 {Z_{G_2}}} - \inner{ge_1}{w + \mu_1 {Z_{G_1}}}}{\mu_2}{Z_{G_2}}\\
        &= g\{{Z_{G_2}}\}_1{Z_{G_2}}
    \end{align*}
    Since ${Z_{SPSA}}, {Z_{FD}}, {Z_{G_2}}$ are i.i.d. random variables, it implies that the given estimators follow the same distribution. Take $\c{E}$ to be any one of the oracles, and for ${Z} \sim \calN(0, I_d)$, we have that $\c{E}(f, w) = g\{{Z}\}_1{Z}$. Thus, we have that $\{\c{E}(f, w)\}_1 = g\{{Z}\}_1^2$ and $\{{Z}\}_1^2 \sim \chisq(1)$. $\{U^{(f)}\}_1 = g{V}$ where ${V} \sim \chisq(1)$. Now, we verify the properties
    \begin{enumerate}
        \item Observe that when $\abs{\{\nabla f\}_{i^*}} = g = 0$ which implies that $\c{E}(f,w) = \mathbf{0}_d$, satisfying property 1.
        \item For the second property, ${V} \geq 0$ which implies that $gV \leq 0$ for all .
        \item $\Ex{V} = 1$ which implies that $\Ex{\{U^{(f)}\}_{i^*}} = g\Ex{V} = g = \abs{\{\nabla f\}_{i^*}}$.
        \item $R = \sum_{j=1}^N V_j \sim \chisq(N)$. Hence, we know that $\Ex{R} = N$ and $Var[R] = 2N$, which implies that $\Ex{R^2} = N^2 + 2N$. We also have that $\sum_{j=1}^N \{U^{(f)}_j\}_{i^*} = g\sum_{j=1}^N V_j$, which implies that $\Ex{\paren{\sum_{j=1}^N \{U^{(f)}_j\}_{i^*}}^2} = g^2(N^2 + 2N)$ and $\Ex{\paren{\sum_{j=1}^N \{U^{(f)}_j\}_{i^*}}}^2 = g^2N^2$. Using $N \geq 1$ gives the value of $C_s = 3$ proving our given claim.
    \end{enumerate}
\end{proof}

\begin{lemma}{(Restated)}
    If an oracle $\c{E}$ is $C_s$-\acs~ then $M_m^{\c{E}}$ is $C_s$-\acs.
\end{lemma}
\begin{proof}
    If $\calE$ is $C_s$-AC, then there exists an $i^* \in [N]$ which satisfies the properties mentioned in Definition~\ref{def:badoracle}. Using definition of mean extensions of estimators, we have that for $f \in \calF$ (as defined in Definition~\ref{def:badoracle})
    \begin{align*}
        M^\calE_m(f, w) = \frac{1}{m} \sum_{j=1}^m U_j^{(f,w)},
    \end{align*}
    where $U_j^{(f,w)}$ is drawn i.i.d. from $\calE(f, w)$. 

    Using property 1 of $\calE$, $\abs{\{\nabla f\}_{i^*}} = 0$ implies $U_j^{(f,w)} = \mathbf{0}_d$ for all $j \in [m]$. Thus, we get $\{M^\calE_m(f, w)\}_{i^*} = \frac{1}{m} \sum_{j=1}^m \{U_j^{(f,w)}\}_{i^*} < 0$, satisfying property 2.

    Similarly, for property 2, $\abs{\{\nabla f\}_{i^*}} \neq 0$ implies that $\{U_j^{(f,w)}\}_{i^*} < 0$ for all $j \in [m]$. Thus, we get $\{M^\calE_m(f, w)\}_{i^*} = \frac{1}{m} \sum_{j=1}^m \{U_j^{(f,w)}\}_{i^*} < 0$, satisfying property 2.

    For the third property, consider $\Ex{\{M^\calE_m(f, w)\}_{i^*}}$. Using linearity of expectation, we get
    \begin{align*}
        \Ex{\frac{1}{m}\sum_{j=1}^m \{U_j^{(f,w)}\}_{i^*}} &= \frac{1}{m}\sum_{j=1}^m \Ex{\{U_j^{(f,w)}\}_{i^*}} \\
        &\leq \{\nabla h\}_{i^*}.
    \end{align*}
    Hence, $M^\calE_m$ satisfies property 3. 

    Consider the set $\{w_{c}\}_{c=1}^{N}$. By the definition of $M^\calE_m$, we have 
    \begin{align*}
        \Ex{\paren{\frac{1}{m}\sum_{k=1}^N\sum_{j=1}^m \{U_j^{(f,w_k)}\}_{i^*}}^2} = \Ex{\paren{\frac{1}{m}\sum_{j=1}^m\sum_{k=1}^N \{U_j^{(f,w_k)}\}_{i^*}}^2}
    \end{align*}
    Let $S_j = \sum_{k=1}^N \{U_j^{(f, w_k)}\}_i$. Since $U_j^{(f, w_k)}$ are sampled i.i.d. from $\calE(f, w_k)$ for all $j \in [m]$, it implies that $S_j = \sum_{k=1}^N \{U_j^{(f, w_k)}\}_{i^*}$ is identically distributed for all $j \in [m]$. Thus, we can take $\Ex{S_u} = K_f$, and $\Ex{S_u^2} = K_s$ for all $u \in [m]$. Applying Young's inequality, we get that
    \begin{align*}
        \Ex{\paren{\frac{1}{m}\sum_{u=1}^mS_u}^2} &\leq \Ex{\frac{1}{m}\sum_{u=1}^m S_u^2} \\
        &= K_s
    \end{align*}
    Using property 4 of $\calE$, we have $K_s \leq C_s K_f^2$. Thus, substituting the original terms, we have
    \begin{align*}
        \Ex{\paren{\frac{1}{m}\sum_{k=1}^N\sum_{j=1}^m \{U_j^{(f,w_k)}\}_{i^*}}^2} \leq C_s \Ex{\sum_{k=1}^N \{U_u^{(f, w_k)}\}_{i^*}}^2  \tag{g}
    \end{align*}
    Thus, using the fact that $U_j^{(f, w_k)}$ is sampled i.i.d. for a $k \in [N]$, we see that $\Ex{\sum_{k=1}^N \{U_u^{(f, w_k)}\}_{i^*}} = \Ex{\frac{1}{m}\sum_{j=1}^m\sum_{k=1}^N \{U_j^{(f, w_k)}\}_{i^*}}$. Substituting this in the RHS of (g), we get that $M^\calE_m$ satisfies the final property.
\end{proof}

