where $ \ell \in \mathbb{N} $ is given by $\ell:= l.c.m (\ord(rs),\ord(rs^{-1}))$. We define the $ U_{r,s}^+(B_2) $-module structure on $ \mathcal{M}(\nu) $ by defining the actions:
\begin{align*}
    e(a)X_1&=\epsilon_1^2\epsilon_3\epsilon_2^{-1}\displaystyle\frac{1-rs^{-1}}{s^2(r^2-s^2)}s^{-2a}e(a(\oplus2)\\
    e(a)X_2&=\epsilon_1e(a\oplus1)\\
    e(a)X_3&=(rs)^a\epsilon_2e(a)\\
    e(a)X_4&=\epsilon_1^{-1}\epsilon_2\epsilon_3^{-1}\displaystyle\frac{(\epsilon_3\left(rs^{-1})^a-1\right)s^{2a}}{1-rs^{-1}} e(a\oplus(-1)).
\end{align*} where, $\oplus$ denotes the addition modulo $\ell$.
\section{\texorpdfstring{Construction of $X_1$-torsion simple $ U_{r,s}^+(B_2) $-modules}{}}




\subsection{\texorpdfstring{Simple $ U_{r,s}^+(B_2) $-modules of type $ \mathcal{M}(\nu) $}{}}

Let $ \nu = (\nu_1, \nu_2, \nu_3) \in (\mathbb{C}^*)^2 \times \mathbb{C} $. 
Define $ \mathcal{M}(\nu) $ as a vector space with basis  
$$
    \{ e(a, b) \mid 0 \leq a \leq \ell_3 - 1, \ 0 \leq b \leq m_3 - 1 \},
$$  
where $ \ell_3, m_3 \in \mathbb{N} $ are given by  

$$
  \ell_3 := \ord(rs), \quad \text{and}\quad   m_3 := 
    \begin{cases}
        \ord(r^{-2}s^2), & \text{if } o(s^2) \mid \ord(r^{-2}s^2) \ord(rs) \text{ or } \nu_3=0 , \\[5pt]
        2\ord(r^{-2}s^2), & \text{otherwise}.
    \end{cases}
$$

We define the $ U_{r,s}^+(B_2) $-module structure on $ \mathcal{M}(\nu) $ by defining the actions:

 $$ e(a,b)X_1 = 
    \begin{cases}
         -\displaystyle  \displaystyle \displaystyle s^{-4(b-1)}(rs)^2 (1 - r^{-1}s)  
            \frac{1 - (r^{-1}s)^{2b}}{1 - (r^{-1}s)^2} \nu_1^2 e(a\oplus 2,b-1), & b \neq 0, \\[10pt]
        0, & b = 0,
    \end{cases}$$

$$ e(a,b)X_2 = s^{-2b} \nu_1 e(a \oplus 1, b),\quad e(a,b)X_3 = (rs)^{a} \nu_2 e(a, b),$$

$$e(a,b)X_4 = 
    \begin{cases}
         \displaystyle \displaystyle\frac{s^{2b}}{s^{-2} - r^{-1}s^{-1}} \Bigg[ 
             \nu_1^{-1}e(a \oplus (-1), b+1)  
           \\ \quad

          -(rs)^{a-1}\nu_1^{-1}\nu_2 e(a \oplus (-1), b)  
        \Bigg],  
        &  b \neq  m_3 - 1,\\[15pt]
 \displaystyle\frac{s^{2b}}{s^{-2} - r^{-1}s^{-1}} \Bigg[ 
            s^{2(a-1)m_3} \nu_1^{-1} \nu_3e(a \oplus (-1), 0) 
          \\ \quad
          -(rs)^{a-1}  \nu_1^{-1} \nu_2 e(a \oplus (-1), b)  
        \Bigg],  
        & b = m_3 - 1.
    \end{cases}$$

where, $\oplus$ denotes the addition modulo $\ell_3$. We can readily confirm the action above indeed defines an $U_{r,s}^+(B_2)$-module structure on $\mathcal{M}(\nu)$, similarly detailed in the first case.
\begin{theorem}
    $\mathcal{M}(\nu)$ is a simple $U_{r,s}^+(B_2)$-module of dimension $\ell_3m_3$.
\end{theorem}
\begin{proof}
     Observe that $X_2$ acts as an invertible operator on $\mathcal{M}(\nu)$. Then we have the following
    \begin{align*}
        e(a,b)X_3&=(rs)^a\nu_2e(a,b)\\
        e(a,b)X_1WX_2^{-2}&=-(rs)^2(1-r^{-1}s)\displaystyle\frac{1-(r^{-1}s)^{2b}}{1-(r^{-1}s)^2}\nu_1^2e(a,b)\\
        e(a,b)X_2^{\ell_3}&=s^{-2b\ell_3}\nu_1^{\ell_3}e(a,b).
    \end{align*} where $W:=X_3+(s^{-2}-r^{-1}s^{-1})X_2X_4$.
    With this fact the proof is parallel to the proof of Theorem \ref{dim1}.
\end{proof}
\subsection{\texorpdfstring{Simple $ U_{r,s}^+(B_2) $-modules of type $ \mathcal{M}(\xi) $}{}}

Let $ \xi = (\xi_1, \xi_2) \in \mathbb{C}^*\times \mathbb{C} $. 
Define $ \mathcal{M}(\xi) $ as a vector space with basis  
$$
    \{ e(a) \mid 0 \leq a \leq \ell_4 - 1\},
$$  
where $ \ell_4\in \mathbb{N} $ are given by  

$$
  \ell_4 := 
    \begin{cases}
        \text{lcm}(\ord(rs),\ord(rs^{-1})), & \text{if } \xi_2\neq 0 , \\[5pt]
        \ord(rs^{-1}), & \text{if } \xi_2=0,
    \end{cases}
$$

We define the $ U_{r,s}^+(B_2) $-module structure on $ \mathcal{M}(\xi) $ by defining the actions:

 $$ e(a)X_1 = 
    \begin{cases}
       \displaystyle -r^{-2(a-1)}\frac{1 - (rs^{-1})^{a-1}}{1 - rs^{-1}}\frac{1 - (rs^{-1})^a}{1 - (rs^{-1})^2}\xi_1e(a-2), & a \neq 0,1, \\[5pt] 
        0, & a = 0,1,
    \end{cases}$$

$$ e(a)X_2 = 
    \begin{cases}
       \displaystyle (rs)^{-(a-1)}\frac{1 - (rs^{-1})^{a}}{1 - rs^{-1}}\xi_1e(a-1), & a \neq 0, \\[10pt]
        0, & a = 0,
    \end{cases}$$


   $$ e(a)X_3 = (rs)^{-a} \xi_1 e(a),\quad e(a)X_4 = 
    \begin{cases}


        e(a+1),  
        &  a \neq  \ell_4 - 1,\\[15pt]
\xi_2e(0),  
        & a = \ell_4 - 1.
    \end{cases} $$ We can easily check these actions indeed define a $U_{r,s}^{+}(B_2)$-module structure on $\mathcal{M}(\xi)$.
   \begin{thm}
    $\mathcal{M}(\xi) $ is a simple $U_{r,s}^{+}(B_2)$-module of dimension $\ell_4$.
   \end{thm}
\begin{proof}
   Note that 
   \begin{align*}
       e(a)X_3&=(rs)^{-a}\xi_1e(a)\\
       e(a)X_2X_4&=(rs)^{-(a-1)}\displaystyle\frac{1-(rs^{-1})^a}{1-rs^{-1}}\xi_1e(a).
   \end{align*} With these observations the proof is parallel to Theorem \ref{dim1}.
\end{proof}

 \section{\texorpdfstring{Classification of $X_1$-torsion Simple $U_{r,s}^{+}(B_2)$-modules}{}}
 In this section, we fully classify all simple $U_{r,s}^{+}(B_2)$-modules with nilpotent action of $X_1$, under the assumption that $r$ and $s$ are primitive $m$-th and $n$-th roots of unity, respectively. Let $\mathcal{N}$ represent a simple $U_{r,s}^{+}(B_2)$-module with nilpotent action of $X_1$. Note that $X_2^l$ is a central element of $U_{r,s}^{+}(B_2)$ and hence by Schur's lemma acts as a scalar say $\beta$ on $\mathcal{N}$. Depending on whether $\beta$ is zero or nonzero we have the following two cases.\\
 \textbf{Case I:} $\beta \neq 0$. Note that the commuting operators 
 \[X_2^{\ell_3}, \ W^{m_3}, \ X_3\] keep $\ker(X_1)$ invariant. So we choose the common eigenvector $v \in \ker(X_2)$ such that 
 \[vX_2^{\ell_3}=\psi_1v, \ vW^{m_3}=\psi_2v, \ vX_3=\psi_3v\] where $ \ell_3, m_3 \in \mathbb{N} $ are given by  

$$
  \ell_3 := \ord(rs), \quad \text{and}\quad   m_3 := 
    \begin{cases}
        \ord(r^{-2}s^2), & \text{if } o(s^2) \mid \ord(r^{-2}s^2) \ord(rs) , \\[5pt]
        2\ord(r^{-2}s^2), & \text{otherwise}.
    \end{cases}
$$ Note as $\beta \neq 0$, we must have $\psi_1 \neq 0$. Also $\psi_3 \neq 0$. 
 If $\psi_2 \neq 0$, then all the vectors $vX_2^{a}{W}^{b}$ with $0 \leq a \leq \ell_3-1$ and $0 \leq b \leq m_3-1$ are nonzero vectors.\\
If $\psi_2=0$, let $p$ be the smallest integer with $1 \leq p \leq m_3$ such that $v{W}^{p-1}\neq 0$ and $v{W}^p=0$. In this case we claim that $p=\ord(r^{-2}s^{2})$. In fact simplify the equality $\left(v{W}^p\right)X_1=0$ to obtain
\begin{align*}
   0&=v\left((rs)^{-2p}X_1{W}^p-(rs)^2(1-r^{-1}s)\displaystyle\frac{1-(r^{-1}s)^{2p}}{1-r^{-1}s}{W}^{p-1}X_2^{2}\right)\\
   &=-(rs)^2(1-r^{-1}s)\displaystyle\frac{1-(r^{-1}s)^{2p}}{1-r^{-1}s}\left(v{W}^{p-1}X_2^{2}\right). 
\end{align*}
Note $vW^{p-1}\neq 0$ and $X_2$ is invertible. So we must have $1-(r^{-1}s)^{2p}=0$ i.e. $\ord(r^2s^{-2})\mid p$. We claim that $p=\ord(r^{-2}s^2)$. 
\par If $o(s^2) \mid \ord(r^{-2}s^2) \ord(rs)$ then $p=\ord(r^{-2}s^2)$. Otherwise if $p \neq \ord(r^{-2}s^2)$ then the $\mathbb{K}$ linear span $S$ of the vectors \[\{vX_{2}^a{W}^b:0 \leq a \leq \ell_3-1, \ord(r^2s^{-2})\leq b \leq 2\ord(r^2s^{-2})\}\] generates a nonzero submodule of $\mathcal{N}$. Since $\mathcal{N}$ is simple, therefore $S=\mathcal{N}$. In particular $v\in S$ and then $v{W}^{\ord(r^2s^{-2})}=0$, which is a contradiction. Hence we define $$
  \ell_3 := \ord(rs), \quad \text{and}\quad   m_3 := 
    \begin{cases}
        \ord(r^{-2}s^2), & \text{if } o(s^2) \mid \ord(r^{-2}s^2) \ord(rs)\ \text{or} \ \psi_2=0 , \\[5pt]
        2\ord(r^{-2}s^2), & \text{otherwise}.
    \end{cases}$$
    and the above discussion ensures all the vectors $vX_2^{a}{W}^{b}$ with $0 \leq a \leq \ell_3-1$ and $0 \leq b \leq m_3-1$ are nonzero vectors. Let us choose
\[\nu_1:=\psi_1^{\frac{1}{\ell_3}},\ \nu_2:=\psi_3,\ \nu_3:=\psi_2^{\frac{1}{m_3}}\] so that 
$(\nu)=(\nu_1,\nu_2,\nu_3)\in {(\mathbb{C}^*)}^2 \times \mathbb{C}$.  Now define a $\mathbb{K}$-linear map \[\Phi_3:\mathcal{M}(\nu)\rightarrow \mathcal{N}\] by specifying the image of the basis vectors of $\mathcal{M}_2(\mu)$ as follows:
\[\Phi_3\left(e(a,b)\right):=\nu_1^{-a}vX_{2}^a{W}^b,\ \ 0\leq a\leq \ell_3-1, 0 \leq b \leq m_3-1.\] We can easily verify that $\Phi_3$ is a nonzero $U_{r,s}^+(B_2)$-module homomorphism. In this verification the following calculations will be useful
\begin{align*}
    \left(vX_2^aW^b\right)X_1=\begin{cases}
        s^{2(b+2)}(rs)^2(1-r^{-1}s)\displaystyle\frac{1-(r^{-1}s)^{2a}}{1-(r^{-1}s)^2}(vX_2^{a+2}W^{b-1})\ & \ b\neq 0\\
        0, & b=0.
    \end{cases}
\end{align*}
Also for any element $n \in \mathcal{N}$, we have 
\[nX_4:=nX_2^{-1}\frac{W-X_3}{s^{-2}-r^{-1}s^{-1}}\] Thus by Schur's lemma, $\Phi_3$ becomes an $U_{r,s}^+(B_2)$-module isomorphism.\\
\textbf{Case II:} $\beta=0$. Define 
\[l:= lcm \left(\ord(rs), \ord(rs^{-1})\right).\]
Note that the commuting operators \[X_4^l, \ X_3\] keep $\ker(X_1) \cap \ker (X_2)$ invariant. So we choose the common eigenvector $v \in \ker(X_1) \cap \ker (X_2)$ such that 
\[vX_4^l=\phi_1 v, \ vX_3=\phi_2 v\] where $\phi_1, \phi_2 \in \mathbb{C}$. As $\mathcal{N}$ is $X_3$-torsionfree, $\phi_2 \neq 0$.\\
If $\phi_1 \neq 0$, then all the vectors $vX_4^a$ with $0 \leq a \leq l-1$ are all nonzero vectors. If not then let $p$ be the smallest integer with $1 \leq p \leq l$ such that $vX_4^{p-1}\neq 0$ and $vX_4^p=0$. In this case we claim $p=\ord(rs^{-1})$. Simplify the equality $\left(vX_4^p\right)X_2$ to obtain 
\begin{align*}
   0&=v \left(s^{-2p}X_2X_4^p+(rs)^{-(p-1)}\displaystyle\frac{1-(rs^{-1})^p}{1-rs^{-1}}X_3X_4^{p-1}\right)\\
   &=\phi_2(rs)^{-(p-1)}\displaystyle\frac{1-(rs^{-1})^p}{1-rs^{-1}}\left(vX_4^{p-1}\right).
\end{align*}
Hence we must have $1-(rs^{-1})^p=0$ i.e. $\ord(rs^{-1})\mid p$. We claim that $p=\ord(rs^{-1})$. If not, let $p=k\ord(rs^{-1})$ where $2 \leq k \leq \displaystyle\frac{l}{\ord(rs^{-1})}$. Then the $\mathbb{C}$-linear span $S$ of the vectors 
\[\{vX_4^a: 1 \leq a \leq k\ord(rs^{-1})-1\}\]
 generates a nonzero submodule of $\mathcal{N}$. Since $\mathcal{N}$ is simple, $S=\mathcal{N}$. In particular $v \in S$ and then $vX_4^{(k-1)\ord(rs^{-1})}=0$, a contradiction. Hence $p=\ord(rs^{-1})$. Hence we define $ \ell_4\in \mathbb{N} $ such that  

$$
  \ell_4 := 
    \begin{cases}
        \text{lcm}(\ord(rs),\ord(rs^{-1})), & \text{if } \phi_1\neq 0 , \\[5pt]
        \ord(rs^{-1}), & \text{if } \phi_1=0,
    \end{cases}
$$
and the above discussion ensures all the vectors $vX_4^{a}$ with $0 \leq a \leq \ell_4-1$ are nonzero vectors. Let us choose
\[\xi_1:=\phi_2,\ \xi_2:=\phi_1\] so that 
$(\xi)=(\xi_1,\xi_2)\in {(\mathbb{C}^*)} \times \mathbb{C}$.  Now define a $\mathbb{K}$-linear map \[\Phi_4:\mathcal{M}(\xi)\rightarrow \mathcal{N}\] by specifying the image of the basis vectors of $\mathcal{M}(\xi)$ as follows:
\[\Phi_4\left(e(a)\right):=vX_{4}^a,\ \ 0\leq a\leq \ell_4-1.\] We can easily verify that $\Phi_4$ is a nonzero $U_{r,s}^+(B_2)$-module homomorphism. In this verification the following calculations will be useful
\begin{align*}
    \left(vX_4^a\right)X_1&=\begin{cases}
        \displaystyle -r^{-2(a-1)}\frac{1 - (rs^{-1})^{a-1}}{1 - rs^{-1}}\frac{1 - (rs^{-1})^a}{1 - (rs^{-1})^2}\phi_2\left(vX_4^{a-2}\right), & a \neq 0,1, \\[5pt] 
        0, & a = 0,1.
    \end{cases}\\
    \left(vX_4^a\right)X_2&=\begin{cases}
        \displaystyle (rs)^{-(a-1)}\frac{1 - (rs^{-1})^{a}}{1 - rs^{-1}}\phi_2\left(vX_4^{a-1}\right), & a \neq 0, \\[10pt]
        0, & a = 0.
    \end{cases}
\end{align*} Thus by Schur's lemma, $\Phi_4$ becomes an $U_{r,s}^+(B_2)$-module isomorphism.
\section{\texorpdfstring{Isomorphism Clasees of simple $U_{r,s}^+(B_2)$-module}{}}


In this final section, we describe the isomorphism classes of all finite-dimensional simple $ U^+_{r,s}(B_2)$-modules. Using the classification results of previous sections for both $ X_1 $-torsionfree and $ X_1 $-torsion modules, we determine the parameters that distinguish non-isomorphic modules. We identify conditions under which two simple modules, possibly arising from different constructions, are isomorphic. The analysis shows that the parameter spaces involved are disjoint in most cases, ensuring a clear separation of module types. As a consequence, we confirm that our classification is complete and each simple module corresponds uniquely to a parameter tuple up to suitable equivalence.

\begin{thm}\label{1stIso}
    Let $\lambda$ and $\lambda'$ be in $(\mathbb{C}^*)^3 \times \mathbb{C}$. Then $M(\lambda)$ is isomorphic to $M(\lambda')$ as $U_{r,s}^+(B_2)$-module if and only if 
    \begin{align*}
    \lambda_1^{\ell_1}=s^{-2v\ell_1}&(\lambda_1')^{\ell_1}, \ \lambda_2^{m_1}=s^{2um_1}(\lambda_2')^{m_1}, \ \lambda_3=(rs)^u(rs^{-1})^v\lambda_3'\\
    \lambda_4&=(rs)^{2u}\left(\lambda_4'-s^2(r^2-s^2)\displaystyle\frac{1-(rs^{-1})^v}{1-rs^{-1}}\lambda_3'\right)
\end{align*} holds for some $0 \leq u \leq \ell_1-1$ and $0 \leq v \leq m_1-1$.
\end{thm}
\begin{proof}
Let $M(\lambda)$ and $M(\lambda')$ be two $U_{r,s}^+(B_2)$-modules. Suppose there exists an isomorphism $\phi : M(\lambda) \to M(\lambda')$. Assume that
\[
\phi(e(0,0)) = \sum J_{u,v} \, e(u,v),
\]
where the sum is finite and at least one coefficient $J_{u,v}$ lies in $\mathbb{C}^*$.

Suppose, for contradiction, that there are two distinct pairs $(u,v) \neq (u',v')$ such that both $J_{u,v}$ and $J_{u',v'}$ are nonzero. Then we have
\begin{align*}
   \phi(e{(0,0)} X_3 X_1)& = \phi(e{(0,0)}) X_3 X_1 \\
   \phi(e{(0,0)} \tilde{W}X_2) &= \phi(e{(0,0)}) \tilde{W}X_2, \\ \phi(e{(0,0)}X_2^{m_1})& = \phi(e_{(0,0)}) X_2^{m_1}. 
\end{align*}

By comparing the coefficients of the basis elements on both sides of these identities, we derive the following
\begin{align*}
    (rs)^{2u}(rs^{-1})^v \lambda_3'&=(rs)^{2u'}(rs^{-1})^{v'} \lambda_3'\\
        (rs)^{2u}\left(\lambda_4-s^2(r^2-s^2)\displaystyle\frac{1-(rs^{-1})^v}{1-rs^{-1}}\lambda_3\right)&=(rs)^{2u'}\left(\lambda_4-s^2(r^2-s^2)\displaystyle\frac{1-(rs^{-1})^{v'}}{1-rs^{-1}}\lambda_3\right)\\
        s^{2um_1}\lambda_2^{m_1}&=s^{2u'm_1}\lambda_2^{m_1}.
\end{align*}
In particular, this leads to the congruences $u \equiv u' (\mod \ell_1)$ and $v \equiv v' (\mod m_1)$, which contradict our earlier assumption that $(u,v) \neq (u',v')$.

Hence, we conclude that
\[
\phi(e{(0,0)}) = J_{u,v} \, e{(u,v)}
\]
for some unique pair $(u,v)$ and some scalar $J_{u,v} \in \mathbb{C}^*$.

This observation allows us to deduce relations among the scalars that appear in the module action. Let us consider the actions of $X_1^{\ell_1}$, $X_2^{m_1}$, $X_3X_1$, $\tilde{W}X_2$ on the basis elements under the isomorphism $\phi$ to obtain
\begin{align*}
    \lambda_1^{\ell_1}=s^{-2v\ell_1}&(\lambda_1')^{\ell_1}, \ \lambda_2^{m_1}=s^{2um_1}(\lambda_2')^{m_1}, \ \lambda_3=(rs)^u(rs^{-1})^v\lambda_3'\\
    \lambda_4&=(rs)^{2u}\left(\lambda_4'-s^2(r^2-s^2)\displaystyle\frac{1-(rs^{-1})^v}{1-rs^{-1}}\lambda_3'\right)
\end{align*}
Conversely, assume that the relations between $\lambda$ and $\lambda'$ hold. Then the map $\tilde{\psi}:M(\lambda)\rightarrow M(\lambda')$ defined by
\[\tilde{\psi}\left(e(a,b)\right))=\begin{cases}
(\lambda_1^{-1}\lambda_1')^a(\lambda_2^{-1}\lambda_2')^bs^{-2av}e(a\oplus u,b+v), & 0 \leq b \leq m_1-v-1\\
(\lambda_1^{-1}\lambda_1')^a(\lambda_2^{-1}\lambda_2')^bs^{-2av}s^{2(a \oplus u)m_1}e(a\oplus u,b+v), & m_1-v \leq b \leq m_1-1   
\end{cases}\]
\end{proof}
\begin{theorem}\label{2ndIso}
    Let $\mu$ and $\mu'$ be in $(\mathbb{C}^*)^2 \times \mathbb{C}$. Then $M(\mu)$ is isomorphic to $M(\mu')$ as $U_{r,s}^+(B_2)$-module if and only if 
\[\mu_1^{\ell_2}=r^{-2v\ell_2}(\mu_1')^{\ell_2},\ \mu_2=(rs)^{2u+v}\mu_2',\ \mu_3=r^{2um_2}\mu_3'\] for some $u,v$ such that $0 \leq u \leq \ell_2-1$ and either $v=0$ or $v=\ord(rs^{-1})$.
\end{theorem}
\begin{proof}
    Using similar argument as in Theorem \ref{1stIso} we can show that any isomorphism $\tilde{\psi}: M(\mu) \rightarrow M(\mu')$ is characterized by $e(0,0)$ and $\tilde{\psi}\left(e(0,0)\right)=J_{u,v}e(u,v)$ for some $J_{u,v}\in \mathbb{C}^*$. We can simplify the equality $\tilde{\psi}(e(0,0)X_2)=\tilde{\psi}(e(0,0))X_2$ to obtain $0=J_{u,v}e(u,v)X_2$ which imply either $v=0$ or 
    \[0=(rs)^{2u}s^2(r^2-s^2)\displaystyle\frac{1-(r^{-1}s)^v}{1-r^{-1}s}\mu_2'\] i.e. $v=\ord(r^{-1}s)$. Then the actions of $X_1^{\ell_2}, \ X_3X_1$ and $\tilde{W}^{m_2}$ under $\tilde{\psi}$ provide the required relations between $\mu$ and $\mu'$. 
    \par Conversely, assume that the relations between $\mu$ and $\mu'$ hold. Then the map $\tilde{\psi}:M(\mu)\rightarrow M(\mu')$ defined by
\[\tilde{\psi}\left(e(a,b)\right))=\begin{cases}
(\mu_1^{-1}\mu_1')^a r^{-2bv}e(a\oplus u,b+v), & 0 \leq b \leq m_2-v-1\\
(\mu_1^{-1}\mu_1')^a r^{-2bv}r^{2(a \oplus u)m_2}e(a\oplus u,b+v), & m_2-v \leq b \leq m_1-1   
\end{cases}\]
\end{proof}
\begin{thm}
 Let   $ \epsilon = (\epsilon_1, \epsilon_2, \epsilon_3)$ and $  \epsilon' = (\epsilon_1', \epsilon_2', \epsilon_3')  \in (\mathbb{C}^*)^3$. Then $M(\epsilon)$ is isomorphic to $M(\epsilon')$ as $U_{r,s}^+(B_2)$-module if and only if 
 \[\epsilon_1^{\ell}=(\epsilon_1')^{\ell}, \ \epsilon_2=(rs)^u(\epsilon_2)', \ \epsilon_3=(rs^{-1})^u\epsilon_3'\] for some $u$ such that $0 \leq u \leq \ell-1$.
\end{thm}
\begin{proof}
    Same as Theorem \ref{1stIso}.
\end{proof}
\begin{theorem}
    Let $ \nu = (\nu_1, \nu_2, \nu_3)$ and $ \nu' = (\nu_1', \nu_2', \nu_3')\in (\mathbb{C}^*)^2 \times \mathbb{C} $. Then $M(\nu)$ is isomorphic to $M(\nu')$ as $U_{r,s}^+(B_2)$-module if and only if 
    \[\nu_1^{\ell_3}=s^{-2v\ell_3}(\nu_1')^{\ell_3}, \ \nu_2=(rs)^v\nu_2', \ \nu_3=s^{2um_3}\nu_3'\] for some $u$ such that $0 \leq u \leq \ell_3-1$ and $v$ such that either $v=0$ or $v=\ord(r^{-2}s^2)$.
\end{theorem}
\begin{proof}
    Same as Theorem \ref{2ndIso}.
\end{proof}
\begin{theorem}
    Let $ \xi = (\xi_1, \xi_2)$ and $ \xi' = (\xi_1', \xi_2')\in \mathbb{C}^*\times \mathbb{C} $. Then $M(\xi)$ is isomorphic to $M(\xi')$ as $U_{r,s}^+(B_2)$-module if and only if
    \[\xi_1=(rs)^{-u}\xi_1', \ \xi_2=\xi_2'\] holds for some $u$ with $0 \leq u \leq \ell_4-1$ and $u$ is a multiple of $\ord(rs^{-1})$.
\end{theorem}
\begin{proof}
    Same as Theorem \ref{2ndIso}.
\end{proof}
