Now, referring to the rules of Fig. \ref{propositional pi} for axiomatic $\Pi$-types \& axiomatic function extensionality, we give the following:

\begin{definition}[Semantics of axiomatic $\Pi$-types \& axiomatic function extensionality---syntactic formulation]\label{def:Semantics of axiomatic Pi-types}
    Let $(\mathbf{C},\mathcal{D})$ be a display map category endowed with axiomatic $=$-types.

\medskip

    Let us assume that, for every object $\Gamma$, every display map $P_A$ of codomain $\Gamma$, and every display map $P_B$ of codomain $\Gamma.A$, there is a choice of:
    \begin{itemize}
        \item[$\succ$] (\textit{Form Rule}) a display map $\Gamma.\pid_A^B\to\Gamma$;
        \item[$\succ$] (\textit{Elim Rule}) a section: $$\ev_A^B:\Gamma.\pid_A^B.A[P_{\pid_A^B}]\to \Gamma.\pid_A^B.A[P_{\pid_A^B}].B[P_{\pid_A^B}^\lilbullet]$$ of the display map $\Gamma.\pid_A^B.A[P_{\pid_A^B}].B[P_{\pid_A^B}^\lilbullet]\to\Gamma.\pid_A^B.A[P_{\pid_A^B}]$;
    \end{itemize} and that, for every object $\Gamma$, every display map $P_A$ of codomain $\Gamma$, every display map $P_B$ of codomain $\Gamma.A$, and every section $\upsilon:\Gamma.A\to\Gamma.A.B$ of $P_B$ there is a choice of:
    \begin{itemize}
        \item[$\succ$] (\textit{Intro Rule}) a section: $$\abst{\upsilon} : \Gamma\to\Gamma.\pid_A^B$$ of the display map $\Gamma.\pid_A^B\to\Gamma$;
        \item[$\succ$] (\textit{Comp Axiom}) a section: $$\beta_\upsilon:\Gamma.A\to\Gamma.A.\id_{B}[\ev_A^B[\abst{\upsilon}^\lilbullet];\upsilon]$$ of the display map $\Gamma.A.\id_{B}[\ev_A^B[\abst{\upsilon}^\lilbullet];\upsilon]\to\Gamma.A$, where the arrow: $$\ev_A^B[\abst{\upsilon}^\lilbullet];\upsilon: \Gamma.A\to\Gamma.A.B.B^\liltriangle$$ is built as explained in Subsection \ref{subsection:Encoding parallel terms into a substitution}.
    \end{itemize} Moreover, let us assume that the following \textit{stability conditions}: $$\begin{alignedat}{2}
        \pid_A^B[f]&=\pid_{A[f]}^{B[f^\lilbullet]}&\quad\quad\abst{\upsilon}[f]&=\abst{\upsilon[f^{\lilbullet}]}\\
        \ev_A^B[f^{\lilbullet\lilbullet}]&=\ev_{A[f]}^{B[f^\lilbullet]}&\beta_\upsilon[f^{\lilbullet}]&=\beta_{\upsilon[f^{\lilbullet}]}\\
    \end{alignedat}$$ hold\footnotemark[1] for every arrow $f:\Delta\to\Gamma$.

    \noindent Then we say that $(\mathbf{C},\mathcal{D})$ is \textit{endowed with axiomatic $\Pi$-types}.

\medskip

    Additionally, let us assume that, for every object $\Gamma$, every display map $P_A$ of codomain $\Gamma$, every display map $P_B$ of codomain $\Gamma.A$, and every pair of sections $z,z'$ of $P_{\pid_A^B}$, there is a choice of:\begin{itemize}
        \item[$\succ$] (\textit{Intro Rule}) a section: $$\funext_q:\Gamma\to\Gamma.\id_{\pid_A^B}[z;z']$$ of the display map $\Gamma.A.\id_{\pid_A^B}[z;z']\to\Gamma.A$ for every section: $$q:\Gamma\to \Gamma.\pid_A^{\id_B[\ev_A^B[z^\lilbullet];\ev_A^B[z'^\lilbullet]]}$$ of the display map $\Gamma.\pid_A^{\id_B[\ev_A^B[z^\lilbullet];\ev_A^B[z'^\lilbullet]]}\to\Gamma$;
        \item[$\succ$] (\textit{Comp Axiom}) a section: $$\beta^\Pi_q:\Gamma\to\Gamma.\id_{\pid_A^{\id_B[\ev_A^B[z^\lilbullet];\ev_A^B[z'^\lilbullet]]}}[\;\happly_{z;z'}[\funext_q]\;;\;q\;]$$ of the display map $\Gamma.\id_{\pid_A^{\id_B[\ev_A^B[z^\lilbullet];\ev_A^B[z'^\lilbullet]]}}[\;\happly_{z;z'}[\funext_q]\;;\;q\;]\to\Gamma$ for every section: $$q:\Gamma\to \Gamma.\pid_A^{\id_B[\ev_A^B[z^\lilbullet];\ev_A^B[z'^\lilbullet]]}$$ of the display map $\Gamma.\pid_A^{\id_B[\ev_A^B[z^\lilbullet];\ev_A^B[z'^\lilbullet]]}\to\Gamma$;
        \item[$\succ$] (\textit{Exp Axiom}) a section: $$\eta^\Pi_p:\Gamma\to\Gamma.\id_{\id_{\pid_A^B}[z;z']}[\;p\;;\;\funext_{\happly_{z;z'}[p]}\;]$$ of the display map $\Gamma\to\Gamma.\id_{\id_{\pid_A^B}[z;z']}[\;p\;;\;\funext_{\happly_{z;z'}[p]}\;]$ for every section: $$p:\Gamma\to\Gamma.\id_{\pid_A^B}[z;z']$$ of the display map $\Gamma.\id_{\pid_A^B}[z;z']\to\Gamma$;
    \end{itemize} where:\begin{itemize}
        \item[$\succ$] $\mathsf{s}$ and $\mathsf{t}$ are $P_{(\pid_A^B)^\liltriangle}P_{\id_{\pid_A^B}}$ and $P_{\pid_A^B}^\lilbullet P_{\id_{\pid_A^B}}$ respectively;
        \item[$\succ$] the section: $$\happly:\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}\to\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}.\pid_{A[P_{\pid_A^B}\mathsf{s}]}^{\id_{B[(P_{\pid_A^B}\mathsf{s})^\lilbullet]}[\ev_A^B[\mathsf{s}^\lilbullet],\ev_A^B[\mathsf{t}^\lilbullet]]}$$ of the display map $\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}.\pid_{A[P_{\pid_A^B}\mathsf{s}]}^{\id_{B[(P_{\pid_A^B}\mathsf{s})^\lilbullet]}[\ev_A^B[\mathsf{s}^\lilbullet],\ev_A^B[\mathsf{t}^\lilbullet]]}\to\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}$ is defined in \Cref{howtohapply};
        \item[$\succ$] and $\happly_{z;z'}$ is $\happly[(z;z')^\lilbullet]$.
    \end{itemize} Moreover, let us assume that the following \textit{stability conditions}: $$\begin{aligned}
    \funext_q[f]&=\funext_{q[f]}\\
    \beta^\Pi_q[f]&=\beta^\Pi_{q[f]}\\
    \eta^\Pi_q[f]&=\eta^\Pi_{q[f]}
    \end{aligned}$$ hold\footnotemark[1] for every arrow $f:\Delta\to\Gamma$.

    \noindent Then we say that $(\mathbf{C},\mathcal{D})$ is \textit{endowed with axiomatic $\Pi$-types \& axiomatic function extensionality}.
\end{definition}

\begin{remark}\label{howtohapply} Let $\mathsf{s}$ and $\mathsf{t}$ be the arrows: $$P_{(\pid_A^B)^\liltriangle}P_{\id_{\pid_A^B}} \quad\quad\text{and}\quad\quad P_{\pid_A^B}^\lilbullet P_{\id_{\pid_A^B}}$$ respectively. By using the \textit{stability conditions} and the commutativity of Diagram (\ref{reindexingprimareindexingdopo}), the re-indexing of the display map: $$\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}.\pid_{A[P_{\pid_A^B}\mathsf{s}]}^{\id_{B[(P_{\pid_A^B}\mathsf{s})^\lilbullet]}[\ev_A^B[\mathsf{s}^\lilbullet],\ev_A^B[\mathsf{t}^\lilbullet]]}\to\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}$$ via the arrow $\refl_{\pid_A^B}:\Gamma.\pid_A^B\to\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}$ is proven to be the display map: $$\Gamma.\pid_A^B.\pid_{A[P_{\pid_A^B}]}^{\id_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B;\ev_A^B]}\to\Gamma.\pid_A^B\;\;.$$ Now, if we build a section $c$ of the latter display map, then a section $\happly$ of the former display map can be defined as $\j_c$. Additionally, if we build a section $\upsilon$ of the display map: $$\Gamma.\pid_A^B.{A[P_{\pid_A^B}]}.{\id_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B;\ev_A^B]}\to\Gamma.\pid_A^B.{A[P_{\pid_A^B}]}$$ then $c$ can be defined as $\abst{\upsilon}$. Finally, we define $\upsilon$ as the unique section $\refl_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B]$ of this display map that makes the diagram: % https://q.uiver.app/#
\[\begin{tikzcd}
	{\Gamma.\pid_A^B.{A[P_{\pid_A^B}]}} && {\Gamma.\pid_A^B.{A[P_{\pid_A^B}]}.{\id_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B;\ev_A^B]}} \\
	\\
	{\Gamma.\pid_A^B.{A[P_{\pid_A^B}]}.B[P_{\pid_A^B}^\lilbullet]} && {\Gamma.\pid_A^B.{A[P_{\pid_A^B}]}.B[P_{\pid_A^B}^\lilbullet].B[P_{\pid_A^B}^\lilbullet]^\liltriangle.\id_{B[P_{\pid_A^B}^\lilbullet]}}
	\arrow[from=1-1, to=1-3]
	\arrow["{\ev_A^B}"{description}, from=1-1, to=3-1]
	\arrow["{(\ev_A^B;\ev_A^B)^\liltriangle}"{description}, from=1-3, to=3-3]
	\arrow["{\refl_{B[P_{\pid_A^B}^\lilbullet]}}", from=3-1, to=3-3]
\end{tikzcd}\] commute. Summarising, the section $\happly$ is defined as: $$\j_{\abst{\refl_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B]}}$$ and it is the interpretation of the term judgement of type $\Pi_{x:A}^{\ev(z,x)=\ev(z',x)}$ in context: $$\judgectx{z,z':\Pi_{x:A}B(x);\;p:z=z'}$$ obtained by elimination via the term judgement $\judge{z:\Pi_{x:A}B(x)}{\lambda x.\refl(\ev(z,x))}$.

Now, by using again the \textit{stability conditions} and the commutativity of Diagram (\ref{reindexingprimareindexingdopo}), the re-indexing of the display map: $$\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}.\pid_{A[P_{\pid_A^B}\mathsf{s}]}^{\id_{B[(P_{\pid_A^B}\mathsf{s})^\lilbullet]}[\ev_A^B[\mathsf{s}^\lilbullet],\ev_A^B[\mathsf{t}^\lilbullet]]}\to\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}$$ via the arrow $(z;z')^\lilbullet p:\Gamma.\pid_A^B\to\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}$---for some section: $p:\Gamma\to\Gamma.\id_{\pid_A^B}[z;z']$ of the display map $\Gamma.\id_{\pid_A^B}[z;z']\to\Gamma$---is proven to be the display map: $$\Gamma.\pid_A^{\id_B[\ev_A^B[z^\lilbullet];\ev_A^B[z'^\lilbullet]]}\to\Gamma\;\;$$ hence $\happly_{z;z'}[p]$ is a section of this display map.

\end{remark}

