\\
\text{Intro Rule\,}&\inferrule{\;\;\quad\quad\quad\text{ }\quad\quad\quad\;\;}{\bot:2\\\\\top:2}&\quad\text{Comp Axiom\,}&\inferrule{\judge{x:2}{C(x):\type}\\\\\quad\; c:C(\bot)\\d:C(\top) \quad\;}{\beta^2_\bot(c,d):\ind^2(c,d,\bot)=c\\\\\beta^2_\top(c,d):\ind^2(c,d,\top)=d}\\
