\end{tikzcd}\hspace{-0.4em}{.C[\pair_A^B]}\] such that $P_{C[\pair_A^B]}*s_c= 1_{1_{\Gamma.A.B}}$ and $(\splitt_c\pair_A^B\Rightarrow(\pair_A^B)^\lilbullet c)=(\pair_A^B)^\lilbullet * s_c$. As for the paragraph \textbf{Comp Axiom for $\boldsymbol{=}$-types}, we define $\sigma_c$ as the unique section: $$\{s_c\}:\Gamma.A.B\to\Gamma.A.B.\id_{C[\pair_A^B]}[\splitt_c[\pair_A^B];c]$$ of $P_{\id_{C[\pair_A^B]}[\splitt_c[\pair_A^B];c]}$ such that (\ref{whatcharacterisescurlyparentheses}) is satisfied---where $A$ is $C[\pair_A^B]$, $a$ and $b$ are $\splitt_c[\pair_A^B]$ and $c$ respectively, and $p$ is $s_c$.



\begin{proposition}\label{stability of sigma in 2d model}
    Let $(\boldsymbol{\mathcal{C}},\mathcal{D})$ be a display map 2-category endowed with axiomatic $=$-types and axiomatic $\Sigma$-types. Referring to the data defined in paragraphs \emph{\textbf{Form Rule, Intro Rule, Elim Rule, and Comp Axiom, for $\boldsymbol{\Sigma}$-types}}, the \emph{stability conditions}: $$\begin{alignedat}{2}
        \sigmad_A^B[f]&=\sigmad_{A[f]}^{B[f^\lilbullet]}&\quad\quad\splitt_c[f^\lilbullet]&=\splitt_{c[f^{\lilbullet\lilbullet}]}\\
        \pairing_A^B[f^{\lilbullet\lilbullet}]&=\pairing_{A[f]}^{B[f^\lilbullet]}&\sigma_c[f^{\lilbullet\lilbullet}]&=\sigma_{c[f^{\lilbullet\lilbullet}]}\\
    \end{alignedat}$$ of Defintion \ref{def:Semantics of axiomatic Sigma-types} hold for every arrow $\Delta \xrightarrow{f}\Gamma$.

\proof
See Appendix \ref{appendixIII}.
\endproof
\end{proposition}

\subsection{Axiomatic $\boldsymbol{\Pi}$-types}

We specialise the notion of a display map 2-category with axiomatic $=$-types to obtain a version that incorporates a 2-dimensional semantic interpretation of axiomatic $\Pi$-types \& axiomatic function extensionality. Again, the condition we require to be satisfied is a generalisation of the condition characterising the semantics of extensional $\Pi$-types: right adjoints \cite{MR1674451} are demoted to right biadjoints. In particular, we observe the same difference between the intensional case \cite{MR2525957} and the axiomatic one, that we observed for $\Sigma$-types: such a right biadjoint need not be a retract right biadjoint.

\begin{definition}[Semantics of axiomatic $\Pi$-types \& axiomatic function extensionality---categorical formulation]\label{def:Categorical semantics of axiomatic Pi-types}
    Let $(\boldsymbol{\mathcal{C}},\mathcal{D})$ be a display map 2-category endowed with axiomatic $=$-types.

    Let us assume that, for every object $\Gamma$, every display map $P_A$ of codomain $\Gamma$, and every display map $P_B$ of codomain $\Gamma.A$, there is a choice of a display map $\Gamma.\pid_A^B\to\Gamma$ in such a way that: $$\Pi_A^B[f]=\Pi_{A[f]}^{B[f^\lilbullet]}$$ for every arrow $f:\Delta\to\Gamma$, and in such a way that the assignment: $$\begin{aligned}
        \mathcal{D}/\Gamma.A &\to \boldsymbol{\mathcal{C}}/\Gamma\\
        P_B&\mapsto P_{\pid_A^B}
    \end{aligned}$$ constitutes a right $I_A$-relative 2-coadjoint to the 2-functor: $$\begin{aligned}
        \boldsymbol{\mathcal{C}}/\Gamma &\to \boldsymbol{\mathcal{C}}/\Gamma.A\\
        f&\mapsto f^\lilbullet
    \end{aligned}$$ where $I_A$ is the full forgetful 2-functor $\mathcal{D}/\Gamma.A\hookrightarrow\boldsymbol{\mathcal{C}}/\Gamma.A$.

    Unfolding this requirement, this means that there is a family of equivalences of categories: $$(\lambda_A^B,\app_A^B,\app_A^B\lambda_A^B\overset{\beta^{A,B}}{\Longrightarrow}1,1\overset{\eta^{A,B}}{\Longrightarrow}\lambda_A^B\app_A^B):(\boldsymbol{\mathcal{C}}/\Gamma.A)(f^\lilbullet,P_B)\simeq (\boldsymbol{\mathcal{C}}/\Gamma)(f,P_{\pid_A^B})$$ 2-natural in $f:\Delta\to\Gamma$ and $P_B$---which means that the diagrams of 1-functors: % https://q.uiver.app/#
\[\begin{tikzcd}[column sep=tiny]
	{(\boldsymbol{\mathcal{C}}/\Gamma.A)(f^\lilbullet,P_B)} && {(\boldsymbol{\mathcal{C}}/\Gamma)(f,P_{\pid_A^B})} & {(\boldsymbol{\mathcal{C}}/\Gamma.A)(f^\lilbullet,P_B)} && {(\boldsymbol{\mathcal{C}}/\Gamma)(f,P_{\pid_A^B})} \\
	\\
	{(\boldsymbol{\mathcal{C}}/\Gamma.A)((fg)^\lilbullet,P_B)} && {(\boldsymbol{\mathcal{C}}/\Gamma)(fg,P_{\pid_A^B})} & {(\boldsymbol{\mathcal{C}}/\Delta.A[f])(1_{\Delta}^\lilbullet,P_{B[f^\lilbullet]})} && {(\boldsymbol{\mathcal{C}}/\Delta)(1_\Delta,P_{\pid_{A[f]}^{B[f^\lilbullet]}})}
	\arrow["{\lambda_A^B}", shift left, from=1-1, to=1-3]
	\arrow["{(\blank)(g^\lilbullet)}"{description}, from=1-1, to=3-1]
	\arrow["{\app_A^B}", shift left, from=1-3, to=1-1]
	\arrow["{(\blank)(g)}"{description}, from=1-3, to=3-3]
	\arrow["{\lambda_A^B}", shift left, from=1-4, to=1-6]
	\arrow["{1_{\Delta.A[f]};\blank}"{description}, from=1-4, to=3-4]
	\arrow["{\app_A^B}", shift left, from=1-6, to=1-4]
	\arrow["{1_{\Delta};\blank}"{description}, from=1-6, to=3-6]
	\arrow["{\lambda_A^B}", shift left, from=3-1, to=3-3]
	\arrow["{\app_A^B}", shift left, from=3-3, to=3-1]
	\arrow["{\lambda_{A[f]}^{B[f.A]}}", shift left, from=3-4, to=3-6]
	\arrow["{\app_{A[f]}^{B[f.A]}}", shift left, from=3-6, to=3-4]
\end{tikzcd}\] commute and the equalities: $$\begin{alignedat}{2}
        \beta^{A,B}_h g^\lilbullet&=\beta^{A,B}_{hg^\lilbullet}&\quad\quad\quad\quad\quad\quad\quad\quad1_{\Delta.A[f]};\beta^{A,B}_h&=\beta^{A[f],B[f.A]}_{1_\Delta.A[f];h}\\
        \eta^{A,B}_kg&=\eta^{A,B}_{kg}&1_\Delta;\eta^{A,B}_k&=\eta^{A[f],B[f.A]}_{1_\Delta;k}\\
    \end{alignedat}$$ hold, for every $g:\Delta'\to\Delta$, every $h:f^\lilbullet\to P_B$, and every $k:f\to P_{\pid_A^B}$.

    Then we say that $(\boldsymbol{\mathcal{C}},\mathcal{D})$ is \textit{endowed with axiomatic $\Pi$-types \& axiomatic function extensionality}.
\end{definition}

Let $(\boldsymbol{\mathcal{C}},\mathcal{D})$ be a display map 2-category endowed with axiomatic $=$-types.

Let us assume that the display map 2-category $(\boldsymbol{\mathcal{C}},\mathcal{D})$ is endowed with axiomatic $\Pi$-types \& axiomatic function extensionality---Definition \ref{def:Categorical semantics of axiomatic Pi-types}---let $P_A$ be a display map of codomain $\Gamma$ and let $P_B$ be a display map of codomain $\Gamma.A$. The next paragraphs show that the display map category $(\mathbf{C},\mathcal{D})$ induced by $(\boldsymbol{\mathcal{C}},\mathcal{D})$ is endowed with appropriate choice functions validating axiomatic $\Pi$-types \& axiomatic function extensionality---as in Definition \ref{def:Semantics of axiomatic Pi-types}.

\medskip

\noindent\textbf{Form Rule for $\boldsymbol{\Pi}$-types.} We already have a choice of a display map $\Gamma.\Pi_A^B\to\Gamma$.


\medskip

\noindent\textbf{Elim Rule for $\boldsymbol{\Pi}$-types.} The diagram:% https://q.uiver.app/#
\[\begin{tikzcd}
	{(\boldsymbol{\mathcal{C}}/\Gamma.A)(P_{\pid_A^B}^\lilbullet,P_B)} && {(\boldsymbol{\mathcal{C}}/\Gamma)(P_{\pid_A^B},P_{\pid_A^B})} \\
	\\
	{(\boldsymbol{\mathcal{C}}/\Gamma.\pid_A^B.A[P_{\pid_A^B}])(1_{\Gamma.\pid_A^B}^\lilbullet,P_{B[P_{\pid_A^B}^\lilbullet]})} && {(\boldsymbol{\mathcal{C}}/\Gamma.\pid_A^B)(1_{\Gamma.\pid_A^B},P_{{\pid_{A}^{B}}^\liltriangle)}}
	\arrow["{1_{\Gamma.\pid_A^B.A[P_{\pid_A^B}]};\blank}"{description}, from=1-1, to=3-1]
	\arrow["{\app_A^B}"', from=1-3, to=1-1]
	\arrow["{1_{\Gamma.\pid_A^B};\blank}"{description}, from=1-3, to=3-3]
	\arrow["{\app_{A[P_{\pid_A^B}]}^{B[P_{\pid_A^B}^\lilbullet]}}", from=3-3, to=3-1]
\end{tikzcd}\] commutes---observe that ${\pid_A^B}^\liltriangle=\pid_{A}^{B}[P_{\pid_A^B}]=\pid_{A[P_{\pid_A^B}]}^{B[P_{\pid_A^B}^\lilbullet]}$. Hence we may define $\ev_A^B$ as the section: $$\app_{A[P_{\pid_A^B}]}^{B[P_{\pid_A^B}^\lilbullet]}\delta_{\pid_A^B}=\app_{A[P_{\pid_A^B}]}^{B[P_{\pid_A^B}^\lilbullet]}(1_{\Gamma.\pid_A^B};1_{\Gamma.\pid_A^B})=1_{\Gamma.\pid_A^B.A[P_{\pid_A^B}]};\app_A^B1_{\Gamma.\pid_A^B}$$ of $P_{B[P_{\pid_A^B}^\lilbullet]}$.

\medskip

\noindent\textbf{Intro Rule for $\boldsymbol{\Pi}$-types.} If $\upsilon$ is a section of $P_B$ then we define the section $\abst{\upsilon}$ of $P_{\pid_A^B}$ as the image of $\upsilon$ via the map $\lambda_A^B:(\boldsymbol{\mathcal{C}}/\Gamma.A)(1_{\Gamma.A},P_B)\to(\boldsymbol{\mathcal{C}}/\Gamma)(1_\Gamma,P_{\pid_A^B})$.

\medskip

\noindent\textbf{Comp Axiom for $\boldsymbol{\Pi}$-types.} We observe that: $$\ev_A^B[\abst{\upsilon}^\lilbullet]=P_{\pid_A^B}^{\lilbullet\lilbullet}\ev_A^B\abst{\upsilon}^\lilbullet$$ because the diagram:
% https://q.uiver.app/#
\[\begin{tikzcd}[column sep=small]
	{\Gamma.A} & {\Gamma.\pid_A^B.A[P_{\pid_A^B}]} \\
	{\Gamma.A.B} & {\Gamma.\pid_A^B.A[P_{\pid_A^B}].B[P_{\pid_A^B}^\lilbullet]} \\
	&& {\Gamma.A.B}
	\arrow["{z^\lilbullet}", from=1-1, to=1-2]
	\arrow["{\ev_A^B[z^\lilbullet]}"', from=1-1, to=2-1]
	\arrow["{\ev_A^B}", from=1-2, to=2-2]
	\arrow["{z^{\lilbullet\lilbullet}}", from=2-1, to=2-2]
	\arrow[curve={height=12pt}, equals, from=2-1, to=3-3]
	\arrow["{P_{\pid_A^B}^{\lilbullet\lilbullet}}"{description}, from=2-2, to=3-3]
\end{tikzcd}\]
commutes for every section $z$ of $P_{\pid_A^B}$. Hence: $$\begin{aligned}
    \ev_A^B[z^\lilbullet]&=P_{\pid_A^B}^{\lilbullet\lilbullet}\ev_A^Bz^\lilbullet\\
    &=P_{\pid_A^B}^{\lilbullet\lilbullet}(1_{\Gamma.\pid_A^B.A[P_{\pid_A^B}]};\app_A^B1_{\Gamma.\pid_A^B})z^\lilbullet\\
    &=(\app_A^B1_{\Gamma.\pid_A^B})z^\lilbullet\\
    &=\app_A^B(1_{\Gamma.\pid_A^B}z)\\
    &=\app_A^Bz
\end{aligned}$$ that is: \begin{equation}\label{evèapp}
    \ev_A^B[z^\lilbullet]=\app_A^Bz
\end{equation} for every section $z$ of $P_{\pid_A^B}$. In particular: $$\ev_A^B[\abst{\upsilon}^\lilbullet]=\app_A^B\abst{\upsilon}=\app_A^B\lambda_A^B\upsilon$$ and therefore $\beta^{A,B}_\upsilon$ is a morphism: $$\ev_A^B[\abst{\upsilon}^\lilbullet]\Rightarrow\upsilon$$ in the category $(\boldsymbol{\mathcal{C}}/\Gamma.A)(1_{\Gamma.A},P_B)$ of the sections of $P_B$. As for the paragraphs \textbf{Comp Axiom for $\boldsymbol{=}$-types} and \textbf{Comp Axiom for $\boldsymbol{\Sigma}$-types}, we define $\beta_\upsilon$ as the unique section: $$\{\beta^{A,B}_\upsilon\}:\Gamma.A\to\Gamma.A.\id_{B}[\ev_A^B[\abst{\upsilon}^\lilbullet];\upsilon]$$ of $P_{\id_{B}[\ev_A^B[\abst{\upsilon}^\lilbullet];\upsilon]}$ such that (\ref{whatcharacterisescurlyparentheses}) is satisfied---where $A$ is $B$, $a$ and $b$ are $\ev_A^B[\abst{\upsilon}^\lilbullet]$ and $\upsilon$ respectively, and $p$ is $\beta^{A,B}_\upsilon$.

\medskip

\noindent\textbf{Stability of $\boldsymbol{\app}$ and $\boldsymbol{\lambda}$ under re-indexing.} By naturalities, if $z$ is a section of $P_{\pid_A^B}$, $\upsilon$ is a section of $P_B$, and $f$ is an arrow $\Delta\to\Gamma$, we observe that: \[\begin{alignedat}{2}
    (\app_A^B z)[f^\lilbullet]&=1_{\Delta.A[f]};(\app_A^Bz)f^\lilbullet& \quad\quad\quad\quad (\lambda_A^B \upsilon)[f]&=1_\Delta;(\lambda_A^B\upsilon)f\\
    &=1_{\Delta.A[f]};\app_A^B(zf)&&=1_\Delta;\lambda_A^B(\upsilon f^\lilbullet)\\
    &=\app_{A[f]}^{B[f^\lilbullet]}(1_{\Delta};zf)&&=\lambda_{A[f]}^{B[f^\lilbullet]}(1_{\Delta.A[f]};\upsilon f^\lilbullet)\\
    &=\app_{A[f]}^{B[f^\lilbullet]}(z[f])&&=\lambda_{A[f]}^{B[f^\lilbullet]}(\upsilon [f^\lilbullet])
\end{alignedat}\] that is: \begin{equation}\label{appandlambdastableunderpullback}
    (\app_A^B z)[f^\lilbullet]=\app_{A[f]}^{B[f^\lilbullet]}(z[f]) \quad\quad\quad\quad\quad\quad (\lambda_A^B \upsilon)[f]=\lambda_{A[f]}^{B[f^\lilbullet]}(\upsilon [f^\lilbullet])\quad.
\end{equation} In particular: $$\begin{aligned}\ev_A^B[f^{\lilbullet\lilbullet}]&=(\app_{A[P_{\pid_A^B}]}^{B[P_{\pid_A^B}^\lilbullet]}\delta_{\pid_A^B})[f^{\lilbullet\lilbullet}]\overset{(\ref{appandlambdastableunderpullback})}{=}\app_{A[P_{\pid_A^B}][f^{\lilbullet}]}^{B[P_{\pid_A^B}^\lilbullet][f^{\lilbullet\lilbullet}]}\delta_{\pid_A^B}[f^{\lilbullet}]
\\&=\app_{A[f][P_{\pid_{A[f]}^{B[f^\lilbullet]}}]}^{B[f^\lilbullet][P_{\pid_{A[f]}^{B[f^\lilbullet]}}^\lilbullet]}\delta_{\pid_A^B[f]}=\app_{A[f][P_{\pid_{A[f]}^{B[f^\lilbullet]}}]}^{B[f^\lilbullet][P_{\pid_{A[f]}^{B[f^\lilbullet]}}^\lilbullet]}\delta_{\pid_{A[f]}^{B[f^\lilbullet]}}\\
&=\ev_{A[f]}^{B[f^\lilbullet]}
\end{aligned}$$ that is: \begin{equation}\label{evstabilesottoreindexing}
    \ev_A^B[f^{\lilbullet\lilbullet}] = \ev_{A[f]}^{B[f^\lilbullet]}\quad.
\end{equation}

\medskip

\noindent\textbf{Characterising \boldsymbol{\happly}.} Referring to the notation of \Cref{howtohapply}, let: % https://q.uiver.app/#
\[\begin{tikzcd}
	{\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}} &&& {\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}.\id_{A[P_{\pid_A^B}\mathsf{s}]}^{B[(P_{\pid_A^B}\mathsf{s})^\lilbullet]}}
	\arrow[""{name=0, anchor=center, inner sep=0}, "{\tilde{\mathsf{s}}}", shift left=3, from=1-1, to=1-4]
	\arrow[""{name=1, anchor=center, inner sep=0}, "{\tilde{\mathsf{t}}}"', shift right=3, from=1-1, to=1-4]
	\arrow["{\tilde\alpha_{\pid_A^B}}", shorten <=2pt, shorten >=2pt, Rightarrow, from=0, to=1]
\end{tikzcd}\hspace{-0.2em}\] be the re-indexing of $\alpha_{\pid_A^B}$ via $P_{\pid_A^B}\mathsf{s}:\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}\to\Gamma$ and let: $$\happ:\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}.A[P_{\pid_A^B}\mathsf{s}]\to\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}.A[P_{\pid_A^B}\mathsf{s}].\id_{B[(P_{\pid_A^B}\mathsf{s})^\lilbullet]}[\app\,\tilde{\mathsf{s}};\app\,\tilde{\mathsf{t}}]$$ be $\{\app\,\tilde\alpha_{\pid_A^B}\}$ i.e. the re-indexing along $\app\,\tilde{\mathsf{s}};\app\,\tilde{\mathsf{t}}$ of the unique factorisation of $\app\,\tilde\alpha_{\pid_A^B}$ through the arrow object $\alpha_{B[(P_{\pid_A^B})^\lilbullet]}$---see (\ref{whatcharacterisescurlyparentheses}). Now, we observe that: $$\app\, \tilde{\mathsf{s}}=\app_{A[P_{\pid_A^B}\mathsf{s}]}^{B[(P_{\pid_A^B}\mathsf{s})^\lilbullet]}\tilde{\mathsf{s}}\overset{(\ref{evèapp})}{=}\ev_{A[P_{\pid_A^B}\mathsf{s}]}^{B[(P_{\pid_A^B}\mathsf{s})^\lilbullet]}[\tilde{\mathsf{s}}^\lilbullet]=\ev_{A}^{B}[(P_{\pid_A^B}\mathsf{s})^{\lilbullet\lilbullet}][\tilde{\mathsf{s}}^\lilbullet]=\ev_A^B[((P_{\pid_A^B}\mathsf{s})^{\lilbullet}\tilde{\mathsf{s}})^\lilbullet]=\ev_A^B[\mathsf{s}^\lilbullet]$$ and analogously $\app\, \tilde{\mathsf{t}}=\ev_A^B[\mathsf{t}^\lilbullet]$. Therefore $\happ$ is an arrow: $$\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}.A[P_{\pid_A^B}\mathsf{s}]\to\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}.A[P_{\pid_A^B}\mathsf{s}].\id_{B[(P_{\pid_A^B}\mathsf{s})^\lilbullet]}[\ev_A^B[\mathsf{s}^\lilbullet];\ev_A^B[\mathsf{t}^\lilbullet]]$$ and hence $\lambda\,\happ$ is parallel to $\happly$. We can now state and prove the following:

\begin{theorem}[The happy theorem]\label{happytheorem} Let $(\boldsymbol{\mathcal{C}},\mathcal{D})$ be a display map 2-category endowed with axiomatic $=$-types and axiomatic $\Pi$-types \& axiomatic function extensionality. Then there exists an arrow: $$\happly\Rightarrow\lambda\,\happ$$in the category of the sections of the display map: $$\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}.\bigg(\pid_{A[P_{\pid_A^B}\mathsf{s}]}^{\id_{B[(P_{\pid_A^B}\mathsf{s})^\lilbullet]}[\ev_A^B[\mathsf{s}^\lilbullet];\ev_A^B[\mathsf{t}^\lilbullet]]}\bigg)\to\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}$$ which is stable under re-indexing.

\proof
Using the appropriate arrow object, it is enough to build a section of the display map: $$\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}.\id_{\bigg(\pid_{A[P_{\pid_A^B}\mathsf{s}]}^{\id_{B[(P_{\pid_A^B}\mathsf{s})^\lilbullet]}[\ev_A^B[\mathsf{s}^\lilbullet];\ev_A^B[\mathsf{t}^\lilbullet]]}\bigg)}[\happly;\lambda\,\happ]\to\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}$$ and, by elimination, such a section can be defined as $\j_c$ if we build a section $c$ of the display map: $$\Gamma.\pid_A^B.\id_{\bigg(\pid_{A[P_{\pid_A^B}\mathsf{s}]}^{\id_{B[(P_{\pid_A^B}\mathsf{s})^\lilbullet]}[\ev_A^B[\mathsf{s}^\lilbullet];\ev_A^B[\mathsf{t}^\lilbullet]]}\bigg)}[\happly;\lambda\,\happ][\refl_{\pid_A^B}]\to\Gamma.\pid_A^B$$ that is: $$\Gamma.\pid_A^B.\id_{\bigg(\pid_{A[P_{\pid_A^B}]}^{\id_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B;\ev_A^B]}\bigg)}[\;\happly[\refl_{\pid_A^B}]\;;\;(\lambda\,\happ)[\refl_{\pid_A^B}]\;]\to\Gamma.\pid_A^B\quad.$$ Again, using the appropriate arrow object, it is enough to build an arrow: $$\begin{aligned}
    \happly[\refl_{\pid_A^B}]\Rightarrow(\lambda\,\happ)[\refl_{\pid_A^B}]&\overset{(\ref{appandlambdastableunderpullback})}{=}\lambda(\happ[\refl_{\pid_A^B}^\lilbullet])=\lambda(\{\app\,\tilde\alpha_{\pid_A^B}\}[\refl_{\pid_A^B}^\lilbullet])\\
    &\overset{(\ref{curlyparenthesespreservereindexing})}{=}\lambda\{(\app\,\tilde\alpha_{\pid_A^B})[\refl_{\pid_A^B}^\lilbullet]\}\\
    &\overset{(\ref{appandlambdastableunderpullback})}{=}\lambda\{\app(\tilde\alpha_{\pid_A^B}[\refl_{\pid_A^B}])\}=\lambda\{\app\,1_{\delta_{\pid_A^B}}\}=\lambda\{1_{\app\,\delta_{\pid_A^B}}\}=\lambda\{1_{\ev_A^B}\}
\end{aligned}$$ in the category of the sections of $\Gamma.\pid_A^B.\pid_{A[P_{\pid_A^B}]}^{\id_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B;\ev_A^B]}\to\Gamma.\pid_A^B$ and, since in this category there is an arrow: $$\happly[\refl_{\pid_A^B}]=\j_{\abst{\refl_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B]}}[\refl_{\pid_A^B}]\Rightarrow\abst{\refl_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B]}=\lambda(\refl_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B])$$ it is enough to build an arrow: $$\lambda(\refl_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B])\Rightarrow \lambda\{1_{\ev_A^B}\}$$ in the same category. Therefore we are left to build an arrow $\refl_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B]\Rightarrow \{1_{\ev_A^B}\}$ which amounts to building an arrow: $$\alpha_{B[P_{\pid_A^B}^\lilbullet]}(\ev_A^B;\ev_A^B)^\lilbullet\refl_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B]\Rightarrow1_{\ev_A^B}$$ in the category $(\boldsymbol{\mathcal{C}}/\Gamma.A)(1_{\Gamma.\pid_A^B.A[P_{\pid_A^B}]},P_{B[P_{\pid_A^B}^\lilbullet]})^\to$. However: $$\alpha_{B[P_{\pid_A^B}^\lilbullet]}(\ev_A^B;\ev_A^B)^\lilbullet\refl_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B]=\alpha_{B[P_{\pid_A^B}^\lilbullet]}\refl_{B[P_{\pid_A^B}^\lilbullet]}\ev_A^B=1_{1_{\Gamma.\pid_A^B.A[P_{\pid_A^B}].B[P_{\pid_A^B}^\lilbullet]}}\ev_A^B=1_{\ev_A^B}$$ hence the identity is such an arrow. In conclusion, an arrow: $$\happly[\refl_{\pid_A^B}]\Rightarrow(\lambda\,\happ)[\refl_{\pid_A^B}]$$ is just the one associated to the computation axiom: $${\h_{\abst{{\refl_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B]}}}}$$ for $\happly[\refl_{\pid_A^B}]$---which is stable under re-indexing by \Cref{stability of id in 2d model}. Then: $$\j_{\h_{\abst{{\refl_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B]}}}}$$ is a section of: $$\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}.\id[\happly;\lambda\,\happ]\to\Gamma.\pid_A^B.(\pid_A^B)^\liltriangle.\id_{\pid_A^B}$$hence, as we said, we can define: $$\happly\Rightarrow\lambda\,\happ$$ as: $$\alpha_{\bigg(\pid_{A[P_{\pid_A^B}\mathsf{s}]}^{\id_{B[(P_{\pid_A^B}\mathsf{s})^\lilbullet]}[\ev_A^B[\mathsf{s}^\lilbullet];\ev_A^B[\mathsf{t}^\lilbullet]]}\bigg)}(\happly;\lambda\,\happ)^\lilbullet\j_{\h_{\abst{{\refl_{B[P_{\pid_A^B}^\lilbullet]}[\ev_A^B]}}}}\quad.$$ This is enough to verify that $\happly\Rightarrow\lambda\,\happ$ is stable under every re-indexing for the domain of $P_A$. Happy ending.
\endproof
\end{theorem}

\medskip

\noindent\textbf{Intro Rule for function extensionality.} Let $z,z'$ be sections of the display map $\Gamma.\pid_A^B\to\Gamma$ and let $q$ be a section of the display map: $$\Gamma.\pid_A^{\id_B[\ev_A^B[z^\lilbullet];\ev[z'^\lilbullet]]}\overset{(\ref{evèapp})}{=}\Gamma.\pid_A^{\id_B[\app_A^Bz;\app_A^Bz']}\to\Gamma\;\;.$$ Then $\app_A^{\id_B[\ev_A^B[z^\lilbullet];\ev_A^B[z'^\lilbullet]]} q$ is a section of the display map $\Gamma.A.\id_B[\app_A^Bz;\app_A^Bz']\to\Gamma.A$ and therefore: $$\alpha_B(\app_A^Bz;\app_A^Bz')^\lilbullet \app_A^{\id_B[\ev_A^B[z^\lilbullet];\ev_A^B[z'^\lilbullet]]}q$$ is an arrow $\app_A^Bz\Rightarrow\app_A^Bz'$ in the category $(\boldsymbol{\mathcal{C}}/\Gamma.A)(1_{\Gamma.A},P_B)$ of the sections of $P_B$. Therefore: $$(\eta^{A,B}_{z'})^{-1}\lambda_A^B(\alpha_B(\app_A^Bz;\app_A^Bz')^\lilbullet \app_A^{\id_B[\ev_A^B[z^\lilbullet];\ev_A^B[z'^\lilbullet]]}q)(\eta^{A,B}_z)$$ is an arrow $z\Rightarrow z'$ in the category of the sections of $P_{\pid_A^B}$. We define $\funext_q$ as: $$\{(\eta^{A,B}_{z'})^{-1}\lambda_A^B(\alpha_B(\app_A^Bz;\app_A^Bz')^\lilbullet \app_A^{\id_B[\ev_A^B[z^\lilbullet];\ev_A^B[z'^\lilbullet]]}q)(\eta^{A,B}_z)\}$$ i.e. the re-indexing via $z;z'$ of the unique factorisation of: $$(\eta^{A,B}_{z'})^{-1}\lambda_A^B(\alpha_B(\app_A^Bz;\app_A^Bz')^\lilbullet \app_A^{\id_B[\ev_A^B[z^\lilbullet];\ev_A^B[z'^\lilbullet]]}q)(\eta^{A,B}_z)$$ through $\alpha_{\pid_A^B}$.

\medskip

\noindent\textbf{Comp Axiom for function extensionality.} If we build an arrow $\happly_{z;z'}[\funext_q]\Rightarrow q$ in the category of the sections of $\Gamma.\pid_A^{\id_B[\app_A^Bz;\app_A^Bz']}\to\Gamma$ then $\beta^\Pi_q$ can be defined as the re-indexing via $\happly_{z;z'}[\funext_q];q$ of the unique factorisation of $\happly_{z;z'}[\funext_q]\Rightarrow q$ through $\alpha_{\pid_A^{\id_B[\app_A^Bz;\app_A^Bz']}}$. By \Cref{happytheorem}, we know that: $$\happly_{z;z'}[\funext_q]=\happly[(z;z')^\lilbullet\funext_q]\Rightarrow (\lambda\,\happ)[(z;z')^\lilbullet\funext_q]$$ hence we are left to build $(\lambda\,\happ)[(z;z')^\lilbullet\funext_q]\Rightarrow q$.

Let $p$ be a section of the display map $\Gamma.\id_{\pid_A^B}[z;z']$. Then: $$(\lambda\,\happ)[(z;z')^\lilbullet p]\overset{(\ref{appandlambdastableunderpullback})}{=}\lambda(\happ[((z;z')^\lilbullet p)^\lilbullet])=\lambda(\{\app \,\tilde\alpha_{\pid_A^B}\}[((z;z')^\lilbullet p)^\lilbullet])$$ where we recall that $\{\app \,\tilde\alpha_{\pid_A^B}\}$ denotes the re-indexing along $\app\,\tilde{\mathsf{s}};\app\,\tilde{\mathsf{t}}$ of the unique factorisation of $\app\,\tilde\alpha_{\pid_A^B}$ through the arrow object $\alpha_{B[(P_{\pid_A^B})^\lilbullet]}$. Therefore: $$(\lambda\,\happ)[(z;z')^\lilbullet p]\overset{(\ref{curlyparenthesespreservereindexing})}{=}\lambda\{(\app \,\tilde\alpha_{\pid_A^B})[((z;z')^\lilbullet p)^\lilbullet]\}\overset{(\ref{appandlambdastableunderpullback})}{=}\lambda\{\app(\tilde\alpha_{\pid_A^B}[(z;z')^\lilbullet p])\}$$ and, since: $$\tilde\alpha_{\pid_A^B}[(z;z')^\lilbullet p]=\alpha_{\pid_A^B}(z;z')^\lilbullet p$$ by definition of $\tilde\alpha_{\pid_A^B}$, we deduce that: \begin{equation}\label{funnyhapp}
    (\lambda\,\happ)[(z;z')^\lilbullet p]=\lambda\{\app(\alpha_{\pid_A^B}(z;z')^\lilbullet p)\}
\end{equation} and in particular, when $p$ is $\funext_q$, we obtain that: $$(\lambda\,\happ)[(z;z')^\lilbullet\funext_q]=\lambda\{\app(\;(\eta^{A,B}_{z'})^{-1}\lambda(\;\alpha_B(\app\, z;\app\, z')^\lilbullet \app\,q\;)(\eta^{A,B}_z)\;)\}\quad.$$ Therefore, in order to build $(\lambda\,\happ)[(z;z')^\lilbullet\funext_q]\Rightarrow q$ it is enough to build: $$\{\app(\;(\eta^{A,B}_{z'})^{-1}\lambda(\;\alpha_B(\app\, z;\app\, z')^\lilbullet \app\,q\;)(\eta^{A,B}_z)\;)\}\Rightarrow \app\,q\quad$$ which amounts to building: $$\app(\;(\eta^{A,B}_{z'})^{-1}\lambda(\;\alpha_B(\app\, z;\app\, z')^\lilbullet \app\,q\;)(\eta^{A,B}_z)\;)\Rightarrow\alpha_B(\app\, z;\app\, z')^\lilbullet \app\,q\quad$$ in the category $(\boldsymbol{\mathcal{C}}/\Gamma.A)(1_{\Gamma.A},P_B)^\to$ i.e. a commutative diagram of the form: % https://q.uiver.app/#
\[\begin{tikzcd}[column sep=scriptsize]
	{\app\,z} && {\app\,z} \\
	\\
	{\app\,z'} && {\app\,z'}
	\arrow[Rightarrow, from=1-1, to=1-3]
	\arrow["{\app(\;(\eta^{A,B}_{z'})^{-1}\lambda(\;\alpha_B(\app\, z;\app\, z')^\lilbullet \app\,q\;)(\eta^{A,B}_z)\;)}"', Rightarrow, from=1-1, to=3-1]
	\arrow["{\alpha_B(\app\, z;\app\, z')^\lilbullet \app\,q}", Rightarrow, from=1-3, to=3-3]
	\arrow[Rightarrow, from=3-1, to=3-3]
\end{tikzcd}\] and the pair $(1_{\app\,z},1_{\app\,z'})$ constitutes such a commutative diagram. We are done.

\medskip

\noindent\textbf{Exp Axiom for function extensionality.} If we build an arrow $p \Rightarrow \funext_{\happly_{z;z'}[p]}$ in the category of the section of $\Gamma.\id_{\pid_A^B}\to \Gamma$ then $\gamma^\Pi_p$ can be defined as the section: $$\{p \Rightarrow \funext_{\happly_{z;z'}[p]}\}$$ of $\Gamma.\id_{\id_{\pid_A^B}}[p;\funext_{\happly_{z;z'}[p]}]\to\Gamma$. By definition $\funext_{\happly_{z;z'}[p]}$ is the section: $$\{(\eta^{A,B}_{z'})^{-1}\lambda(\;\alpha_B(\app\,z;\app\,z')^\lilbullet (\app\,\happly_{z;z'}[p])\;)(\eta^{A,B}_z)\}$$ and, by \Cref{happytheorem}, we know that: $$\lambda\{\app(\alpha_{\pid_A^B}(z;z')^\lilbullet p)\}\overset{(\ref{funnyhapp})}{=}(\lambda\,\happ)[(z;z')^\lilbullet p]\Rightarrow\happly[(z;z')^\lilbullet p]=\happly_{z;z'}[p]$$ hence: $$\{\app(\alpha_{\pid_A^B}(z;z')^\lilbullet p)\}\Rightarrow\app\,\lambda\{\app(\alpha_{\pid_A^B}(z;z')^\lilbullet p)\}\Rightarrow\app\,\happly_{z;z'}[p].$$ Therefore we are left to exhibit an arrow: $$\begin{aligned}
    p \Rightarrow \{(\eta^{A,B}_{z'})^{-1}&\lambda(\;\alpha_B(\app\,z;\app\,z')^\lilbullet \{\app(\alpha_{\pid_A^B}(z;z')^\lilbullet p)\}\;)(\eta^{A,B}_z)\}\\&=\{(\eta^{A,B}_{z'})^{-1}\lambda\app(\alpha_{\pid_A^B}(z;z')^\lilbullet p)(\eta^{A,B}_z)\}\\
    &=\{\alpha_{\pid_A^B}(z;z')^\lilbullet p\}\\
    &=\,p
\end{aligned}$$ and $1_p$ is such an arrow.

\begin{proposition}\label{stability of pi in 2d model}
    Let $(\boldsymbol{\mathcal{C}},\mathcal{D})$ be a display map 2-category endowed with axiomatic $=$-types and axiomatic $\Pi$-types \& axiomatic function extensionality. Referring to the data defined in paragraphs \emph{\textbf{Form Rule, Intro Rule, Elim Rule, and Comp Axiom, for $\boldsymbol{\Pi}$-types}} and \emph{\textbf{Intro Rule, Comp Axiom, and Exp Axiom, for function extensionality}}, the \emph{stability conditions}: $$\begin{alignedat}{2}
        \pid_A^B[f]&=\pid_{A[f]}^{B[f^\lilbullet]}&\quad\quad\abst{\upsilon}[f]&=\abst{\upsilon[f^{\lilbullet}]}\\
        \ev_A^B[f^{\lilbullet\lilbullet}]&=\ev_{A[f]}^{B[f^\lilbullet]}&\beta_\upsilon[f^{\lilbullet}]&=\beta_{\upsilon[f^{\lilbullet}]}\\
    \end{alignedat}$$ and: $$\begin{aligned}
    \funext_q[f]&=\funext_{q[f]}\\
    \beta^\Pi_q[f]&=\beta^\Pi_{q[f]}\\
    \eta^\Pi_q[f]&=\eta^\Pi_{q[f]}
    \end{aligned}$$ of Definition \ref{def:Semantics of axiomatic Pi-types} hold for every arrow $\Delta \xrightarrow{f}\Gamma$.

\proof
See Appendix \ref{appendixIII}.
\endproof
\end{proposition}

\subsection{Axiomatic $\boldsymbol{0}$-, $\boldsymbol{1}$-, $\boldsymbol{2}$-, and $\boldsymbol{\nat}$-types}

We specialise the notion of a display map 2-category with axiomatic $=$-types to obtain a version that incorporates a 2-dimensional semantic interpretation of axiomatic $0$-, $1$-, $2$-, and $\nat$-types. We observe the usual weakening from the intensional case \cite{MR2525957} to the very intensional, axiomatic one: retract bireflections are demoted to mere bireflections.

\begin{definition}[Semantics of axiomatic $0$-, $1$-, $2$-, $\nat$-types---categorical formulation]\label{def:Categorical semantics of axiomatic Nat-types}
    Let $(\boldsymbol{\mathcal{C}},\mathcal{D})$ be a display map 2-category endowed with axiomatic $=$-types. If $\Delta$ is an object of $\mathcal{C}$, we define $(\mathcal{D}/\Delta)^\dagger :=(\mathcal{D}/\Delta)\cup\{1_\Delta\}$.

    \begin{itemize}
        \item Let us assume that, for every object $\Gamma$, there is a choice of: \begin{center}
            a display map $\Gamma.0\to\Gamma$
        \end{center} in such a way that the pair: $$(\;1_{\Gamma.0}\;,\;1_{\circ}\;)$$ is a \textit{bireflection} of $\circ$ along the 2-functor $U:(\mathcal{D}/\Gamma.0)^\dagger\to (\boldsymbol{\mathcal{C}}/\Gamma.0)^0=\mathbf{1}$, being $\circ$ the unique object of the terminal 2-category $\mathbf{1}$. Let us assume that these data are stable under re-indexing.

        Unfolding this requirement, this means that, for every display map $P_C$ of codomain $\Gamma.0$, the functor: $$(U\blank)(1_\circ):(\mathcal{D}/\Gamma.0)^\dagger(1_{\Gamma.0},P_C)\to \mathbf{1}(\circ,\circ)$$ has a chosen pseudo-inverse functor with the corresponding natural isomorphisms between the two compositions and the respective identity functors.

        Then we say that $(\boldsymbol{\mathcal{C}},\mathcal{D})$ is \textit{endowed with axiomatic $0$-types}.

        \item Let us assume that, for every object $\Gamma$, there is a choice of: \begin{center}
            a display map $\Gamma.1\to\Gamma$ and a section $\star$ of $\Gamma.1\to\Gamma$
        \end{center} in such a way that the pair: $$(\;1_{\Gamma.1}\;,\;\star\xrightarrow{\star}1_{\Gamma.1}\;)$$ is a \textit{bireflection} of $\star$ along the 2-functor $U:(\mathcal{D}/\Gamma.1)^\dagger\to (\boldsymbol{\mathcal{C}}/\Gamma.1)^1$. Let us assume that these data are stable under re-indexing.

        Unfolding this requirement, this means that, for every display map $P_C$ of codomain $\Gamma.1$, the functor: $$(U\blank)(\star):(\mathcal{D}/\Gamma.1)^\dagger(1_{\Gamma.1},P_C)\to (\boldsymbol{\mathcal{C}}/\Gamma.1)(\star,P_C)$$ has a chosen pseudo-inverse functor with the corresponding natural isomorphisms $\beta^1,\eta^1$ between the two compositions and the respective identity functors.

        Then we say that $(\boldsymbol{\mathcal{C}},\mathcal{D})$ is \textit{endowed with axiomatic $1$-types}.

        % $$\hat{\blank}:(\boldsymbol{\mathcal{C}}/\Gamma.1)(\star,P_C)\to (\mathcal{D}/\Gamma.1)^\dagger(1_{\Gamma.1},P_C)$$ together with natural isomorphisms $$$$

        \item Let us assume that, for every object $\Gamma$, there is a choice of: \begin{center}
            a display map $\Gamma.2\to\Gamma$ and a pair $(\bot,\top)$ of sections of $\Gamma.2\to\Gamma$
        \end{center} in such a way that the pair: $$(\;1_{\Gamma.2}\;,\;(\bot,\top)\xrightarrow{(\bot,\top)}(1_{\Gamma.2},1_{\Gamma.2})\;)$$ is a \textit{bireflection} of $(\bot,\top)$ along the 2-functor $U:(\mathcal{D}/\Gamma.1)^\dagger\to (\boldsymbol{\mathcal{C}}/\Gamma.1)^2$. Let us assume that these data are stable under re-indexing.

        Unfolding this requirement, this means that, for every display map $P_C$ of codomain $\Gamma.2$, the functor: $$(U\blank)(\bot,\top):(\mathcal{D}/\Gamma.2)^\dagger(1_{\Gamma.2},P_C)\to (\boldsymbol{\mathcal{C}}/\Gamma.2)^2((\bot,\top),(P_C,P_C))$$ has a chosen pseudo-inverse functor with the corresponding natural isomorphisms $\beta^2,\eta^2$ between the two compositions and the respective identity functors.

        Then we say that $(\boldsymbol{\mathcal{C}},\mathcal{D})$ is \textit{endowed with axiomatic $2$-types}.


        \item Let us assume that, for every object $\Gamma$, there is a choice of: \begin{center}
            a display map $\Gamma.\nat\to\Gamma$ a section $\0$ of $\Gamma.\nat\to\Gamma$ and an arrow $\s:\Gamma.\nat\to\Gamma.\nat$ over $\Gamma$
        \end{center} in such a way that the functor: $$(U\blank)(\0,\s P_C):(\mathcal{D}/\Gamma.\nat)^\dagger(1_{\Gamma.\nat},P_C)\to (\boldsymbol{\mathcal{C}}/\Gamma.\nat)^2((\0,\s P_C),(P_C,P_C))$$ is an equivalence, being $U$ the 2-functor $(\mathcal{D}/\Gamma.\nat)^\dagger\to (\boldsymbol{\mathcal{C}}/\Gamma.\nat)^2$. Let us assume that these data are stable under re-indexing.

        Unfolding this requirement, this means that, for every display map $P_C$ of codomain $\Gamma.\nat$, the functor: $$(U\blank)(\0,\s P_C):(\mathcal{D}/\Gamma.\nat)^\dagger(1_{\Gamma.\nat},P_C)\to (\boldsymbol{\mathcal{C}}/\Gamma.\nat)^2((\0,\s P_C),(P_C,P_C))$$ has a chosen pseudo-inverse functor with the corresponding natural isomorphisms $\beta^\nat,\eta^\nat$ between the two compositions and the respective identity functors.

        Then we say that $(\boldsymbol{\mathcal{C}},\mathcal{D})$ is \textit{endowed with axiomatic $\nat$-types}.
    \end{itemize}
\end{definition}

Let $(\boldsymbol{\mathcal{C}},\mathcal{D})$ be a display map 2-category endowed with axiomatic $=$-types.

Let us assume that the display map 2-category $(\boldsymbol{\mathcal{C}},\mathcal{D})$ is endowed with axiomatic $0$-types (resp. axiomatic $1$-types, axiomatic $2$-types, axiomatic $\nat$-types)---Definition \ref{def:Categorical semantics of axiomatic Nat-types}---and let $\Gamma$ be a context. As usual, we can define appropriate choice functions \textbf{Form Rule, Elim Rule, for $\boldsymbol{0}$-types} and \textbf{Form Rule, Intro Rule, Elim Rule, and Comp Axiom, for $\boldsymbol{1}$-types, $\boldsymbol{2}$-types, $\boldsymbol{\nat}$-types}---as in Definition \ref{def:Semantics of axiomatic Nat-types}---using the endowment of the structure $(\boldsymbol{\mathcal{C}},\mathcal{D})$ with axiomatic $0$-types, axiomatic $1$-types, axiomatic $2$-types, axiomatic $\nat$-types. We provide a proof sketch of this fact.

\medskip

\noindent\textbf{Form Rule for $\boldsymbol{0}$-types, $\boldsymbol{1}$-types, $\boldsymbol{2}$-types, $\boldsymbol{\nat}$-types} and \textbf{Intro Rule for $\boldsymbol{1}$-types, $\boldsymbol{2}$-types} are already defined.

\medskip

\noindent\textbf{Intro Rule for $\boldsymbol{\nat}$-types.} We define $\successivo$ as the unique section of $P_{\nat^\liltriangle}$ whose post-composition via $P_\nat^\lilbullet$ is $\s$.

\medskip

\noindent\textbf{Elim Rule for $\boldsymbol{0}$-types, $\boldsymbol{1}$-types, $\boldsymbol{2}$-types, $\boldsymbol{\nat}$-types.} If $P_C$ is an arrow of codomain $\Gamma.0$, then we define $\ind^0$ as the image of $1_\circ$ via the chosen pseudo-inverse of $(U\blank)(1_\circ)$. If $P_C$ is an arrow of codomain $\Gamma.1$ and $c$ is a section of $P_{C[\star]}$, then we define $\ind^1_c$ as the image of $\star^\lilbullet c$ via the chosen pseudo-inverse of $(U\blank)(\star)$. If $P_C$ is an arrow of codomain $\Gamma.2$ and $c$ is a section of $P_{C[\bot]}$ and $d$ is a section of $P_{C[\top]}$, then we define $\ind^2_{c,d}$ as the image of $(\bot^\lilbullet c,\top^\lilbullet d)$ via the chosen pseudo-inverse of $(U\blank)(\bot,\top)$. If $P_C$ is an arrow of codomain $\Gamma.\nat$ and $c$ is a section of $P_{C[\0]}$ and $d$ is a section of $P_{C[\s P_C]}$, then we define $\ind^\nat_{c,d}$ as the image of $(\0^\lilbullet c,(\s P_C)^\lilbullet d)$ via the chosen pseudo-inverse of $(U\blank)(\0,\s P_C)$.

\medskip

\noindent\textbf{Comp Axiom for $\boldsymbol{1}$-types, $\boldsymbol{2}$-types, $\boldsymbol{\nat}$-types.} We have a chosen 2-cell $(U\ind^1_c)(\star) \Rightarrow \star^\lilbullet c$, i.e. $\ind^1_c \star \Rightarrow \star^\lilbullet c$, over $\Gamma.1$. Therefore, referring to the diagram: % https://q.uiver.app/#
\begin{equation}\label{reindexingone}\begin{tikzcd}[column sep=scriptsize,row sep=small]
	\Gamma && \Gamma \\
	\\
	{\Gamma.C[\star]} && {\Gamma.1.C} \\
	\\
	\Gamma && {\Gamma.1}
	\arrow[equals, from=1-1, to=1-3]
