Then, any type I node has its horizontal multiplicity $h \geq \frac16$ due to the $\frac16$-lc property of the pairs $(Z_i, B_i)$ {with $B_i \geq 0$}, while a type II node may as well have $h <\frac16$. 
Note that the only allowed multiplicities in the latter case are $h = \frac{1}{12}$ or $0$.


Without loss of generality, we assume that the series $\{h_i\}_{i=0}^{r-1}$ of horizontal multiplicities is non-increasing, and denote by $r_1$ what distinguishes the two regimes of $h_i$ as follows: 
\beq\label{r'}
h_0 \geq \cdots \geq h_{r_1-1} \geq \frac{1}{6} > h_{r_1} \geq \cdots \geq h_r \,.
\eeq


\section{A Picard Rank Bound}\label{sec:strategy}


Let $\mathcal S_\alpha$ be the total number of type I nodes attached to the special fibers over $X_\alpha$, $\alpha=1,2,3$, and similarly, let $\mathcal D_\alpha$ be that of type II nodes over $X_\alpha$. 

\begin{lemma}\label{lem1} 
The coefficient $b$ of $B_r$ in each component of a special fiber over $x\in X$ is subject to 
\beq\label{b-ineq}
b \leq 
\begin{cases}
    \frac{8}{12} & \text{if } x \in X_1 \\
    \frac{9}{12} & \text{if } x \in X_2  \\  
    \frac{10}{12} & \text{if } x \in X_3 
\end{cases}
\eeq  
\end{lemma} 

\paragraph{Proof} 
For each component $T$ of a special fiber $F$ over $x \in X$, the multiplicity $\mu_x^{\rm sf}$ is subject to the following inequality, 
\beq\label{mu-sf}
\mu_x^{\rm sf} \geq 1-\frac{1-\mu_T B_r}{\mu_T F} \,, 
\eeq
where $b_T :=\mu_T B_r$ is the coefficient of $T$ in $B_r$ and $\mu_T F \in \mathbb Z_{\geq 1}$ is the multiplicity of $T$ in the full fiber. Therefore, if $\mu_x^{\rm sf}$ is strictly bounded from above by $\frac{k}{12}$ with $k\geq \mathbb Z_{\geq 1}$, we have 
\beq
\frac{k}{12} > \mu_x^{\rm sf} \geq b_T ~\Rightarrow~\frac{k-1}{12} \geq b_T \,, \quad \forall T \,, 
\eeq
manifesting the first two inequalities of~\eqref{b-ineq}. On the other hand, the last inequality of~\eqref{b-ineq} is obvious from the $\frac16$-lc property of the pair $(Z_r, B_r)$. \hfill\(\Box\)






\begin{corollary}\label{coro2} 
Each node of type I attached to a special fiber over $x\in X$ has the associated horizontal multiplicity $h$ subject to 
\beq\label{lb}
h \geq 
\begin{cases}
    \frac{4}{12} & \text{if } x \in X_1 \\
    \frac{3}{12} & \text{if } x \in X_2  \\  
    \frac{2}{12} & \text{if } x \in X_3 
\end{cases}
\eeq  
Similarly, $h$ is also subject to the following upper bound, 
\beq\label{ub}
h \leq 
\begin{cases}
    \frac{20}{12} & \text{if } x \in X_1 \\
    \frac{21}{12} & \text{if } x \in X_2  \\  
    \frac{22}{12} & \text{if } x \in X_3 
\end{cases}
\eeq  


\end{corollary}

\paragraph{Proof} 
Suppose that a type $I$ node is generated by $\varphi_i$, which blows up a point $z_i$ in a {vertical} curve $C$, leading to an exceptional curve $C':=E_{i+1}$. Then, the coefficients $b:={\rm coeff}_C B_i$ and $b':={\rm coeff}_{C'} B_{i+1}$, are related by 
\beq
b + h -1 = b' \quad \Rightarrow \quad  h= 1 + b' - b \,, 
\eeq
where $h:=h_i$ denotes the horizontal multiplicity~\eqref{order-param} of the single-type blowup. Then, the inequality~\eqref{b-ineq} of Lemma~\ref{lem1} applies both to $b$ and $b'$, from which the bounds~\eqref{lb} and~\eqref{ub} immediately follow. \hfill\(\Box\)



\begin{lemma}\label{lem3} 
For the nodes attached to special fibers over $X_1$, we have 
\beq
\mathcal D_1 \leq 3 \mathcal S_1 \,.
\eeq 
\end{lemma}

\paragraph{Proof}
The inequality~\eqref{mu-sf}, once applied to the multiplicity $\mu_x^{\rm sf}$ of a special fiber $F$ over $x\in X_1$, tells us that $\mu_T F <4$ for every component $T$ of $F$. Therefore, any set of blowups, whose associated nodes form a chain within a given tree of nodes in $F$, can have at best two double-type blowups. Clusters of type II nodes within a tree can therefore come only in the following three forms:\footnote{Hereafter, a cluster within a tree will refer to a connected subtree of the tree.} 


