\begin{lemma}\label{lem6}
Assume $(Z,B)$ is an $\epsilon$-lc pair of dimension 2 and that $Z$ is smooth projective with $K_Z+B\equiv 0$. Then for any smooth projective curve $C \subseteq Z$, we have
\beq
C^2 \geq -\frac{2}{\epsilon} \,. 
\eeq
In particular, for the case of $\frac{1}{6}$-lc pair $(Z_r, B_r)$, we have $C^2 \geq -12$ for any smooth projective curve $C \subseteq Z_r$. 
\end{lemma}

\paragraph{Proof} Let $b$ be the coefficient of $C$ in $B$. We can assume $C^2 <0$. Then
\beq
(K_Z + B+(1-b) C) \cdot C \geq (K_Z + bC + (1-b)C )\cdot C \,,
\eeq
from which it follows that 
\beq
(1-b) C^2 \geq 2g(C) - 2 \geq -2 \,.
\eeq
Since $(Z,B)$ is $\epsilon$-lc and $C^2<0$, we see that  
\beq
\epsilon C^2 \geq (1-b) C^2 \geq -2 \,,
\eeq
and hence that  
\beq
C^2 \geq -\frac{2}{\epsilon} \,.
\eeq 
In particular, if $\epsilon = \frac{1}{6}$, then we have 
\beq
C^2 \geq -12 \,,
\eeq
for any smooth projective curve $C$. 
\hfill\(\Box\) 


\begin{lemma}\label{lem7}
\bea
-K_{Z_0} \cdot B_0^{\rm h} &\leq& 8 \,,\\
-K_{Z_r} \cdot B_r^{\rm h} &\geq& -20 \,.  
\eea
\end{lemma}

\paragraph{Proof} 
For $Z_0 = \mathbb F_a$ a Hirzebruch surface, 
\beq\label{KZ^2}
-K_{Z_0} \cdot B_0^{\rm h} = B_0 \cdot B_0^{\rm h} \leq B_0 \cdot (B_0^{\rm h} + B_0^{\rm v})= B_0^2  = K_{Z_0}^2 = 8 \,, 
\eeq
where, in the inequality, we have used that the vertical part $B_0^{\rm v}$ is a nef divisor. Furthermore, the last equality can be seen from the fact that $K_{Z_0} \sim -(a+2) f - 2e$, where $f$ is a general fiber of $p_0: Z_0 \to \mathbb P^1_{\rm b}$ and $e$ the section with $e^2=-a$. 

Next, to show that 
\beq
-K_{Z_r} \cdot B_r^{\rm h} \geq -20 \,,  
\eeq
let us first recall that each coefficient of $B_r$ is less than or equal to $\frac56$ since $(Z_r, B_r)$ is $\frac16$-lc. For any curve $C \subseteq Z_r$, it then follows that $B_r^{\rm h} \cdot C \geq -10$. To see this we may assume $C^2 <0$ and observe that 
\beq
2p_a(C) - 2 = (K_{Z_r} + C) \cdot C \leq (K_{Z_r} +B_r +(1-b)C) \cdot C < 0 \,, 
\eeq
where $b$ denotes the coefficient of $C$ in $B_r$ and $p_a(C)$ the arithmetic genus of $C$. Hence, $C\simeq \mathbb P^1$. In particular, $C$ is smooth, so $C^2 \geq -12$ by Lemma~\ref{lem6}. 
On the other hand, 
\beq
B_r^{\rm h} \cdot C \geq aC^2 \geq \frac56 C^2 \geq \frac56 \times (-12) =-10 \,,
\eeq
where $a$ is the coefficient of $C$ in $B_r^{\rm h}$. 
Thus, 
\beq
B_r^{\rm h} + 10F 
\eeq
is a nef divisor where $F$ is a general fiber of $p_r:Z_r \to \mathbb P^1_{\rm b}$. 
We therefore have 
\bea
-K_{Z_r} \cdot B_r^{\rm h} &=& -K_{Z_r} \cdot (B_r^{\rm h} + 10F) + K_{Z_r} \cdot 10F \\
&=& B_r \cdot (B_r^{\rm h} + 10F) + K_{Z_r} \cdot 10 F \\ 
&\geq& K_{Z_r} \cdot 10F = -20 \,,  
\eea 
and hence the lemma holds. \hfill\(\Box\) 




\begin{lemma}\label{lem8}
