In fact, 
\beq\label{336-improved}
4 \mathcal S_1 + \Big(2 \mathcal D_2^{(\geq 2)}  + \sum_{k=3}^{21} k\, \mathcal S_2^{(k)} \Big) +  \Big(2 \check{\mathcal D}_3^{(\geq 2)} + 3 \bar{\mathcal D}_3^{(\geq 2)} + 4 \hat{\mathcal D}_3^{(\geq 2)} +  \sum_{k=2}^{22} \big(k \,\check{\mathcal S}_3^{(k)} +  { (k+1) \,{{\bar{\mathcal S}}_3}^{(k)} + (k+2) \,{{\hat{\mathcal S}}_3}^{(k)}} \big)\Big)  \leq 336\,, 
\eeq
where the refined variables defined in~\eqref{def-D-refine} and~\eqref{def-S-refine} have been used. 


\end{lemma}


\paragraph{Proof} 
Let us first observe that for each $i = 0, \cdots, r-1$, we have 
\bea
- K_{Z_{i+1}} \cdot B_{i+1}^{\rm h} &=& - (\varphi_{i}^* K_{Z_{i}} + E_{i+1}) \cdot B_{i+1}^{\rm h} \\ 
&=& -\varphi_{i}^* K_{Z_{i}} \cdot B_{i+1}^{\rm h} - E_{i+1} \cdot B_{i+1}^{\rm h} \\ 
&=&  -K_{Z_{i}} \cdot B_{i}^{\rm h} - \mu_{z_i} B_i^{\rm h} \\ \label{inductive}
&=& - K_{Z_{i}} \cdot B_{i}^{\rm h} - h_i \,. 
\eea
where in the last step the definition~\eqref{order-param} for the horizontal multiplicity has been used. 
Then, Lemma~\ref{lem7}, once combined with the relations~\eqref{inductive}, leads to 
\beq
8 \geq - K_{Z_0} \cdot B_0^{\rm h} =  - K_{Z_r}\cdot B_r^{\rm h} + \sum_{i=0}^{r-1} h_i  \geq -20 + \sum_{i=0}^{r-1} h_i \quad \Rightarrow\quad  \sum_{i=0}^{r-1} h_i \leq 28 \,. 
\eeq
Recalling from Corollary~\ref{coro2} that the horizontal multiplicity $h$ of a single-type blowup in $p_r^{-1}(x)$ for $x\in X_1$ is subject to $h \geq \frac{4}{12}$, it follows immediately that 
\beq\label{before-strengthen}
\frac{4}{12} \mathcal S_1 + \Big(\frac{2}{12} \mathcal D_2^{(\geq 2)} + \sum_{k=3}^{21}  \frac{k}{12} \mathcal S_2^{(k)} \Big)  + \Big(\frac{2}{12} \mathcal D_3^{(\geq 2)} + \sum_{i=2}^{22} \frac{k}{12} \mathcal S_3^{(k)}\Big) \leq \sum_{i=0}^{r-1} h_i \leq 28 \,, 
\eeq
ane hence~\eqref{336} holds. 

Note that we may strengthen the constraint~\eqref{before-strengthen} by taking also into account the blowups with $h=\frac{1}{12}$. In particular, for the special fibers over $X_3$, we may further consider the $\bar{\mathcal D}_3^{(\geq 2)}+2 \hat{\mathcal D}_3^{(\geq 2)} { + \sum_{k=2}^{22}  \big(\bar{\mathcal S}_3^{(k)}+2 \hat{\mathcal S}_3^{(k)}\big)} $ blowups with $h=\frac{1}{12}$. This allows us to replace $\frac{2}{12} \mathcal D_3^{(\geq 2)}$ and $\frac{k}{12}\mathcal S_3^{(k)}$ in the left hand side of~\eqref{before-strengthen}, respectively, by 
\beq
\frac{2}{12} \check{\mathcal D}_3^{(\geq 2)} + \frac{3}{12}\bar{\mathcal D}_3^{(\geq 2)} + \frac{4}{12} \hat{\mathcal D}_3^{(\geq 2)}\,\quad\text{and}\quad 
\frac{k}{12} \check{\mathcal S}_3^{(\geq 2)} + \frac{k+1}{12}\bar{\mathcal S}_3^{(\geq 2)} + \frac{k+2}{12} \hat{\mathcal S}_3^{(\geq 2)}\,,
\eeq
establishing the improved constraint~\eqref{336-improved}. 
\hfill\(\Box\) 



\paragraph{Proof of Theorem~\ref{thm0-3}} 
In order to establish $\rho(Z) \leq 568$, we will prove that $r \leq 566$ in the construction~\eqref{chain}.   
From Lemmas~\ref{lem3},~\ref{lem4} and~\ref{lem5}, let us first observe that 
\bea
r &= & (\mathcal D_1 + \mathcal S_1) +  (\mathcal D_2^{(\geq 2)} + \mathcal D_2^{(<2)} + \mathcal S_2) + (\mathcal D_3^{(\geq 2)} + \mathcal D_3^{(<2)} + \mathcal S_3)  \\ \nn
&\leq & 4 \mathcal S_1 + 8 \mathcal D_2^{(\geq 2)} + \sum_{k=3}^{21} (\sigma_2^{(k)}+1) \mathcal S_2^{(k)} +12  {\check{\mathcal D}}_3^{(\geq 2)} + 16 {\bar{\mathcal D}}_3^{(\geq 2)} + 23 {\hat{\mathcal D}}_3^{(\geq 2)}   \\ 
&& +\; \sum_{k=2}^{22} \big((\check\sigma_3^{(k)}+1)  \check{\mathcal S}_3^{(k)} { + (\bar\sigma_3^{(k)}+1)  \bar{\mathcal S}_3^{(k)} +(\hat\sigma_3^{(k)}+1)  \hat{\mathcal S}_3^{(k)}}  \big) \\ \nn 
&\leq &  4 \mathcal S_1 + 8 \mathcal D_2^{(\geq 2)} + \sum_{k=3}^{21} { (k-2)} \mathcal S_2^{(k)} +12  {\check{\mathcal D}}_3^{(\geq 2)} + 16 {\bar{\mathcal D}}_3^{(\geq 2)} + 23 {\hat{\mathcal D}}_3^{(\geq 2)}  \\ \label{rmax}
&&+\; \sum_{k=2}^{22} \big(k \check{\mathcal S}_3^{(k)}  + { (k+4)}\bar{\mathcal S}_3^{(k)} + { (k+11)} \hat{\mathcal S}_3^{(k)} \big) \\
&=:& r_{\rm bound} \,,
\eea
where we have used, in the last step before defining $r_{\rm bound}$, that the constants $\sigma_2^{(k)}$, $\check\sigma_3^{(k)}$, $\bar\sigma_3^{(k)}$ and $\hat\sigma_3^{(k)}$ are subject to the inequalities~\eqref{c2k},~\eqref{c3k-check}, ~\eqref{c3k-bar} and~\eqref{c3k-hat}, respectively. 
On the other hand, upon combining the two inequalities~\eqref{D2-ineq} and~\eqref{D3-ineq} with weight 6 and 10, we obtain 
\beq
6 \mathcal D_2^{(\geq 2)} +10  {\check{\mathcal D}}_3^{(\geq 2)} + 15 {\bar{\mathcal D}}_3^{(\geq 2)} + 20 {\hat{\mathcal D}}_3^{(\geq 2)}  + \sum_{k=2}^{22} \big( 5\bar{\mathcal S}_3^{(k)} + 10 \hat{\mathcal S}_3^{(k)} \big)  
\leq 66|X_2| + 115|X_3| 
\eeq
which, once added to~\eqref{336-improved} of Lemma~\ref{lem8}, results in   
\beq
r_{\rm bound} \leq 336 + 66|X_2| + 115|X_3| \,. 
\eeq
It thus follows that 
\beq
r \leq r_{\rm bound} \leq 336 + 66|X_2| + 115|X_3| \leq 336 + 115(|X_2| + |X_3|) \leq 566 \,, 
\eeq
where~\eqref{X2X3} has been used in the last step. \hfill\(\Box\)  



