	\begin{theorem}
		Let $\mathbb{X}$ and $\mathbb{Y}$ be Banach spaces and $T_1,T_2\in \mathbb{L}(\mathbb{X},\mathbb{Y}).$ Suppose that $M_{T_1+T_2}\neq \emptyset.$ Then $T_1,T_2$ form a TEA pair if and only if there exists  $x\in M_{T_1}\cap M_{T_2}\cap M_{T_1+T_2}$ such that $J(T_1x)\cap J(T_2x)\neq \emptyset.$
	\end{theorem}
	\begin{proof}
		Let  $T_1,T_2\in \mathbb{K}(\mathbb{X},\mathbb{Y})$ form a TEA pair. suppose that $x\in M_{T_1+T_2}.$ Then 
		\[\|T_1\|+\|T_2\|=\|T_1+T_2\|=\|T_1x+T_2x\|\leq \|T_1x\|+\|T_2y\|\leq \|T_1\|+\|T_2\|.\]
		This implies that $\|T_1x+T_2x\| = \|T_1x\|+\|T_2x\|$ and $\|T_1x\|=\|T_1\|,\|T_1x\|=\|T_1\|.$ Thus $x\in M_{T_1}\cap M_{T_2}\cap M_{T_1+T_2}.$ Also  from  Proposition \ref{par char}, it follows that $J(T_1x)\cap J(T_2x)\neq \emptyset.$ \\
		Conversely, let there exist  $x\in M_{T_1}\cap M_{T_2}\cap M_{T_1+T_2}$ such that $J(T_1x)\cap J(T_2x)\neq \emptyset.$
		Since $J(T_1x)\cap J(T_2(x))\neq \emptyset,$ it follows from    Proposition \ref{par char} that $\|T_1x+T_2x\| = \|T_1x\|+\|T_2x\|.$ Thus,
		\[\|T_1+T_2\|=\|T_1x+T_2x\|= \|T_1x\|+\|T_2x\|= \|T_1\|+\|T_2\|.\]
		Therefore, $T_1,T_2$ form a TEA pair.
	\end{proof}

