\draw[thick, cyan, rounded corners=5pt] (-.2,.3) -- (2.3,.3) -- (2.3,2.7);
\node[cyan] at (.75,1.75) {$\bbQ$};
}
$$
we get a boundary net of algebras $\fB^\partial$ on $\cK$ together with a quantum channel $\fA_\bbQ \to \fB^\partial$.


Similar to \cite[Lem.~2.13]{2307.12552}, the axioms \ref{BoundaryLTO:QECC}--\ref{BoundaryLTO:Injective} above ensure that $\fB^\partial(\Lambda \Subset_s^\delta \Delta)$ is independent of the choice of $\Lambda \Subset_s^\delta \Delta\subset \bbQ$ beyond the intersection $I:=\partial \Lambda \cap \partial \Delta\cap  \cK$.
Indeed, we may choose $\Lambda_I\subset \Lambda$ to be the smallest sufficiently large rectangle with $\partial \Lambda_I \cap \cK=I$ and $\Delta_I\subset \Delta$ to be the smallest rectangle with $\Lambda_I\Subset_s^\partial \Delta_I$ and $\partial\Lambda_I\cap \partial\Delta_I = I$.
We then define 
$$
\fB^\partial(I):= \fB^\partial(\Lambda_I\Subset_s\Delta_I),
$$
and the map $I\mapsto \fB^\partial(I)$ defines a net of algebras with boundary on $\cK$.

We now introduce the notion of a \emph{boundary DHR bimodule} for a net of algebras $\fA$ on a lattice $\cL$ with boundary $\partial \cL$, which is localized near the boundary $\partial \cL$.
(We will use this notion for the boundary algebra $\fB^\partial$ on $\cK$, which has boundary $\partial \cK = \cK\cap \partial \cL$.)

\begin{defn}
\label{defn:BoundaryDHRBimodule}
A \emph{boundary DHR bimodule} for $\fA$ is an $\fA-\fA$ Hilbert $\rmC^*$-correspondence ${}_{\fA} Y_{\fA}$ such that 
for any sufficiently large rectangle $\Lambda\subset \cL$ which meets $\partial \cL$, $Y$ is localized in $\Lambda$ in the sense of Definition~\ref{def:LocalizableBimodule} above.
Unpacking, this means there is a finite $Y_{\fA}$-basis $\{\beta_i\}\subset Y$ such that $\beta_i a=a\beta_i$ for all 
$$
a\in \fA(\Lambda^c)
:= 
\varinjlim_{\Delta\subset \Lambda^c} \fA(\Delta)
\subset 
\fA.
$$
That is, the basis elements $\beta_i$ commute with all the elements of $\fA$ which are in the subalgebra supported on $\Lambda^c$.

We denote the full subcategory of boundary DHR-bimodules by $\DHR^\partial(\fA)\subset \Bim(\fA)$.
Observe that $\DHR^\partial(\fA)$ is closed under composition of bimodules and thus forms a full $\rmC^*$ tensor subcategory.
\end{defn}

Similar to Lemma \ref{lem:DHRBimoduleCharacterization} above, we have the following characterization of boundary DHR bimodules whose proof is identical and therefore omitted.

\begin{lem}[Local triviality of boundary DHR bimodules]
\label{lem:BoundaryDHRBimoduleCharacterization}
A bimodule ${}_{\fA} Y_{\fA}\in \Bim(\fA)$ lies in $\DHR^\partial(\fA)$ if and only if for any sufficiently large $\Lambda$ which meets $\partial\cL$, the restriction
$
{}_{\fA(\Lambda^c)} Y_{\fA}
$
is isomorphic to a summand of a finite direct sum of copies of ${}_{\fA(\Lambda^c)}\fA_{\fA}$.
\end{lem}

Even though our net of algebras on our lattice with boundary may no longer satisfy algebraic Haag duality (e.g., the fusion module categorical net in \S\ref{sec:BoundaryDHRforBoundaryLW} below does not have this property), we still have a notion of \emph{boundary algebraic Haag duality}.
(There are obvious weaker/bounded spread variants of this notion, which we leave to the reader.)

\begin{defn}
A net of algebras $\fA$ on a lattice with boundary satisfies \emph{boundary algebraic Haag duality} if for every rectangle $\Delta$ meeting the boundary $\partial \cL$,
$Z_{\fA}(\fA(\Delta^c))=\fA(\Delta)$,
where again $\fA(\Delta^c)$ is the subalgebra of $\fA$ generated by the $\fA(\Lambda)$ with $\Lambda\subset \Delta^c$.
\end{defn}

The proof of the following lemma is identical to Lemma \ref{lem:IPLocalizedInCentralizer}.

\begin{lem}
\label{lem:BoundaryIPLocalizedInCentralizer}
If $\eta,\xi\in Y\in \Bim^\partial(\fA)$ are both localized in $\Delta$ which meets $\partial\cL$ and $a\in \fA(\Delta)$, then
$\langle \eta|a\xi\rangle_{\fA} \in Z_{\fA}(\fA(\Lambda))$ for all $\Lambda\subset \Delta^c$.
In particular, if $\fA$ satisfies boundary algebraic Haag duality, then $\langle \eta|a\xi\rangle_{\fA}\in \fA(\Delta)$.
\end{lem}

The tensor category $\DHR^\partial(\fA)$ does not have a braiding. 
We expect that one can adapt the definition of the braiding on $\DHR(\fA)$ to get a canonical \emph{half-braiding} for the image of $\DHR(\fA)$ in $\DHR^\partial(\fA)$ with $\DHR^\partial(\fA)$.
We leave this exploration for a future article as it would take us too far afield.


