\subsection{The boundary DHR theory for the boundary Levin-Wen model}
\label{sec:BoundaryDHRforBoundaryLW}

We now analyze the boundary DHR theory for our boundary Levin-Wen model using subfactor theory.
We denote the fusion module boundary algebra by
$$
\fM:=\varinjlim_n \End_\cM(W\lhd X^{\otimes n}).
$$

We now unpack Definition \ref{defn:BoundaryDHRBimodule} of the tensor category $\DHR^\partial(\fM)$ of boundary DHR bimodules for $\fM$.
Such a bimodule is an $\fM-\fM$ Hilbert $\rmC^*$-correspondence ${}_\fM Y_\fM$ such that there is an interval $I\subset \cK$ which meets the boundary ($I\cap \partial\cL\neq \emptyset$) such that $Y$ is \emph{localizable} in $I$, i.e., there is a finite $Y_\fM$-basis $\{\beta_i\}\subset Y$ such that $\beta_i a=a\beta_i$ for all 
$$
a\in 
\fM(I^c)
:= 
\varinjlim_k \End_\cC(X^{\otimes k})
\subset 
\varinjlim_k \End_\cM(W\lhd X^{\otimes |I-1|+k})
=
\fM
$$
That is, the basis elements $\beta_i$ commute with all the elements of $\fM$ which are in the subalgebra supported on $I^c$.

\begin{construction}
\label{construct:BoundaryDHR}
We construct for each $F\in \End(\cM_\cC)$ a DHR bimodule ${}_\fM Y^F_\fM$.
We then show that the bimodules $Y^F$ assemble into a fully faithful tensor functor 
\begin{equation}
\label{eq:EmbedEndIntoDHR}
Y: \End(\cM_\cC)\to \DHR^\partial(\fM).
\end{equation}
For $n\geq 0$, we define
$$
Y^F_n := \cM(W\lhd X^{\otimes n} \to FW\lhd \otimes X^{\otimes n})
$$
which is naturally a bimodule for $\fM_n:=\End_\cM(W\lhd X^{\otimes n})$, where
the left action is post-composition after applying $F$ and the right action is pre-composition.
We equip $Y^F_n$ with a right $\fM_n$-valued inner product by 
$$
\langle \eta|\xi\rangle_{\fM_n}:= \eta^\dag\circ \xi \in \End((\fM_n)_{\fM_n})=\fM_n.
$$
Observe that the inclusions $-\otimes \id_X: Y^F_n\hookrightarrow Y^F_{n+1}$
are compatible with the inclusions $-\otimes \id_X : \fM_n\hookrightarrow \fM_{n+1}$, and that
$$
\langle \eta\otimes\id_X|\xi\otimes\id_X\rangle_{\fM_{n+1}}
=
(\eta\otimes \id_X)^\dag\circ (\xi\otimes \id_X)
=
\eta^\dag\circ \xi \otimes \id_X
=
\langle \eta|\xi\rangle_{\fM_n}\otimes \id_X.
$$
We thus get an inductive limit $\fM-\fM$ bimodule $Y^F:=\varinjlim Y^F_n$.

Now for each $\cC$-module natural transformation $\theta: F\Rightarrow G$ in $\End(\cM_\cC)$, we get a bimodule intertwiner as the inductive limit of the maps
$$
\cM(W\lhd X^{\otimes n} \to FW\lhd \otimes X^{\otimes n})
=
Y_n^F
\ni
f
\mapsto 
(\theta_W\otimes \id_{X^{\otimes n}})\circ f
\in 
Y_n^G
=
\cM(W\lhd X^{\otimes n} \to GW\lhd \otimes X^{\otimes n}).
$$
This construction is easily seen to be a unitary tensor functor.
Moreover, it can be shown that this functor is fully faithful using the unitary multifusion category embedding results of \cite{MR4916103}, together with the \emph{Q-system realization} technique from \cite{MR4419534}.
We review this argument in the context of $\rmC^*$-Hilbert bimodules in Appendix \ref{appendix:AFActionsOfUmFCs} below for convenience of the reader.
\end{construction}

\begin{rem}
\label{rem:FullyFaithful}
Appendix \ref{appendix:AFActionsOfUmFCs} proves far more than the fully faithfulness of the unitary tensor functor
$\End(\cM_\cC)\hookrightarrow \Bim(\fM)$ given by $F\mapsto Y^F$.
We may think of $\End(\cM_\cC)$ as one corner of a unitary multifusion category which also includes $\cC,\cM$:
$$
\cE := 
\begin{pmatrix}
\End(\cM_\cC) & \cM
\\
\cM^{\rm op} & \cC
\end{pmatrix}.
$$
Similar to the above construction, we may also embed $\cC$ fully faithfully as $\rmC^*$-Hilbert bimodules over the inductive limit algebra
$$
\fN:=\varinjlim_k \End_\cC(X^{\otimes k}),
$$
and similarly, we can embed $\cM$ fully faithfully as $\fM-\fN$ bimodules.
All told, this produces a fully faithful unitary tensor functor
$$
\cE := 
\begin{pmatrix}
\End(\cM_\cC) & \cM
\\
\cM^{\rm op} & \cC
\end{pmatrix}
\hookrightarrow
\begin{pmatrix}
\Bim(\fM) & \Bim(\fM,\fN)
\\
\Bim(\fN,\fM) & \Bim(\fN)
\end{pmatrix}
=
\Bim(\fM\oplus\fN).
$$
Indeed, one first uses the results of \cite{MR4916103} to fully faithfully embed $\cC$ into $\Bim(\fN)$.
The Q-system realization technique then allows one to boost this embedding into a fully faithful embedding of the unitary multifusion category of $Q-Q$ bimodules ${}_Q\cC_Q$ into $\Bim(|Q|_{\fN})$, the Hilbert $\rmC^*$-bimodules over the realized Q-system.
Choosing $Q=1\oplus \underline{\End}_\cC(W)$ using the unitary internal end \cite{MR4750417,2410.05120}, we have ${}_Q\cC_Q\cong \cE$ and $|Q|_\fN\cong \fM\oplus\fN$, as claimed.

Moreover, we do not need that $\cC$ is fusion nor that $\cM$ is indecomposable; this construction works for arbitrary unitary multifusion $\cC$ and unitary modules $\cM_\cC$.
However, one must choose the unitary module trace on $\cM$ carefully to be compatible with the generator $W\in\cM$.

We refer the reader to Appendix \ref{appendix:AFActionsOfUmFCs} for a more detailed discussion.
\end{rem}

\begin{nota}
For an interval $I\subset \cK$ which meets $\partial \cL$,
we write $\fN_I:=\fM(I^c)$, so that we have a canonical inclusion 
$\iota_I:=1_{\fM(I)}\otimes - :\fN_I\hookrightarrow \fM$.
The algebra $\fN_I$ is the relative commutant of $\fM(I)$ in $\fM$.
Observe that for all $I$, the algebras $\fN_I$ are obviously isomorphic to
$$
\fN:=\varinjlim_k \End_\cC(X^{\otimes k}).
$$
\end{nota}

The algebra $\fM$ is naturally an $\fN_I-\fN_I$ Hilbert $\rmC^*$-bimodule using the Q-system realization technique for the Q-system
$\underline{\End}_\cC(W\lhd X^{\otimes |I|-1})\in\cC$.
Hence ${}_{\fN_I}\fM_{\fN_I}$ lies in the fully faithful image of $\cC \subset \Bim(\fN_I)\cong\Bim(\fN)$.
Moreover, the centralizer
\begin{equation}
\label{eq:FusionModuleBoundaryHaagDuality}
Z_\fM(\fN_I) 
= 
\End_{\fN_{I}-\fM}(\fM)
\cong
\End_\cM(W\lhd X^{\otimes |I|-1})=\fM(I),
\end{equation}
i.e., the fusion module categorical net satisfies boundary algebraic Haag duality.
Again, more details can be found in Appendix \ref{appendix:AFActionsOfUmFCs}.


\begin{thm}
\label{thm:BoundaryLTOforLW}
The category $\DHR^\partial(\fM)$ of boundary DHR bimodules is the essential image of $\End(\cM_\cC)\subseteq \DHR^\partial(\fM)$.
\end{thm}
\begin{proof}
Suppose ${}_\fM Y_\fM\in \DHR^\partial(\fM)$.
Since $Y$ is localized in some boundary interval $I$, by Lemma~\ref{lem:DHRBimoduleCharacterization}, 
the restriction ${}_{\fN_I}Y_\fM=  {}_{\fN_I}\fM\boxtimes_\fM Y_\fM$ is isomorphic to a summand of a finite direct sum of copies of ${}_{\fN_I}\fM_\fM$, which lies in the essential image of $\cE$ in $\Bim(\fM\oplus \fN_I)$.
The result now follows by Lemma~\ref{lem:2outof3},
as each of ${}_{\fN_I} Y_{\fM}$ and ${}_{\fN_I}\fM_\fM$ lie in $\cE\subset \Bim(\fM\oplus \fN_I)$.
\end{proof}


