\node at (1,.5) {$f$};
}
\longmapsto
\tikzmath{
\foreach \y in {0,1,2}{
\foreach \x in {0,1,2}{
\draw[red, thick] (\x,\y) -- ($ (\x,\y) + (.2,-.2) $);
\filldraw[red] ($ (\x,\y) + (.2,-.2) $) circle (.05cm);
