\draw[blue,thick,->] (\x,.5) to[out=-30,in=-90] 
($ (8,2) - (\x,0) $);
}
\foreach \y in {1,1.5,2}{
\draw[blue,thick,->] (.5,\y) to[out=-30,in=-90] 
($ (6.5,2) - (\y,0) $);
\foreach \x in {1,1.5,2}{
\draw[red,thick,->] (\x,\y) to[out=-30,in=-90] 
($ 3*(\y,0)+(\x,0) + (4,2) $);
}
}
\draw[thick, cyan] (.75,2.25) -- (.75,.75) -- (2.25,.75);
\draw[thick, cyan] (7.75, 2.25) -- (7.75,1.75);
\node[cyan] at (1.25,1.25) {$\Lambda$};
%
