\draw (-.3,-.3) -- (-.3,-.7);
\node at (.03,-.5) {$\cdots$};
\draw (.3,-.3) -- (.3,-.7);
\draw[cyan] (0,1.3) node[right,yshift=.2cm]{$\scriptstyle x$} arc(0:180:.5cm and .3cm) --node[left]{$\scriptstyle x^\vee$} (-1,-1.3) arc(-180:0:.5cm and .3cm) node[right,yshift=-.2cm]{$\scriptstyle x$};
