Observe that the above equality is compatible with adding strands to the right, i.e., taking inductive limits in $\fA(\Lambda)$.
The result follows.
\end{proof}

\begin{lem}
\label{lem:IrreducbleConeAlgebraRepresentation}
For a cone $\Lambda$, let $\cK_x(\Lambda):=\varinjlim \cK_x(\Lambda_n)$ for $\Lambda_n$ bounded contractible regions which increase to $\Lambda$.
The action of $\fA(\Lambda)$ on $\cK_x(\Lambda)$ is irreducible.
\end{lem}
\begin{proof}
Set $\cL_1:=\cK_x(\Lambda_1)$, and inductively define $\cL_{n+1}:=\cK_x(\Lambda_{n+1})\ominus \cK_x(\Lambda_n)$.
Now $\cK_x(\Lambda)=\bigoplus \cL_n$, and we may choose an ONB $B_n$ for each $\cL_n$, and observe that the ONBs for $m\neq n$ are orthogonal.
Moreover, for all $f,g\in B_n$, observe that
$g^\dag\circ f = \delta_{g=f} d_x^{-1} \cdot \id_x$.

We now observe that we can form a system of matrix units for the ONB $\bigcup B_n$ of $\cK_x(\Lambda)$ which lie in $\bigcup \fA(\Lambda_n)\subset \fA(\Lambda)$.
That is, for $f\in B_m$ and $g\in B_n$ with $m\leq n$, we define 
$$
e_{fg}
:=
\begin{cases}
d_x\cdot (f\otimes i_X^{\otimes n-m})g^\dag
&
\text{if }m<n
\\
d_x\cdot fg^\dag
&
\text{if }m=n
\\
d_x\cdot f(g\otimes i_X^{\otimes m-n})^\dag
&
\text{if }m>n,
\end{cases}
$$
which lies in $\fA(\Lambda_{\max\{m,n\}})$.
The result follows.
\end{proof}

\begin{thm}
\label{thm:BraidedCategoricalNetHaagDuality}
The net of von Neumann algebras $(A_\Lambda)$ satisfies Haag duality.
Moreover, each cone algebra $A_\Lambda$ is a finite direct sums of type $\rm I_\infty$ factors, with one summand for each simple object in the full fusion subcategory of $\cB$ generated by $X$.
\end{thm}
\begin{proof}
Consider $A_\Lambda$ acting in the ground state representation
$L^2(\fA,\psi)\cong \cK_{1_\cB}$.
Let $\Delta_n$ be an increasing family of rectangles where $\bigcup \Delta_n$ covers the entire lattice,
such that $\Delta_n\cap \Lambda = \Lambda_n$.
By semisimplicity,
\begin{align*}
\cK_x(\Delta_n) 
&=
\cB(1_\cC\to X^{\otimes \Delta_n})
\\&\cong
\cB(\overline{X}^{\otimes\Delta_n\setminus\Lambda} \to X^{\otimes \Lambda_n})
\\&\cong
\bigoplus_{x\in \Irr\langle X\rangle} \cB(\overline{X}^{\otimes\Delta\setminus\Lambda} \to x)\otimes \cB(x\to X^{\otimes \Lambda_n})
\\&=
\bigoplus_{x\in \Irr\langle X\rangle} \cB(\overline{X}^{\otimes\Delta_n\setminus\Lambda} \to x)\otimes \cK_x(\Lambda_n)
\\&\cong
\bigoplus_{x\in \Irr\langle X\rangle} \cB(x^\vee\to X^{\otimes\Delta_n\setminus\Lambda})\otimes \cK_x(\Lambda_n)
\\&\cong
\bigoplus_{x\in \Irr\langle X\rangle} \cK_{x^\vee}(\Delta_n\setminus\Lambda)\otimes \cK_x(\Lambda_n)
\end{align*}
(There is a subtlety with the inner product on each summand above where one normalizes by $d_X$ as in the proof of Lemma \ref{lem:IrreducbleConeAlgebraRepresentation}, but this normalization does not affect the rest of this argument.)
One may visualize this isomorphism as splitting each map as follows.
$$
\tikzmath{
\draw (-.3,.3) --node[left]{$X^{\otimes \Delta_n\setminus\Lambda}$} (-.3,.7);
\draw (.3,.3) --node[right]{$X^{\otimes \Lambda_n}$} (.3,.7);
\roundNbox{}{(0,0)}{.3}{.3}{.3}{$f$}
}
=
\sum_{x\in\Irr\langle X\rangle}\sum_{i=1}^{n_x}
\tikzmath{
\draw (0,.3) --node[left]{$X^{\otimes \Delta_n\setminus\Lambda}$} (0,.7);
\draw (1,.3) --node[right]{$X^{\otimes \Lambda_n}$} (1,.7);
\draw[thick, cyan] (0,-.3) node[left,yshift=-.2cm]{$\scriptstyle x^\vee$} arc(-180:0:.5cm) node[right,yshift=-.2cm]{$\scriptstyle x$};
\roundNbox{}{(0,0)}{.3}{0}{0}{$f_x^i$}
\roundNbox{}{(1,0)}{.3}{0}{0}{$g_x^i$}
}
$$
The $\fA(\Lambda_n)$-action is by post-composition on the Hilbert space $\cB(x\to X^{\otimes \Lambda_n})=\cK_x(\Lambda_n)$,
and each space $\cK_{x^\vee}(\Delta_n\setminus\Lambda)$ acts as a multiplicity space for the $\fA(\Lambda_n)$ action.
Observe that the left $\fA(\Lambda_n)$-action may never change the internal label $x\in\Irr\langle X\rangle$, and we thus see that $\cK_{1_\cB}$ decomposes as an $\fA(\Lambda)$-representation as 
$$
\bigoplus_{x\in\Irr\langle X\rangle} \cK_{x^\vee}(\Lambda^c) \otimes \cK_x(\Lambda).
$$
We know that the action of $\fA(\Lambda)$ on each $\cK_x(\Lambda)$ is irreducible, so $A_\Lambda\cong \bigoplus_{x\in\Irr\langle X\rangle} B(\cK_x(\Lambda))$ is a finite direct sum of type $\rmI_\infty$ factors as claimed.
The commutant is clearly the action by $\fA(\Lambda^c)$ on the multiplicity spaces.
\end{proof}

Thus our net of von Neumann algebras $(A_\Lambda)$ is isotone, properly infinite, and satisfies Haag duality.
By \cite[Thm.~A]{2410.21454}, we have a well-defined braided $\rmW^*$-tensor category $\mathsf{SSS}(A)$ of superselection sectors.
We now characterize the underlying $\rmW^*$-category of $\mathsf{SSS}(A)$.
Clearly the map $z\mapsto \cK_z$ is a unitary functor $\langle X\rangle^{\rm op} \to \mathsf{SSS}(A)$, as precomposition with $f\in \cB(x\to y)$ commutes with post-composition by $\End_\cB(X^{\otimes\Lambda})$.


\begin{thm}
\label{thm:SSSforBraidedCategoricalNet}
The functor $\Hilb\langle X\rangle^{\rm op}\ni z\mapsto \cK_z \in \mathsf{SSS}(A)$ is a unitary equivalence of $\rmW^*$-categories.
\end{thm}
\begin{proof}
As with the above results, as we are ignoring the fusion and braiding, it suffices to consider the case of a 1D fusion spin system.
The result then follows by \cite[Const.~6.13 and Thm.~6.14]{2307.12552} (ignoring the module-action there, as we only care about the category itself).
\end{proof}

We leave the identification of the braiding and fusion of $\mathsf{SSS}(A)$ with that of $\Hilb\langle X\rangle$ to a future article.


