\subsection{Bounded spread isomorphism to edge-restricted Levin-Wen operators}
\label{sec:BoundedSpreadIso}

\begin{nota}
For a region $\Lambda$, $\Lambda^{+s}$ is the smallest region containing all lattice points of distance at most $s$ away from $\Lambda$.
When $\Lambda$ is a rectangle, $\Lambda^{+s}$ is another rectangle.
When $\Lambda$ is a cone, $\Lambda^{+s}$ means the cone obtained from $\Lambda$ by moving the boundaries of the cone perpendicularly by $s$ to obtain a larger cone.

Even though our $\bbZ^n$ lattice is discrete, since $\bbZ^n\subset \bbR^n$, we say a region $\Lambda\subset \cL$ is \emph{contractible} if the union of all edges and plaquettes contained in $\Lambda$ is contractible in $\bbR^n$.
\end{nota}

\begin{defn}
Suppose $\fA$ and $\fB$ are two nets of finite dimensional $\rm C^*$-algebras on the same lattice.
A \emph{bounded spread isomorphism} $\alpha:\fA\to \fB$ is a $*$-algebra isomorphism between the quasi-local algebras such that there is a universal constant $s>0$ called the \emph{spread} such that $\alpha(\fA(\Lambda)) \subset \fB(\Lambda^{+s})$ 
and
$\alpha^{-1}(\fB(\Lambda)) \subset \fA(\Lambda^{+s})$ 
for all bounded contractible $\Lambda$.
\end{defn}

One utility of bounded spread isomorphism between nets of algebras is that bounded spread Haag duality for one net implies the same for the other \cite[Prop.~5.10]{2410.21454} in a given state.
Thus the two nets of algebras have isomorphic braided $\rmW^*$-tensor categories of superselection sectors \cite[Thm.~C]{2410.21454}.

\begin{ex}[Intertwined nets of algebras]
Suppose $\fA,\fB$ are two nets of finite dimensional $\rmC^*$-algebras on the same lattice.
We say that $\fA$ and $\fB$ are \emph{intertwined with spread $t>0$} if $\fA(\Lambda)\subseteq \fB(\Lambda^{+t})$ and $\fB(\Lambda)\subseteq \fA(\Lambda^{+t})$ for all bounded contractible $\Lambda$. 
Choosing increasing finite rectangles whose union is all of $\cL$, we see that we have an \emph{equality} of quasi-local algebras $\fA=\fB$, and the identity map is manifestly bounded spread.
\end{ex}

\begin{subex}[{\cite[\S~IV.E]{MR4808260}}]
\label{subex:EdgeRestricted}
Consider the \emph{edge restricted local Hilbert spaces} of the Levin-Wen model for a UFC $\cC$ given by $p^A_\Lambda\bigotimes_{v\in\Lambda} \cH_v$ where $p^A_\Lambda:=\prod_{\ell\in \Lambda} A_\ell$.
It was shown in \cite[Prop.~2.6]{2305.14068} that
$$
p^A_\Lambda\bigotimes_{v\in\Lambda} \cH_v
\cong
\cC(X^{\partial \Lambda} \to F(A)^{\# p\in\Lambda})
\cong
Z(\cC)(\Tr(X^{\partial \Lambda}) \to A^{\#p\in \Lambda}),
$$
where $X^{\partial \Lambda}$ is the tensor product of our generator $X=\bigoplus_{c\in\Irr(\cC)}c$ over the number of edges in $\partial \Lambda$, $A\in Z(\cC)$ is the canonical Lagrangian algebra given by $A=I(1)$ where $\Tr: \cC\to Z(\cC)$ is the unitary adjoint \cite[\S2.1]{MR4750417} of the forgetful functor $F: Z(\cC)\to \cC$, and $\#p\in \Lambda$ is the number of plaquettes in $\Lambda$.

We now consider two nets of algebras.
The first is given by 
$$
\fA(\Lambda):= \End_{Z(\cC)}(A^{\#p\in \Lambda}),
$$
which is exactly the commutant of 
$\End_{Z(\cC)}(\Tr(X^{\otimes \partial \Lambda}) )$
on the above Hilbert space by Lemma~\ref{lem:SemisimpleCommutation}.
Indeed, $X$ contains all simples in $\cC$, so $\Tr(X^{\otimes \partial \Lambda})$ contains all simples in $Z(\cC)$.
It is worth mentioning that $\End_{Z(\cC)}(\Tr(X^{\otimes \partial \Lambda}) )$ is Morita equivalent to Ocneanu's tube algebra, which is given by
$$
\bigoplus_{a,b,c\in\Irr(\cC)} \cC(ac\to cb)
\cong
\bigoplus_{a,b,c\in\Irr(\cC)} \cC(a\to cbc^\vee)
\cong
\cC(X\to F(\Tr(X))
\cong
\End_{Z(\cC)}(\Tr(X)).
$$
Indeed, we define the algebra
$$
\Tube_\cC(\partial\Lambda)
=
\left\{
\tikzmath{
