\filldraw[thick, fill=red!30] ($ (\x,\y) + (.2,0) $) ellipse (.2 and .1);
}}
\filldraw[thick, rounded corners=5pt, fill=gray!50, opacity=.8] (.1,.8) rectangle (2.9,3.4);
\foreach \x in {.3,1.3,2.3}{
\foreach \y in {1.1,2.1,3.1}{
\filldraw[white, opacity=.8] ($ (\x,\y) $) arc(-180:0:.2 and .1) -- ($ (\x,\y) + (.4,.4) $) -- ($ (\x,\y) + (0,.4) $);
