\draw (0,-.5) node[below]{$\scriptstyle X$} -- (0,.5) node[above]{$\scriptstyle X$};
}\,
\end{equation}
is an isomorphism.

Since $\cC$ is unitary multifusion, by \cite{MR4133163}, there is a faithful \emph{spherical weight} $\psi: \cC(1_\cC\to 1_\cC)\to \bbC$ such that
$$
\psi\left(
\tikzmath{
\draw (0,.3) arc(180:0:.3cm) --node[right]{$\scriptstyle c^\vee$} (.6,-.3) arc(0:-180:.3cm);
\roundNbox{}{(0,0)}{.3}{0}{0}{$f$}
}
\right)
=
\psi\left(
\tikzmath{
\draw (0,.3) arc(0:180:.3cm) --node[left]{$\scriptstyle c^\vee$} (-.6,-.3) arc(-180:0:.3cm);
\roundNbox{}{(0,0)}{.3}{0}{0}{$f$}
}
\right)
\qquad\qquad\qquad
\forall\,f:c\to c,
\quad
\forall\,c\in\cC,
$$
which is unique subject to the normalization
$\psi(\id_{1_+})=\psi(\id_{1_-})=1$.
This means that $\Tr^\cC:=\psi\circ \tr_L^\vee = \psi\circ \tr_R^\vee$ is a unitary trace on $\cC$ which equips it with the structure of a \emph{2-Hilbert space} in the sense of \cite{MR1448713}.
Each hom space $\cC(a\to b)$ is equipped with a Hilbert space structure given by
$$
\langle f| g\rangle_{a\to b}:= 
\Tr^\cC_a(f^\dag\circ g)
=
\Tr^\cC_b(g\circ f^\dag)
$$
which satisfies that for all $f:a\to b$, $g:b\to c$, and $h: a\to c$,
$$
\langle g| h\circ f^\dag\rangle_{b\to c}
=
\langle g\circ f| h\rangle_{a\to c}
=
\langle f| g^\dag\circ h\rangle_{a\to b}.
$$

\begin{construction}
One now constructs two AF $\rmC^*$-algebras as follows.
First, we write
$$
X^{\alt\otimes n}:= \underbrace{X\otimes X^\vee \otimes X\otimes \cdots X^?}_{n\text{ tensorands}}
\qquad\qquad\text{and}\qquad\qquad
(X^\vee)^{\alt\otimes n}:= \underbrace{X^\vee\otimes X \otimes X^\vee\otimes \cdots X^?}_{n\text{ tensorands}}
$$
where the question marks are determined by parity of $n$.
We define
$$
A_n:= \End_\cC(X^{\alt \otimes n})
\qquad\qquad\text{and}\qquad\qquad
B_n:=\End_\cC((X^\vee)^{\alt\otimes n}).
$$
We have the inductive limit AF algebras $A:=\varinjlim A_n$ and $B:=\varinjlim B_n$,
where the inclusions are always given by tensoring by identities on the right, i.e., taking inductive limit over the map
$$
-\otimes \id:
\tikzmath{
\draw[cyan, dashed] (0,.7) -- (0,-.7);
\draw[cyan,->] (-.15,.5) -- (.15,.5);
\draw[cyan,->] (-.15,-.5) -- (.15,-.5);
\draw (-.7,0) node[left]{$\scriptstyle n$} -- (-.3,0);
\draw (.7,0) node[right]{$\scriptstyle n$} -- (.3,0);
\roundNbox{fill=white}{(0,0)}{.3}{0}{0}{$\eta$}
}
\,
\longmapsto
\,
\tikzmath{
\draw[cyan, dashed] (0,.7) -- (0,-.7);
\draw[cyan,->] (-.15,.5) -- (.15,.5);
\draw (-.7,-.5) -- (.7,-.5);
\draw (-.7,0) node[left]{$\scriptstyle n$} -- (-.3,0);
\draw (.7,0) node[right]{$\scriptstyle n$} -- (.3,0);
\roundNbox{fill=white}{(0,0)}{.3}{0}{0}{$\eta$}
}
$$
Here, a strand labeled $n$ denotes $X^{\alt\otimes n}$ or $(X^\vee)^{\alt\otimes n}$,
and the single strand represents either $X$ or $X^\vee$ depending on the parity of $n$.
The top string is always $X$ for $A$ and $X^\vee$ for $B$.
As the map \eqref{eq:ZEndXIso} is an isomorphism, we see that 
$Z(A)\cong \End_\cC(1_+)$ and $Z(B)\cong \End_\cC(1_-)$.
This also relies on the fact that eventually the Bratteli diagrams for $A,B$ are stationary \cite[Thm.~4.1.4]{MR999799} (see also \cite[\S3.1]{MR4227743}).
The inclusion $A\subset B$ is obtained by taking the inductive limit of the map $\id_{X^\vee}\otimes -:A_n\hookrightarrow B_{n+1}$ given by
$$
\tikzmath{
\draw[cyan, dashed] (0,.7) -- (0,-.7);
\draw[cyan,->] (-.15,.5) -- (.15,.5);
\draw[cyan,->] (-.15,-.5) -- (.15,-.5);

\draw (-.7,0) node[left]{$\scriptstyle n$} -- (-.3,0);
\draw (.7,0) node[right]{$\scriptstyle n$} -- (.3,0);
\roundNbox{fill=white}{(0,0)}{.3}{0}{0}{$\eta$}
}
\,
\longmapsto
\,
\tikzmath{
\draw[cyan, dashed] (0,.7) -- (0,-.7);
\draw[cyan,->] (-.15,-.5) -- (.15,-.5);
\draw (-.7,.5) -- (.7,.5);
\draw (-.7,0) node[left]{$\scriptstyle n$} -- (-.3,0);
\draw (.7,0) node[right]{$\scriptstyle n$} -- (.3,0);
\roundNbox{fill=white}{(0,0)}{.3}{0}{0}{$\eta$}
}\,.
$$

Now on $A_n$, we can define a faithful tracial state by $\tr_n:= d_X^{-n}\Tr^\cC$, and similarly for $B_n$.
(The normalization for $\psi$ ensures that $\tr_n(1)=1$ for all $n$ for both $A$ and $B$.)
Note that the inclusions 
$A_n\hookrightarrow A_{n+1}$
and
$A_n\hookrightarrow B_{n+1}$
are both trace preserving.
We can thus complete $A,B$ to $\rm II_1$ \emph{multifactors} (direct sums of $\rm II_1$ factors) $\cA,\cB$ by using the GNS construction with respect to $\tr:=\varinjlim \tr_n$,
which yields a homogeneous connected finite index inclusion whose standard invariant $(\cC(\cA\subset \cB), {}_\cA L^2\cB_\cB)$ is unitarily equivalent to $(\cC,X)$ \cite[Prop.~6.5]{MR4916103}.
These results rely on Popa's generating tunnel for finite depth inclusions \cite{MR1055708}
and the Ocneanu Compactness Theorem \cite{MR1473221}, \cite[\S11.4]{MR1642584}, generalized to the multifactor setting \cite[Appendices B and C]{MR4916103}. 
To see this, one performs Jones' basic construction to get a tower of multifactors equipped with traces
$$
\cA_0:=\cA \subset \cB:=\cA_1 
\overset{e_1}{\subset} 
\cA_2 
\overset{e_2}{\subset} 
\cA_3
\subset \cdots
$$
and the \emph{higher relative commutants} can be identified with endomorphism spaces in $\cC$ as follows \cite{MR1424954}:
\begin{equation}
\label{eq:HigherRelativeCommutants}
\begin{aligned}
\cA_0' \cap \cA_{2k} 
&\cong 
\End_{\cA-\cA}(L^2\cB^{\boxtimes_\cA k})
\cong 
\End_\cC((X\otimes X^\vee)^{\otimes k})
\\
\cA_0' \cap \cA_{2k+1} 
&\cong 
\End_{\cA-\cB}(L^2\cB^{\boxtimes_\cA k+1})
\cong 
\End_\cC((X\otimes X^\vee)^{\otimes k}\otimes X)
\\
\cA_1' \cap \cA_{2k+1} 
&\cong 
\End_{\cB-\cB}(L^2\cB^{\boxtimes_\cA k})
\cong 
\End_\cC((X^\vee\otimes X)^{\otimes k+1})
\\
\cA_1' \cap \cA_{2k+2} 
&\cong 
\End_{\cB-\cA}(L^2\cB^{\boxtimes_\cA k+1})
\cong 
\End_\cC((X^\vee\otimes X)^{\otimes k}\otimes X^\vee).
\end{aligned}
\end{equation}
We thus get a unitary tensor functor into $\Bim(\cA\oplus \cB)$ from the full subcategory $\cC_0\subset \cC$ whose objects are of the form $X^{\alt\otimes n}$ and $(X^\vee)^{\alt\otimes n}$.
We then use the universal property of unitary idempotent completion to uniquely extend the functor to
$$
\cF:\cC
=
\begin{pmatrix}
\cC_{++} & \cC_{+-}  
\\
\cC_{-+} & \cC_{--}
\end{pmatrix}
\hookrightarrow
\begin{pmatrix}
\Bim(\cA) & \Bim(\cA,\cB)
\\
\Bim(\cB,\cA) & \Bim(\cB)
\end{pmatrix}
=
\Bim(\cA\oplus \cB).
$$

There are also uniqueness results in \cite{MR4916103}, but these are not necessary for the results in this article.
\end{construction}

