\node at (.23,.5) {$\scriptstyle \cdots$};
\draw (.4,.3) -- (.4,.7);
\draw (0,-.3) -- (0,-.7);
\node at (.23,-.5) {$\scriptstyle \cdots$};
\draw (.4,-.3) -- (.4,-.7);
\roundNbox{}{(0,0)}{.3}{.3}{.3}{$y$}
}
\,=
\tikzmath{
\fill[gray!50] (-.2,.7) -- (-.2,.3) -- (-.4,.3) arc(0:180:.2cm) -- (-.8,-.7) -- (-1,-.7) -- (-1,.7);
\draw[thick, blue] (-.4,.3) arc(0:180:.2cm) -- (-.8,-.7);
\draw[thick, blue] (-.2,.3) -- (-.2,.7);
\draw[thick, blue] (-1,-.7) -- (-1,.7);
\draw (0,.3) -- (0,.7);
\node at (.23,.5) {$\scriptstyle \cdots$};
\draw (.4,.3) -- (.4,.7);
\draw (0,-.3) -- (0,-.7);
\node at (.23,-.5) {$\scriptstyle \cdots$};
\draw (.4,-.3) -- (.4,-.7);
\draw (0,-1.3) -- (0,-1.7);
\node at (.23,-1.5) {$\scriptstyle \cdots$};
\draw (.4,-1.3) -- (.4,-1.7);
\roundNbox{}{(0,0)}{.3}{.3}{.3}{$x$}
\roundNbox{}{(0,-1)}{.3}{.9}{.3}{$y$}
}
$$
The main problem here is that the choice of cap above depends on a choice of unitary duality for $\cE$.
Moreover, one must use the notion of \emph{unitary internal end} in order for $\underline{\End}_\cM(W)$ to define an honest element of $\cC$ and not just the underlying multifusion category $\cC^{\natural}$ where we have forgotten the dagger structure. 
Both of these goals can be accomplished by endowing $\cM$ with a carefully chosen \emph{unitary module trace} as in \S\ref{sec:BoundaryLTOforBoundaryLW}, which allows one to use \emph{unitary adjunction} \cite[\S2.1]{MR4750417} to constuct the unitary itnernal hom as in \cite[\S3.3]{2410.05120}.
Indeed, when $\cM$ is indecomposable,  $\End(\cM_\cC)$ is fusion, so the bubble for $W$ is always a positive scalar.
There is thus a unique unitary module trace such that the $W$-bubble is equal to one.\footnote{This is entirely analogous to the situation of an operator $T: H\to K$ such that $T^*T=r 1_H$ for some $r>0$.
We can uniquely rescale the inner product on $H$ so that $T$ becomes unitary.}
For an arbitrary module, there is a unique faithful convex combination of traces on the indecomposable summands so that the bubble for $W$ in $\End(\cM_\cC)$ equals one. 
This immediately implies that $|\underline{\End}_\cC(W)|$ is a (special) Q-system
$$
\tikzmath{
\fill[gray!50] (-.2,-.7) to[out=90,in=-90] (-.6,0) to[out=90,in=-90] (-.2,.7) -- (.2,.7) to[out=-90,in=90] (.6,0) to[out=-90,in=90] (.2,-.7);
\draw[thick, blue] (-.2,-.7) to[out=90,in=-90] (-.6,0) to[out=90,in=-90] (-.2,.7);
\draw[thick, blue] (.2,-.7) to[out=90,in=-90] (.6,0) to[out=90,in=-90] (.2,.7);
\filldraw[thick, blue, fill=white] (0,0) circle (.3cm);
}
\,\,
=
\,\,
\tikzmath{
\fill[gray!50] (-.2,-.7) rectangle (.2,.7);
\draw[thick, blue] (-.2,-.7) -- (-.2,.7);
\draw[thick, blue] (.2,-.7) -- (.2,.7);
}
\,\,
=
\id_{\underline{\End}_\cC(W)},
$$
and we thus get an isomorphism $B\cong |\underline{\End}_\cC(W)|$.

Now by \cite[Cor.~C]{MR4419534}, we have a fully faithful tensor functor $\End(\cM_\cC)\hookrightarrow \Bim(B)$.
Unpacking as in Example \ref{ex:MoreDetailForFF-AF-Action} above, 
for $F\in \End(\cM_\cC)$,
we obtain exactly the DHR bimodules $Y^F:=\varinjlim Y^F_n$ where
$$
Y^F_n := \cM(W\lhd X^{\otimes n} \to FW\lhd \otimes X^{\otimes n})
$$
for the boundary algebra $\fB=B=\varinjlim \End_\cM(W\lhd X^{\otimes n})$ from \S\ref{sec:BoundaryDHRforBoundaryLW} above.

One can also repeat the above analysis for the Q-system $1\oplus |\underline{\End}_\cC(W)| \in\cC$ in order to obtain a fully faithful tensor functor 
$$
\cE = 
\begin{pmatrix}
\End(\cM_\cC) & \cM
\\
\cM^{\rm op} & \cC
\end{pmatrix}
\hookrightarrow
\begin{pmatrix}
\Bim(B) & \Bim(B,A)
\\
\Bim(A,B) & \Bim(A)
\end{pmatrix}
=
\Bim(B\oplus A).
$$
\end{ex}



