\section{Preliminaries on the direct problem}\label{sec:direct}
In this section, we develop several key analytic properties of the direct problem \eqref{eq:2D3D:ibvp}, which play a crucial role in the analysis of the inverse problem in Section \ref{sec:inverse}. The first result gives the well-posedness of the direct problem.
\begin{theorem}
\label{theorem:analyticity}
Under Assumptions \ref{ass:alpha:basic} and \ref{ass:g}, problem \eqref{eq:2D3D:ibvp} is well-posed, the solution $U(t,\cdot)$ is analytic in time $t$, and its Laplace transform $\widehat{U}(p,\cdot):=\int_0^\infty U(t.x)e^{-pt}\d t$ is in $H^2(\Omega)$ for all $p>0$.
\end{theorem}
\begin{proof}
The well-posedness of problem \eqref{eq:2D3D:ibvp} can be deduced by combining the argument of \cite[Proposition 3.1]{Kian:2018:TFD} with \cite[p. 16]{Ki1} in a similar way to \cite[Theorem 3.1]{HJK:2025:ISDVO}, where the result was stated in the one-dimensional case. The time analyticity is direct from \cite[Lemma 3.2]{Kian:2018:TFD}.
\end{proof}

\begin{remark}[Regularity of $\widehat{U}$]
\label{remark:Uhat:C1lambda}
The Laplace transform $\widehat{U}(p,\cdot)$ of $U(t,\cdot)$ satisfies, for $p>0$,
\begin{equation}\label{eq:afterLaptrans}
\left\{\begin{aligned}
- \nabla \cdot( \sigma(x) \nabla\widehat{U}(p,x)) + (q(x) + \rho(x) p^{\alpha(x)})\widehat{U}(p,x)=0,&\quad\mbox{in } \Omega,\\
\widehat{U}(p,x)=\widehat{g}(p,x),&\quad\mbox{on }\partial\Omega.
\end{aligned}\right.
\end{equation}
Fix any $p>0$.
There holds $\widehat{U}(p,\cdot)\in W^{2,r}(\Omega)$, in view of \cite[Theorem 2.4.2.5]{Grisvard:1985:EPND} and the following properties: $\partial\Omega$ is of class $C^{1,1}$, $\sigma(x)\in C^{1}(\overline{\Omega})$, and for each $p>0$, $q(x)+\rho(x) p^{\alpha(x)}$ is nonnegative, bounded and measurable under the given conditions on $q$ and $\rho$. Moreover, Assumption \ref{ass:g} implies
\begin{equation*}
\widehat{g}(p,\cdot)=\sum_{k=2}^N k!p^{-k-1} \varphi_k(\cdot)\in W^{2-\frac{1}{r},r}(\partial\Omega).
\end{equation*}
By the Sobolev embedding theorem for  domains satisfying the strong local Lipschitz condition \cite[Part II of Chapter 4.12]{Adams:2003:SS}, $\widehat{U}(p,\cdot)\in W^{2,r}(\Omega)\hookrightarrow C^{1,r_0}(\overline{\Omega})$ for all $0<r_0\le 1-\frac{d}{r}$.
\end{remark}

\subsection{Representations for $\widehat{U}$ and $\p_\nu  \widehat{U}$}

Let the coefficients $\rho$, $\sigma$ and $q$ satisfy the stated conditions. Then we define an elliptic operator $\mathcal{A}$ on $W^{2,r}(\Omega)$ by
$$\mathcal{A}[v](x):=\rho(x)^{-1}(-\nabla\cdot(\sigma(x)\nabla v(x))+q(x)v(x)),\quad\forall  v\in W^{2,r}(\Omega).$$
\begin{lemma}\label{lemma:iso:Apluspalpha}
For each fixed $p\geq 0$, the map $u\mapsto((\mathcal{A}+p^{\alpha})u,u|_{\partial\Omega})$ defines an isomorphism from $W^{2,r}(\Om)$ onto $L^{r}(\Om)\times W^{2-1/r,r}(\partial\Omega)$.
\end{lemma}
\begin{proof}
By \cite[Theorem 2.4.2.5 and Remark 2.5.1.2]{Grisvard:1985:EPND}), $u\mapsto(\rho(\mathcal{A}+p^{\alpha})u,u|_{\partial\Omega})$ defines an isomorphism from $W^{2,r}(\Om)$ onto $L^{r}(\Om)\times W^{2-1/r,r}(\partial\Omega)$.
Since $\rho$ is bounded from below and above by positive numbers, the same assertion holds for the map $u\mapsto((\mathcal{A}+p^{\alpha})u,u|_{\partial\Omega})$.
\end{proof}

By Lemma \ref{lemma:iso:Apluspalpha} and Poincar\'{e}'s inequality, we have
$$\|u\|_{W^{2,r}(\Om)}\le C\|(\mathcal{A}+p^{\alpha})u\|_{L^r(\Om)},\quad\forall u\in H_0^1(\Om)\cap W^{2,r}(\Om),$$
where the constant $C$ is independent of $p$.
Below we denote by $\mathbb A_r$ the unbounded operator acting on $L^r(\Omega)$ with its domain $D(\mathbb A_r)=H_0^1(\Om)\cap W^{2,r}(\Om)$ defined by
$$\forall v\in D(\mathbb A_r),\quad \mathbb A_rv=\mathcal A v.$$
From Lemma \ref{lemma:iso:Apluspalpha}, we deduce that, for all $p\geq0$, $(\mathbb A_r+p^{\alpha})^{-1}$ is well-defined as a  bounded linear map from $L^{r}(\Om)$ to $H_0^1(\Om)\cap W^{2,r}(\Om)$.
We also define the solution operator $\mathcal{S}:W^{2-1/r,r}(\partial\Omega)\to W^{2,r}(\Om)$ by $v_0\mapsto v$ for the unique solution $v$ of the following boundary value problem (see Lemma \ref{lemma:iso:Apluspalpha} with $p=0$):
\begin{equation}\label{eq:S:bvp:wholedomain}
\left\{
\begin{aligned}
-\nabla\cdot(\sigma\nabla v) + q v&=0,\quad \mbox{in }\Om,\\
v&=v_0,\quad\mbox{on }\partial\Omega.
\end{aligned}
\right.
\end{equation}

Now we can give an important solution representation. Let $\widehat{U}(p,x)$ be the Laplace transform of $U(t,x)$ in time $t$.
By Remark \ref{remark:Uhat:C1lambda}, we have $\widehat{U}(p,\cdot)\in W^{2,r}(\Omega)\hookrightarrow C^{1,r_0}(\overline{\Omega})$ for all $p>0$.
The next lemma can be alternatively stated as an eigenfunction expansion; see \cite[Lemma 3.2]{HJK:2025:ISDVO} for a piecewise constant $\alpha$ in the one-dimension case. Below the notation id denotes the identity operator.
\begin{lemma}
\label{lemma:representation:resolvents}
Fix any $p>0$. Under Assumption \ref{ass:alpha:basic}, we have
\begin{align}
\widehat{U}(p,\cdot)&=\left({\rm id}-(\mathbb A_r+p^{\alpha})^{-1}p^{\alpha}\right)\mathcal{S}[\widehat{g}(p,\cdot)],\quad\mbox{in }\Om,
\label{eq:Uhat:repr}
\end{align}
where $(\mathbb A_r+p^{\alpha})^{-1}$ is a bounded linear operator from $L^{r}(\Omega)$ to $H_0^1(\Omega)\cap W^{2,r}(\Omega)$.
Moreover, for all $0<r_0\le 1-\frac{d}{r}$, there holds
\begin{equation}\label{eq:normalder:Uhat}
 \p_\nu \widehat{U}(p,\cdot)\big|_{\partial\Omega}=
\p_\nu \left({\rm id}-(\mathbb A_r+p^{\alpha})^{-1}p^{\alpha}\right)\mathcal{S}[\widehat{g}(p,\cdot)]\big|_{\partial\Omega}\in C^{0,r_0}(\partial\Omega).
\end{equation}
%    where $\Gamma=\{x\in\partial\Omega\,:\,|x-x_0|<\varepsilon\}$ and $\Gamma=\partial\Omega$ under Assumptions \ref{ass:alpha:basic} (ii) and (iii), respectively.
\end{lemma}
\begin{proof}
From the relations $\mathcal{A}\mathcal{S}\widehat{g}(p,\cdot)=0$ and $(\mathcal{A}+p^{\alpha})\widehat{U}(p,\cdot)=0$ in $\Om$, we obtain
$$(\mathcal{A}+p^{\alpha})\left[\widehat{U}(p,\cdot) - \mathcal{S}\widehat{g}(p,\cdot)\right] = -p^{\alpha}\mathcal{S}[\widehat{g}(p,\cdot)],\quad\mbox{in }\Omega.$$
This identity, the relation $\widehat{U}(p,\cdot) - \mathcal{S}\widehat{g}(p,\cdot)\in H_0^1(\Omega)$ and Lemma \ref{lemma:iso:Apluspalpha} imply the desired identity \eqref{eq:Uhat:repr}.
The Sobolev embedding $W^{2,r}(\Om)\hookrightarrow C^{1,r_0}(\overline{\Omega})$ \cite[Part II of Chapter 4.12]{Adams:2003:SS} shows the H\"{o}lder continuity of the normal derivative $\p_\nu \widehat{U}(p,\cdot)\big|_{\partial\Omega}$.
\end{proof}

\subsection{Asymptotic expansions}
Now we present two asymptotic expansions of the normal derivative $\p_\nu \widehat{U}(p,\cdot)$  using the expression \eqref{eq:normalder:Uhat}, one as $p\to 0^+$, and one near $p=1$. These two expansions provide crucial technical tools for establishing the unique and stability results stated in Section \ref{sec:main}.
The asymptotic expansion is based on the following Neumann series expansion.

\begin{lemma}\label{lemma:neumannseries}
Fix any $N\in\mathbb{N}$. There exist $C>0$ and $p_0\in(0,1)$ such that for all $p\in(0,p_0)$ and $f\in L^r(\Om)$:
\begin{equation}\label{eq:bound:Neumannseries}
\left\|(\mathbb A_r+p^{\alpha})^{-1}f-\mathbb A_r^{-1}\sum_{i=0}^{N-1}(-p^{\alpha}\mathbb A_r^{-1})^i f\right\|_{W^{2,r}(\Om)}\le Cp^{N\underline{\alpha}}\|f\|_{L^r(\Om)}.
\end{equation}
\end{lemma}
\begin{proof}
%We deduce from \cite[Theorem 2.4.2.5]{Grisvard:1985:EPND} that $C_A:=\|\mathbb A_r^{-1}\|_{L^r(\Om)\to W^{2,r}(\Om)}<\infty$ holds.
Recall that $(\mathbb A_r + p^\alpha)^{-1}$ is well-defined as a bounded linear map from $L^{r}(\Om)$ to $H_0^1(\Om)\cap W^{2,r}(\Om)$ for all $p\ge0$.
Upon recalling that $0$ is not in the spectrum of $\mathbb A_r$, we fix  $C_A:=\|\mathbb A_r^{-1}\|_{L^r(\Om)\to W^{2,r}(\Om)}<\infty$.
Then, we have
$$\|p^{\alpha} \mathbb A_r^{-1}\|_{L^r(\Om)\to L^r(\Om)}\le C_A\|p^{\alpha}\|_{L^\infty(\Om)}=C_A p^{\underline{\alpha}},\quad \forall p\in(0,1).$$
Fix any $p_0\in(0,1)$ satisfying $C_A p_0^{\underline{\alpha}}<1/2$.
Then, for all $p\in(0,p_0)$, the operator ${\rm id}+p^{\alpha}\mathbb A_r^{-1}$ is invertible on $L^r(\Om)$ and satisfies the following estimate for all $p\in(0,p_0)$:
\begin{align*}
&\quad\left\|({\rm id}+p^{\alpha}\mathbb A_r^{-1})^{-1}-\sum_{i=0}^{N-1}(-p^\alpha \mathbb A_r^{-1})^i\right\|_{L^r(\Om)\to L^r(\Om)}\le \sum_{i\ge N}\|p^\alpha \mathbb A_r^{-1}\|_{L^r(\Om)\to L^r(\Om)}^i\\
&
\le \sum_{i\ge N} (C_A p^{\underline{\alpha}})^i = \frac{(C_A p^{\underline{\alpha}})^N}{1-C_A p^{\underline{\alpha}}}\le 2 C_A^N p^{N\underline{\alpha}}.
\end{align*}
Also, there holds the identity $(\mathbb A_r+p^{\alpha})^{-1}=\mathbb A_r^{-1}({\rm id}+p^{\alpha}\mathbb A_r^{-1})^{-1}$ for all $p\in(0,p_0)$.
Therefore, the desired estimate \eqref{eq:bound:Neumannseries} holds with $C=2C_A^{N+1}$.
\end{proof}

Note that similar to the case $p=0$, for the case $p=1$, the value of $p^\alpha$ is also independent of $\alpha$. This motivates the following Neumann series expansion near $p=1$.

\begin{lemma}\label{lemma:neumannseries:near:1}
Fix any $N\in\mathbb{N}$. There exist  $C,\varepsilon>0$ satisfying the following for all $p\in(1-\varepsilon,1+\varepsilon)$ and $f\in L^r(\Om)$:
\begin{equation}\label{eq:bound:Neumannseries:near:1}
\left\|(\mathbb A_r+p^{\alpha})^{-1}f-(\mathbb A_r+{\rm id})^{-1}\sum_{i=0}^{N-1}(({\rm id}-p^{\alpha})(\mathbb A_r+{\rm id})^{-1})^i f\right\|_{W^{2,r}(\Om)}\le C\|{\rm id}-p^\alpha\|_{L^\infty(\Om)}^{N}\|f\|_{L^r(\Om)}.
\end{equation}
\end{lemma}
\begin{proof}
The proof is similar to that of Lemma \ref{lemma:neumannseries}. We use the identity $$(\mathbb A_r+p^{\alpha})^{-1}=(\mathbb A_r+{\rm id})^{-1}({\rm id}+(p^{\alpha}-{\rm id})(\mathbb A_r+{\rm id})^{-1})^{-1},$$
and the Neumann series $({\rm id}+(p^{\alpha}-{\rm id})(\mathbb A_r+{\rm id})^{-1})^{-1}$ for $p$ sufficiently close to $1$.
\end{proof}

Now we can state two important asymptotic expansions on the Laplace transform $\p_\nu \widehat{U}(p,x_0)$ of the Normal derivative.
\begin{theorem}\label{theorem:flux:lowfreq:asympt:general}
Let $\alpha$ satisfy Assumption \ref{ass:alpha:basic}, and let $g$ satisfy Assumption \ref{ass:g}.
Let $U$ be the solution of problem \eqref{eq:2D3D:ibvp}.
Fix any $x_0\in \partial\Omega$ and $N\in\mathbb{N}$.
There exist $C,p_0>0$ and $R(p)$ satisfying $|R(p)|\le C p^{N\underline{\alpha}}$ for all $p\in(0,p_0)$ and
\begin{equation}\label{eq:flux:lowfreq:asympt}
\p_\nu \widehat{U}(p,x_0)=p^{-M-1}\left(\sum_{k=2}^M \sum_{\ell=0}^{N-1} \p_\nu  u_{k,\ell}(p,x_0) + R(p)\right),\quad\forall p\in(0,p_0),
\end{equation}
where the functions $u_{k,0}(p,\cdot)\in W^{2,r}(\Om)\hookrightarrow C^{1,r_0}(\overline{\Om})$ for $k=2,3,\dots,M$ are the unique solutions of
\begin{equation}\label{eq:bvp:u0}
\left\{
\begin{aligned}
-\nabla\cdot(\sigma\nabla u_{k,0})+qu_{k,0}&=0,\quad\mbox{in }\Om,\\
u_{k,0}&=k!p^{M-k}\varphi_k,\quad\mbox{on }\partial\Omega,
\end{aligned}
\right.
\end{equation}
and $u_{k,\ell}(p,\cdot)\in W^{2,r}(\Om)\hookrightarrow C^{1,r_0}(\overline{\Om})$ for $k=2,3,\dots,M$ and $\ell\in\mathbb{N}$ are recursively defined to be the unique solutions of
\begin{equation}\label{eq:bvp:ui}
\left\{
\begin{aligned}
-\nabla\cdot(\sigma\nabla u_{k,\ell})+qu_{k,\ell}&=-p^{\alpha}\rho u_{k,\ell-1},\quad\mbox{in }\Om,\\
u_{k,\ell}&=0,\quad\mbox{on }\partial\Omega.
\end{aligned}
\right.
\end{equation}
\end{theorem}
\begin{proof}
Under Assumption \ref{ass:g}, we have $\widehat{g}(p,x)=\sum_{k=2}^M k! p^{-k-1} \varphi_k(x)$ for all $(p,x)\in(0,\infty)\times\partial\Omega$.
Hence, the identity \eqref{eq:normalder:Uhat} in Lemma \ref{lemma:representation:resolvents} gives
\begin{equation}\label{eq:lemma3.2:copy}
    \p_\nu \widehat{U}(p,x)=
\sum_{k=2}^M \p_\nu \left[\left({\rm id}-(\mathbb A_r+p^{\alpha})^{-1}p^{\alpha}\right)k! p^{-k-1}\mathcal{S} \varphi_k\right](x),\quad\forall (p,x)\in(0,\infty)\times\partial\Omega.
\end{equation}
Now fix any $N\in\mathbb{N}$ with $N\ge2$.
Upon letting $\mathbb{B}_N:=(\mathbb A_r + p^\alpha)^{-1}-\mathbb A_r^{-1}\textstyle\sum_{i=0}^{N-2}(-p^{\alpha}\mathbb A_r^{-1})^i$, we have the following identity
\begin{align}
{\rm id}-(\mathbb A_r + p^\alpha)^{-1}p^\alpha &= {\rm id}-\left(\mathbb A_r^{-1}\sum_{i=0}^{N-2}(-p^{\alpha}\mathbb A_r^{-1})^i +\mathbb B_N\right)p^\alpha \nonumber\\
&= \sum_{\ell=0}^{N-1}(-\mathbb A_r^{-1}p^{\alpha})^\ell-\mathbb B_N p^\alpha,\quad\forall p>0.\label{eq:lemma3.3:copy}
\end{align}
It follows from Lemma \ref{lemma:neumannseries} that there exist constants $C,p_0>0$ independent of $p$ satisfying 
$$\|\mathbb B_N\|_{L^r(\Om)\to W^{2,r}(\Om)}\le C p^{(N-1)\underline{\alpha}},\quad \forall p\in(0,p_0).$$
Meanwhile, from the definitions of $\mathcal{S}$ and $\mathbb A_r$, we deduce 
\begin{align*}
u_{k,0}&=k! p^{M-k}\mathcal{S}\varphi_k,\\ 
u_{k,\ell} &= (-\mathbb A_r^{-1} p^{\alpha})u_{k,\ell-1},\quad \forall k\in\{2,3,\dots,M\},\, \forall\ell\in\mathbb{N}.
\end{align*}
Consequently, for all $k=2,3,\dots,M$ and $\ell\in\mathbb{N}\cup\{0\}$,
\begin{equation}\label{eq:intermsof:ukl}
\p_\nu (-\mathbb A_r^{-1}p^{\alpha})^\ell (k! p^{-k-1}\mathcal{S} \varphi_k)(x)=p^{-M-1}\p_\nu  u_{k,\ell}(p,x),\quad\forall (p,x)\in(0,\infty)\times\partial\Omega.
\end{equation}
By plugging \eqref{eq:lemma3.3:copy} and \eqref{eq:intermsof:ukl} into \eqref{eq:lemma3.2:copy}, we obtain the desired assertion \eqref{eq:flux:lowfreq:asympt} with the remainder
$$R(p)=-p^{M+1}\sum_{k=2}^M \p_\nu \left[\mathbb{B}_N p^\alpha (k!p^{-k-1}\mathcal{S}\varphi_k)\right](x_0),\quad\forall p\in(0,p_0).$$
From the estimate $\|\mathbb B_N p^\alpha\|_{L^r(\Om)\to W^{2,r}(\Om)}\le C p^{N\underline{\alpha}}$ for all $p\in(0,p_0)$, we obtain $|R(p)|\le C p^{N\underline{\alpha}}$ for all $p\in(0,p_0)$, and hence the theorem for every $N\ge2$.
Also the assertion for $N=2$ directly implies that for $N=1$. This completes the proof of the theorem. 
