\section{Proof of main results}\label{sec:inverse}
In this section, we present the detailed proofs of the main results stated in Section \ref{sec:main}. Throughout this section, $\mathbb A_r^i$, $i=1,2$, denotes the operator $\mathbb A_r$ associated with $\sigma=\sigma^i$, $\rho=\rho^i$ and $q=q^i$.
\subsection{Proof of Theorem \ref{theorem:flux:lowfreq:asympt:onept}}
\begin{proof}
Theorem \ref{theorem:flux:lowfreq:asympt:general} for $N=2$ and $U=U^i$ with $i=1,2$ gives, as stated in Remark \ref{remark:Neq2:asympt},
\begin{equation}\label{eq:pf:uniq:asympt-0}
\p_\nu \widehat{U}^i(p,x_0)=p^{-M^i-1}\left( \sum_{\ell=0}^{1} \p_\nu  u_{M^i,\ell}(p,x_0) + O(p+p^{2\underline{\alpha^i}})\right),\quad\mbox{as }p\to0^+.	
\end{equation}
For $i=1,2$, by the piecewise constancy of $\alpha_i$, there holds
$$\p_\nu  u_{M^i,1}^i=-\p_\nu  (\mathbb A_r^i)^{-1}[p^{\alpha^i} u_{M^i,0}^i]=-\sum_{j=0}^{n^i}p^{\alpha_j^i}\p_\nu  (\mathbb A_r^i)^{-1}\left[ u_{M^i,0}^i \chi_{\Om_j^i}\right].$$
By the analytic continuation in time and the hypothesis, using this identity and \eqref{eq:pf:uniq:asympt-0}, we obtain that as $p\to0^+$,
\begin{align}
&\hskip5mm \sigma^1(x_0){p^{-M^1-1}}\left(\p_\nu  u_{M^1,0}^1(x_0)-\sum_{j=0}^{n^1}p^{\alpha_j^1}\p_\nu  (\mathbb A_r^1)^{-1}\left[ u_{M^1,0}^1 \chi_{\Om_j^1}\right](x_0)+O(p+p^{2\alpha_{0}^1})\right)\nonumber \\
&=\sigma^2(x_0){p^{-M^2-1}}\left(\p_\nu  u_{M^2,0}^2(x_0)-\sum_{j=0}^{n^2}p^{\alpha_j^2}\p_\nu  (\mathbb A_r^2)^{-1}\left[ u_{M^2,0}^2 \chi_{\Om_j^2}\right](x_0)+O(p+p^{2\alpha_{0}^2})\right).\label{eq:thm32:mainid}
\end{align}
\iffalse
Comparing the leading orders, we obtain $M^1=M^2=:M$ and $\eta_{N^1}^1\p_\nu  u_0^1(p,x_0)=\eta_{N^2}^2\p_\nu  u_0^2(p,x_0)$.
Since $\alpha=\alpha^i$ is valued in $(0,1)$ and satisfies Assumption \ref{ass:stratified:structure}, \eqref{eq:thm32:mainid} implies
\beq\label{eq:same:coeff}
\textstyle\sum_{j=0}^{n^1} p^{\alpha_j^1} \mathbb A_r^{-1}\left[ u_0^1 \chi_{\Om_j^1}\right](p,x_0)\equiv (\eta_{N^1}^1)^{-1}\eta_{N^2}^2\textstyle\sum_{j=0}^{n^2} p^{\alpha_j^2}\mathbb A_r^{-1}\left[ u_0^2 \chi_{\Om_j^2}\right](p,x_0).
\eeq
\fi
Next we prove the assertions in parts (a) and (b) separately.
%Let $B^i:=\{\alpha^i(x)\,:\,x\in\Om\}$.

\medskip
\noindent{\bf Part (a).}
The proof employs the relation \eqref{eq:thm32:mainid} essentially.
Without loss of generality, suppose that $M^1\ge M^2$ and $\varphi_{M^1}^1\ge0$ is not uniformly vanishing (recall that $\varphi_{M^1}^1$ is from the Dirichlet boundary data $g^1$).
Then we have $u_{M^1,0}^1(x)>0$, and thus, $(\mathbb A_r^1)^{-1}[ u_{M^1,0}^1 \chi_{\Om_j^1}](x)>0$ for all $j\in \{0,\ldots,n^1\}$ and $x\in\Om$ by the strong maximum principle \cite[Theorem 3.5]{GT}.
Next by Hopf's lemma \cite[Lemma 3.4]{GT}, we conclude 
$$\p_\nu  (\mathbb A_r^1)^{-1}[ u_{M^1,0}^1 \chi_{\Om_j^1}](x_0)<0,\quad \forall j.$$ 
First we prove $M^1=M^2$ by means of contradiction. Suppose to the contrary that $M^1> M^2$.
Then, by multiplying $p^{M^1+1}$ on both sides of the identity \eqref{eq:thm32:mainid} and then taking the limit $p\to 0^+$, we obtain $\p_\nu  u_{M^1,0}^1(p,x_0)=0$, because the function $u_{M^i,0}^i=M^i!\mathcal{S}^i\varphi^i_{M^i}$ is independent of $p$ for $i=1,2$.
Next, by multiplying $p^{M^1+1-\alpha_0^1}$ on both sides of \eqref{eq:thm32:mainid} and then taking the limit $p\to 0^+$, we obtain a contradiction: the left-hand side becomes $-\sigma^1(x_0)\p_\nu  (\mathbb{A}_r^1)^{-1}\left[ u_{M^1,0}^1 \chi_{\Om_0^1}\right](x_0)>0$, but the right-hand side becomes zero.
Therefore, we have $M^1=M^2$, which simplifies the identity \eqref{eq:thm32:mainid} into 
$$\sum_{j=0}^{n^1}p^{\alpha_j^1}\p_\nu  (\mathbb A_r^1)^{-1}\left[ u_{M^1,0}^1 \chi_{\Om_j^1}\right](x_0)=\frac{\sigma^2(x_0)}{\sigma^1(x_0)}\sum_{j=0}^{n^2}p^{\alpha_j^2}\p_\nu  (\mathbb A_r^2)^{-1}\left[ u_{M^2,0}^2 \chi_{\Om_j^2}\right](x_0)+O(p^{\min\{1,2\alpha_{0}^1,2\alpha_{0}^2\}}).$$
Since $\{\alpha_j^i\}_{j=0}^{n^i}$ is strictly increasing for $i=1,2$ and every coefficient of $p^{\alpha_j^i}$ on both sides is nonzero, one can easily show that $n^1=n^2$ and $\alpha_j^1=\alpha_j^2$ for all $j$, hence part (a) follows.

\medskip
\noindent{\bf Part (b).}
Let $\rho^1=\rho^2=:\rho$, $\sigma^1=\sigma^2=:\sigma$, $q^1=q^2=:q$ (so that $\mathbb A_r^1=\mathbb A_r^2=:\mathbb A_r$).
Also, let $M^1=M^2=:M$ and $\varphi_M^1=\varphi_M^2=:\varphi_M$.
From the proof of part (a), we have $n^1=n^2=:n$ and $\alpha_j^1=\alpha_j^2$ for all $j=0,1,\dots,n$.
Consequently, $u_{M,0}^1=M!\mathcal{S}\varphi_{M}=u_{M,0}^2$.
Let $u_{M,0}^1=u_{M,0}^2=:u_{M,0}$.
By identifying the coefficients of the powers of $p$ on both sides of \eqref{eq:thm32:mainid}, we obtain
\begin{equation}\label{eq:coeff:identify}
\p_\nu  \mathbb A_r^{-1}\left[ u_{M,0} \chi_{\Om_j^1}\right](x_0)=\p_\nu  \mathbb A_r^{-1}\left[ u_{M,0} \chi_{\Om_j^2}\right](x_0), \quad j=0,1,\dots,n.    
\end{equation}
Summing the identity \eqref{eq:coeff:identify} over $j\in\{0,1,\dots,k\}$ gives, for $k=0,1,\dots,n$, 
\begin{equation}\label{eq:coeff:identify:cumulate}
\p_\nu  \mathbb A_r^{-1}\left[ u_{M,0} \chi_{\cup_{j=0}^k\Om_j^1}\right](x_0)=\p_\nu  \mathbb A_r^{-1}\left[ u_{M,0} \chi_{\cup_{j=0}^k\Om_j^2}\right](x_0).        
\end{equation}
Meanwhile, by using the strong maximum principle and Hopf's lemma as in part (a), for all measurable subsets $A,B$ of $\Om$, the following strict monotonicity holds:
$$\mbox{if }A\subset B\mbox{ and }|B\backslash A|>0,\mbox{ then }0>\p_\nu  \mathbb A_r^{-1}\left[ u_{M,0} \chi_{A}\right](x_0)>\p_\nu  \mathbb A_r^{-1}\left[ u_{M,0} \chi_{B}\right](x_0).$$
The first assumption $\alpha^1\ge\alpha^2$ implies $\cup_{j=0}^k\Om_j^2\subset \cup_{j=0}^k\Om_j^1$ for all $k=0,1,\dots,n$, while the second assumption implies either $\Om_j^{1}\subset \Om_j^{2}$ or $\Om_j^{2}\subset \Om_j^{1}$ holds for all $j=0,1,\dots,n$.
By combining the strict monotonicity with the identities \eqref{eq:coeff:identify} and \eqref{eq:coeff:identify:cumulate}, we conclude $\Om_j^1=\Om_j^2$ for all $j=0,1,\dots,n$ if either the first or the second assumption holds true. This completes the proof of the theorem.
\end{proof}

\subsection{Proof of Theorem \ref{theorem:uniqueness:measfuns}}

\begin{proof}
Let $\mu$ be the Lebesgue measure in $\mathbb{R}^d$.
For part (a), we prove that
$$\underline{\alpha^1}:=\operatorname{essinf}\{\alpha^1(x)\,:\,x\in\Om\}=\underline{\alpha^2}:=\operatorname{essinf}\{\alpha^2(x)\,:\,x\in\Om\}.$$
For part (b), under the additional assumptions, we shall prove that $\mu(\{x\in\Om\,:\,\alpha^1(x)\ne\alpha^2(x)\})=0$.
The main idea of the proof is to combine Hopf's lemma with Theorem \ref{theorem:flux:lowfreq:asympt:general}
and the continuity of measures.

\medskip
\noindent{\bf Part (a).} 
%Let $m^i:=\operatorname{essinf}\{\alpha^i(x)\,:\,x\in\Om\}$ for $i=1,2$.
We prove $\underline{\alpha^1}=\underline{\alpha^2}$ by means of contradiction: Suppose to the contrary that $\underline{\alpha^1}\ne \underline{\alpha^2}$, say $\underline{\alpha^1}<\underline{\alpha^2}$.
Fix any $m\in(\underline{\alpha}^1,\min\{2\underline{\alpha^1},\underline{\alpha^2}\})$.
Then we have $$\mu\left(\{x\in\Om\,:\, \alpha^1(x)<m\}\right)>0\quad\mbox{and}\quad\mu\left(\{x\in\Om\,:\, \alpha^2(x)<\underline{\alpha}^2\}\right)=0.$$
By the analytic continuation in time of the hypothesis, we have 
$$\sigma^1(x_0)\p_\nu  \widehat{U}^1(p,x_0)=\sigma^2(x_0)\p_\nu  \widehat{U}^2(p,x_0)=:F(p),\quad \forall p>0.$$
Theorem \ref{theorem:flux:lowfreq:asympt:general} with $N=2$ gives the following asymptotic relation (cf. Remark \ref{remark:Neq2:asympt}):
\begin{equation}\label{eq:F:twoasymptotics}
    F(p)= p^{-M^i-1}\sigma^i(x_0)\left(\p_\nu  u_{M^i,0}^i(x_0) - \p_\nu (\mathbb{A}_r^{i})^{-1}[p^{\alpha^i}u_{M^i,0}^i](x_0)+ O\big(p+p^{2\underline{\alpha^i}}\big)\right),
\end{equation}
as $p\to 0^+$ for $i=1,2$.
In particular, for $i=1,2$, we have
\begin{align}
\lim_{p\to 0^+} p^{M^i+1} |F(p)|&= \sigma^i(x_0)|\p_\nu  u_{M^i,0}^i(x_0)|<\infty,\label{eq:powerplus1}
\\
\lim_{p\to 0^+} p^{M^i} |F(p)|&= \sigma^i(x_0)\lim_{p\to 0^+} p^{-1}\left|\p_\nu  u_{M^i,0}^i(x_0) - \p_\nu (\mathbb{A}_r^{i})^{-1}[p^{\alpha^i}u_{M^i,0}^i](x_0)\right|=\infty.\label{eq:powerplus0}
\end{align}
The last relation of \eqref{eq:powerplus0} for the case  $\p_\nu  u_{M^i,0}^i(x_0)\ne0$ is immediate.
It suffices to show the last relation of \eqref{eq:powerplus0} for the case $\p_\nu  u_{M^i,0}^i(x_0)=0$. By the strong maximum principle for the operator $(\mathbb{A}_r^i)^{-1}$ and Hopf's lemma, there holds for all $0<p<1$,
\begin{align*}
    |\p_\nu (\mathbb{A}_r^{i})^{-1}[p^{\alpha^i}u_{M^i,0}^i](x_0)|&\ge |\p_\nu (\mathbb{A}_r^{i})^{-1}[\chi_{\alpha^i<\frac{\underline{\alpha^i}+1}{2}}p^{\alpha^i}u_{M^i,0}^i](x_0)|\\
    &\ge p^{\frac{\underline{\alpha^i}+1}{2}}|\p_\nu (\mathbb{A}_r^{i})^{-1}[\chi_{\alpha^i<\frac{\underline{\alpha^i}+1}{2}}u_{M^i,0}^i](x_0)|,
\end{align*}
where the estimate $|\p_\nu (\mathbb{A}_r^{i})^{-1}[\chi_{\alpha^i<\frac{\underline{\alpha^i}+1}{2}}u_{M^i,0}^i](x_0)|>0$ holds due to the condition $\mu(\{x\in\Om\,:\,\alpha^i(x)<\frac{\underline{\alpha^i}+1}{2}\})>0$, the strong maximum principle for $(\mathbb{A}_r^i)^{-1}$ and Hopf's lemma again. Thus the second assertion in \eqref{eq:powerplus1} holds also for the case $\p_\nu  u_{M^i,0}^i(x_0)=0$.
Since there can only be one integer $M^i$ satisfying both \eqref{eq:powerplus1} and \eqref{eq:powerplus0}, we have $M^1=M^2=:M$.
By using this fact, the identity \eqref{eq:F:twoasymptotics} with $i=2$ and $m<\underline{\alpha^2}$, we obtain
$$\lim_{p\to 0^+} p^{-m}\left(p^{M+1} F(p)-\sigma^2(x_0)\p_\nu  u_{M,0}^2(x_0)\right)=0.$$
From the relations $$\sigma^2(x_0)\p_\nu  u_{M^2,0}^2(x_0)=\lim_{p\to0^+}p^{M+1}F(p)=\sigma^1(x_0)\p_\nu  u_{M^1,0}^1(x_0),$$ and  the identity \eqref{eq:F:twoasymptotics} with $i=1$, we arrive at
$$\lim_{p\to 0^+} p^{-m}\sigma^1(x_0)\p_\nu (\mathbb{A}_r^{1})^{-1}[p^{\alpha^1}u_{M,0}^1](x_0)=0.$$
This contradicts the choice $m>\underline{\alpha^1}$ since the strong maximum principle for the operator $(\mathbb{A}_r^1)^{-1}$, Hopf's lemma and the condition $\mu(\{x\in\Om\,:\,\alpha^1(x)<m\})>0$ give the following relation: for all $0<p<1$,
$$p^{-m}|\p_\nu (\mathbb{A}_r^{1})^{-1}[p^{\alpha^1}u_{M,0}^1](x_0)|\ge|\p_\nu (\mathbb{A}_r^{1})^{-1}[\chi_{\alpha^1<m} u_{M,0}^1](x_0)|>0.$$
\begin{comment}
