\noindent{\bf Part (b).}
We suppress the superscript $i$ as $\mathbb A_r^i=\mathbb A_r$ and $u_{M,0}^i=u_{M,0}$, $\underline{\alpha^i}=\underline{\alpha}$ etc. in view of the additional assumptions.
We prove the assertion by contradiction.
Suppose to the contrary that $\mu(\{x\in\Om\,:\,\alpha^1(x)\ne\alpha^2(x)\})>0$ holds.
Then, by the continuity of measures, the ascending sequence of measurable sets $E_n:=\{x\in\Om\,:\,\alpha^1(x)-\alpha^2(x)>1/n\}$ satisfies
$$\lim_{n\to\infty}\mu(E_n)=\mu(\{x\in\Om\,:\,\alpha^1(x)-\alpha^2(x)\ne 0\})>0.$$
In other words, there exist some $N\in\mathbb{N}$ such that $\mu(E_n)\ge\mu(E_N)>0$ for all $n\ge N$.
Without loss of generality, we assume $\varphi_M^1\le0$ on $\p\Om$.
Then we have $u_{M,0}<0$ in $\Om$ by the strong maximum principle.
Thus, from the strong maximum principle for the elliptic operator $\mathbb{A}_r^{-1}$ and Hopf's lemma, we have
\begin{align*}
&\quad\p_\nu  \mathbb A_r^{-1}\left[(p^{\alpha^2}-p^{\alpha^1})u_{M,0}\right](x_0)\ge \p_\nu  \mathbb A_r^{-1}\left[\chi_{E_n}(p^{\alpha^2}-p^{\alpha^1})u_{M,0}\right](x_0)\\
&\ge (1-p^{1/n})\p_\nu  \mathbb A_r^{-1}\left[\chi_{E_n}p^{\alpha^2}u_{M,0}\right](x_0)\ge C'(1-p^{1/n})p^{\overline{\alpha^2}},\quad\forall n\ge N\mbox{ and }p\in(0,1),
\end{align*}
where $C' = \p_\nu  \mathbb A_r^{-1}\left[\chi_{E_N}u_{M,0}\right](x_0)>0 $.
Let $n_p=\lceil |\log p|\rceil$. Then, for all $n\ge n_p$, we have $1-p^{1/n}\ge1-p^{1/|\log p|}=1-e^{-1}$, which gives
$$\p_\nu  \mathbb A_r^{-1}\left[(p^{\alpha^2}-p^{\alpha^1})u_{M,0}\right](x_0)\ge C'(1-e^{-1})p^{\overline{\alpha^2}},\quad\forall p\in(0,1).$$
Meanwhile, the identity \eqref{eq:F:twoasymptotics} for $i=1$ and $i=2$ gives
$$|\p_\nu  \mathbb A_r^{-1}\left[(p^{\alpha^2}-p^{\alpha^1})u_{M,0}\right](x_0)|\le C (p+p^{2\underline{\alpha}}),\quad\forall p\in(0,1),$$
which contradicts the fact $\overline{\alpha^2}< \min\{1,2\underline{\alpha}\}$.
\end{proof}


\subsection{Proof of Theorem \ref{theorem:stability}}\label{ssec:thm:stability}
First we give two preliminary results.
\begin{lemma}
Let $U$ be the solution of problem \eqref{eq:2D3D:ibvp} under Assumptions \ref{ass:alpha:basic} and \ref{ass:g}. Then the following identity holds
\begin{equation}\label{eq:limit:diffp1}
    \lim_{p\to1}\frac{\p_\nu \widehat{U}(p,x_0)-\p_\nu \widehat{U}(1,x_0)}{p-1}=\int_{0}^\infty \p_\nu  U(t,x_0)(te^{-t})\d t.
\end{equation}
\end{lemma}
\begin{proof}
For all $p\in(0,2)\backslash\{1\}$ and $t>0$, Taylor's formula gives
$$|e^{-pt}-e^{-t}+(p-1)te^{-t}|\le \tfrac{1}{2}|p-1|^2 t^2 e^{-t}.$$
Thus, we have
\begin{align}
    &\hskip5mm \left|\p_\nu \widehat{U}(p,x_0)-\p_\nu \widehat{U}(1,x_0) + (p-1)\int_{0}^\infty \p_\nu  U(t,x_0)(te^{-t})\d t\right|\nonumber\\
&\le \frac{|p-1|^2}{2}\int_0^\infty|\p_\nu  U(t,x_0)|t^2e^{-t}\d t,\quad\forall p\in(0,2).\label{eq:CSineq:stability}
\end{align}
Dividing both sides of the identity \eqref{eq:CSineq:stability} by $p-1$ and then taking the limit $p\to1$ give the desired assertion.
\end{proof}


\begin{lemma}\label{lemma:linf:numb}
    Let $\alpha$ satisfy Assumption \ref{ass:alpha:basic}. Then there holds $$\|p^{\alpha}-1-(p-1)\alpha \|_{L^\infty(\Om)}\le %\tfrac{1}{6}
    |p-1|^2,\quad\forall p\in(0.5,1.5).$$
\end{lemma}
\begin{proof}
    For each $\beta\in(0,1)$ and $x\in(-1,1)$, Taylor's theorem gives
    $$(1+x)^{\beta}=1+\beta x+ \beta(\beta-1)(1+x^*)^{\beta-2} x^2,$$ for some $x^*$ between $0$ and $x$. Thus, for all $\beta\in(0,1)$ and $x\in(-0.5,0.5)$, there holds
    \begin{equation*}%\label{eq:Taylor:near1}
        |(1+x)^{\beta}-1-\beta x|\le %(0.5)^2(1.5)^{-1}
        (0.5)^2(0.5)^{-2}x^2 = x^2.
        %=\tfrac{x^2}{6}.
    \end{equation*}
Using this inequality with $x=p-1$ and taking supremum over $\beta\in(0,1)$ gives the desired inequality.
\end{proof}

Now we can state the proof of Theorem \ref{theorem:stability}.
\begin{proof}
Theorem \ref{theorem:flux:freqisone:asympt:general} with $N=2$ and $U=U^i$ with $i=1,2$ gives
\begin{equation}\label{eq:pf:uniq:asympt}
\p_\nu \widehat{U}^i(p,x_0)=p^{-M-1}\left( \sum_{k=2}^M\sum_{\ell=0}^{1} \p_\nu  v_{k,\ell}(p,x_0) + O(\|1-p^{\alpha}\|_{L^\infty(\Om)}^2)\right),\quad\mbox{as }p\to1.	
\end{equation}
By Lemma \ref{lemma:linf:numb}, we may replace $O(\|1-p^{\alpha}\|_{L^\infty(\Om)}^2)$ by $O(|p-1|^2)$.
Consequently, we obtain, as $p\to1$,
\begin{align}
&\hskip5mm \p_\nu \widehat{U}^1(p,x_0)-\p_\nu \widehat{U}^2(p,x_0) =p^{-M-1}\sum_{k=2}^M\left(\p_\nu  v_{k,1}^1(p,x_0)-\p_\nu  v_{k,1}^2(p,x_0) \right)+ O(|p-1|^2).\label{eq:thm32:mainid:stable}
\end{align}
From Lemmas \ref{lemma:iso:Apluspalpha} and \ref{lemma:linf:numb},  for $i=1,2$ and $k=2, \dots,M$, we deduce
$$\p_\nu  v_{k,1}^1(p,x_0)-\p_\nu  v_{k,1}^2(p,x_0)= (1-p)\p_\nu \widetilde{v}_{k,1}(x_0) + O(|p-1|^2),\quad\mbox{as }p\to1,$$
where the function $\widetilde{v}_{k,1}$ satisfies
\begin{equation}\label{eq:bvp:vi:tilde}
\left\{
\begin{aligned}
-\nabla\cdot(\sigma\nabla \widetilde{v}_{k,1})+(q+\rho)\widetilde{v}_{k,1}&=(\alpha^1-\alpha^2)\rho v_{k,0}(1,\cdot),\quad\mbox{in }\Om,\\
\widetilde{v}_{k,1}&=0,\quad\mbox{on }\partial\Omega.
\end{aligned}
\right.
\end{equation}
Moreover, we obtain $\sum_{k=2}^M\p_\nu \widetilde{v}_{k,1}(x_0)=\p_\nu  \widetilde{v}(x_0)$ for the solution $\widetilde{v}$ to
\begin{equation}\label{eq:bvp:v:total:for:stabliliy}
\left\{
\begin{aligned}
-\nabla\cdot(\sigma\nabla \widetilde{v})+(q+\rho)\widetilde{v}&=(\alpha^1-\alpha^2)\rho \sum_{k=2}^M v_{k,0}(1,\cdot),\quad\mbox{in }\Om,\\
\widetilde{v}&=0,\quad\mbox{on }\partial\Omega.
\end{aligned}
\right.
\end{equation}
By dividing both sides of \eqref{eq:thm32:mainid:stable} by $p-1$, taking the limit $p\to1$ and then comparing with the identity \eqref{eq:limit:diffp1}, we arrive at
\begin{align} -\p_\nu  \widetilde{v}(x_0)&=\lim_{p\to1}\frac{\p_\nu \widehat{U}^1(p,x_0)-\p_\nu \widehat{U}^2(p,x_0)}{p-1}\nonumber\\
&=\int_{0}^\infty (\p_\nu  U^1(t,x_0)-\p_\nu  U^2(t,x_0))(te^{-t})\d t. \label{tata}
\end{align}
Fix $\{\alpha^{2,\ell}\}_{\ell\in\mathbb N}$ an $L^r(\Om)$-convergent sequence of  functions satisfying Assumption \ref{ass:alpha:basic} with $\alpha^{2,\ell}\geq \alpha^1$, $\ell\in\mathbb N$. For all $\ell\in\mathbb N$, let $U^{2,\ell}$
be the solution of problem \eqref{eq:2D3D:ibvp} with $\alpha=\alpha^{2,\ell}$. For $\ell\in\mathbb N$, by choosing $\alpha^2=\alpha^{2,\ell}$, we obtain the following identity 
\begin{equation} \label{eq:totakelimit}
-\p_\nu  \widetilde{v}_\ell(x_0)=\int_{0}^\infty (\p_\nu  U^1(t,x_0)-\p_\nu  U^{2,\ell}(t,x_0))(te^{-t})\d t,\quad \ell\in\mathbb N,
\end{equation}
where $\widetilde{v}_\ell$ solves problem \eqref{eq:bvp:v:total:for:stabliliy} with $\alpha^2=\alpha^{2,\ell}$.
To prove the desired assertion, suppose that the right-hand side of \eqref{eq:totakelimit} converges to zero as $\ell$ tends to infinity.
We prove that $\|\alpha^{2,\ell}-\alpha^1\|_{L^r(\Om)}\to0$ as $\ell\to+\infty$ by contradiction. Suppose that $\|\alpha^{2,\ell}-\alpha^3\|_{L^r(\Om)}\to0$ as $\ell\to+\infty$  for some $\alpha^3\neq\alpha^1$ and note that $\alpha^3\geq\alpha^1$. Let $\widetilde{v}_*$ be the solution of problem \eqref{eq:bvp:v:total:for:stabliliy} with $\alpha^2=\alpha^3$.
Then, by recalling the condition $r>d$, by the continuous Sobolev embedding $W^{1-1/r,r}(\partial\Omega)\hookrightarrow C(\partial\Omega)$ and trace lemma, we have
\begin{equation}\label{eq:tracelemma:vtild}
    |\p_\nu  \widetilde{v}_\ell(x_0)-\p_\nu  \widetilde{v}_*(x_0)|\le C\|\p_\nu  \widetilde{v}_\ell-\p_\nu  \widetilde{v}_*\|_{W^{1-1/r,r}(\partial\Omega)}
    \leq C \|\widetilde{v}_\ell-\widetilde{v}_*\|_{W^{2,r}(\Om)},\quad k\in\mathbb N.
\end{equation}
Also, applying Lemma \ref{lemma:iso:Apluspalpha} with $p=1$ in relation to problem \eqref{eq:bvp:v:total:for:stabliliy} with $\alpha^1-\alpha^2$ replaced by $\alpha^3-\alpha^{2,\ell}$, the right-hand side of \eqref{eq:tracelemma:vtild} is bounded by
$$|\p_\nu  \widetilde{v}_\ell(x_0)-\p_\nu  \widetilde{v}_*(x_0)|\le  C\|(\alpha^3-\alpha^{2,\ell})\rho v\|_{L^r(\Om)},\quad \ell\in\mathbb N,$$ which converges to zero, so taking the limit as $\ell\to\infty$ on both sides of the identity \eqref{eq:totakelimit} gives $\p_\nu  \widetilde{v}_*(x_0)=0$. Next we derive the contradiction.
Note that the function ${v}:=\sum_{k=2}^M v_{k,0}(1,\cdot)$ satisfies
\begin{equation}\label{eq:bvp:vtild:total:for:stabliliy}
\left\{
\begin{aligned}
-\nabla\cdot(\sigma\nabla {v})+(q+\rho){v}&=0,\quad\mbox{in }\Om,\\
{v}&= \sum_{k=2}^M k!\varphi_k,\quad\mbox{on }\partial\Omega.
\end{aligned}
\right.
\end{equation}
It follows from the hypothesis that $\textstyle\sum_{k=2}^M k!\varphi_k$ is neither everywhere-vanishing nor sign-changing.
Then, by the strong maximum principle for problem \eqref{eq:bvp:vtild:total:for:stabliliy}, we have $v(x)>0$ for all $x\in\Om$.
Finally, recalling that $\alpha^3\geq\alpha^1$ and $\alpha^3\neq\alpha^1$, from Hopf's lemma for problem \eqref{eq:bvp:v:total:for:stabliliy} with $\alpha^2=\alpha^3$, we get $\p_\nu  \widetilde{v}_*(x_0)\ne0$, which contradicts the previous statement and completes the proof of the theorem.
\end{proof}

\subsection{Proof of Theorem \ref{theorem:stability:fullbdydata}}
We use the notation of section \ref{ssec:thm:stability} and let $\tilde{v}$ be the solution of \eqref{eq:bvp:v:total:for:stabliliy}. One can derive the following identity in the same way as in the proof of Theorem \ref{theorem:stability}:
\begin{equation} \label{eq:totakelimit:fullmeas}
-\p_\nu  \widetilde{v}(x)=\int_{0}^\infty (\p_\nu  U^1(t,x)-\p_\nu  U^{2}(t,x))(te^{-t})\,\d t,\quad x\in\partial\Omega,
\end{equation}
with $\widetilde v$ being the solution to \eqref{eq:bvp:v:total:for:stabliliy}.
Define the auxiliary function $w\in H^2(\Om)$ to be the  solution to 
\begin{equation}\label{eq:bvp:w:aux}
\left\{
\begin{aligned}
-\nabla\cdot(\sigma\nabla w)+(q+\rho)w&=0,\quad\mbox{in }\Om,\\
w&=1,\quad\mbox{on }\partial\Omega.
\end{aligned}
\right.
\end{equation}
Then, by multiplying $w$ on both sides of equation \eqref{eq:bvp:v:total:for:stabliliy}, integrating over $\Omega$ and integrating by parts, we obtain the identity
$$\int_\Om \sigma \nabla\widetilde{v}\cdot\nabla w \,{\rm d}x + \int_\Om (q+\rho)\widetilde{v}w \,{\rm d}x- \int_{\p\Om}\sigma (\p_\nu \widetilde{v})w \,{\rm d}s= \int_\Om (\alpha^1-\alpha^2)\rho v w \,{\rm d}x,$$
where $v$ is the solution to problem \eqref{eq:bvp:vtild:total:for:stabliliy}.
Using the identity \eqref{eq:bvp:w:aux}, we arrive at
$$\int_\Om (\alpha^1-\alpha^2)\rho v w\,{\rm d} x = - \int_{\p\Om}\sigma \p_\nu \widetilde{v}\, {\rm d }s.$$
By the strong maximum principle for problems \eqref{eq:bvp:vtild:total:for:stabliliy} and \eqref{eq:bvp:w:aux}, $v$ is not sign-changing and there hold $|v|\ge g_0>0$ and $w\ge1$ in $\Om$.  Using these two facts, the condition $\operatorname{essinf}\{\rho(x)\,:\,x\in\Omega\}>0$ and the monotonicity condition $\alpha^1\ge\alpha^2$ gives
$$\|\alpha^1-\alpha^2\|_{L^1(\Om)}\leq C\|\p_\nu \widetilde{v}\|_{L^1(\p\Omega)},$$
with $C>0$ depending on $\sigma$, $\rho$, $\Omega$, $q$ and  $g$. 
This completes the proof of the theorem.
